INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b3cf3d30-326b-50e9-acec-da355df17a49','Paleolithic flute','A flute dating to the Upper Palaeolithic, typically made from bird bone or mammoth ivory with bored finger holes, representing some of the earliest known musical instruments. Well-documented European examples come from sites such as those in the Swabian Jura and are tens of thousands of years old. Analysis of hole placement and bore allows reconstruction of possible pitches, demonstrating deliberate instrument-making in deep prehistory, while exact tuning and technique remain inferred.','A Paleolithic flute is a flute from the Stone Age. Some were made of bird bone or ivory. Holes bored in them changed the pitch. The oldest known ones are tens of thousands of years old. They show people made real instruments very early.','It pushes the evidence for human music far back in time, showing that people were crafting tuned wind instruments during the last Ice Age.','A researcher studies a Swabian ivory or bone flute, models its pitch range from the hole spacing, and builds a replica to test it.','Archaeological & Heritage Acoustics',ARRAY['Bone flute','Music archaeology','Sound-producing artifact','Archaeological instrument reconstruction','Palaeolithic soundscape']::text[],ARRAY['Assuming a perforated bone is a flute without checking for deliberate, bored holes','Claiming a precise ancient scale from a fragmentary instrument','Treating a single find as typical of all Palaeolithic music']::text[],ARRAY['Reconstructing an Ice Age flute''s pitches','Distinguishing a flute from a gnawed bone','Demonstrating early music with a replica']::text[],'beginner',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Paleolithic flute');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b3cf3d30-326b-50e9-acec-da355df17a49','601f6272-8859-47f6-a873-447c45f286ef',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b3cf3d30-326b-50e9-acec-da355df17a49') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b3cf3d30-326b-50e9-acec-da355df17a49');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5aa3d5b-2284-55f7-a1bd-bc26b84afdcc','Sound-producing artifact','Any archaeological object made or used to produce sound, including musical instruments, signalling devices, rattles, whistles, bullroarers, and struck idiophones, studied as evidence of past sonic and musical behaviour. The category is deliberately broad because many objects can make sound without being instruments in a modern sense. Identification draws on form, wear, acoustic testing, and context, and often avoids assuming a purely musical function.','A sound-producing artifact is an object made to make sound. It can be a flute, whistle, rattle, or bullroarer. Not all such objects are true instruments. Researchers judge them by shape, wear, and testing. The term keeps the idea broad on purpose.','It gives archaeologists a cautious, inclusive way to group objects by their capacity to make sound, without prematurely labelling them musical instruments.','An excavator catalogues a clay whistle, a bone rattle, and a bullroarer together as sound-producing artefacts pending acoustic study.','Archaeological & Heritage Acoustics',ARRAY['Music archaeology','Bone flute','Bullroarer','Lithophone','Archaeological instrument reconstruction']::text[],ARRAY['Assuming every sound-producing artefact was a musical instrument','Overlooking objects that make sound but had practical or ritual uses','Labelling an object by shape alone without acoustic or wear evidence']::text[],ARRAY['Cataloguing possible sound tools from a dig','Testing whether an object can produce sound','Distinguishing instruments from signalling devices']::text[],'beginner',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-producing artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5aa3d5b-2284-55f7-a1bd-bc26b84afdcc','601f6272-8859-47f6-a873-447c45f286ef',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5aa3d5b-2284-55f7-a1bd-bc26b84afdcc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5aa3d5b-2284-55f7-a1bd-bc26b84afdcc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '76b5d9d7-cad6-5937-bd94-760515fddabd','Archaeological instrument reconstruction','The process of building a playable replica of an ancient musical instrument from archaeological evidence, the original artefact, fragments, iconography, and texts, using appropriate materials and techniques to study its sound, playing method, and musical possibilities. Reconstruction is both a research method and an interpretive act, since gaps in the evidence must be filled with informed choices. Acoustic testing of the replica helps recover pitch range, timbre, and performance characteristics.','This means building a working copy of an old instrument. Researchers use the find, pictures, and texts as guides. They pick likely materials and methods. Playing the copy reveals its sound and range. Some choices must be filled in with care.','It turns silent, often fragile finds into something that can be heard, letting researchers test how an instrument sounded and was played.','A team recreates a bronze horn from an excavated example, then measures and plays it to study its pitches and volume.','Archaeological & Heritage Acoustics',ARRAY['Experimental archaeoacoustics','Music archaeology','Bone flute','Sound-producing artifact','Paleolithic flute']::text[],ARRAY['Presenting a reconstruction''s sound as certainly identical to the original','Hiding the interpretive choices needed to fill evidence gaps','Using modern materials that change the instrument''s sound']::text[],ARRAY['Building a replica flute to test its pitches','Recreating a horn from fragments','Comparing several reconstructions of one instrument']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Archaeological instrument reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '76b5d9d7-cad6-5937-bd94-760515fddabd','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='76b5d9d7-cad6-5937-bd94-760515fddabd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='76b5d9d7-cad6-5937-bd94-760515fddabd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fd29035f-bf3a-59d1-b567-21776d4ed0e6','Experimental archaeoacoustics','The application of experimental-archaeology methods to questions of past sound: building and testing replica instruments, reproducing sound-making activities, and using controlled acoustic measurement to investigate how objects and spaces behaved sonically. It generates physical, testable evidence, such as an instrument''s playable range or a technique''s audibility, to complement finds and models. Results inform interpretation but must be generalised to the past with care.','Experimental archaeoacoustics tests ideas about past sound by doing. Researchers build replica instruments and try them out. They copy old sound-making and measure the results. This gives real, testable evidence. The findings still need care when applied to the past.','It moves claims about ancient sound from speculation toward experiment, producing measurable data on what past instruments and actions could actually do.','Researchers play a reconstructed flute in a measured space to record its real pitch range and how far it carries.','Archaeological & Heritage Acoustics',ARRAY['Archaeological instrument reconstruction','Archaeoacoustics','Music archaeology','Auralization of ancient spaces','Impulse response']::text[],ARRAY['Treating one experiment''s result as proof of past practice','Ignoring how modern materials or players differ from ancient ones','Skipping controlled measurement and relying on impression']::text[],ARRAY['Testing a replica instrument''s real range','Measuring how far a signalling sound carries','Reproducing a technique to study its acoustics']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Experimental archaeoacoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fd29035f-bf3a-59d1-b567-21776d4ed0e6','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fd29035f-bf3a-59d1-b567-21776d4ed0e6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fd29035f-bf3a-59d1-b567-21776d4ed0e6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '18cdfd46-cb6b-585a-beb3-ef53694cc811','Acoustic impulse-response reconstruction','The determination of a space''s acoustic impulse response, the signal describing how the space responds to a brief sound at a given source and receiver position, for a heritage or archaeological site, whether by direct measurement or by modelling a site that no longer survives intact. The impulse response encodes reflections and reverberation and yields standard room-acoustic parameters; it also enables auralization by convolving anechoic sound with it. For altered or lost spaces, the response is reconstructed from geometry and material data rather than measured directly.','An impulse response shows how a space answers a short sound. It captures all the echoes and reverberation. Researchers measure it with a test sound. For lost spaces, they model it from the shape and materials. It lets them recreate how the place sounded.','It provides the core acoustic fingerprint of a space, from which parameters and realistic listening simulations are derived.','An engineer captures a chapel''s impulse response with a swept sine tone, then uses it to compute reverberation time and to auralize speech.','Archaeological & Heritage Acoustics',ARRAY['Impulse response','Auralization of ancient spaces','Reverberation time','Room-acoustic parameters','Heritage acoustics']::text[],ARRAY['Assuming one source-receiver position represents the whole space','Confusing a modelled response for a lost site with a direct measurement','Ignoring how background noise corrupts a measured response']::text[],ARRAY['Measuring a chapel''s impulse response for study','Modelling the response of a ruined hall','Using a response to auralize ancient speech']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic impulse-response reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '18cdfd46-cb6b-585a-beb3-ef53694cc811','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='18cdfd46-cb6b-585a-beb3-ef53694cc811') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='18cdfd46-cb6b-585a-beb3-ef53694cc811');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd83678e2-adf2-5ccb-b932-bd356e3f696b','Auralization of ancient spaces','The rendering of an audible simulation of how an ancient or heritage space sounded, produced by combining a measured or modelled acoustic impulse response with anechoic (dry) source sound, typically through convolution. Auralization lets listeners hear reconstructed reverberation and coloration, of speech, music, or ritual sound, in a space that is ruined, altered, or otherwise inaccessible. It is the acoustic counterpart of visual reconstruction and depends on the quality of the underlying acoustic model.','Auralization lets you hear how an old space sounded. It mixes dry sound with the space''s echo pattern. The result is a realistic sound of that place. It works even for ruined or changed sites. It is like a picture, but for the ears.','It makes acoustic reconstruction audible, so researchers and the public can experience a heritage space''s sound rather than only reading measurements.','A museum plays visitors an auralization of a chant as it would have sounded in a now-ruined abbey, built from a modelled impulse response.','Archaeological & Heritage Acoustics',ARRAY['Acoustic impulse-response reconstruction','Impulse response','Convolution','Heritage acoustics','Reverberation time']::text[],ARRAY['Treating an auralization as an exact recording rather than a model','Using a low-quality acoustic model and presenting it as authoritative','Forgetting that dry source recordings must be anechoic for a valid result']::text[],ARRAY['Letting visitors hear a ruined space''s acoustics','Comparing music in a building''s past and present states','Testing how speech would have carried in a lost hall']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auralization of ancient spaces');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd83678e2-adf2-5ccb-b932-bd356e3f696b','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d83678e2-adf2-5ccb-b932-bd356e3f696b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d83678e2-adf2-5ccb-b932-bd356e3f696b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e0b2038-f2f0-54ac-b469-bdf76c3bdd6b','Paleoacoustic reconstruction','The reconstruction of the acoustic conditions of the deep past, of sites, spaces, or environments, using surviving physical evidence, geometry, material properties, and acoustic modelling. It overlaps with impulse-response reconstruction and auralization but stresses recovering acoustic conditions for periods and places where the original space is lost, altered, or must be inferred. Results are models constrained by evidence, not direct records of past sound.','Paleoacoustic reconstruction rebuilds how the ancient past sounded. It uses ruins, shapes, and material data. Researchers model the missing acoustics from these clues. It helps when the original space is gone. The result is a model, not a recording.','It extends acoustic reconstruction to remote periods and lost settings, giving a principled way to estimate how vanished spaces behaved sonically.','Researchers estimate a collapsed tomb''s original acoustics from its surviving plan, dimensions, and likely surfaces.','Archaeological & Heritage Acoustics',ARRAY['Acoustic impulse-response reconstruction','Auralization of ancient spaces','Archaeoacoustics','Cave acoustics','Heritage acoustics']::text[],ARRAY['Presenting a modelled reconstruction as certain fact','Ignoring how missing roofs, surfaces, or fittings changed the sound','Overstating precision when key inputs are estimated']::text[],ARRAY['Estimating a ruined tomb''s original acoustics','Modelling a lost hall from its foundations','Reconstructing an open-air site''s sound behaviour']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Paleoacoustic reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e0b2038-f2f0-54ac-b469-bdf76c3bdd6b','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e0b2038-f2f0-54ac-b469-bdf76c3bdd6b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e0b2038-f2f0-54ac-b469-bdf76c3bdd6b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3701358-84e6-56bc-af18-27a05f0f86ad','Acoustic heritage','The acoustic properties and sonic characteristics of culturally significant places, objects, and practices, regarded as part of cultural heritage worthy of study, documentation, and safeguarding. It encompasses the measurable acoustics of monuments and spaces and the intangible sonic dimensions of how places were heard and used. The concept underpins efforts to record, conserve, and present sound as heritage, alongside visual and material remains.','Acoustic heritage is the sound side of cultural heritage. It covers how important places and objects sound. It treats that sound as worth saving. This includes echoes in monuments and old sonic practices. It sits beside visible heritage like buildings and art.','It establishes sound as a recognised category of heritage, justifying its documentation and conservation rather than its neglect.','A heritage body commissions acoustic surveys of historic worship spaces so their sound is recorded as part of the protected heritage.','Archaeological & Heritage Acoustics',ARRAY['Heritage acoustics','Intangible sonic heritage','Room-acoustic parameters','Auralization of ancient spaces','Reverberation time']::text[],ARRAY['Assuming heritage is only visual and material, not sonic','Confusing acoustic heritage (the sonic asset) with acoustics (the physics)','Neglecting to document sound before a site is altered']::text[],ARRAY['Recording a monument''s sound as protected heritage','Arguing to conserve a space''s acoustic character','Presenting acoustic heritage to the public']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic heritage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3701358-84e6-56bc-af18-27a05f0f86ad','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3701358-84e6-56bc-af18-27a05f0f86ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3701358-84e6-56bc-af18-27a05f0f86ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff52f33e-01a5-5543-8d39-491a43d45291','Intangible sonic heritage','The non-material sonic dimensions of cultural heritage, such as traditional sounds, acoustic practices, ways of using and hearing spaces, and the sonic character of places, understood within the framework of intangible cultural heritage. Unlike a monument''s physical fabric, this heritage exists in practice, memory, and experience, and is safeguarded through documentation, recording, and transmission. It links heritage acoustics to broader efforts to protect living cultural traditions.','Intangible sonic heritage is the non-physical sound of a culture. It includes traditional sounds and ways of hearing places. It lives in practice and memory, not in objects. It is saved by recording and passing it on. It is part of protecting living traditions.','It brings sound into the concept of intangible cultural heritage, so sonic traditions and experiences can be recognised and safeguarded, not just physical monuments.','A cultural body records and archives a traditional bell-ringing practice and its sound as intangible sonic heritage.','Archaeological & Heritage Acoustics',ARRAY['Acoustic heritage','Heritage acoustics','Soundscape','Acoustic ecology of a site','Auralization of ancient spaces']::text[],ARRAY['Assuming heritage must be a physical object to be protected','Recording a sound once and treating the living practice as preserved','Separating the sound from the community and context that give it meaning']::text[],ARRAY['Documenting a traditional sound practice','Archiving the sonic character of a place','Supporting transmission of a sonic tradition']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intangible sonic heritage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff52f33e-01a5-5543-8d39-491a43d45291','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff52f33e-01a5-5543-8d39-491a43d45291') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff52f33e-01a5-5543-8d39-491a43d45291');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'acf33345-cb1f-5b90-99c5-c9fd8b32ffb1','Archaeoacoustic mapping','The spatial mapping of acoustic properties across an archaeological site or landscape, plotting measurements such as reverberation, echo strength, resonance, or audibility at many positions to reveal how sonic behaviour varies through the space. It supports comparison between areas, for example decorated and undecorated zones, and integrates with spatial tools such as GIS. Maps are built from systematic measurement or modelling and interpreted alongside other archaeological data.','Archaeoacoustic mapping charts sound across a site. Researchers measure acoustics at many spots. They plot how echoes or resonance change place to place. This shows which areas stand out sonically. The maps are read with other site data.','It reveals spatial patterns in a site''s acoustics, helping researchers ask whether sonic properties relate to how different areas were used or decorated.','A team measures reverberation at a grid of points in a cave and maps the results to compare art-bearing and blank areas.','Archaeological & Heritage Acoustics',ARRAY['Acoustic GIS','Archaeoacoustics','Rock-art acoustics','Cave acoustics','Audibility analysis']::text[],ARRAY['Mapping too few points to capture real spatial variation','Assuming a sonic pattern proves intentional design','Ignoring how changes since antiquity distort the map']::text[],ARRAY['Mapping resonance across a decorated cave','Comparing acoustic zones of a monument','Feeding acoustic measurements into a site GIS']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Archaeoacoustic mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'acf33345-cb1f-5b90-99c5-c9fd8b32ffb1','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='acf33345-cb1f-5b90-99c5-c9fd8b32ffb1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='acf33345-cb1f-5b90-99c5-c9fd8b32ffb1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '900de06e-1913-5b76-a209-523bab5f8c1c','Acoustic GIS','The use of geographic information systems to store, model, and analyse acoustic and sound-related data across space, such as modelling how far a sound would carry, mapping audibility, or combining sonic layers with terrain, visibility, and site data. In archaeology it supports landscape-scale study of how sound may have propagated and been heard, integrating acoustic modelling with spatial analysis. Outputs depend on the quality of the terrain, source, and propagation assumptions.','Acoustic GIS uses mapping software for sound data. It can model how far a sound travels over land. It maps where a sound could be heard. It joins sound with terrain and site layers. The results depend on the input assumptions.','It brings sound into landscape analysis, letting researchers study propagation and audibility across whole sites and territories, not just single rooms.','An archaeologist models where a drum at a ceremonial centre would have been audible across the surrounding valley using terrain data.','Archaeological & Heritage Acoustics',ARRAY['Archaeoacoustic mapping','Viewshed-soundscape analysis','Audibility analysis','Soundscape','Sound propagation']::text[],ARRAY['Trusting model output without checking propagation assumptions','Ignoring vegetation, wind, and weather effects on real sound travel','Treating a modelled audibility map as measured fact']::text[],ARRAY['Modelling audibility of a signal across a landscape','Combining sound and terrain layers for a site','Comparing sound reach from different locations']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic GIS');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '900de06e-1913-5b76-a209-523bab5f8c1c','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='900de06e-1913-5b76-a209-523bab5f8c1c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='900de06e-1913-5b76-a209-523bab5f8c1c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ca37392e-2785-5c5b-ad1d-8781cd67831c','Viewshed–soundscape analysis','A spatial analysis pairing the visual viewshed (the area visible from a point) with an acoustic or soundshed analysis (the area within which a sound from that point can be heard), to study how sight and sound structured the experience and use of a site or landscape. Often GIS-based, it models both visibility and audibility from key locations to explore how a place could be seen and heard. Results are models constrained by terrain data and propagation assumptions.','This analysis pairs what can be seen with what can be heard. A viewshed is the area visible from a spot. A soundshed is where a sound from that spot reaches. Together they show how a place was seen and heard. Both are modelled from terrain data.','It combines sight and sound in one framework, helping researchers ask how visibility and audibility together shaped where activities and monuments were placed.','A study models both the view and the sound reach from a monument to see how far a ceremony could be seen and heard.','Archaeological & Heritage Acoustics',ARRAY['Acoustic GIS','Audibility analysis','Soundscape','Archaeoacoustic mapping','Viewshed']::text[],ARRAY['Assuming sound and sight cover the same area, when they usually differ','Ignoring terrain, vegetation, and weather effects on audibility','Reading intentional design into modelled overlaps without other evidence']::text[],ARRAY['Comparing view and sound reach from a monument','Studying how a ceremony was seen and heard','Planning site layout analysis in GIS']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Viewshed–soundscape analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ca37392e-2785-5c5b-ad1d-8781cd67831c','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ca37392e-2785-5c5b-ad1d-8781cd67831c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ca37392e-2785-5c5b-ad1d-8781cd67831c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b3fd696c-72e9-539b-b1df-270f946607fd','Audibility analysis','The assessment of whether, and how well, a sound from a given source could be heard at other locations, accounting for source level, distance, terrain, obstacles, and background noise. In archaeology it models the soundshed of activities such as signalling, calling, or ceremony to study how sound may have linked places and people. It can be pursued through GIS modelling, field experiments, or both, and its conclusions depend on assumed source levels and conditions.','Audibility analysis asks if a sound could be heard elsewhere. It weighs the source''s loudness and distance. It also weighs terrain, blocks, and background noise. Researchers use it to map where a signal reached. The results depend on the assumed sound level.','It tests how far sound could connect people and places, turning questions about signalling and ceremony into modelled or measured audibility.','A study estimates whether a horn blown at a fort could be heard at neighbouring settlements, given terrain and likely loudness.','Archaeological & Heritage Acoustics',ARRAY['Acoustic GIS','Viewshed-soundscape analysis','Sound propagation','Soundscape','Archaeoacoustic mapping']::text[],ARRAY['Assuming an ideal source level rather than a realistic range','Ignoring background noise that would mask the sound','Treating a clear-weather model as valid in all conditions']::text[],ARRAY['Estimating the reach of a signalling horn','Testing audibility between related sites','Modelling how far a ceremony could be heard']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audibility analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b3fd696c-72e9-539b-b1df-270f946607fd','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b3fd696c-72e9-539b-b1df-270f946607fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b3fd696c-72e9-539b-b1df-270f946607fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab0b4628-8a9d-5c4f-ae62-d26c9ddc1ab5','Hi-fi soundscape','A soundscape, in R. Murray Schafer''s terminology, with a high signal-to-noise ratio, in which individual sounds can be heard clearly and distinctly against a low background level. Characteristic of quieter, often rural or pre-industrial environments, a hi-fi soundscape allows sounds to be perceived at a distance and in perspective, so that near and far events are distinguishable. The concept is used in soundscape studies and in reconstructing past sonic environments.','A hi-fi soundscape is a clear, quiet sound world. Its background noise is low. Single sounds stand out sharply. You can hear things near and far apart. Calm countryside is a good example.','It names sonic environments where sounds are heard clearly and in depth, giving a way to describe and compare how legible a soundscape is.','A soundscape researcher describes a quiet rural valley, where distant calls carry clearly, as a hi-fi soundscape.','Archaeological & Heritage Acoustics',ARRAY['Soundscape','Lo-fi soundscape','Acoustic ecology of a site','Signal-to-noise ratio','Archaeological soundscape']::text[],ARRAY['Confusing hi-fi here with audio equipment quality rather than a soundscape''s clarity','Assuming hi-fi means loud, when it means low background noise','Treating the label as a value judgement rather than a description']::text[],ARRAY['Describing a quiet rural soundscape','Contrasting past and modern sonic clarity','Reconstructing a pre-industrial sound environment']::text[],'beginner',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hi-fi soundscape');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab0b4628-8a9d-5c4f-ae62-d26c9ddc1ab5','601f6272-8859-47f6-a873-447c45f286ef',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab0b4628-8a9d-5c4f-ae62-d26c9ddc1ab5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab0b4628-8a9d-5c4f-ae62-d26c9ddc1ab5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eeb3dbf7-bda3-557c-8d31-13ee4bc87c33','Lo-fi soundscape','A soundscape, in R. Murray Schafer''s terminology, with a low signal-to-noise ratio, in which a high background noise level masks individual sounds so they lose clarity and perspective. Characteristic of dense, often urban or industrial environments, a lo-fi soundscape crowds sounds together so that near and distant events are hard to distinguish. The concept is used to describe and compare sonic environments, including in reconstructing how past soundscapes may have changed.','A lo-fi soundscape is a crowded, noisy sound world. Its background noise is high. Single sounds get buried in the din. You cannot tell near from far easily. A busy city street is a good example.','It names sonic environments where noise masks detail, providing a contrast to hi-fi soundscapes and a way to describe sonic crowding.','A researcher labels a traffic-filled city centre, where individual sounds blur together, as a lo-fi soundscape.','Archaeological & Heritage Acoustics',ARRAY['Soundscape','Hi-fi soundscape','Acoustic ecology of a site','Signal-to-noise ratio','Noise']::text[],ARRAY['Confusing lo-fi here with poor audio equipment rather than a noisy soundscape','Assuming lo-fi simply means unpleasant rather than low in clarity','Treating the term as a judgement instead of a description']::text[],ARRAY['Describing a noisy urban soundscape','Contrasting clarity of city and rural sound','Discussing how industrialisation changed soundscapes']::text[],'beginner',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lo-fi soundscape');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eeb3dbf7-bda3-557c-8d31-13ee4bc87c33','601f6272-8859-47f6-a873-447c45f286ef',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eeb3dbf7-bda3-557c-8d31-13ee4bc87c33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eeb3dbf7-bda3-557c-8d31-13ee4bc87c33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1ddd6ee-38e1-5a6f-b564-cdab791ede0f','Acoustemology','A concept, joining ''acoustic'' and ''epistemology'', for the study of sound as a way of knowing. It holds that people come to understand and inhabit their world through hearing and sounding, so that acoustic experience is a primary source of knowledge about place, relationship, and self. Developed within the anthropology of sound, it treats listening and voicing as active, situated practices through which cultural knowledge is formed rather than as passive reception of stimuli.','Acoustemology means knowing the world through sound. The word joins ''acoustic'' and ''epistemology''. It says people learn about a place by hearing it. Listening is an active skill, not just receiving noise. Through sound, people sense space, others, and themselves.','It gives researchers a way to treat sound and listening as sources of cultural knowledge, correcting a long scholarly bias toward vision and text.','An ethnographer uses it when analysing how a community reads weather, territory, or social ties from everyday sounds, or how singing shapes a sense of place.','Anthropology & Sound Studies',ARRAY['Anthropology of sound','Soundscape','Auditory culture','Ethnographic listening','Sound studies']::text[],ARRAY['Treating it as just a synonym for ''soundscape'' rather than a theory of knowing through sound','Assuming it only concerns listening, when sounding and voicing are equally central','Reducing it to acoustics or physics instead of cultural experience']::text[],ARRAY['Analysing how a rainforest community navigates and dwells through listening','Studying how ritual song builds local knowledge of place','Framing a field project around sound as evidence, not just illustration']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustemology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1ddd6ee-38e1-5a6f-b564-cdab791ede0f','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1ddd6ee-38e1-5a6f-b564-cdab791ede0f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1ddd6ee-38e1-5a6f-b564-cdab791ede0f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44c8dc42-7b51-5842-af42-c373fe306446','Auditory culture','The shared, historically shaped ways in which a social group produces, organises, values, and interprets sound and listening. As an object of study it treats hearing as a cultural and political practice, examining how technologies, spaces, and conventions train people to attend to some sounds and ignore others, and how sound carries meaning, identity, and power.','Auditory culture is how a group deals with sound. Every society teaches its members what to listen for. It also teaches which sounds to ignore. These habits change across time and place. Sound then carries meaning, identity, and power.','It lets scholars study listening as learned and social, showing that ways of hearing differ across cultures and eras rather than being natural or universal.','A researcher applies it when comparing how city dwellers and villagers hear noise, or how recording and radio reshaped public listening habits.','Anthropology & Sound Studies',ARRAY['Sound studies','Soundscape','Acoustemology','Listening practice','Sonic environment']::text[],ARRAY['Assuming hearing is purely biological and the same for everyone','Treating ''auditory culture'' as only about music rather than all sound','Ignoring how technologies and institutions shape listening']::text[],ARRAY['Comparing listening norms in a concert hall and a market','Studying how headphones changed private listening','Examining which street sounds a city labels as noise']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory culture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44c8dc42-7b51-5842-af42-c373fe306446','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44c8dc42-7b51-5842-af42-c373fe306446') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44c8dc42-7b51-5842-af42-c373fe306446');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe66338e-5043-538d-aa2c-ce832446e076','Sound studies','An interdisciplinary field that takes sound, listening, and hearing as central objects of inquiry across the humanities and social sciences. Drawing on anthropology, history, musicology, media studies, and science and technology studies, it examines how sound is produced, circulated, technologised, and given meaning, and how listening practices are shaped by culture, power, and history.','Sound studies is a field that studies sound and listening. It crosses many subjects, like history and anthropology. It asks how sound is made, shared, and recorded. It also asks how people learn to listen. Sound is treated as worth serious study.','It provides a shared home for research on sound, countering the long dominance of vision in scholarship and linking work that was scattered across many disciplines.','Scholars use it to frame studies of recording technology, noise law, deaf experience, radio, or the sounds of a city.','Anthropology & Sound Studies',ARRAY['Auditory culture','Acoustemology','Soundscape','Anthropology of sound','Sonic materiality']::text[],ARRAY['Confusing it with acoustics or audio engineering, which study sound physically','Assuming it is only about music','Thinking it is a single method rather than a broad field']::text[],ARRAY['Framing a thesis on the history of the microphone','Studying how communities contest noise','Analysing podcast listening as a cultural practice']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound studies');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe66338e-5043-538d-aa2c-ce832446e076','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe66338e-5043-538d-aa2c-ce832446e076') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe66338e-5043-538d-aa2c-ce832446e076');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12729381-8916-5151-9fef-d0f4e25729d3','Anthropology of sound','The subfield of sociocultural anthropology that studies how sound, listening, and voicing function within human societies. It investigates the cultural meanings, social relations, and forms of knowledge that people create through making and hearing sound, using ethnographic fieldwork to understand sonic life on its own terms within specific communities.','The anthropology of sound studies sound in human cultures. It looks at how people make and hear sound. It asks what these sounds mean to them. Researchers learn by living with a community. They pay close attention to local ways of listening.','It brings anthropology''s fieldwork and cultural focus to sound, showing that listening and sounding are woven into social life, belief, and power.','An anthropologist uses it when doing fieldwork on ceremonies, work songs, market cries, or the everyday soundscape of a village.','Anthropology & Sound Studies',ARRAY['Acoustemology','Ethnomusicology','Sonic anthropology','Sound studies','Ethnographic listening']::text[],ARRAY['Confusing it with ethnomusicology, which centres specifically on music','Assuming it studies sound as physics rather than culture','Overlooking silence and listening as part of its subject']::text[],ARRAY['Fieldwork on how a community uses sound in ritual','Studying the meaning of bells or drums in a town','Recording and interpreting a village''s daily sounds']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Anthropology of sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12729381-8916-5151-9fef-d0f4e25729d3','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12729381-8916-5151-9fef-d0f4e25729d3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12729381-8916-5151-9fef-d0f4e25729d3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e7d451a-d35b-5a1b-a14f-de0d7fb1d5a5','Sonic anthropology','An approach within anthropology that treats sound both as a subject of study and as a medium of research and representation. Closely related to the anthropology of sound, it foregrounds sonic methods such as recording, listening, and sometimes composing as ways to investigate and convey cultural life, arguing that some social realities are best grasped and communicated through sound rather than text alone.','Sonic anthropology studies culture through sound. It treats sound as a topic to explore. It also treats sound as a research tool. Researchers record, listen, and sometimes compose. They argue some things are best shown by sound.','It pushes anthropology beyond written text, using recording and listening as methods and encouraging sound-based ways of sharing findings.','A researcher uses it when producing a sound piece or listening-based study instead of, or alongside, a written ethnography.','Anthropology & Sound Studies',ARRAY['Anthropology of sound','Acoustemology','Sonic ethnography','Sound studies','Phonography']::text[],ARRAY['Treating it as identical to ethnomusicology','Assuming the recordings speak for themselves without analysis','Ignoring the ethics of recording people''s voices and lives']::text[],ARRAY['Making a sound work to present fieldwork','Using field recordings as primary research data','Teaching culture through listening exercises']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic anthropology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e7d451a-d35b-5a1b-a14f-de0d7fb1d5a5','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e7d451a-d35b-5a1b-a14f-de0d7fb1d5a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e7d451a-d35b-5a1b-a14f-de0d7fb1d5a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1e15ff9-ad08-5cb7-9d36-ed3fff41b31c','Ethnographic listening','A methodological practice in which a researcher listens attentively and reflexively during fieldwork, treating sound and the act of listening as sources of ethnographic data. It involves attending not only to what people say but to how they sound, what they hear, and how listening is culturally organised, while remaining aware of the researcher''s own position and habits of hearing.','Ethnographic listening is careful listening during fieldwork. The researcher treats sound as real evidence. They notice how people speak and what they hear. They also watch their own listening habits. Listening becomes a research skill.','It turns listening into a deliberate research method, helping fieldworkers gather knowledge that observation and interview transcripts alone would miss.','A fieldworker practises it when sitting in on gatherings, attending to tone, silence, and ambient sound rather than only recording words.','Anthropology & Sound Studies',ARRAY['Acoustemology','Anthropology of sound','Sonic ethnography','Listening practice','Participant observation']::text[],ARRAY['Reducing it to simply making audio recordings','Ignoring the researcher''s own cultural filters on hearing','Attending only to speech content and not to how things sound']::text[],ARRAY['Noting tone and silence in a community meeting','Learning local ways of hearing a landscape','Reflecting on one''s own bias while listening in the field']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ethnographic listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1e15ff9-ad08-5cb7-9d36-ed3fff41b31c','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1e15ff9-ad08-5cb7-9d36-ed3fff41b31c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1e15ff9-ad08-5cb7-9d36-ed3fff41b31c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b367e157-9161-5f4b-930a-82a471185955','Acoustic ethnography','An ethnographic approach that centres the recording, analysis, and representation of a community''s sonic life. It uses sound recording as a core fieldwork tool and often presents results in sonic or multimodal form, aiming to document and interpret how sound shapes social experience, space, and meaning within a particular setting.','Acoustic ethnography studies a group through its sounds. The researcher records the sounds of daily life. They study what those sounds mean. Results may be shared as audio. Sound is central to both method and output.','It documents cultural life through sound, capturing atmospheres, rhythms, and acoustic relations that written notes struggle to convey.','A researcher applies it when building a sound-based portrait of a place, such as a market, temple, or factory floor.','Anthropology & Sound Studies',ARRAY['Sonic ethnography','Anthropology of sound','Phonography','Soundscape','Field recording']::text[],ARRAY['Assuming recordings are neutral rather than framed by the recorder''s choices','Neglecting consent and ownership of recorded sound','Treating sound as illustration rather than evidence']::text[],ARRAY['Recording the daily sound cycle of a neighbourhood','Documenting the acoustics of a workplace','Presenting fieldwork as a sound installation']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic ethnography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b367e157-9161-5f4b-930a-82a471185955','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b367e157-9161-5f4b-930a-82a471185955') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b367e157-9161-5f4b-930a-82a471185955');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '334d0eb6-9ea7-5366-b3ca-fdccf00460fc','Sonic ethnography','An ethnographic practice that uses sound recording and composition as primary means of researching and representing social and sensory experience. Associated with sensory and experimental ethnography, it often produces sound works or audiovisual pieces that immerse audiences in the textures of a place, treating the sonic rendering itself as a form of analysis rather than a mere illustration of written argument.','Sonic ethnography researches life through sound. The researcher records and shapes sound into a work. The finished piece lets listeners feel a place. The sound itself carries the argument. It is more than a recording of words.','It offers an immersive, sensory way to convey fieldwork, engaging audiences through sound rather than through written description alone.','A researcher uses it to craft an immersive sound piece or film soundtrack drawn from field recordings of a community.','Anthropology & Sound Studies',ARRAY['Acoustic ethnography','Sonic anthropology','Phonography','Soundscape','Sensory ethnography']::text[],ARRAY['Confusing it with simply adding sound to a documentary','Assuming artistic form removes the need for ethnographic rigour','Overlooking consent and representation ethics']::text[],ARRAY['Composing a field-recording piece about a place','Building an audiovisual work from ceremony recordings','Using sound to evoke a sensory environment for viewers']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic ethnography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '334d0eb6-9ea7-5366-b3ca-fdccf00460fc','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='334d0eb6-9ea7-5366-b3ca-fdccf00460fc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='334d0eb6-9ea7-5366-b3ca-fdccf00460fc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7192eb6a-04e1-55fc-85a8-add2b2afa27e','Ethnomusicology','The study of music as a cultural and social phenomenon, examining music in its human context across the world''s societies. Combining musicological analysis with anthropological fieldwork, it investigates how music is made, learned, performed, and given meaning within particular cultures, and treats all musical traditions as worthy of serious study rather than privileging Western art music.','Ethnomusicology studies music as part of culture. It looks at music from all over the world. Researchers ask how music is made and used. They usually do fieldwork with musicians. Every musical tradition is taken seriously.','It provides tools to understand music within its social and cultural life, challenging the idea that only Western classical music deserves scholarly attention.','An ethnomusicologist does fieldwork with performers, records and transcribes music, and studies its role in ritual, identity, or daily life.','Anthropology & Sound Studies',ARRAY['Anthropology of sound','Organology','Ethnopoetics','Oral tradition','Ethno-organology']::text[],ARRAY['Thinking it studies only ''non-Western'' or ''folk'' music','Confusing it with music theory or pure musicology','Ignoring the social context and treating songs as isolated objects']::text[],ARRAY['Fieldwork with a village drumming ensemble','Transcribing and analysing a vocal tradition','Studying how a genre marks group identity']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ethnomusicology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7192eb6a-04e1-55fc-85a8-add2b2afa27e','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7192eb6a-04e1-55fc-85a8-add2b2afa27e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7192eb6a-04e1-55fc-85a8-add2b2afa27e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '688a76c6-2b88-5c7b-bbee-90d2ffa03735','Organology','The scholarly study of musical instruments, including their classification, construction, acoustics, history, and cultural use. It encompasses systematic schemes for grouping instruments by how they produce sound, most influentially the Hornbostel-Sachs system, as well as the documentation of how instruments are built, played, and valued across societies.','Organology is the study of musical instruments. It looks at how they are built and played. It also sorts them into groups. A famous system groups them by how they make sound. History and culture are part of the study too.','It gives researchers a systematic way to describe, classify, and compare instruments, supporting museum work, history, and cross-cultural study.','A curator or researcher uses it to catalogue instruments, identify how they sound, and trace their construction and origins.','Anthropology & Sound Studies',ARRAY['Ethnomusicology','Ethno-organology','Hornbostel-Sachs classification','Musical acoustics','Instrument classification']::text[],ARRAY['Reducing it to naming instruments without studying sound production or context','Assuming the Hornbostel-Sachs system is the only classification','Ignoring cultural meaning and treating instruments as mere objects']::text[],ARRAY['Cataloguing a museum''s instrument collection','Classifying an unfamiliar instrument by how it sounds','Studying how a lute''s design changed over time']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Organology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '688a76c6-2b88-5c7b-bbee-90d2ffa03735','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='688a76c6-2b88-5c7b-bbee-90d2ffa03735') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='688a76c6-2b88-5c7b-bbee-90d2ffa03735');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56c2785e-1d72-5e73-baf3-8833c87b7f8c','Ethno-organology','The cultural study of musical instruments, combining organology with ethnomusicological fieldwork to examine instruments within their social and cultural settings. It looks beyond physical description to how instruments are made, learned, symbolically valued, gendered, and embedded in ritual and social relations within specific communities.','Ethno-organology studies instruments inside their culture. It goes beyond how they are built. It asks what they mean to people. It looks at who may play them and when. Fieldwork with makers and players is central.','It links the physical study of instruments to their cultural meaning, showing how making and playing them carry social and symbolic weight.','A researcher uses it when studying how a community builds, restricts, or venerates a particular instrument during fieldwork.','Anthropology & Sound Studies',ARRAY['Organology','Ethnomusicology','Anthropology of sound','Instrument classification','Material culture']::text[],ARRAY['Treating it as identical to classical organology','Focusing on the object while ignoring its players and uses','Overlooking gendered or ritual rules about who may play']::text[],ARRAY['Studying who is allowed to play a sacred drum','Documenting how a local instrument is built and taught','Analysing an instrument''s symbolic role in a ceremony']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ethno-organology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56c2785e-1d72-5e73-baf3-8833c87b7f8c','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56c2785e-1d72-5e73-baf3-8833c87b7f8c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56c2785e-1d72-5e73-baf3-8833c87b7f8c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f059fed1-c122-57a9-a505-10925b6fca75','Ethnopoetics','The study and translation of oral verbal art such as myth, narrative, chant, and song in ways that convey its poetic structure and performance qualities. It seeks to represent spoken traditions on the page by attending to line, pause, rhythm, and voice, rather than reducing them to plain prose, and it often draws on close analysis of recorded performance.','Ethnopoetics studies spoken art like myth and chant. It tries to show its poetry on the page. It marks pauses, rhythm, and lines. Plain prose would lose these features. Recorded performances guide the work.','It preserves the artistry of oral traditions in writing and translation, showing that spoken verbal art has poetic form worth careful representation.','A scholar uses it when transcribing a recorded oral narrative into lines that reflect its pauses and delivery.','Anthropology & Sound Studies',ARRAY['Orality','Oral tradition','Oral history','Ethnomusicology','Verbal art']::text[],ARRAY['Flattening oral performance into ordinary prose','Ignoring pauses, tone, and timing as meaningful','Assuming written poetry conventions fit all oral traditions']::text[],ARRAY['Transcribing a myth to show its performed rhythm','Translating a chant while keeping its line breaks','Analysing a storyteller''s pauses and repetitions']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ethnopoetics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f059fed1-c122-57a9-a505-10925b6fca75','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f059fed1-c122-57a9-a505-10925b6fca75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f059fed1-c122-57a9-a505-10925b6fca75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '81f31362-4f76-586b-835a-30b9520eb716','Orality','The condition and characteristics of cultures and communication grounded in spoken rather than written language. Scholarship on orality examines how thought, memory, and expression are organised where knowledge is stored and transmitted by voice, contrasting ''primary orality'' in cultures without writing with the reshaped, ''secondary orality'' fostered by electronic media.','Orality is culture based on the spoken word. In such cultures, knowledge is kept by voice. Memory and speaking shape how people think. Writing changes this pattern. Radio and television create a new kind of orality.','It helps scholars understand how communication and thought work without writing, and how speech-based habits persist even in literate, media-rich societies.','A researcher uses it when studying storytelling, memorised knowledge, or how radio and podcasts revive spoken forms.','Anthropology & Sound Studies',ARRAY['Oral tradition','Oral history','Ethnopoetics','Literacy','Secondary orality']::text[],ARRAY['Assuming oral cultures are simply ''primitive'' or less complex','Ignoring ''secondary orality'' created by modern media','Equating orality only with the absence of writing']::text[],ARRAY['Studying how epics are memorised and performed','Analysing podcast talk as a spoken form','Comparing spoken and written ways of storing knowledge']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Orality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '81f31362-4f76-586b-835a-30b9520eb716','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='81f31362-4f76-586b-835a-30b9520eb716') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='81f31362-4f76-586b-835a-30b9520eb716');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a36e7ecd-8224-5ec2-88bd-10cb4f4a65d2','Oral tradition','The body of knowledge, narratives, songs, and practices transmitted across generations by spoken word and performance rather than in writing. As a field of study it examines how such material is composed, remembered, varied, and passed on, and how it can serve as historical and cultural evidence when critically interpreted.','Oral tradition is knowledge passed on by speech. Stories and songs travel across generations. No writing is needed to keep them. Each telling can change a little. Scholars can use them as evidence.','It preserves and transmits a group''s history, values, and art without writing, and offers researchers a source for the past of non-literate or partly literate societies.','A historian or anthropologist uses it when gathering and cross-checking spoken accounts to reconstruct events or beliefs.','Anthropology & Sound Studies',ARRAY['Orality','Oral history','Ethnopoetics','Folklore','Collective memory']::text[],ARRAY['Assuming oral traditions are fixed and unchanging','Treating them as either wholly true or wholly false rather than critically weighed','Confusing oral tradition with oral history']::text[],ARRAY['Collecting genealogies passed down by elders','Comparing versions of a widely told legend','Using spoken accounts to study a community''s past']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oral tradition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a36e7ecd-8224-5ec2-88bd-10cb4f4a65d2','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a36e7ecd-8224-5ec2-88bd-10cb4f4a65d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a36e7ecd-8224-5ec2-88bd-10cb4f4a65d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '21ff6262-e59a-547e-b956-bd0fb96991fb','Oral history','A method and field of research that records and interprets people''s spoken recollections of their own lived experience, usually through recorded interviews. It generates first-person testimony as a primary source, emphasises the perspectives of ordinary and often marginalised people, and involves careful practices of interviewing, archiving, and ethical use of recordings.','Oral history records people telling their own life stories. Researchers interview them and save the audio. These memories become primary sources. It often captures voices left out of records. Care with consent and storage is important.','It preserves firsthand testimony and gives voice to people whose experiences rarely enter written archives, enriching the historical record.','A researcher conducts, records, transcribes, and archives interviews about events the speakers lived through.','Anthropology & Sound Studies',ARRAY['Oral tradition','Orality','Sonic archive','Testimony','Collective memory']::text[],ARRAY['Treating recollections as flawless fact rather than interpreted memory','Neglecting consent, archiving, and ethical reuse','Confusing oral history with older oral tradition']::text[],ARRAY['Interviewing factory workers about a closed plant','Recording elders'' memories of migration','Archiving testimony for a community history project']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oral history');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '21ff6262-e59a-547e-b956-bd0fb96991fb','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='21ff6262-e59a-547e-b956-bd0fb96991fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='21ff6262-e59a-547e-b956-bd0fb96991fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e6e16164-90b7-5363-8b5a-110b5221d55f','Voice studies','An interdisciplinary field that studies the human voice as a physical, expressive, cultural, and technological phenomenon. It brings together perspectives from performance, linguistics, anthropology, media, and sound studies to examine how the voice produces meaning and identity, how it is trained and represented, and how recording and amplification have reshaped its social life.','Voice studies looks at the human voice from many angles. It treats the voice as body, sound, and culture. It asks how voices carry identity and meaning. It also studies how recording changed the voice. Several fields contribute to it.','It brings scattered work on the voice into one conversation, treating voice as more than speech content and including its grain, style, and technological presence.','A scholar uses it to analyse singing, accent, radio voices, dubbing, or voice technologies.','Anthropology & Sound Studies',ARRAY['Paralinguistics','Sound studies','Auditory culture','Phonation','Vocal timbre']::text[],ARRAY['Reducing the voice to the words it carries','Ignoring how technology mediates the voice','Treating voice as natural rather than trained and cultural']::text[],ARRAY['Analysing a singer''s vocal style','Studying how radio shaped ideal voices','Examining synthetic or dubbed voices']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice studies');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e6e16164-90b7-5363-8b5a-110b5221d55f','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e6e16164-90b7-5363-8b5a-110b5221d55f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e6e16164-90b7-5363-8b5a-110b5221d55f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e8cbbdd0-41e0-5679-b0b9-94bc9b89651d','Paralinguistics','The study of the vocal features of speech that accompany words but lie outside the phonemic and lexical system, such as tone of voice, pitch, loudness, tempo, and vocal quality. These paralinguistic cues convey emotion, attitude, emphasis, and social information, shaping how an utterance is understood beyond its literal content.','Paralinguistics studies how we say words, not the words themselves. It covers tone, pitch, speed, and loudness. These features show feelings and attitude. The same words can sound kind or angry. Meaning comes from more than the words.','It explains how speakers convey emotion and social meaning through vocal delivery, adding a layer of information beyond the verbal message.','Researchers use it when analysing conversation, emotion in speech, or how tone changes an utterance''s meaning.','Anthropology & Sound Studies',ARRAY['Voice studies','Phonetics','Prosody','Nonverbal communication','Intonation']::text[],ARRAY['Confusing paralanguage with the words'' literal meaning','Assuming vocal cues mean the same across all cultures','Ignoring tone and treating transcripts as complete']::text[],ARRAY['Analysing how tone signals sarcasm','Studying emotion in recorded speech','Comparing polite and rude ways of saying the same words']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Paralinguistics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e8cbbdd0-41e0-5679-b0b9-94bc9b89651d','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e8cbbdd0-41e0-5679-b0b9-94bc9b89651d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e8cbbdd0-41e0-5679-b0b9-94bc9b89651d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a37b9d71-4aaf-5ed7-b0b3-bd55e58c350e','Phonemic contrast','The relationship by which two sounds in a language distinguish meaning, so that substituting one for the other can change one word into another. Sounds that contrast in this way belong to separate phonemes, typically demonstrated through minimal pairs; sounds that do not contrast are variants of the same phoneme. Which contrasts a language uses is a defining part of its sound system.','A phonemic contrast is a sound difference that changes meaning. Swap one sound and the word changes. ''Pat'' and ''bat'' show this with p and b. Such pairs prove the sounds are separate units. Each language picks its own contrasts.','It lets linguists identify a language''s meaningful sound units and map how its sound system is organised.','A linguist uses minimal pairs to test which sound differences carry meaning when analysing a language.','Anthropology & Sound Studies',ARRAY['Phoneme','Minimal pair','Phonetic variation','Allophone','Phonology']::text[],ARRAY['Confusing meaningful contrasts (phonemes) with non-meaningful variants (allophones)','Assuming every audible sound difference changes meaning','Applying one language''s contrasts to another']::text[],ARRAY['Testing minimal pairs to find phonemes','Analysing an undocumented language''s sound system','Explaining why a contrast in one language is absent in another']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phonemic contrast');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a37b9d71-4aaf-5ed7-b0b3-bd55e58c350e','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a37b9d71-4aaf-5ed7-b0b3-bd55e58c350e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a37b9d71-4aaf-5ed7-b0b3-bd55e58c350e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3fd5ecdb-4303-539b-a116-777e7567a405','Phonetic variation','Differences in the actual pronunciation of speech sounds across speakers, groups, situations, and time, without necessarily changing the underlying phonemes. Studied in phonetics and sociolinguistics, such variation reflects factors like region, social identity, style, and phonetic context, and provides evidence for how accents form and how sound change spreads.','Phonetic variation is difference in how sounds are said. The same word can be pronounced many ways. Region, age, and setting all play a part. These differences build accents. They also show how pronunciation changes over time.','It reveals how social identity and context shape pronunciation and offers evidence for the origins and spread of accents and sound change.','A sociolinguist measures and compares how different speakers pronounce the same sounds to study accent and change.','Anthropology & Sound Studies',ARRAY['Phonemic contrast','Accent','Sociolinguistics','Sound change','Allophone']::text[],ARRAY['Assuming one pronunciation is correct and others are wrong','Confusing meaning-changing contrasts with mere variation','Ignoring social factors behind pronunciation differences']::text[],ARRAY['Comparing vowel sounds across regions','Tracking a pronunciation shift over generations','Studying how setting changes a speaker''s accent']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phonetic variation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3fd5ecdb-4303-539b-a116-777e7567a405','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3fd5ecdb-4303-539b-a116-777e7567a405') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3fd5ecdb-4303-539b-a116-777e7567a405');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac85d0e2-79bc-5ece-8269-cec93bc008d2','Speech community','A group of people who share a language or variety together with the norms and rules for its use. In sociolinguistics and linguistic anthropology the concept is defined less by uniform speech than by shared understandings of how to interpret and evaluate ways of speaking, making it a key unit for studying language variation and social meaning.','A speech community shares a language and how to use it. Members agree on what different ways of speaking mean. They may still speak in varied ways. What unites them is shared judgement about speech. It is a basic unit for language study.','It gives sociolinguists a unit for studying how language use, variation, and social meaning are shared within a group.','A researcher defines a speech community to study how a group uses and evaluates particular ways of speaking.','Anthropology & Sound Studies',ARRAY['Sociolinguistics','Phonetic variation','Linguistic anthropology','Dialect','Language variety']::text[],ARRAY['Assuming a speech community must speak identically','Equating it strictly with a nation or region','Ignoring shared norms and focusing only on shared forms']::text[],ARRAY['Defining a group to study its slang','Comparing how two communities judge an accent','Mapping shared speaking norms in a neighbourhood']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech community');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac85d0e2-79bc-5ece-8269-cec93bc008d2','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac85d0e2-79bc-5ece-8269-cec93bc008d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac85d0e2-79bc-5ece-8269-cec93bc008d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aec23489-ae48-5a19-a636-60e4070611aa','Communicative ecology','The full set of people, media, technologies, and social relationships through which communication happens within a particular community or setting. Used in media anthropology and community informatics, the concept frames communication as an interconnected environment with social, technological, and discursive layers, rather than as isolated channels or single media.','A communicative ecology is a group''s whole world of contact. It brings people, media, and tools together. It also includes their social ties. We treat it as one linked system. No single channel is studied alone.','It helps researchers study communication as an interconnected whole, showing how people mix media and relationships to stay in contact.','A researcher maps a community''s communicative ecology when studying how it adopts phones, radio, or online tools alongside face-to-face talk.','Anthropology & Sound Studies',ARRAY['Media anthropology','Sonic environment','Communication network','Community informatics','Media ecology']::text[],ARRAY['Studying one medium in isolation from the others','Ignoring the social relationships that carry communication','Treating technology as separate from everyday talk']::text[],ARRAY['Mapping how a village mixes phones and gatherings','Studying media use after a new network arrives','Analysing communication layers in a local group']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Communicative ecology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aec23489-ae48-5a19-a636-60e4070611aa','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aec23489-ae48-5a19-a636-60e4070611aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aec23489-ae48-5a19-a636-60e4070611aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eb220678-1473-5ee9-b8ab-4753748e274c','Sonic environment','The totality of sound present in a given place or setting, considered as the surroundings within which people and other organisms live and act. Overlapping with the notions of acoustic environment and soundscape, it encompasses natural, human, and technological sounds together, and can be studied both as a physical field and as something perceived and interpreted by those within it.','A sonic environment is all the sound in a place. It surrounds the people who live there. It mixes nature, machines, and human sounds. It can be measured as physical sound. It can also be studied as something people sense.','It provides a way to talk about the sound surrounding people in a place, linking physical sound to how it is experienced.','A researcher or planner refers to the sonic environment when assessing how a place sounds and how that affects those in it.','Anthropology & Sound Studies',ARRAY['Soundscape','Acoustic environment','Acoustic ecology','Acoustic community','Auditory culture']::text[],ARRAY['Treating it only as noise to be measured, ignoring meaning','Assuming it equals just background noise','Overlooking non-human sounds']::text[],ARRAY['Assessing how a park sounds to visitors','Comparing the sound of two neighbourhoods','Studying how machines reshape a place''s sound']::text[],'beginner',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic environment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eb220678-1473-5ee9-b8ab-4753748e274c','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eb220678-1473-5ee9-b8ab-4753748e274c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eb220678-1473-5ee9-b8ab-4753748e274c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '65993fb8-d975-529b-bf96-759abce9b623','Acoustic community','A community understood through the ways sound defines and connects it, in which the local soundscape carries shared meaning and supports social life. In acoustic ecology the term describes a setting where sounds such as bells, calls, or signals are heard, recognised, and interpreted in common by inhabitants, so that the sonic environment both reflects and sustains the community''s identity and relations.','An acoustic community is a group joined by shared sounds. Local sounds carry meaning everyone understands. Bells or calls may mark time or events. People recognise and read these sounds together. The sound of the place supports community life.','It shows how a shared soundscape can bind people together and support communication, identity, and a sense of place.','A researcher uses it when studying how meaningful local sounds hold a village or neighbourhood together.','Anthropology & Sound Studies',ARRAY['Acoustic ecology','Soundscape','Sonic environment','Acoustemology','Sound signal']::text[],ARRAY['Reducing it to just the physical sounds present','Assuming larger or louder always means stronger community','Ignoring how shared meaning, not just sound, defines it']::text[],ARRAY['Studying how church bells order village life','Analysing shared signals in a small town','Assessing how new noise erodes shared sounds']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic community');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '65993fb8-d975-529b-bf96-759abce9b623','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='65993fb8-d975-529b-bf96-759abce9b623') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='65993fb8-d975-529b-bf96-759abce9b623');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '43f2a02e-d3fd-56c9-9021-90bcd9cda72d','Listening practice','A culturally and historically shaped way of listening that a person or group has learned and habitually uses. The concept treats listening as an active, trainable skill governed by conventions about what to attend to, how to interpret, and how to behave while hearing, rather than as a natural, uniform response, and it varies across settings such as worship, medicine, music, and science.','A listening practice is a learned way of listening. People are trained how to pay attention. Rules say what to notice and ignore. A doctor and a concertgoer listen differently. Listening is a skill, not just a reflex.','It lets scholars treat listening as learned and varied, showing that different settings and eras cultivate different ways of hearing.','A researcher uses it to compare how people listen in church, at a concert, or when using a stethoscope.','Anthropology & Sound Studies',ARRAY['Auditory culture','Modes of listening','Acoustemology','Ethnographic listening','Sound studies']::text[],ARRAY['Assuming everyone listens the same way','Treating listening as passive reception','Ignoring how training and setting shape hearing']::text[],ARRAY['Comparing medical and musical listening','Studying how a tradition teaches attentive listening','Analysing how recording changed listening habits']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Listening practice');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '43f2a02e-d3fd-56c9-9021-90bcd9cda72d','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='43f2a02e-d3fd-56c9-9021-90bcd9cda72d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='43f2a02e-d3fd-56c9-9021-90bcd9cda72d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2eb09c4-5cb7-5571-82ef-a18b81ab2b79','Auditory habitus','An application of the concept of habitus to hearing: the set of durable, largely unconscious dispositions that shape how a person listens, what they notice, and how they respond to sound. Acquired through upbringing and social position, this listening disposition inclines individuals toward particular tastes and habits of attention, reproducing cultural and class distinctions through the ear.','Auditory habitus means learned habits of listening. We pick them up from our upbringing. They shape what sounds we notice and enjoy. We rarely think about them. They can reflect our social background.','It explains why listening tastes and habits feel natural yet track social background, showing how the ear is trained by culture and class.','A researcher uses it to explain why groups differ in what music or noise they value and how they attend to sound.','Anthropology & Sound Studies',ARRAY['Sonic habitus','Auditory culture','Listening practice','Habitus','Taste']::text[],ARRAY['Treating listening taste as purely personal and innate','Ignoring the class and upbringing behind it','Assuming these habits are conscious choices']::text[],ARRAY['Explaining differing musical tastes by background','Studying how upbringing shapes tolerance of noise','Analysing trained listening in a profession']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory habitus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2eb09c4-5cb7-5571-82ef-a18b81ab2b79','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2eb09c4-5cb7-5571-82ef-a18b81ab2b79') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2eb09c4-5cb7-5571-82ef-a18b81ab2b79');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d3bc675-739c-5b0f-8d52-eee508044770','Sonic habitus','An extension of the concept of habitus to the sonic domain: the embodied, socially acquired dispositions that shape how people both produce and respond to sound. Broader than listening alone, it covers habitual ways of speaking, making noise, moving, and inhabiting sonic space that are learned through social position and that reproduce cultural distinctions.','Sonic habitus means learned habits around sound. It covers how we make sound and react to it. We learn these habits from our surroundings. They feel automatic to us. They can mark our social group.','It shows how bodily habits of sounding and listening are socially learned, linking a person''s sonic behaviour to their cultural background.','A researcher uses it to study how groups habitually speak, make noise, or use sound in shared space.','Anthropology & Sound Studies',ARRAY['Auditory habitus','Habitus','Auditory culture','Sonic agency','Embodiment']::text[],ARRAY['Confusing it narrowly with listening taste alone','Assuming sonic behaviour is purely individual','Overlooking the body''s learned role in making sound']::text[],ARRAY['Studying habitual noise norms in a group','Analysing learned ways of speaking loudly or softly','Examining how a culture uses sound in public space']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic habitus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d3bc675-739c-5b0f-8d52-eee508044770','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d3bc675-739c-5b0f-8d52-eee508044770') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d3bc675-739c-5b0f-8d52-eee508044770');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '289cb9f6-da28-54fb-8562-7a0948c58d50','Sonic memory','The remembering of experience through sound, whether an individual''s recall of particular sounds and voices or a group''s shared associations between sounds and the past. As an analytic concept it examines how sounds evoke, store, and reconstruct memory, and how listening can bind personal recollection to collective and historical experience.','Sonic memory is memory tied to sound. A voice or song can bring back the past. Both people and groups hold such memories. Certain sounds trigger strong recall. Sound helps store and share the past.','It highlights how sound anchors memory, offering a route into personal and collective pasts that images and text may not reach.','A researcher uses it when studying how songs, voices, or place-sounds trigger recollection in individuals or communities.','Anthropology & Sound Studies',ARRAY['Acoustic memory','Collective memory','Sonic archive','Soundscape','Oral history']::text[],ARRAY['Treating sonic memory as an exact recording of the past','Ignoring how groups, not just individuals, remember through sound','Assuming only music, not everyday sound, evokes memory']::text[],ARRAY['Studying how a song recalls a past era','Analysing how a place''s sounds trigger memory','Exploring voices in family recordings']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic memory');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '289cb9f6-da28-54fb-8562-7a0948c58d50','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='289cb9f6-da28-54fb-8562-7a0948c58d50') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='289cb9f6-da28-54fb-8562-7a0948c58d50');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f1eeab6-0d97-5c27-99f6-16cdffcfa69e','Acoustic memory','The shared or transmitted memory carried by the sounds of places, events, and practices, and how communities remember through preserved or recalled sound and the acoustic character of significant sites. In heritage and anthropological work the term names the cultural dimension of sonic remembering; it should be distinguished from the psychological sense of brief auditory sensory (''echoic'') memory.','Acoustic memory is memory held in sounds and places. A community can recall its past through certain sounds. The sound of a site can carry history. This is a shared, cultural kind of memory. It differs from the brief memory of a just-heard sound.','It draws attention to sound as a carrier of cultural heritage and shared remembering tied to particular places and events.','A heritage researcher uses it when documenting the meaningful sounds of a site or the recalled sounds of a community''s past.','Anthropology & Sound Studies',ARRAY['Sonic memory','Collective memory','Sonic archive','Soundscape','Cultural heritage']::text[],ARRAY['Confusing this cultural sense with brief ''echoic'' sensory memory in psychology','Assuming the recorded sound equals the remembered experience','Ignoring that such memory is shared and shaped by a group']::text[],ARRAY['Documenting the historic sounds of a place','Studying how a community recalls past soundscapes','Preserving meaningful sounds as heritage']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic memory');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f1eeab6-0d97-5c27-99f6-16cdffcfa69e','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f1eeab6-0d97-5c27-99f6-16cdffcfa69e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f1eeab6-0d97-5c27-99f6-16cdffcfa69e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '48aa6edc-fb42-51cd-b6de-5ca11bcaea54','Soundwalk','A structured walk whose primary purpose is to listen attentively to the surrounding sonic environment. Developed within acoustic ecology, it is used as a method of research, education, and artistic practice, guiding participants to move through a place while focusing on its sounds, sometimes following a set route or set of listening prompts and documenting what they hear.','A soundwalk is a walk taken mainly to listen. Walkers focus on the sounds around them. A route or prompts may guide them. It is used for study, teaching, and art. The goal is careful attention to a place''s sound.','It trains and focuses listening, letting people experience and document a place''s soundscape directly rather than through recordings alone.','A researcher or educator leads a soundwalk to survey a place''s sounds or to teach attentive listening.','Anthropology & Sound Studies',ARRAY['Acoustic ecology','Soundscape','Listening practice','Sonic environment','Field recording']::text[],ARRAY['Treating it as just a walk with background sound','Assuming it always requires recording equipment','Ignoring the guided, attentive listening that defines it']::text[],ARRAY['Leading students on a listening walk','Surveying a neighbourhood''s sounds on foot','Using a soundwalk as an art event']::text[],'beginner',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Soundwalk');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '48aa6edc-fb42-51cd-b6de-5ca11bcaea54','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='48aa6edc-fb42-51cd-b6de-5ca11bcaea54') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='48aa6edc-fb42-51cd-b6de-5ca11bcaea54');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '523e8a44-7f77-5c80-8fcd-c8615143747e','Phonography','The practice and art of recording sound from the environment, especially field recording pursued for documentary or aesthetic purposes. In sound studies the term names an approach that treats recorded environmental sound as a work or document in its own right; historically the word also referred more broadly to the writing or inscription of sound, including early sound-recording and shorthand systems.','Phonography is the art of recording real-world sound. It captures the sounds of places and events. The recording itself is treated as the work. It can be documentary or artistic. The old meaning was ''writing sound'' more broadly.','It frames field recording as a creative and documentary practice, valuing captured environmental sound as an artefact worth attention.','A phonographer records the sounds of a place to create a sound work or an archive of environmental audio.','Anthropology & Sound Studies',ARRAY['Field recording','Acoustic ethnography','Soundscape','Sonic archive','Sound object']::text[],ARRAY['Assuming a field recording is a neutral copy of reality','Confusing the recording art with the old ''shorthand'' meaning','Ignoring the recordist''s framing choices']::text[],ARRAY['Recording a forest as a sound work','Building an archive of a city''s sounds','Capturing environmental audio for an installation']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phonography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '523e8a44-7f77-5c80-8fcd-c8615143747e','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='523e8a44-7f77-5c80-8fcd-c8615143747e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='523e8a44-7f77-5c80-8fcd-c8615143747e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '13c09534-edfc-57ed-922e-41c243937668','Acoustic ecology','The interdisciplinary study of the relationships between living beings and their sonic environment. Emerging from the World Soundscape Project, it examines how soundscapes function, how human activity alters them, and how balanced, meaningful acoustic environments might be sustained, combining scientific measurement with cultural and aesthetic concern for the quality of the sound around us.','Acoustic ecology studies life and its sound environment. It asks how soundscapes work. It looks at how people change them. It also cares about keeping them healthy. Science and culture both inform it.','It links the study of sound to environmental awareness, treating the soundscape as something to understand, value, and protect.','Researchers use it to assess soundscapes, study the effects of noise, and argue for healthier sonic environments.','Anthropology & Sound Studies',ARRAY['Soundscape','Acoustic community','Schizophonia','Sonic environment','Noise pollution']::text[],ARRAY['Reducing it to noise measurement alone','Ignoring the cultural meaning of sounds','Treating all human sound as unwanted noise']::text[],ARRAY['Assessing how traffic changed a soundscape','Studying natural sounds lost to development','Arguing for quieter, healthier sound in a city']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic ecology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '13c09534-edfc-57ed-922e-41c243937668','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='13c09534-edfc-57ed-922e-41c243937668') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='13c09534-edfc-57ed-922e-41c243937668');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5dd44428-853a-5529-96e9-93caf525f483','Sonic territoriality','The use of sound to claim, mark, control, or contest space. As an analytic concept in sound and urban studies it examines how playing, broadcasting, or imposing sound establishes presence and authority over an area, and how such sonic assertion can include or exclude others, drawing on the older ethological idea that organisms defend territory acoustically.','Sonic territoriality is using sound to claim space. Loud music or calls can mark an area. Sound signals who is present and in charge. It can invite some people and push others out. Animals defend territory with sound too.','It explains how sound becomes a tool of power over space, shaping who feels welcome or excluded in an area.','A researcher uses it to analyse conflicts over loud music, amplified calls, or broadcast sound in shared spaces.','Anthropology & Sound Studies',ARRAY['Acoustic territoriality','Soundscape','Noise','Sonic agency','Sound sovereignty']::text[],ARRAY['Assuming only loudness, not meaning, marks territory','Ignoring who is excluded by dominant sound','Treating it as unique to humans']::text[],ARRAY['Studying disputes over amplified street music','Analysing broadcast calls that claim public space','Examining sound conflicts between neighbours']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic territoriality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5dd44428-853a-5529-96e9-93caf525f483','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5dd44428-853a-5529-96e9-93caf525f483') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5dd44428-853a-5529-96e9-93caf525f483');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '10dd81a3-1f54-50d8-95d1-f171dc9e7378','Acoustic territoriality','The establishment and defence of territory through acoustic signals. Well documented in animal behaviour, where calls and songs advertise occupancy and deter rivals, the concept is also applied to human settings to describe how sound is used to mark and hold space. It emphasises the signalling function by which sound communicates and enforces claims to an area.','Acoustic territoriality is defending an area with sound. Many animals sing or call to claim space. The sound warns rivals to stay away. People can use sound this way too. The sound sends a clear claim.','It describes how sound advertises and enforces control of space, a signalling strategy seen in animals and adapted to human life.','A researcher uses it when studying animal calls that mark territory or human sound used to hold space.','Anthropology & Sound Studies',ARRAY['Sonic territoriality','Bioacoustics','Animal communication','Soundscape','Sound signal']::text[],ARRAY['Assuming it applies only to humans','Confusing signalling with mere loudness','Ignoring the communicative purpose of the sound']::text[],ARRAY['Studying birdsong that marks territory','Analysing loud sound used to hold public space','Comparing animal and human sonic claims']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic territoriality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '10dd81a3-1f54-50d8-95d1-f171dc9e7378','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='10dd81a3-1f54-50d8-95d1-f171dc9e7378') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='10dd81a3-1f54-50d8-95d1-f171dc9e7378');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f80454e9-f3a4-5de6-bca3-b2e7d3f2a0f8','Sound sovereignty','The right and capacity of a community, especially an Indigenous one, to exercise authority over its own sounds, voices, songs, and sonic heritage, including how these are recorded, circulated, and reused. An emerging concept in Indigenous and political studies of sound, it links self-determination to control over sonic cultural property and challenges extractive practices of recording and archiving.','Sound sovereignty is a group''s control over its own sounds. This includes its songs, voices, and recordings. The community decides how they are used. It is often tied to Indigenous rights. It resists outsiders taking sound without consent.','It asserts that communities should govern their own sonic heritage, framing recording and archiving as matters of rights and self-determination.','It guides ethical policy on who may record, hold, and reuse a community''s songs and voices.','Anthropology & Sound Studies',ARRAY['Repatriation of sound recordings','Ethical listening','Sonic agency','Cultural heritage','Indigenous knowledge']::text[],ARRAY['Assuming recorded sound belongs to whoever recorded it','Ignoring community authority over songs and voices','Treating it only as copyright rather than self-determination']::text[],ARRAY['Deciding who may reuse a community''s songs','Setting terms for access to sacred recordings','Guiding an archive''s return of recordings']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound sovereignty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f80454e9-f3a4-5de6-bca3-b2e7d3f2a0f8','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f80454e9-f3a4-5de6-bca3-b2e7d3f2a0f8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f80454e9-f3a4-5de6-bca3-b2e7d3f2a0f8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e13c6dd2-692e-579c-b0f4-e61311f16634','Sonic agency','The capacity to act, resist, or bring about effects in the world through sound and listening. Developed in sound studies, the concept examines how making, withholding, or organising sound can be a form of political and social power, enabling marginalised or unseen actors to assert presence, build solidarity, and contest domination through the sonic.','Sonic agency is the power to act through sound. Making or withholding sound can change situations. It lets unseen groups make themselves felt. Sound can build unity and resist power. Listening can be part of this action too.','It frames sound and listening as means of political action, showing how those without visibility can still exert influence sonically.','A researcher uses it to analyse protest sound, collective chanting, or strategic silence as forms of action.','Anthropology & Sound Studies',ARRAY['Sonic territoriality','Sound sovereignty','Acoustic mediation','Sonic habitus','Soundscape']::text[],ARRAY['Assuming only loud sound has power','Overlooking silence as a form of sonic action','Treating sound as expression only, not action']::text[],ARRAY['Analysing chanting at a protest','Studying strategic silence as resistance','Examining how unseen groups assert presence by sound']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic agency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e13c6dd2-692e-579c-b0f4-e61311f16634','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e13c6dd2-692e-579c-b0f4-e61311f16634') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e13c6dd2-692e-579c-b0f4-e61311f16634');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd35d269-ffe1-5ae5-8c7c-5224ff9e7696','Acoustic mediation','The process by which sound serves as a medium that shapes social relations, experience, and knowledge. The concept examines how sound stands between people and the world, carrying messages, linking or separating groups, and being transformed by technologies of recording and transmission, so that meaning and connection are produced through, and altered by, the sonic medium.','Acoustic mediation is how sound connects people and things. Sound sits between us and the world. It carries messages and links or divides groups. Recording and broadcasting change how it works. Meaning is shaped by the sound medium itself.','It highlights sound''s role as a connective medium, showing how relationships and knowledge are formed and reshaped through sonic means.','A researcher uses it to study how radio, calls to prayer, or recordings link and shape communities.','Anthropology & Sound Studies',ARRAY['Sonic agency','Media anthropology','Acoustemology','Sonic materiality','Schizophonia']::text[],ARRAY['Treating sound as a neutral channel that adds nothing','Ignoring how technology transforms the sound','Overlooking sound''s power to divide as well as connect']::text[],ARRAY['Studying how radio binds a dispersed group','Analysing amplified calls that organise a community','Examining how recording reshapes a relationship to sound']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic mediation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd35d269-ffe1-5ae5-8c7c-5224ff9e7696','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd35d269-ffe1-5ae5-8c7c-5224ff9e7696') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd35d269-ffe1-5ae5-8c7c-5224ff9e7696');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '85772e89-5fb9-59b6-b4bf-48a4e0c4fb18','Auditory epistemology','The study of how knowledge is produced through hearing and listening, treating the ear as a source of understanding rather than a lesser sense beneath sight. It considers what and how we come to know by listening, and how listening practices shape claims to truth; the concept of acoustemology is an influential formulation within this broader concern.','Auditory epistemology asks how we know through hearing. It treats the ear as a real source of knowledge. It studies what listening lets us learn. It also asks how listening shapes truth claims. Acoustemology is one version of this idea.','It challenges the dominance of vision in ideas about knowledge, arguing that careful listening yields genuine understanding.','A scholar uses it when analysing how doctors, scientists, or fieldworkers come to know things by listening.','Anthropology & Sound Studies',ARRAY['Acoustemology','Auditory culture','Listening practice','Sound studies','Sonic ontology']::text[],ARRAY['Assuming knowledge comes mainly through the eyes','Treating listening as passive and unreliable','Confusing it entirely with the specific concept of acoustemology']::text[],ARRAY['Studying diagnosis by listening in medicine','Analysing how fieldworkers know a place by ear','Examining listening in scientific practice']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory epistemology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '85772e89-5fb9-59b6-b4bf-48a4e0c4fb18','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='85772e89-5fb9-59b6-b4bf-48a4e0c4fb18') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='85772e89-5fb9-59b6-b4bf-48a4e0c4fb18');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8b0e80c-0ea4-5ec9-8786-4c4c87865944','Sonic ontology','Philosophical inquiry into the nature and mode of existence of sound: what sound fundamentally is, how it relates to its sources and to time and space, and whether it should be understood as an event, a property, or a thing. Within sound studies and the philosophy of sound it also asks how attending to sound might reshape broader accounts of reality.','Sonic ontology asks what sound really is. Is a sound a thing, an event, or a quality? It studies how sound relates to its source. It also asks how sound exists in time and space. Thinking about sound can reshape ideas of reality.','It clarifies the basic nature of sound and uses that inquiry to rethink assumptions about objects, events, and perception.','A theorist draws on it when arguing about whether sounds are events or objects and what that means for listening.','Anthropology & Sound Studies',ARRAY['Acousmatic sound','Sound object','Sonic materiality','Auditory epistemology','Philosophy of sound']::text[],ARRAY['Assuming sound is obviously just a vibration and needs no analysis','Confusing the physics of sound with its philosophical status','Treating sound as identical to its source']::text[],ARRAY['Debating whether sounds are events or objects','Analysing how recording changes sound''s status','Rethinking perception through the case of hearing']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic ontology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8b0e80c-0ea4-5ec9-8786-4c4c87865944','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8b0e80c-0ea4-5ec9-8786-4c4c87865944') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8b0e80c-0ea4-5ec9-8786-4c4c87865944');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '666c1024-9de9-5b3d-9648-e83510b057c2','Sonic materiality','The material dimension of sound: the idea that sound is not immaterial but a physical, embodied phenomenon that acts on bodies, objects, and spaces and is bound up with the media and technologies that produce and carry it. In sound studies the concept counters treating sound as purely symbolic, stressing its felt, vibrational, and infrastructural reality.','Sonic materiality means sound is physical, not just an idea. Sound is vibration that touches bodies and things. It can be felt, not only heard. Machines and media give it material form. So sound has real, physical effects.','It insists on sound''s physical reality, correcting views that treat sound only as symbol or message and highlighting how it acts on the world.','A researcher uses it when studying how bass is felt in the body or how media technologies give sound physical form.','Anthropology & Sound Studies',ARRAY['Sonic ontology','Sound object','Acoustic mediation','Vibration','Embodiment']::text[],ARRAY['Treating sound as immaterial or purely symbolic','Ignoring how sound physically affects bodies and objects','Overlooking the technologies that carry sound']::text[],ARRAY['Studying bass that is felt in the chest','Analysing how a medium shapes a sound''s force','Examining sound''s physical effect on a space']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic materiality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '666c1024-9de9-5b3d-9648-e83510b057c2','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='666c1024-9de9-5b3d-9648-e83510b057c2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='666c1024-9de9-5b3d-9648-e83510b057c2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f97320a-f6c1-56d7-a8ca-a2a056c83de2','Sound object','A sound perceived and studied in itself, apart from its source or cause, as a distinct unit for listening and analysis. Introduced in the context of musique concrete, the sound object is grasped through focused, repeated listening, especially to recorded sound, that brackets the question of what produced it in favour of the sound''s own qualities.','A sound object is a sound studied on its own. You set aside what made it. You focus only on the sound itself. Careful, repeated listening reveals its qualities. The idea came from working with recorded sound.','It gives listeners and composers a way to treat sound as raw material, focusing on its intrinsic qualities rather than its source.','A composer or analyst isolates a recorded sound and studies its shape, texture, and dynamics as a sound object.','Anthropology & Sound Studies',ARRAY['Reduced listening','Acousmatic sound','Musique concrete','Sonic materiality','Timbre']::text[],ARRAY['Confusing the sound object with the thing that made the sound','Assuming any sound is automatically a sound object without focused listening','Treating it as a physical object rather than a heard unit']::text[],ARRAY['Isolating a recorded sound for close study','Composing with sounds detached from their sources','Analysing a sound''s texture apart from its cause']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound object');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f97320a-f6c1-56d7-a8ca-a2a056c83de2','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f97320a-f6c1-56d7-a8ca-a2a056c83de2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f97320a-f6c1-56d7-a8ca-a2a056c83de2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9dbda3da-e979-5c65-8db6-757abb73dd8a','Reduced listening','A mode of listening that focuses on the qualities of a sound in itself, such as its pitch, texture, dynamics, and shape, while deliberately setting aside its source and any meaning it might carry. Named within the theory of musique concrete and later elaborated, it is the disciplined listening through which a sound is apprehended as a sound object.','Reduced listening focuses only on the sound itself. You set aside what made it and what it means. You attend to its pitch, texture, and shape. It takes practice and repeated hearing. It reveals the sound as pure material.','It trains attention on a sound''s own qualities, enabling analysis and composition based on how sound behaves rather than what it signifies.','A sound designer or composer uses reduced listening to judge a sound''s texture and shape independent of its source.','Anthropology & Sound Studies',ARRAY['Sound object','Causal listening','Semantic listening','Acousmatic sound','Musique concrete']::text[],ARRAY['Slipping back into identifying the source instead of the sound','Confusing it with simply listening closely for meaning','Assuming it comes naturally without practice']::text[],ARRAY['Judging a sound effect by its texture alone','Training students to hear sound qualities','Selecting sounds for their shape, not their source']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reduced listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9dbda3da-e979-5c65-8db6-757abb73dd8a','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9dbda3da-e979-5c65-8db6-757abb73dd8a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9dbda3da-e979-5c65-8db6-757abb73dd8a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f61b718b-1460-59f6-b448-f23031a3c1e5','Causal listening','A mode of listening focused on identifying the source or cause of a sound, that is, what or who produced it. Described as one of three listening modes, it is the most common everyday form of listening, used to gather information about events and objects in the environment, though it can be misled, especially when a sound''s true source is hidden.','Causal listening tries to find what made a sound. It asks ''what is that?'' or ''who is there?''. We use it constantly in daily life. It gives us news about our surroundings. Hidden sources can fool it.','It lets listeners gather information about the world by tracing sounds to their causes, the everyday basis of using hearing to stay aware.','A person uses causal listening to identify footsteps, an engine fault, or a knock at the door.','Anthropology & Sound Studies',ARRAY['Semantic listening','Reduced listening','Acousmatic sound','Listening practice','Sound source']::text[],ARRAY['Assuming the identified cause is always correct','Confusing it with understanding a sound''s meaning','Forgetting that hidden sources can mislead it']::text[],ARRAY['Identifying a strange noise in a machine','Recognising who is approaching by footsteps','Diagnosing a fault by the sound it makes']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Causal listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f61b718b-1460-59f6-b448-f23031a3c1e5','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f61b718b-1460-59f6-b448-f23031a3c1e5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f61b718b-1460-59f6-b448-f23031a3c1e5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a6e9a53-7f4e-5631-884f-ee5d32c27a55','Semantic listening','A mode of listening that interprets a sound as a coded sign carrying meaning, most clearly in understanding spoken language. Described as one of three listening modes, it relies on a shared system such as a language or signal code, so that the listener decodes the message rather than attending to the sound''s source or its raw acoustic qualities.','Semantic listening treats sound as a message. We use it to understand speech. The sound stands for meaning through a code. We decode the meaning, not the sound itself. It needs a shared language or signal system.','It enables communication by letting listeners extract coded meaning from sound, the basis of understanding speech and signals.','A listener uses semantic listening to understand spoken words, a signalled code, or a coded alarm.','Anthropology & Sound Studies',ARRAY['Causal listening','Reduced listening','Paralinguistics','Phonemic contrast','Speech perception']::text[],ARRAY['Confusing the message with the sound''s physical qualities','Assuming meaning is in the sound rather than a shared code','Overlooking tone and delivery that carry extra meaning']::text[],ARRAY['Understanding speech in conversation','Decoding an alarm or signal pattern','Following coded radio calls']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Semantic listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a6e9a53-7f4e-5631-884f-ee5d32c27a55','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a6e9a53-7f4e-5631-884f-ee5d32c27a55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a6e9a53-7f4e-5631-884f-ee5d32c27a55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa0117e8-cba3-50c1-b206-657fc87ba076','Acousmatic sound','Sound that is heard without seeing its source. The term, revived within the theory of recorded sound, describes the condition created by recording, radio, and loudspeakers, in which sounds are separated from their visible causes. Acousmatic sound invites attention to the sound itself and raises questions about how listeners infer or imagine sources they cannot see.','Acousmatic sound is sound heard with the source unseen. You hear it but cannot see what made it. Radio and speakers create this all the time. It makes you focus on the sound itself. You may guess or imagine the source.','It names the now-common situation of source-separated sound, prompting analysis of how we listen when we cannot see what makes a sound.','A sound designer or theorist considers acousmatic sound when audio reaches listeners through speakers with no visible source.','Anthropology & Sound Studies',ARRAY['Acousmatic listening','Reduced listening','Sound object','Schizophonia','Musique concrete']::text[],ARRAY['Assuming it means any recorded sound rather than source-hidden sound','Confusing the sound with a guessed source','Overlooking how film reunites sound with an image']::text[],ARRAY['Hearing a voice on radio with no speaker in view','Designing sound heard from hidden speakers','Analysing a sound whose source stays unseen']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acousmatic sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa0117e8-cba3-50c1-b206-657fc87ba076','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa0117e8-cba3-50c1-b206-657fc87ba076') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa0117e8-cba3-50c1-b206-657fc87ba076');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd21b9a41-d6de-54d3-ab82-5d701187238b','Acousmatic listening','Listening to sound whose source is not seen, and the attentive stance this encourages. Because the visible cause is absent, acousmatic listening can foster focus on the sound''s own qualities, though listeners often still try to infer sources. It is central to experiences of recorded, broadcast, and loudspeaker-based sound and to the analysis of electroacoustic music.','Acousmatic listening is listening when you cannot see the source. The hidden source shifts your attention. You may focus on the sound''s own qualities. Or you may try to guess what made it. It is common with recordings and speakers.','It describes how hiding a sound''s source changes the way we listen, encouraging attention to sound itself or to imagined causes.','It informs how composers and designers shape sound meant to be heard without a visible source.','Anthropology & Sound Studies',ARRAY['Acousmatic sound','Reduced listening','Causal listening','Sound object','Electroacoustic music']::text[],ARRAY['Assuming hidden sources always lead to pure sound-focused listening','Confusing it with simply listening with eyes closed','Ignoring the pull to imagine a source']::text[],ARRAY['Listening to electroacoustic music','Experiencing sound from concealed speakers','Analysing radio drama sound']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acousmatic listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd21b9a41-d6de-54d3-ab82-5d701187238b','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d21b9a41-d6de-54d3-ab82-5d701187238b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d21b9a41-d6de-54d3-ab82-5d701187238b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2a89045-d9b7-5517-b68a-ae2de66b793f','Sonic ritual','Ritual practice in which sound is a central and constitutive element, so that particular sounds, chants, drumming, or silences are essential to the rite''s meaning and efficacy. As an analytic focus it examines how organised sound structures ritual time and space, induces altered states, marks the sacred, and binds participants together.','A sonic ritual is a rite built around sound. Chant, drumming, or silence carry the meaning. The right sounds make the rite work. Sound shapes the time and space of the event. It can move people and mark the sacred.','It shows how organised sound gives ritual its structure and power, joining participants and marking sacred moments.','A researcher uses it when studying how drumming, chant, or bells organise a ceremony''s key moments.','Anthropology & Sound Studies',ARRAY['Ritual soundscape','Sacred sound','Ethnomusicology','Sonic environment','Trance']::text[],ARRAY['Treating ritual sound as mere decoration, not essential','Ignoring silence as part of the sonic rite','Assuming the same sounds mean the same in every culture']::text[],ARRAY['Studying drumming that drives a ceremony','Analysing chant in a religious service','Examining sound that marks a rite''s climax']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic ritual');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2a89045-d9b7-5517-b68a-ae2de66b793f','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2a89045-d9b7-5517-b68a-ae2de66b793f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2a89045-d9b7-5517-b68a-ae2de66b793f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '49a8ec5a-8ec2-5b09-9760-d07e9e7c6885','Ritual soundscape','The organised sonic environment of a ritual setting: the ensemble of sounds, including instruments, voices, bells, and ambient acoustics, that together shape a ceremony and its space. Used in anthropology and archaeoacoustics, the concept treats these sounds as a structured whole that defines sacred space, orders ritual action, and shapes participants'' experience.','A ritual soundscape is all the sound of a ceremony. It includes voices, instruments, and the room''s echo. Together these sounds shape the event. They help mark the space as sacred. They guide how the ritual feels.','It lets researchers study the whole sound world of a rite, showing how combined sounds and acoustics create sacred space and order action.','A researcher maps a ritual soundscape when studying how a site''s acoustics and sounds shape a ceremony.','Anthropology & Sound Studies',ARRAY['Sonic ritual','Sacred sound','Soundscape','Archaeoacoustics','Acoustic community']::text[],ARRAY['Ignoring the site''s acoustics as part of the soundscape','Treating individual sounds in isolation','Overlooking how sound defines sacred space']::text[],ARRAY['Studying the sounds and echo of a temple rite','Analysing how a cave''s acoustics shaped ancient ritual','Mapping the full sound world of a ceremony']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ritual soundscape');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '49a8ec5a-8ec2-5b09-9760-d07e9e7c6885','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='49a8ec5a-8ec2-5b09-9760-d07e9e7c6885') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='49a8ec5a-8ec2-5b09-9760-d07e9e7c6885');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '88a7423b-1cd9-588a-ad06-b3a6df8e2cdc','Acoustic taboo','A culturally enforced prohibition concerning sound, restricting which sounds may be made, by whom, when, or who may hear them. Such prohibitions often protect sacred or secret sounds, for example instruments or songs reserved for initiates and forbidden to others, and they show how societies regulate sound as part of managing power, gender, and the sacred.','An acoustic taboo is a rule that forbids certain sounds. It may say who can make a sound. It may say who is allowed to hear it. Sacred sounds are often protected this way. Breaking the rule can be a serious offence.','It shows how societies control sound to guard the sacred, mark social boundaries, and manage who holds sonic knowledge.','A researcher meets acoustic taboos when a community restricts recording or hearing of certain songs or instruments.','Anthropology & Sound Studies',ARRAY['Sacred sound','Sound sovereignty','Ethical listening','Sonic ritual','Secret knowledge']::text[],ARRAY['Assuming all sounds are freely recordable','Ignoring gender or initiation rules about sound','Treating such rules as mere superstition rather than social order']::text[],ARRAY['Encountering songs forbidden to outsiders','Respecting instruments only initiates may hear','Planning fieldwork around restricted sounds']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic taboo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '88a7423b-1cd9-588a-ad06-b3a6df8e2cdc','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='88a7423b-1cd9-588a-ad06-b3a6df8e2cdc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='88a7423b-1cd9-588a-ad06-b3a6df8e2cdc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bc3a3577-a7a1-5a53-9339-be1f0a1eb849','Sacred sound','Sound regarded within a religious or spiritual tradition as holy, powerful, or connected to the divine. It includes chant, sacred syllables, bells, and instruments believed to carry spiritual efficacy, and as a topic of study it examines how sound is used to create sacred experience, communicate with the divine, and mark holy time and space.','Sacred sound is sound treated as holy. Many traditions use special chants or syllables. Bells and certain instruments can be sacred too. People believe such sound holds spiritual power. It helps mark holy moments and places.','It shows how sound is used to reach the divine and create sacred experience, a core role of sound in religious life.','A researcher studies sacred sound when analysing chant, ritual bells, or holy words in worship.','Anthropology & Sound Studies',ARRAY['Sonic ritual','Ritual soundscape','Acoustic taboo','Ethnomusicology','Chant']::text[],ARRAY['Assuming sacred sound is just music for worship','Ignoring the power and rules attached to it','Treating one tradition''s ideas as universal']::text[],ARRAY['Studying chant believed to hold power','Analysing sacred syllables in prayer','Examining bells that mark holy time']::text[],'beginner',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sacred sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bc3a3577-a7a1-5a53-9339-be1f0a1eb849','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bc3a3577-a7a1-5a53-9339-be1f0a1eb849') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bc3a3577-a7a1-5a53-9339-be1f0a1eb849');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '79d180a7-4e9c-53a9-a6d8-418f43d045a8','Sonic archive','A collection of recorded sound preserved for future access, study, or cultural use, and the broader notion of sound as a store of the past. It includes institutional sound and oral-history archives as well as the theoretical idea that recordings hold traces of vanished voices and environments, raising questions of preservation, access, ownership, and interpretation.','A sonic archive is a stored collection of recorded sound. It keeps voices and sounds for the future. Libraries and projects build such archives. They hold traces of a vanished past. Questions of access and ownership arise.','It preserves recorded sound as evidence and heritage, letting later listeners study voices and environments that would otherwise be lost.','Researchers and archivists build and use sonic archives of oral history, music, and environmental recordings.','Anthropology & Sound Studies',ARRAY['Oral history','Repatriation of sound recordings','Sonic memory','Phonography','Cultural heritage']::text[],ARRAY['Assuming recordings preserve the past perfectly','Ignoring who controls access and ownership','Treating an archive as neutral rather than shaped by choices']::text[],ARRAY['Building an oral-history sound collection','Preserving endangered-language recordings','Managing access to a community''s archive']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic archive');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '79d180a7-4e9c-53a9-a6d8-418f43d045a8','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='79d180a7-4e9c-53a9-a6d8-418f43d045a8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='79d180a7-4e9c-53a9-a6d8-418f43d045a8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5dcd2bce-5272-5b24-913c-93b24f826b12','Repatriation of sound recordings','The return of recorded sound, especially early ethnographic recordings of music, speech, and ritual, to the communities from which it was collected or their descendants. As a practice in ethnomusicology and archives, it addresses histories of extractive collecting, restores access and control to source communities, and can renew cultural knowledge while raising legal and ethical questions of ownership and use.','Repatriation returns old recordings to their source communities. Many were collected long ago without fair consent. Giving them back restores access and control. It can revive lost songs and knowledge. It also raises questions of rights and use.','It corrects past extractive collecting by returning recordings to source communities, restoring their access, control, and cultural knowledge.','Archivists and ethnomusicologists carry out repatriation by returning digitised recordings to descendant communities under agreed terms.','Anthropology & Sound Studies',ARRAY['Sound sovereignty','Sonic archive','Ethical listening','Oral history','Cultural heritage']::text[],ARRAY['Assuming the collecting archive automatically owns the recordings','Treating repatriation as a simple file transfer, not a relationship','Ignoring community terms for access and use']::text[],ARRAY['Returning wax-cylinder recordings to a community','Negotiating terms for reusing repatriated songs','Reviving a tradition from returned recordings']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Repatriation of sound recordings');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5dcd2bce-5272-5b24-913c-93b24f826b12','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5dcd2bce-5272-5b24-913c-93b24f826b12') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5dcd2bce-5272-5b24-913c-93b24f826b12');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5231f80-47cf-5e08-950f-b6ced154d5de','Ethical listening','An approach to listening that attends to the responsibilities, power relations, and consent involved in hearing others, especially across cultural difference. Emerging in sound studies, oral history, and Indigenous scholarship, it asks listeners to recognise how they listen, whose terms govern the encounter, and how listening can either respect or appropriate the voices and sounds of others.','Ethical listening means listening with care and respect. It asks who has power in the encounter. It weighs consent and cultural difference. It warns against taking others'' voices unfairly. How we listen carries responsibility.','It makes listening a matter of ethics, guiding researchers and audiences to hear others without exploiting or misrepresenting them.','A researcher practises ethical listening when handling interviews and recordings on the speakers'' terms and with consent.','Anthropology & Sound Studies',ARRAY['Sound sovereignty','Repatriation of sound recordings','Acoustic taboo','Oral history','Listening practice']::text[],ARRAY['Assuming listening is neutral and free of power','Ignoring consent and the speaker''s terms','Treating others'' voices as free material to use']::text[],ARRAY['Handling sensitive interviews with consent','Respecting community terms for recordings','Reflecting on power while listening across cultures']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ethical listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5231f80-47cf-5e08-950f-b6ced154d5de','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5231f80-47cf-5e08-950f-b6ced154d5de') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5231f80-47cf-5e08-950f-b6ced154d5de');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '954643b7-ddc8-5842-8767-dbdeb4df73aa','Sonochemistry','The branch of chemistry that studies chemical effects driven by high-intensity ultrasound. Its reactivity does not arise from direct molecular absorption of sound but from acoustic cavitation: the growth and violent collapse of gas- and vapour-filled bubbles, which concentrates diffuse acoustic energy into transient, highly localized regions of extreme temperature and pressure that generate radicals, drive reactions, and modify materials.','Sonochemistry uses strong sound waves to make chemistry happen. The sound is far too weak to break bonds by itself. Instead it forms tiny bubbles in the liquid. These bubbles grow and then burst hard. The burst makes a tiny, very hot, high-pressure spot. That hot spot drives the reactions.','It exploits cavitation to create reactive conditions in an otherwise cool bulk liquid, offering a mild, tunable way to generate radicals, mix reactants, and activate surfaces without high oven temperatures.','Chemists run sonochemistry with an ultrasonic bath or a probe horn to speed reactions, make nanoparticles, degrade pollutants, and clean or activate catalyst surfaces.','Chemical & Molecular Acoustics',ARRAY['Acoustic cavitation','Bubble collapse','Hot spot theory','Sonolysis','Ultrasonic irradiation']::text[],ARRAY['Assuming the sound directly excites the molecules rather than acting through cavitation','Believing more power always means more product, ignoring cavitation and degassing limits','UNSAFE: running high-power ultrasound without hearing protection or without controlling the heat, aerosols, and pressure it can build in a vessel']::text[],ARRAY['Speeding an organic reaction that is slow under normal stirring','Generating oxidizing radicals to break down a water pollutant','Making metal or oxide nanoparticles in a lab reactor']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonochemistry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '954643b7-ddc8-5842-8767-dbdeb4df73aa','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='954643b7-ddc8-5842-8767-dbdeb4df73aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='954643b7-ddc8-5842-8767-dbdeb4df73aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '07e017ea-5ead-5072-8f2b-ef5abd43e9ca','Cavitation bubble','A gas- and vapour-filled cavity that forms, oscillates, and may collapse in a liquid subjected to an alternating acoustic pressure field. During the rarefaction phase the local pressure falls enough to nucleate or expand the bubble; during compression it contracts, and under sufficient drive it collapses nearly adiabatically, concentrating energy at its centre.','A cavitation bubble is a tiny pocket of gas and vapour in a liquid. Sound waves pull the liquid apart and the bubble grows. Then the sound pushes back and the bubble shrinks. A strong push can make it collapse fast. That collapse squeezes the trapped gas and heats it.','It is the basic energy carrier of sonochemistry: the bubble gathers weak, spread-out sound energy over its surface and focuses it inward during collapse.','Technicians picture cavitation bubbles when tuning ultrasonic cleaning, degassing, or sonochemical work, since bubble behaviour sets the cleaning and reaction rate.','Chemical & Molecular Acoustics',ARRAY['Acoustic cavitation','Cavitation nucleus','Transient cavitation','Non-inertial cavitation','Bubble collapse']::text[],ARRAY['Picturing one steady bubble instead of many that form, move, and vanish each cycle','Confusing a vapour cavitation bubble with an ordinary air bubble that just rises and pops','UNSAFE: assuming cavitation is harmless, when its collapse can pit metal surfaces and erode equipment']::text[],ARRAY['Explaining why an ultrasonic cleaner removes grime from a part','Diagnosing surface erosion on a sonicator probe tip','Setting drive level so bubbles collapse usefully rather than just drifting']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavitation bubble');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '07e017ea-5ead-5072-8f2b-ef5abd43e9ca','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='07e017ea-5ead-5072-8f2b-ef5abd43e9ca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='07e017ea-5ead-5072-8f2b-ef5abd43e9ca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '035eb121-b1b4-57ea-8181-4462cbb84aed','Transient cavitation','A violent, inertia-dominated cavitation regime in which a bubble grows over one or a few acoustic cycles to several times its equilibrium radius, then collapses catastrophically, driven by the inertia of the inrushing liquid. The near-adiabatic implosion produces the extreme local temperatures and pressures responsible for radical formation, sonoluminescence, and most sonochemical activity. It is synonymous with inertial cavitation.','Transient cavitation is the violent kind of bubble action. The bubble grows large over a cycle or two. Then the liquid rushes in and crushes it fast. This hard collapse makes the hot spots and radicals. Most real sonochemistry comes from this kind of collapse.','It distinguishes the destructive, energy-focusing bubble behaviour that powers sonochemistry from gentle stable oscillation, and it defines the threshold conditions chemists aim to exceed.','Chemists drive systems above the transient-cavitation threshold to produce radicals, erode particles, or emit light, adjusting frequency, power, and dissolved gas.','Chemical & Molecular Acoustics',ARRAY['Inertial cavitation','Non-inertial cavitation','Bubble collapse','Sonoluminescence','Cavitation threshold']::text[],ARRAY['Using ''transient'' to mean short-lived in time rather than the inertial collapse regime','Assuming every cavitation bubble collapses violently, when many only oscillate gently','UNSAFE: pushing power to force transient cavitation without managing sample heating, splashing, and vessel overpressure']::text[],ARRAY['Confirming a reactor reaches the regime that makes hydroxyl radicals','Explaining probe-tip erosion as inertial collapse damage','Choosing a low frequency to favour violent collapse over gentle oscillation']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transient cavitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '035eb121-b1b4-57ea-8181-4462cbb84aed','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='035eb121-b1b4-57ea-8181-4462cbb84aed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='035eb121-b1b4-57ea-8181-4462cbb84aed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1207ae7-383e-5f19-b639-e4c3557f765b','Non-inertial cavitation','A cavitation regime, also called stable cavitation, in which a bubble oscillates repeatedly about its equilibrium radius over many acoustic cycles without collapsing violently. Liquid inertia does not dominate, so the bubble persists and drives steady effects such as microstreaming and enhanced mass transfer rather than the extreme conditions of inertial collapse.','Non-inertial cavitation is the gentle kind of bubble action. The bubble just pulses in and out around one size. It does this for many cycles and does not burst hard. It stirs the nearby liquid and helps mixing. It rarely makes the hot spots that violent collapse does.','It describes the mild, repeatable bubble motion used when steady stirring or mass transfer is wanted without the erosion and radical chemistry of collapse.','This regime is exploited in gentle mixing, sonophoresis, and low-power cleaning where microstreaming helps but violent collapse would damage a sample.','Chemical & Molecular Acoustics',ARRAY['Stable cavitation','Transient cavitation','Microstreaming','Bubble oscillation','Acoustic cavitation']::text[],ARRAY['Treating stable cavitation as producing no effect, when it still drives useful microstreaming','Assuming the line between stable and inertial cavitation is sharp rather than condition-dependent','Confusing ''non-inertial'' with ''no motion'' when the bubble is clearly oscillating']::text[],ARRAY['Enhancing mixing near a surface without eroding it','Explaining gentle mass-transfer gains in a low-power bath','Keeping a delicate sample below the violent-collapse threshold']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Non-inertial cavitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1207ae7-383e-5f19-b639-e4c3557f765b','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1207ae7-383e-5f19-b639-e4c3557f765b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1207ae7-383e-5f19-b639-e4c3557f765b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92b213b4-f514-5ade-b04f-c920d74a8555','Cavitation nucleus','A pre-existing weak point that seeds bubble formation in a liquid, lowering the acoustic pressure needed to initiate cavitation. Nuclei are typically small stabilized gas pockets trapped in solid impurities, on container walls, or in surface crevices. Without such nuclei a pure degassed liquid can withstand very large negative pressures before cavitating.','A cavitation nucleus is a tiny seed that starts a bubble. It is usually a small trapped bit of gas. It can hide in dust, on the wall, or in a crack. These seeds make cavitation start much more easily. A very clean, gas-free liquid resists cavitation far longer.','It explains why real liquids cavitate far below their theoretical strength, and why dissolved gas and particles set the practical cavitation threshold.','Knowing about nuclei guides degassing choices and explains why filtered, degassed solvents need more power to cavitate than ordinary tap-grade liquids.','Chemical & Molecular Acoustics',ARRAY['Cavitation threshold','Crevice model','Dissolved gas','Nucleation','Cavitation bubble']::text[],ARRAY['Thinking cavitation begins in truly empty liquid rather than at gas-filled nuclei','Ignoring how removing dissolved gas raises the pressure needed to cavitate','Assuming nuclei are always free bubbles, not gas trapped in crevices and particles']::text[],ARRAY['Explaining why degassed solvent cavitates less readily','Adding particles or gas to seed cavitation on purpose','Troubleshooting weak cavitation in an over-filtered liquid']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavitation nucleus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92b213b4-f514-5ade-b04f-c920d74a8555','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92b213b4-f514-5ade-b04f-c920d74a8555') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92b213b4-f514-5ade-b04f-c920d74a8555');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9eb189f8-1208-5684-af97-e63aaa7a4e6c','Bubble collapse','The rapid, near-adiabatic implosion of a cavitation bubble during the compression phase of the acoustic cycle. As the surrounding liquid rushes inward, the trapped gas and vapour are compressed on a timescale too short for heat to escape, producing a transient core of very high temperature and pressure. The idealized inward motion of an empty cavity is described by the Rayleigh collapse time.','Bubble collapse is the fast crush of a cavitation bubble. The liquid pours in and squeezes the trapped gas. This happens too fast for the heat to leak away. So the tiny core gets very hot and very high in pressure. This crushing event drives sonochemical reactions.','It is the moment that concentrates diffuse sound energy into a small hot core, making it the source of radicals, light, and shock in sonochemistry.','Understanding collapse helps technicians link ultrasonic power and frequency to reaction yield, surface erosion, and light emission.','Chemical & Molecular Acoustics',ARRAY['Rayleigh-Plesset equation','Transient cavitation','Hot spot theory','Shockwave emission','Sonoluminescence']::text[],ARRAY['Imagining a slow squeeze instead of an implosion lasting well under a microsecond','Assuming all the sound energy heats the whole liquid rather than a tiny core','UNSAFE: treating collapse as gentle, when repeated implosions pit and erode metal parts']::text[],ARRAY['Explaining how collapse heats the bubble core enough to split water','Linking collapse violence to probe-tip wear','Modelling collapse time to estimate peak conditions']::text[],'advanced','τ_c ≈ 0.915·R_max·√(ρ_L / (p_∞ − p_v))','The Rayleigh collapse time equals about 0.915 times the maximum bubble radius, times the square root of the liquid density divided by the difference between the ambient pressure and the vapour pressure.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bubble collapse');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9eb189f8-1208-5684-af97-e63aaa7a4e6c','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9eb189f8-1208-5684-af97-e63aaa7a4e6c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9eb189f8-1208-5684-af97-e63aaa7a4e6c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd8527729-d271-5cb5-9de6-eb09b4fe255b','Hot spot theory','The prevailing explanation for sonochemical reactivity, which holds that the near-adiabatic collapse of a cavitation bubble creates a transient, microscopic hot spot within and around the bubble. Reported peak conditions reach temperatures of order several thousand kelvin and pressures of order hundreds to a thousand atmospheres, lasting under a microsecond with cooling rates exceeding a billion kelvin per second, enough to break bonds and form radicals.','Hot spot theory explains where sonochemistry gets its energy. When a bubble collapses, it makes a tiny, very hot, high-pressure spot. This spot lasts less than a millionth of a second. It cools again almost instantly. In that brief flash it can break bonds and make radicals.','It provides the accepted physical picture that ties bubble collapse to extreme local conditions, explaining radical formation and light emission without heating the bulk liquid.','Chemists cite hot spot theory to justify why a cool-to-the-touch reactor can still split water or drive high-temperature-like reactions.','Chemical & Molecular Acoustics',ARRAY['Sonochemical hot spot','Bubble collapse','Sonoluminescence','Transient cavitation','Two-site model']::text[],ARRAY['Thinking the whole liquid reaches the hot-spot temperature rather than a tiny transient region','Confusing the hot spot with a slow, steady heating of the sample','Treating quoted temperatures as exact values rather than order-of-magnitude estimates']::text[],ARRAY['Justifying radical chemistry in a room-temperature reactor','Explaining why sonoluminescence light appears during collapse','Comparing gas-phase versus interface reaction sites in a bubble']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hot spot theory');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd8527729-d271-5cb5-9de6-eb09b4fe255b','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d8527729-d271-5cb5-9de6-eb09b4fe255b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d8527729-d271-5cb5-9de6-eb09b4fe255b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5fb110cd-c1cd-5676-9ed9-421e0649e6c8','Sonochemical hot spot','The transient, spatially localized high-temperature, high-pressure zone produced by collapsing cavitation, treated as the reaction site in sonochemistry. In the widely used two-site picture it comprises a very hot gaseous core, where thermal bond cleavage forms radicals, and a cooler but still elevated interfacial liquid shell surrounding the bubble, where solutes can react.','A sonochemical hot spot is the tiny reactive spot made by a bubble collapse. It has a very hot gas core inside the bubble. It also has a thin, warm liquid layer just outside it. Bonds break in the hot core and make radicals. Nearby chemicals can react in the warm shell.','It localizes where reactions happen, letting chemists predict which molecules react in the gas core versus the surrounding liquid shell.','This concept guides solvent and additive choices, since volatile species enter the hot core while non-volatile ones react at the cooler shell.','Chemical & Molecular Acoustics',ARRAY['Hot spot theory','Two-site model','Interfacial region','Radical formation','Bubble collapse']::text[],ARRAY['Ignoring the cooler interfacial shell and assuming all chemistry occurs in the gas core','Assuming non-volatile solutes enter the hot bubble interior','Treating the hot spot as a fixed location rather than a fleeting, moving region']::text[],ARRAY['Deciding whether a volatile reactant will enter the bubble core','Explaining why a non-volatile dye degrades at the bubble interface','Choosing solvent volatility to steer reaction pathways']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonochemical hot spot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5fb110cd-c1cd-5676-9ed9-421e0649e6c8','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5fb110cd-c1cd-5676-9ed9-421e0649e6c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5fb110cd-c1cd-5676-9ed9-421e0649e6c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2b0ebd08-ebd7-51e7-abb5-9fe3ea92e78f','Microstreaming','Steady, small-scale circulatory fluid motion generated in the liquid surrounding an oscillating gas bubble. Driven by the bubble''s non-linear surface oscillations, this acoustic microstreaming produces persistent vortical flow that strongly enhances local convective mixing and mass and heat transfer near the bubble, even in the absence of violent collapse.','Microstreaming is the steady swirling of liquid around a buzzing bubble. The bubble''s pulsing pushes the nearby liquid in small loops. This gentle flow mixes and moves material near the bubble. It boosts mixing and heat transfer without any hard collapse.','It is the main way stable, non-collapsing bubbles do useful work, enhancing transport of reactants, heat, and cells near a surface or membrane.','Microstreaming underlies ultrasonic mixing, sonoporation, and mass-transfer gains in cleaning and reactions where collapse is avoided.','Chemical & Molecular Acoustics',ARRAY['Non-inertial cavitation','Acoustic streaming','Mass transfer','Sonoporation','Bubble oscillation']::text[],ARRAY['Confusing local microstreaming around a bubble with bulk acoustic streaming of the whole liquid','Assuming streaming needs violent collapse, when steady oscillation alone drives it','Overlooking its strong effect on mixing right next to surfaces']::text[],ARRAY['Boosting reactant transport near an electrode or membrane','Enhancing gentle mixing in a low-power bath','Explaining improved cell uptake during sonoporation']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microstreaming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2b0ebd08-ebd7-51e7-abb5-9fe3ea92e78f','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2b0ebd08-ebd7-51e7-abb5-9fe3ea92e78f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2b0ebd08-ebd7-51e7-abb5-9fe3ea92e78f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '798ce43b-f26f-5049-80d1-07325803a68d','Microjetting','The formation of a high-speed liquid jet during the asymmetric collapse of a cavitation bubble near a solid boundary or interface. Because the boundary breaks the spherical symmetry of collapse, the far side of the bubble involutes and drives a focused jet of liquid toward the surface at speeds of order tens to hundreds of metres per second, causing localized impact, erosion, and cleaning.','Microjetting happens when a bubble collapses next to a surface. The wall makes the collapse lopsided instead of even. One side of the bubble punches through the other. This shoots a fast, thin jet of liquid at the surface. The jet can clean, dent, or erode the surface.','It explains how cavitation cleans and erodes surfaces, directing concentrated mechanical force at a boundary rather than symmetrically into the liquid.','Microjetting is central to ultrasonic cleaning, surface activation, and the pitting seen on sonicator tips and nearby components.','Chemical & Molecular Acoustics',ARRAY['Bubble collapse','Asymmetric collapse','Shockwave emission','Cavitation erosion','Ultrasonic cleaning']::text[],ARRAY['Assuming collapse is always symmetric, ignoring the jet formed near a wall','Confusing the liquid microjet with the separate shockwave emitted on collapse','UNSAFE: underestimating jet impact, which can pit metal and damage delicate surfaces']::text[],ARRAY['Explaining how ultrasonic cleaning lifts grime from a crevice','Diagnosing pitting on parts placed near a probe tip','Activating a catalyst surface by directed jet impact']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microjetting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '798ce43b-f26f-5049-80d1-07325803a68d','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='798ce43b-f26f-5049-80d1-07325803a68d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='798ce43b-f26f-5049-80d1-07325803a68d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf824977-8d46-5020-b026-75da54d08058','Shockwave emission','The launch of a sharp pressure wave into the surrounding liquid at the final stage of a violent cavitation-bubble collapse. As the imploding cavity rebounds, it radiates a shock that propagates outward, contributing to particle fragmentation, surface erosion, interparticle collisions, and the mechanical effects of cavitation, distinct from the thermal hot spot inside the bubble.','Shockwave emission is the pressure blast sent out when a bubble collapses. As the bubble bottoms out, it bounces back hard. This sends a sharp pressure wave into the liquid. The wave can break up particles and wear surfaces. It is separate from the heat inside the bubble.','It accounts for the mechanical, outward-directed effects of collapse, complementing the internal hot spot and helping explain particle size reduction and erosion.','Shockwaves drive interparticle collisions in metal-powder processing and contribute to erosion and dispersion in sonochemical reactors.','Chemical & Molecular Acoustics',ARRAY['Bubble collapse','Microjetting','Cavitation erosion','Interparticle collision','Transient cavitation']::text[],ARRAY['Confusing the emitted shockwave with the internal hot spot of the same collapse','Assuming shock effects are negligible compared with chemical effects','Ignoring cumulative shock damage to nearby surfaces and particles']::text[],ARRAY['Explaining size reduction of metal powders under ultrasound','Attributing reactor-wall erosion to repeated shocks','Understanding interparticle collisions in slurry sonication']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shockwave emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf824977-8d46-5020-b026-75da54d08058','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf824977-8d46-5020-b026-75da54d08058') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf824977-8d46-5020-b026-75da54d08058');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b485613-4aac-5c4d-98d2-a0884f48ae71','Single-bubble sonoluminescence','The emission of short flashes of light from a single gas bubble trapped at a pressure antinode of a standing acoustic wave and driven into repeated stable, near-adiabatic collapses. Each cycle produces a picosecond-scale flash, and the phenomenon offers a clean, reproducible system for studying the extreme conditions inside a collapsing cavitation bubble.','Single-bubble sonoluminescence is light from one trapped bubble. Sound holds a single bubble in place in a liquid. Each cycle the bubble collapses and flashes light. The flash is incredibly short, only trillionths of a second. It lets scientists study one bubble very cleanly.','It isolates one bubble for precise study, making it the key laboratory system for probing the temperatures and physics of cavitation collapse.','Researchers use it to measure collapse conditions and test cavitation theory, since one steady bubble is far easier to study than a chaotic cloud.','Chemical & Molecular Acoustics',ARRAY['Sonoluminescence','Multi-bubble sonoluminescence','Standing wave','Bubble collapse','Acoustic trapping']::text[],ARRAY['Confusing single-bubble with multi-bubble sonoluminescence, which behaves differently','Assuming the light is continuous rather than a brief flash each cycle','Thinking the bubble is visible by eye rather than needing sensitive detection']::text[],ARRAY['Measuring peak conditions inside a single collapsing bubble','Testing whether models predict flash timing and brightness','Demonstrating cavitation light in a controlled lab cell']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Single-bubble sonoluminescence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b485613-4aac-5c4d-98d2-a0884f48ae71','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b485613-4aac-5c4d-98d2-a0884f48ae71') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b485613-4aac-5c4d-98d2-a0884f48ae71');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9d0353b1-d7ea-5a41-9fea-3cda9344a2e1','Multi-bubble sonoluminescence','The light emitted from a cloud of cavitating bubbles in a liquid irradiated with high-intensity ultrasound. Its spectrum typically combines a broad continuum with emission lines from excited species, such as excited-state hydroxyl radicals or metal atoms, providing a spectroscopic probe of the reactive conditions and chemistry inside collapsing bubbles.','Multi-bubble sonoluminescence is light from a whole cloud of bubbles. Strong ultrasound makes many bubbles form and collapse at once. Together they give off a faint glow. The light carries lines from excited atoms and radicals. Scientists read those lines to learn what happens inside.','It links the light output of a working reactor to the chemistry inside the bubbles, serving as a spectroscopic window on sonochemical conditions.','Chemists use its emission lines to detect radicals, gauge cavitation activity, and probe conditions in real sonochemical reactors.','Chemical & Molecular Acoustics',ARRAY['Sonoluminescence','Single-bubble sonoluminescence','Excited hydroxyl radical','Cavitation cloud','Emission spectrum']::text[],ARRAY['Assuming its spectrum matches single-bubble sonoluminescence, which it does not','Treating the glow as thermal only, ignoring the radical emission lines','Expecting bright, visible light rather than a faint emission needing dark conditions']::text[],ARRAY['Detecting hydroxyl radical emission to confirm reactive cavitation','Comparing cavitation activity between reactor designs','Estimating effective bubble conditions from emission lines']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multi-bubble sonoluminescence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9d0353b1-d7ea-5a41-9fea-3cda9344a2e1','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9d0353b1-d7ea-5a41-9fea-3cda9344a2e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9d0353b1-d7ea-5a41-9fea-3cda9344a2e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7701be07-46ab-594b-965d-de004742d37b','Sonolysis','The chemical decomposition or bond cleavage of a substance brought about by ultrasound acting through acoustic cavitation. The extreme transient conditions of bubble collapse fragment volatile molecules in the gas core and generate reactive radicals that attack solutes, driving degradation of the target compound.','Sonolysis is breaking molecules apart using ultrasound. The sound forms bubbles that collapse hard. The collapse makes tiny hot spots and radicals. These break bonds in nearby molecules. It is used to break down unwanted chemicals.','It names the destructive side of sonochemistry, providing a route to fragment or degrade target molecules without added heat or harsh reagents.','Sonolysis is applied to break down pollutants, disinfect water, and cleave polymers in solution.','Chemical & Molecular Acoustics',ARRAY['Water sonolysis','Sonochemistry','Radical formation','Bubble collapse','Pollutant degradation']::text[],ARRAY['Assuming ultrasound cleaves bonds directly rather than through cavitation','Expecting all molecules to fragment equally, ignoring the role of volatility','UNSAFE: sonolysing unknown or hazardous compounds without ventilation and heat control']::text[],ARRAY['Breaking down a persistent organic pollutant in water','Reducing polymer chain length in solution','Assisting disinfection by radical attack']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonolysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7701be07-46ab-594b-965d-de004742d37b','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7701be07-46ab-594b-965d-de004742d37b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7701be07-46ab-594b-965d-de004742d37b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9a554ee-1b30-579d-813d-d0c58e4be157','Water sonolysis','The ultrasound-driven decomposition of water molecules within collapsing cavitation bubbles. The high transient temperatures split water vapour into hydrogen atoms and hydroxyl radicals; these recombine and react to yield molecular hydrogen, hydrogen peroxide, and, in the presence of dissolved oxygen or nitrogen, further reactive species that diffuse into the surrounding liquid.','Water sonolysis is splitting water with ultrasound. Inside a collapsing bubble the water gets very hot. The heat breaks water into hydrogen atoms and hydroxyl radicals. These pieces then recombine and react. They form hydrogen gas and hydrogen peroxide.','It is the source reaction for the oxidizing radicals used in sonochemical water treatment, generating hydroxyl radicals without added chemicals.','It underlies advanced oxidation for water treatment and is measured by dosimetry that tracks hydrogen peroxide or hydroxyl-radical yield.','Chemical & Molecular Acoustics',ARRAY['Hydroxyl radical generation','Sonolysis','Hydrogen peroxide','Sonochemical radical','Advanced oxidation']::text[],ARRAY['Thinking water splits in the bulk liquid rather than inside the hot bubbles','Ignoring how dissolved gas changes which radicals and products form','Assuming yields are unaffected by frequency, temperature, and gas type']::text[],ARRAY['Producing hydroxyl radicals for pollutant oxidation','Measuring hydrogen peroxide as a dosimeter of cavitation','Studying gas effects on radical yield']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Water sonolysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9a554ee-1b30-579d-813d-d0c58e4be157','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9a554ee-1b30-579d-813d-d0c58e4be157') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9a554ee-1b30-579d-813d-d0c58e4be157');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e0aed8f8-1429-5d26-89f2-754528051e57','Sonochemical radical','A reactive free radical generated by acoustic cavitation, formed either by thermal bond cleavage of vapour inside a collapsing bubble or by radical attack at the hot bubble interface. In aqueous systems the dominant species are hydrogen atoms and hydroxyl radicals; in other solvents or gases, corresponding radicals form and can initiate oxidation, reduction, or polymerization.','A sonochemical radical is a reactive piece made by sound. A bubble bursts and its heat splits molecules. This leaves broken pieces that react fast. In water they are mostly split bits of water. They then react quickly with other things.','It identifies the reactive intermediates that carry out most sonochemical reactions, linking bubble collapse to oxidation, reduction, and initiation.','Chemists rely on these radicals to start polymerizations, degrade pollutants, and drive oxidation, and they measure them with radical traps and dosimeters.','Chemical & Molecular Acoustics',ARRAY['Hydroxyl radical generation','Water sonolysis','Radical trap','Sonolysis','Free radical']::text[],ARRAY['Assuming radicals form throughout the liquid rather than at or in the bubbles','Treating all sonochemical radicals as hydroxyl, ignoring hydrogen atoms and solvent radicals','Overlooking radical scavenging by dissolved species']::text[],ARRAY['Initiating a radical polymerization with ultrasound','Trapping radicals to confirm a sonochemical mechanism','Degrading an organic contaminant by radical attack']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonochemical radical');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e0aed8f8-1429-5d26-89f2-754528051e57','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e0aed8f8-1429-5d26-89f2-754528051e57') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e0aed8f8-1429-5d26-89f2-754528051e57');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11427d08-90b9-552f-81d0-cd410fb5d6a2','Hydroxyl radical generation','The production of hydroxyl radicals, a highly reactive and short-lived oxidizing species, by acoustic cavitation, chiefly through the sonolysis of water inside collapsing bubbles. The radicals escape to the interfacial region and bulk liquid where they oxidize solutes. Their yield is commonly quantified by chemical dosimetry such as the oxidation of iodide or terephthalate.','Hydroxyl radicals are very strong, short-lived cleaners. Sound makes them from water inside bursting bubbles. They spread out and attack chemicals in the liquid. They break down waste too tough for milder methods. Their amount is checked with simple test reactions.','It supplies the powerful oxidant behind sonochemical advanced oxidation, enabling breakdown of pollutants that resist gentler treatment.','It is central to sonochemical water treatment and is tracked by iodide or terephthalate dosimetry to gauge reactor performance.','Chemical & Molecular Acoustics',ARRAY['Water sonolysis','Advanced oxidation','Dosimetry','Sonochemical radical','Sono-Fenton process']::text[],ARRAY['Assuming hydroxyl radicals persist long enough to store or handle directly','Ignoring scavengers that consume radicals before they reach the target','Treating radical yield as fixed rather than dependent on gas, frequency, and power']::text[],ARRAY['Oxidizing a dye or pollutant in a sonoreactor','Using terephthalate dosimetry to map cavitation activity','Comparing radical yield across frequencies']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hydroxyl radical generation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11427d08-90b9-552f-81d0-cd410fb5d6a2','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11427d08-90b9-552f-81d0-cd410fb5d6a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11427d08-90b9-552f-81d0-cd410fb5d6a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45697b40-07f5-5050-81ed-2e3d34ff87dc','Sonocatalysis','The use of ultrasound to initiate, accelerate, or enhance a catalyzed reaction. Cavitation improves catalysis by cleaning and continuously renewing catalyst surfaces, fragmenting particles to increase surface area, boosting mass transfer of reactants to active sites, and, in some cases, generating reactive radicals that supplement the catalytic pathway.','Sonocatalysis uses sound to help a catalyst work better. The sound cleans and refreshes the catalyst surface. It also breaks big particles into smaller ones. It pushes reactants to the active sites faster. So the reaction runs faster and gives more product.','It improves catalyst performance without changing the catalyst itself, mainly by physical surface renewal and mass-transfer enhancement.','It is applied in heterogeneous catalysis, electrocatalysis, and pollutant degradation to raise rates and keep catalyst surfaces active.','Chemical & Molecular Acoustics',ARRAY['Sonochemistry','Heterogeneous catalysis','Mass transfer','Sonophotocatalysis','Surface activation']::text[],ARRAY['Assuming ultrasound is itself a catalyst rather than an aid to the catalyst','Crediting only radicals, overlooking surface cleaning and mass-transfer effects','Expecting benefits without matching frequency and power to the system']::text[],ARRAY['Keeping a catalyst surface clean during a reaction','Increasing catalyst surface area by breaking up particles','Boosting reactant delivery to active sites']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonocatalysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45697b40-07f5-5050-81ed-2e3d34ff87dc','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45697b40-07f5-5050-81ed-2e3d34ff87dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45697b40-07f5-5050-81ed-2e3d34ff87dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fc5b296a-9d93-5215-a376-859a6666c9cc','Sonophotocatalysis','The combined application of ultrasound and photocatalysis, in which a light-activated catalyst such as titanium dioxide is irradiated simultaneously with ultrasound. Cavitation continuously cleans and disperses the catalyst, increases its active surface, improves mass transfer, and supplies additional radicals, often producing a synergistic degradation rate greater than the sum of the two methods used alone.','Sonophotocatalysis mixes ultrasound with light-driven catalysis. A catalyst is switched on by light, often UV light. Ultrasound runs at the same time in the liquid. It cleans the catalyst, spreads it out, and adds radicals. Together they break down pollutants faster than either alone.','It couples two advanced oxidation methods so their effects reinforce each other, targeting pollutants that neither method degrades well alone.','It is used in water and wastewater treatment to degrade dyes, drugs, and other stubborn organic contaminants.','Chemical & Molecular Acoustics',ARRAY['Sonocatalysis','Photocatalysis','Advanced oxidation','Titanium dioxide','Synergy']::text[],ARRAY['Assuming the two effects simply add, missing that they can act in synergy','Ignoring that ultrasound also keeps the photocatalyst clean and dispersed','Expecting good results without matching light, catalyst, and ultrasound conditions']::text[],ARRAY['Degrading a dye with combined UV, catalyst, and ultrasound','Keeping a photocatalyst from fouling during treatment','Comparing combined versus single-method degradation rates']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonophotocatalysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fc5b296a-9d93-5215-a376-859a6666c9cc','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fc5b296a-9d93-5215-a376-859a6666c9cc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fc5b296a-9d93-5215-a376-859a6666c9cc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8dfec2eb-94bb-58c1-8e06-32bde4a2ab51','Sono-Fenton process','An advanced oxidation method that combines ultrasound with the Fenton reaction, in which ferrous iron and hydrogen peroxide generate hydroxyl radicals. Ultrasound boosts the process by producing extra hydrogen peroxide through water sonolysis, regenerating active iron species, and improving mixing and mass transfer, giving faster and more complete oxidation of organic pollutants than the Fenton reaction alone.','The sono-Fenton process adds sound to the Fenton method. In Fenton, iron and peroxide make strong cleaners. Sound makes more peroxide by splitting water. It also refreshes the iron and stirs the liquid. Together they break down waste faster.','It intensifies Fenton oxidation, raising radical supply and pollutant removal for treating contaminated water.','It is applied to degrade dyes, pharmaceuticals, and refractory organics in wastewater treatment.','Chemical & Molecular Acoustics',ARRAY['Fenton reaction','Hydroxyl radical generation','Advanced oxidation','Water sonolysis','Sonochemistry']::text[],ARRAY['Thinking ultrasound replaces the iron catalyst rather than assisting the Fenton chemistry','Ignoring the strong pH dependence inherited from the Fenton reaction','Overlooking the extra peroxide that sonolysis contributes']::text[],ARRAY['Degrading a textile dye in wastewater','Removing a pharmaceutical contaminant from water','Boosting radical yield over plain Fenton treatment']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sono-Fenton process');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8dfec2eb-94bb-58c1-8e06-32bde4a2ab51','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8dfec2eb-94bb-58c1-8e06-32bde4a2ab51') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8dfec2eb-94bb-58c1-8e06-32bde4a2ab51');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ebc5b514-a937-5441-8d3e-f56863907104','Sonoelectrochemistry','The application of ultrasound to an electrochemical system. Cavitation and acoustic streaming near the electrode thin the diffusion layer and enhance mass transfer, continuously clean and depassivate the electrode surface, degas the interface, and can alter nucleation during electrodeposition, thereby increasing current efficiency and modifying deposit morphology.','Sonoelectrochemistry runs sound in a plating cell. The sound stirs the liquid at the electrode. This brings reactants to the surface faster. It also keeps the electrode clean of bubbles. So the cell works better and makes finer coats.','It removes mass-transfer and fouling limits at electrodes, improving current efficiency and letting operators tune deposited films.','It is used in electroplating, electrosynthesis, and sensing to speed reactions and control coating structure.','Chemical & Molecular Acoustics',ARRAY['Mass transfer','Diffusion layer','Electrodeposition','Acoustic streaming','Sonocatalysis']::text[],ARRAY['Assuming ultrasound only cleans, ignoring its strong mass-transfer effect','Overlooking possible cavitation erosion of the electrode','Expecting the same benefit at every ultrasonic frequency and power']::text[],ARRAY['Speeding an electroplating process and refining the deposit','Keeping an electrode surface active during electrosynthesis','Improving detection limits at an ultrasound-assisted electrode']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonoelectrochemistry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ebc5b514-a937-5441-8d3e-f56863907104','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ebc5b514-a937-5441-8d3e-f56863907104') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ebc5b514-a937-5441-8d3e-f56863907104');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9d39d194-04be-5305-af60-857731b6a919','Sonocrystallization','The use of ultrasound to control crystallization from solution or melt. Cavitation promotes and shortens nucleation, narrows the metastable zone, and enables reproducible primary and secondary nucleation, giving smaller, more uniform crystals with tighter size distribution and improved batch-to-batch consistency compared with unsonicated crystallization.','Sonocrystallization uses ultrasound to control how crystals form. Cavitation helps crystals start sooner and more evenly. It makes many small seeds instead of a few large ones. This gives smaller crystals of a similar size. It also makes batches more consistent.','It gives fine, reproducible control over crystal nucleation and size, which is hard to achieve by cooling or stirring alone.','It is applied in pharmaceutical and fine-chemical manufacture to set particle size, polymorph, and purity of crystalline products.','Chemical & Molecular Acoustics',ARRAY['Nucleation','Metastable zone','Sonoprecipitation','Crystal size distribution','Sonochemistry']::text[],ARRAY['Assuming ultrasound grows large crystals, when it usually makes smaller, more uniform ones','Ignoring its effect on which polymorph forms','Expecting control without tuning timing, power, and temperature']::text[],ARRAY['Setting drug particle size for a formulation','Shortening the induction time before crystals appear','Improving batch-to-batch consistency of a crystalline product']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonocrystallization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9d39d194-04be-5305-af60-857731b6a919','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9d39d194-04be-5305-af60-857731b6a919') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9d39d194-04be-5305-af60-857731b6a919');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9f7305f4-0d32-5760-994c-c59ac561b31d','Sonoprecipitation','A precipitation method carried out under ultrasound, in which cavitation-driven mixing and nucleation control produce fine, uniformly sized particles. Rapid, homogeneous nucleation and efficient dispersion limit particle growth and agglomeration, making it a common route to nanoparticles and finely divided powders with narrow size distributions.','Sonoprecipitation makes solid particles form under ultrasound. Two solutions react and a solid drops out. Ultrasound mixes them fast and evenly. This makes many tiny particles at once. The particles stay small and similar in size.','It controls particle size and uniformity during precipitation, giving a simple route to nanoparticles that resist clumping.','It is used to synthesize oxide and metal nanoparticles and fine powders for catalysis, coatings, and materials research.','Chemical & Molecular Acoustics',ARRAY['Sonocrystallization','Nucleation','Nanoparticle synthesis','Ultrasonic dispersion','Sonochemical synthesis']::text[],ARRAY['Confusing sonoprecipitation with sonocrystallization of an ordered lattice','Assuming particles never agglomerate afterward without a stabilizer','Expecting uniform size without controlling addition rate and power']::text[],ARRAY['Making oxide nanoparticles with a narrow size range','Preventing clumping during particle formation','Producing fine powder for a catalyst support']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonoprecipitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9f7305f4-0d32-5760-994c-c59ac561b31d','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9f7305f4-0d32-5760-994c-c59ac561b31d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9f7305f4-0d32-5760-994c-c59ac561b31d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17b1f8ee-efd5-5c1d-96c4-09cedf9d18b6','Sonochemical synthesis','The preparation of chemical compounds and materials using ultrasound, exploiting cavitation to drive reactions, control particle formation, and create unusual products. A classic example is the ultrasonic decomposition of volatile metal carbonyls to form high-surface-area amorphous or nanostructured metals, illustrating how the extreme, rapidly quenched conditions of collapse yield materials hard to make by conventional heating.','Sonochemical synthesis makes compounds and materials with ultrasound. Cavitation drives the reaction and shapes the product. The hot spots form and then cool almost instantly. This fast quench can lock in unusual, disordered materials. It is a known way to make nanostructured metals.','It offers a route to nanostructured and amorphous materials by using the extreme, rapidly cooled conditions of cavitation collapse.','It is used to make metal, alloy, and oxide nanomaterials, high-surface-area catalysts, and composites in the lab.','Chemical & Molecular Acoustics',ARRAY['Sonochemistry','Sonoprecipitation','Nanoparticle synthesis','Amorphous metal','Hot spot theory']::text[],ARRAY['Assuming products match those from ordinary heating rather than rapid-quench conditions','Ignoring how dissolved gas and solvent volatility shape the product','UNSAFE: sonicating volatile or toxic precursors without proper ventilation and containment']::text[],ARRAY['Preparing amorphous or nanostructured metal particles','Making a high-surface-area catalyst','Synthesizing oxide nanomaterials in solution']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonochemical synthesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17b1f8ee-efd5-5c1d-96c4-09cedf9d18b6','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17b1f8ee-efd5-5c1d-96c4-09cedf9d18b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17b1f8ee-efd5-5c1d-96c4-09cedf9d18b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f2da5be9-6b8e-53b9-9ffa-87d6c1bf94fa','Ultrasonic irradiation','The exposure of a liquid, suspension, or reaction mixture to ultrasound, typically above about twenty kilohertz, to induce physical and chemical effects through acoustic cavitation. It is the general operational term for applying ultrasound in a bath or with a probe, encompassing mixing, dispersion, degassing, cleaning, and sonochemical reaction.','Ultrasonic irradiation means putting ultrasound into a sample. Ultrasound is sound too high for us to hear. It is applied with a bath or a probe. It forms bubbles that mix, clean, or react. It is the general name for treating a sample with ultrasound.','It names the basic act of applying ultrasound, covering the many physical and chemical uses that cavitation makes possible.','Technicians describe bath or probe treatment of a sample as ultrasonic irradiation across cleaning, dispersion, degassing, and reaction work.','Chemical & Molecular Acoustics',ARRAY['Sonication','Ultrasonic bath','Probe sonication','Acoustic cavitation','Sonochemistry']::text[],ARRAY['Assuming irradiation means ionizing radiation rather than sound exposure','Thinking any exposure level gives the same effect regardless of power and time','UNSAFE: applying high-power ultrasound without hearing protection or heat and aerosol control']::text[],ARRAY['Describing sample treatment in a method write-up','Selecting bath versus probe for a given task','Setting exposure time for dispersion or reaction']::text[],'beginner',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic irradiation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f2da5be9-6b8e-53b9-9ffa-87d6c1bf94fa','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f2da5be9-6b8e-53b9-9ffa-87d6c1bf94fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f2da5be9-6b8e-53b9-9ffa-87d6c1bf94fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f63d68b-01be-5932-8cc7-4c7bba1d126c','Ultrasonic bath','A tank of liquid fitted with piezoelectric transducers bonded to its base or walls that set up an acoustic field and cavitation throughout the bath. It delivers relatively low, distributed ultrasonic intensity and is widely used for cleaning, degassing, dispersion, and gentle sonochemistry, with samples treated directly in the bath or indirectly in a vessel immersed in it.','An ultrasonic bath is a tank of liquid that makes cavitation. Transducers under the tank send sound into the liquid. This forms bubbles all through the bath. The power is fairly low and spread out. It is used to clean parts and to treat samples.','It provides a simple, gentle, whole-vessel way to apply ultrasound, spreading modest energy through the liquid rather than focusing it.','Labs use ultrasonic baths to clean glassware and parts, degas solvents, disperse samples, and run mild sonochemistry.','Chemical & Molecular Acoustics',ARRAY['Bath sonication','Probe sonication','Ultrasonic cleaning','Cavitation','Transducer']::text[],ARRAY['Assuming a bath gives the same intense cavitation as a probe','Ignoring hot and cold spots from the standing-wave pattern in the tank','UNSAFE: overheating flammable solvents or running the bath with too little liquid']::text[],ARRAY['Cleaning laboratory glassware and small parts','Degassing a solvent before use','Dispersing a sample gently before analysis']::text[],'beginner',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic bath');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f63d68b-01be-5932-8cc7-4c7bba1d126c','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f63d68b-01be-5932-8cc7-4c7bba1d126c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f63d68b-01be-5932-8cc7-4c7bba1d126c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '282a004a-f90c-5026-af7a-9c4729a25dda','Probe sonication','The direct delivery of high-intensity ultrasound into a sample using a metal horn, or probe, whose tip vibrates in the liquid. The horn concentrates transducer energy at the tip, producing intense localized cavitation for efficient cell disruption, dispersion, emulsification, and sonochemistry, but also strong local heating, tip erosion, and aerosol generation.','Probe sonication puts a vibrating metal tip into the sample. The tip drives strong ultrasound right into the liquid. This makes intense cavitation near the tip. It is powerful for breaking cells or mixing hard samples. It also heats the sample and can spray droplets.','It focuses ultrasonic energy at a probe tip for the most intense, direct cavitation, used when a bath is too weak for the task.','It is used to lyse cells, homogenize tissue, disperse nanoparticles, and run demanding sonochemistry, usually with cooling.','Chemical & Molecular Acoustics',ARRAY['Bath sonication','Ultrasonic horn','Cell disruption','Ultrasonic dispersion','Cavitation']::text[],ARRAY['Assuming a probe never contaminates the sample, when tip erosion sheds metal particles','Overheating a sample by omitting an ice bath or pulsed operation','UNSAFE: running a probe without hearing protection, or aerosolizing pathogens without containment']::text[],ARRAY['Breaking open cells to release proteins','Dispersing nanoparticles that a bath cannot separate','Homogenizing a tough tissue sample with ice cooling']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Probe sonication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '282a004a-f90c-5026-af7a-9c4729a25dda','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='282a004a-f90c-5026-af7a-9c4729a25dda') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='282a004a-f90c-5026-af7a-9c4729a25dda');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0040724d-ca2d-5e7f-a5e5-cb22b153042e','Bath sonication','The treatment of a sample using an ultrasonic bath rather than an immersed probe. Because the acoustic energy is distributed through the bath liquid and coupled indirectly into the sample vessel, cavitation is gentler and more uniform than probe sonication, giving milder dispersion, mixing, and degassing with less heating, contamination, and sample loss.','Bath sonication treats a sample using an ultrasonic bath. The sample sits in a tube inside the bath water. The sound reaches it through the water. This is gentler and more even than a probe. It causes less heating and adds no metal from a tip.','It offers a gentle, low-contamination way to sonicate samples, trading intensity for uniformity and cleanliness.','It is used for mild dispersion, degassing, and mixing of samples where a probe would be too harsh or add contamination.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic bath','Probe sonication','Sonication','Ultrasonic dispersion','Degassing by sonication']::text[],ARRAY['Expecting bath sonication to match a probe''s intensity','Ignoring that vessel position in the bath strongly affects the result','Assuming no heating occurs, when the bath water still warms over time']::text[],ARRAY['Gently dispersing a sample before measurement','Degassing a small solvent volume','Mixing samples without probe contamination']::text[],'beginner',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bath sonication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0040724d-ca2d-5e7f-a5e5-cb22b153042e','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0040724d-ca2d-5e7f-a5e5-cb22b153042e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0040724d-ca2d-5e7f-a5e5-cb22b153042e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3adf9de9-2cfe-5916-8851-4d5366acfcda','Sonication','The application of ultrasound to a liquid sample to produce mechanical and chemical effects through cavitation, including mixing, dispersion, particle-size reduction, degassing, emulsification, and cell disruption. It is a general term covering both bath and probe methods and is a routine sample-preparation step across chemistry and biology.','Sonication means treating a sample with ultrasound. The sound makes tiny bubbles that form and collapse. This mixes, disperses, or breaks up the sample. It can also remove gas or open cells. It is a common step in preparing samples.','It is the standard operation for using ultrasound in sample preparation, gathering many physical and chemical tasks under one term.','Chemists and biologists sonicate to dissolve, disperse, degas, emulsify, and lyse samples before analysis or reaction.','Chemical & Molecular Acoustics',ARRAY['Bath sonication','Probe sonication','Ultrasonic dispersion','Cell disruption','Cavitation']::text[],ARRAY['Using ''sonication'' loosely without stating bath or probe, power, and time','Assuming longer sonication is always better, ignoring heating and degradation','UNSAFE: sonicating volatile or biohazardous samples without heat control or containment']::text[],ARRAY['Dispersing a powder into a solvent','Degassing a sample before measurement','Breaking cells to extract their contents']::text[],'beginner',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3adf9de9-2cfe-5916-8851-4d5366acfcda','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3adf9de9-2cfe-5916-8851-4d5366acfcda') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3adf9de9-2cfe-5916-8851-4d5366acfcda');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3d32bf8f-5171-5edf-8df8-fdf86d4de7d9','Degassing by sonication','The removal of dissolved gas from a liquid using ultrasound. Acoustic cavitation and bubble oscillation cause dissolved gas to come out of solution and coalesce into larger bubbles that rise and escape, lowering dissolved-gas content. It is a fast, chemical-free way to prepare degassed solvents and mobile phases.','Degassing by sonication removes dissolved gas from a liquid. Ultrasound pulls the gas out of solution. Small bubbles join into larger ones. These larger bubbles rise and leave the liquid. This gives a liquid with less dissolved gas.','It provides a quick, reagent-free method to lower dissolved gas, which otherwise causes bubbles, noise, and errors in sensitive systems.','It is used to degas HPLC mobile phases, solvents, and samples before chromatography, electrochemistry, or precise measurements.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic degassing','Sonication','Dissolved gas','Cavitation','Mobile phase preparation']::text[],ARRAY['Thinking sonication adds gas, when brief treatment mainly drives it out','Over-sonicating and warming the liquid instead of just degassing it','Assuming degassing lasts indefinitely, when gas slowly redissolves from air']::text[],ARRAY['Degassing an HPLC mobile phase','Removing air from a solvent before electrochemistry','Preparing a bubble-free sample for measurement']::text[],'beginner',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Degassing by sonication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3d32bf8f-5171-5edf-8df8-fdf86d4de7d9','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3d32bf8f-5171-5edf-8df8-fdf86d4de7d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3d32bf8f-5171-5edf-8df8-fdf86d4de7d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8228ff8c-7d2f-5c99-b33f-db6617cc63fa','Ultrasonic degassing','The use of ultrasound to remove dissolved and entrained gas from liquids and melts. Cavitation nucleates and grows bubbles that sweep out dissolved gas as they coalesce and rise. Beyond laboratory solvent preparation, it is applied in metallurgy to remove hydrogen and other gases from molten metals, reducing porosity in the solidified product.','Ultrasonic degassing uses ultrasound to remove gas from liquids. Cavitation grows bubbles that gather the dissolved gas. The bubbles rise and carry the gas away. In the lab it prepares gas-free solvents. In metal casting it removes gas from molten metal.','It removes trapped and dissolved gas that would otherwise cause bubbles, porosity, or measurement errors in liquids and castings.','It is used to degas solvents and to remove hydrogen from molten aluminium and other melts before casting.','Chemical & Molecular Acoustics',ARRAY['Degassing by sonication','Dissolved gas','Cavitation','Melt degassing','Porosity']::text[],ARRAY['Assuming the same conditions work for solvents and for high-temperature melts','Ignoring that gas slowly re-enters a liquid left open to air','Overlooking cavitation erosion of tools used in hot metal melts']::text[],ARRAY['Degassing a solvent for sensitive measurements','Removing hydrogen from molten aluminium before casting','Reducing porosity in a cast part']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic degassing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8228ff8c-7d2f-5c99-b33f-db6617cc63fa','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8228ff8c-7d2f-5c99-b33f-db6617cc63fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8228ff8c-7d2f-5c99-b33f-db6617cc63fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2327842c-5a45-501a-96f0-3d68d659d579','Acoustic emulsification','The formation of an emulsion of two immiscible liquids using ultrasound. Cavitation and intense local shear near collapsing bubbles break the dispersed phase into very fine droplets, producing emulsions with small droplet size and narrow distribution, often as fine nanoemulsions, frequently with less surfactant than mechanical methods require.','Acoustic emulsification makes an emulsion using ultrasound. Two liquids that do not mix are combined. Cavitation tears one liquid into tiny droplets in the other. The droplets are very small and similar in size. This can need less surfactant than stirring.','It provides an efficient route to fine, stable emulsions and nanoemulsions, using cavitation shear instead of high-speed mechanical mixing.','It is used to make nanoemulsions for foods, cosmetics, drug delivery, and coatings.','Chemical & Molecular Acoustics',ARRAY['Sonoemulsification','Nanoemulsion','Cavitation','Droplet size','Surfactant']::text[],ARRAY['Assuming an emulsion is stable forever without a suitable surfactant','Over-processing, which can warm the sample and coarsen droplets','Expecting the same result regardless of the two liquids'' properties']::text[],ARRAY['Producing a nanoemulsion for a drug formulation','Making a fine oil-in-water emulsion for a food product','Reducing surfactant use compared with mechanical mixing']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic emulsification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2327842c-5a45-501a-96f0-3d68d659d579','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2327842c-5a45-501a-96f0-3d68d659d579') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2327842c-5a45-501a-96f0-3d68d659d579');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c82ae43a-b809-5076-858e-f8fde8ab0dc0','Sonoemulsification','A synonym for acoustic emulsification, denoting the ultrasound-driven production of emulsions and nanoemulsions. Cavitation-generated shear disrupts the dispersed phase into fine droplets; the term is common in materials and formulation contexts where ultrasound is used to prepare small-droplet emulsions with narrow size distributions.','Sonoemulsification is another word for using sound to make emulsions. Sound breaks one liquid into fine drops in another. The drops end up small and even in size. It often makes very tiny drops. The word is common in mixing work.','It labels the ultrasonic route to fine emulsions in formulation and materials work, emphasizing the small droplet sizes achievable.','It is applied to prepare nanoemulsions and fine dispersions for pharmaceuticals, cosmetics, and material precursors.','Chemical & Molecular Acoustics',ARRAY['Acoustic emulsification','Nanoemulsion','Cavitation','Ultrasonic dispersion','Droplet size']::text[],ARRAY['Treating it as different from acoustic emulsification, when the terms overlap','Assuming stability without an appropriate stabilizer','Ignoring heating during extended ultrasonic processing']::text[],ARRAY['Making a nanoemulsion precursor for a material','Formulating a fine cosmetic emulsion','Preparing a small-droplet drug-delivery emulsion']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonoemulsification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c82ae43a-b809-5076-858e-f8fde8ab0dc0','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c82ae43a-b809-5076-858e-f8fde8ab0dc0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c82ae43a-b809-5076-858e-f8fde8ab0dc0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8fdaac3c-725d-59ec-9855-80cc21a08c9f','Ultrasonic dispersion','The use of ultrasound to break up and distribute solid particles, aggregates, or agglomerates uniformly throughout a liquid. Cavitation-driven shear and shockwaves separate clustered particles and disperse them, and it is a standard step in preparing stable suspensions and nanoparticle dispersions for processing and analysis.','Ultrasonic dispersion spreads solid particles evenly in a liquid. Particles often stick together in clumps. Cavitation and shock break the clumps apart. This spreads the particles through the liquid. It gives a more uniform, stable suspension.','It produces uniform, stable suspensions by separating clustered particles, which is essential for reproducible processing and measurement.','It is used to disperse pigments, fillers, and nanoparticles for coatings, composites, and particle-size analysis.','Chemical & Molecular Acoustics',ARRAY['Deagglomeration by ultrasound','Sonication','Suspension','Nanoparticle','Cavitation']::text[],ARRAY['Confusing dispersing particles with dissolving them','Assuming a dispersion stays stable without a stabilizer or surfactant','Over-sonicating, which can damage particles or warm the sample']::text[],ARRAY['Dispersing nanoparticles before size analysis','Mixing a pigment evenly into a coating','Preparing a stable filler suspension for a composite']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic dispersion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8fdaac3c-725d-59ec-9855-80cc21a08c9f','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8fdaac3c-725d-59ec-9855-80cc21a08c9f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8fdaac3c-725d-59ec-9855-80cc21a08c9f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ecd3794b-eed5-5248-9c0d-1542483726bb','Deagglomeration by ultrasound','The ultrasonic breakup of loosely bound particle agglomerates into their smaller primary particles or aggregates. Cavitation-induced shear, microjets, and shockwaves overcome the weak attractive forces holding agglomerates together, and it is widely used to restore fine particle size in nanopowders that clump during handling and storage.','Deagglomeration by ultrasound breaks up clumps of particles. Fine powders often stick into loose clumps. Cavitation shear and shocks pull the clumps apart. This frees the smaller original particles. The powder then disperses much better.','It restores fine particle size by separating weakly bound clumps, which is key to using nanopowders effectively.','It is used to deagglomerate nanopowders and pigments before dispersion, formulation, or particle-size measurement.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic dispersion','Agglomerate','Primary particle','Nanopowder','Cavitation']::text[],ARRAY['Confusing deagglomeration of loose clumps with breaking strongly bonded aggregates','Assuming particles never re-clump after treatment','Using excessive energy that damages the primary particles']::text[],ARRAY['Breaking up clumped nanopowder before dispersion','Restoring fine pigment size for a coating','Preparing a deagglomerated sample for size analysis']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Deagglomeration by ultrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ecd3794b-eed5-5248-9c0d-1542483726bb','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ecd3794b-eed5-5248-9c0d-1542483726bb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ecd3794b-eed5-5248-9c0d-1542483726bb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4fb3f38f-2be9-5b4d-80d0-9b6db15c16bf','Acoustic droplet vaporization','A process in which a short, high-intensity acoustic pulse vaporizes a superheated liquid droplet, typically a perfluorocarbon nanodroplet, converting it into a gas microbubble. Widely studied for biomedical use, it enables acoustically triggered, on-demand generation of microbubbles from injectable droplets for imaging, drug delivery, and therapy.','Acoustic droplet vaporization turns a liquid droplet into a bubble with sound. The droplet holds a liquid that is ready to boil. A strong sound pulse tips it over. The droplet then flashes into a gas bubble. This lets sound switch on bubbles on demand.','It gives acoustic, on-demand control over where and when microbubbles appear, which is valuable for targeted imaging and therapy.','It is studied for ultrasound imaging contrast, targeted drug delivery, and vessel occlusion using injectable nanodroplets.','Chemical & Molecular Acoustics',ARRAY['Microbubble','Superheated droplet','Perfluorocarbon','Cavitation nucleus','Ultrasound contrast agent']::text[],ARRAY['Confusing droplet vaporization with ordinary cavitation of an existing bubble','Assuming any acoustic level triggers it, ignoring the vaporization threshold','Overlooking that the resulting bubble can itself cavitate']::text[],ARRAY['Generating microbubbles inside tissue on command','Delivering a drug payload triggered by ultrasound','Creating localized contrast for imaging']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic droplet vaporization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4fb3f38f-2be9-5b4d-80d0-9b6db15c16bf','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4fb3f38f-2be9-5b4d-80d0-9b6db15c16bf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4fb3f38f-2be9-5b4d-80d0-9b6db15c16bf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '340476ed-dea1-513d-9b7b-4de985026c91','Acoustophoresis','The migration of suspended particles or cells under the acoustic radiation force of an ultrasonic field, usually a standing wave. Particles move toward pressure nodes or antinodes depending on their size, density, and compressibility relative to the medium, enabling label-free, contactless manipulation, focusing, and separation in microfluidic devices.','Acoustophoresis moves particles using sound pressure. A sound field pushes on tiny particles in a liquid. The push gathers them at set points in the wave. Where they go depends on size and density. It sorts particles without touching or tagging them.','It enables gentle, label-free sorting and focusing of cells and particles by their physical properties, using only an acoustic field.','It is used in microfluidic chips to separate cells, concentrate particles, and purify samples for analysis.','Chemical & Molecular Acoustics',ARRAY['Acoustic radiation force','Acoustic standing-wave separation','Standing wave','Microfluidics','Cell sorting']::text[],ARRAY['Confusing acoustophoresis, which uses sound, with electrophoresis, which uses electric fields','Assuming all particles collect at nodes, ignoring the role of their properties','Expecting sharp separation without matching frequency to the channel size']::text[],ARRAY['Sorting cell types on a microfluidic chip','Concentrating particles from a dilute sample','Separating particles by size and density']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustophoresis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '340476ed-dea1-513d-9b7b-4de985026c91','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='340476ed-dea1-513d-9b7b-4de985026c91') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='340476ed-dea1-513d-9b7b-4de985026c91');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ab96bf4-bc34-5733-8848-86ae0835d49b','Acoustic standing-wave separation','A separation technique that uses an ultrasonic standing wave to sort or concentrate suspended particles and cells. The radiation force drives particles toward pressure nodes or antinodes according to their acoustic contrast, so components of differing size, density, or compressibility collect at different positions and can be collected separately in a flow channel.','Acoustic standing-wave separation sorts particles with a fixed sound pattern. A standing wave has steady high and low pressure zones. The wave pushes particles toward set positions. Different particles gather in different places. They can then be collected apart.','It provides contactless, continuous separation of suspended matter using the fixed pressure pattern of a standing wave.','It is used to separate cells, clarify suspensions, and concentrate particles in flow-through acoustofluidic systems.','Chemical & Molecular Acoustics',ARRAY['Acoustophoresis','Standing wave','Acoustic radiation force','Pressure node','Acoustic contrast factor']::text[],ARRAY['Assuming every particle collects at a node regardless of its properties','Confusing the fixed standing-wave method with travelling-wave manipulation','Expecting clean separation without tuning frequency to the chamber']::text[],ARRAY['Separating red blood cells from plasma in a chip','Concentrating particles from a flowing sample','Clarifying a suspension by collecting particles at nodes']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic standing-wave separation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ab96bf4-bc34-5733-8848-86ae0835d49b','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ab96bf4-bc34-5733-8848-86ae0835d49b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ab96bf4-bc34-5733-8848-86ae0835d49b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9267c850-f076-57ba-950f-a090958ad97f','SAW sensor','A surface acoustic wave sensor, in which a piezoelectric substrate with interdigitated electrodes launches an acoustic wave that travels along the surface. Mass loading or property changes in a coating on the propagation path shift the wave''s velocity and frequency, and measuring that shift transduces binding of a target analyte into an electrical signal for gas and biosensing.','A SAW sensor detects chemicals using a wave on a surface. A special crystal sends a sound wave along its top. A coating on the path grabs the target molecules. Added mass slows the wave and shifts its frequency. The sensor reads that shift as a signal.','It converts tiny mass or property changes at a surface into a measurable frequency shift, giving sensitive, real-time chemical detection.','SAW sensors are used for gas detection, vapour sensing, and biosensing, often in compact wireless devices.','Chemical & Molecular Acoustics',ARRAY['Acoustic wave sensor','Interdigitated transducer','Quartz crystal microbalance','Piezoelectric substrate','Gas sensor']::text[],ARRAY['Confusing a surface-wave SAW device with a bulk-wave QCM','Assuming response comes only from mass, ignoring coating stiffness and conductivity','Expecting selectivity without a suitable sensing coating']::text[],ARRAY['Detecting a target gas at low concentration','Sensing vapours in a compact wireless tag','Building a coated biosensor for a specific molecule']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SAW sensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9267c850-f076-57ba-950f-a090958ad97f','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9267c850-f076-57ba-950f-a090958ad97f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9267c850-f076-57ba-950f-a090958ad97f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '58f27ced-bded-5a95-a0d2-960073864627','Quartz crystal microbalance','A mass-sensing instrument based on an AT-cut quartz crystal driven at its resonant frequency by the piezoelectric effect. Mass deposited on the electrode lowers the resonant frequency; for thin, rigid, uniform films the shift is proportional to the added mass per unit area through the Sauerbrey relation, enabling nanogram-scale measurement of adsorption and film growth.','A quartz crystal microbalance weighs tiny amounts of material. A quartz crystal vibrates at a set frequency. Adding mass to its surface slows that frequency. The frequency drop tells you the mass added. It can sense down to nanograms.','It gives a real-time, extremely sensitive readout of mass change at a surface, tracking adsorption, deposition, and film growth.','It is used to monitor thin-film deposition thickness, study adsorption, and build gravimetric chemical and biosensors.','Chemical & Molecular Acoustics',ARRAY['Sauerbrey equation','QCM-D','Piezoelectric effect','Thin-film thickness monitor','Acoustic wave sensor']::text[],ARRAY['Applying the Sauerbrey relation to soft or thick films where it fails','Ignoring liquid loading and viscosity effects when operating in liquids','Assuming frequency shift always equals rigid added mass']::text[],ARRAY['Monitoring evaporation thickness in a vacuum coater','Measuring adsorption of molecules onto a surface','Building a gravimetric biosensor']::text[],'advanced','Δf = −(2 f_0² / (A·√(ρ_q·μ_q)))·Δm','The frequency shift equals minus two times the fundamental frequency squared, divided by the electrode area times the square root of the product of quartz density and quartz shear modulus, all multiplied by the added mass.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quartz crystal microbalance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '58f27ced-bded-5a95-a0d2-960073864627','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='58f27ced-bded-5a95-a0d2-960073864627') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='58f27ced-bded-5a95-a0d2-960073864627');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '51c5b77f-6a76-54b0-aba8-e734eb9d9000','QCM-D','A quartz crystal microbalance with dissipation monitoring, which measures both the resonant frequency shift and the energy dissipation, or damping, of the oscillating crystal. The frequency reports added mass while dissipation reports the film''s viscoelastic character, so soft, hydrated, or structured layers can be characterized where the simple rigid-film assumption breaks down.','QCM-D is a quartz microbalance that also measures damping. It tracks the frequency shift from added mass. At the same time it measures how fast the vibration dies away. That damping shows whether a film is soft or stiff. So it handles soft, watery layers that a plain QCM cannot.','It adds a viscoelastic readout to mass sensing, letting scientists study soft, hydrated films that violate the rigid-film assumption.','It is used to study protein adsorption, polymer and lipid layers, and hydrated biological films in real time.','Chemical & Molecular Acoustics',ARRAY['Quartz crystal microbalance','Dissipation','Viscoelasticity','Sauerbrey equation','Thin-film characterization']::text[],ARRAY['Using only the frequency and treating a soft film as rigid','Ignoring trapped water that adds to the measured mass','Assuming dissipation is noise rather than useful viscoelastic data']::text[],ARRAY['Studying protein layers forming on a surface','Characterizing a soft polymer or lipid film','Distinguishing a rigid film from a soft, hydrated one']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='QCM-D');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '51c5b77f-6a76-54b0-aba8-e734eb9d9000','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='51c5b77f-6a76-54b0-aba8-e734eb9d9000') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='51c5b77f-6a76-54b0-aba8-e734eb9d9000');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8c2b0f63-789a-5b65-841c-f6384e6a1093','Acoustic wave sensor','A class of sensors that transduce a chemical or physical change into a shift in the properties of an acoustic wave in a piezoelectric device. Adsorbed mass or changes in stiffness, density, or viscosity alter the wave''s velocity, frequency, or amplitude. The family includes bulk-wave devices such as the quartz crystal microbalance and surface-wave devices such as SAW sensors.','An acoustic wave sensor detects change through a sound wave in a crystal. The crystal carries a wave at a set speed. Added mass or a property change alters that wave. The sensor reads the shift in frequency or speed. QCM and SAW devices are common types.','It provides a general, label-free sensing principle in which acoustic properties report tiny surface or medium changes.','These sensors are used for gas and vapour detection, biosensing, and monitoring film growth and liquid properties.','Chemical & Molecular Acoustics',ARRAY['Quartz crystal microbalance','SAW sensor','Piezoelectric effect','Bulk acoustic wave','Surface acoustic wave']::text[],ARRAY['Treating all acoustic wave sensors as the same rather than distinct bulk and surface types','Assuming response depends on mass alone, ignoring stiffness and viscosity','Expecting selectivity without a suitable sensing layer']::text[],ARRAY['Choosing between a QCM and a SAW device for a task','Detecting a vapour with a coated resonator','Monitoring a liquid''s property change in real time']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic wave sensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8c2b0f63-789a-5b65-841c-f6384e6a1093','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8c2b0f63-789a-5b65-841c-f6384e6a1093') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8c2b0f63-789a-5b65-841c-f6384e6a1093');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b9779721-d630-583c-a419-60ab80ef5c5b','Photoacoustic signal','The acoustic pressure wave produced when a sample absorbs pulsed or intensity-modulated light and converts the absorbed energy into heat, causing rapid thermal expansion. The resulting pressure transient, detected by a microphone or piezoelectric sensor, has an amplitude that scales with the sample''s optical absorption, making it the basis of photoacoustic spectroscopy and imaging.','A photoacoustic signal is sound made by absorbed light. Light hits a sample and is soaked up. The absorbed light heats the spot very quickly. The fast heating makes it expand and send out a pressure wave. A microphone or sensor picks up that sound.','It turns optical absorption directly into a sound wave, giving a sensitive, background-free way to measure how strongly a sample absorbs light.','It underlies photoacoustic spectroscopy for trace-gas detection and photoacoustic imaging of tissue and materials.','Chemical & Molecular Acoustics',ARRAY['Photoacoustic spectroscopy','Photothermal acoustic detection','Optical absorption','Thermal expansion','Piezoelectric detector']::text[],ARRAY['Assuming the signal comes from light scattering rather than absorption and heating','Ignoring that only absorbed light, not transmitted light, produces sound','Overlooking how modulation frequency shapes the signal']::text[],ARRAY['Detecting a trace gas by its light absorption','Imaging blood vessels by their optical absorption','Measuring absorption in an opaque or scattering sample']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photoacoustic signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b9779721-d630-583c-a419-60ab80ef5c5b','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b9779721-d630-583c-a419-60ab80ef5c5b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b9779721-d630-583c-a419-60ab80ef5c5b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c12d1b32-1337-542b-bb47-ccc64150410f','Photothermal acoustic detection','A detection method in which light absorbed by a sample is converted to heat and then to an acoustic wave through thermal expansion, and the sound is measured to quantify absorption. Because it responds only to absorbed light and can use resonant acoustic detection, it achieves very low detection limits, making it well suited to trace-gas and weak-absorption measurements.','Photothermal acoustic detection senses absorbed light through heat and sound. A sample absorbs light and warms slightly. The warming makes it expand and emit sound. A sensitive detector measures that sound. It only responds to absorbed light, so it is very sensitive.','It provides a low-noise route to detect very weak absorption, since the signal appears only when light is truly absorbed.','It is used for trace-gas monitoring, pollutant detection, and measuring weak absorbers that transmission methods miss.','Chemical & Molecular Acoustics',ARRAY['Photoacoustic signal','Photoacoustic spectroscopy','Quartz-enhanced photoacoustic spectroscopy','Thermal expansion','Trace-gas detection']::text[],ARRAY['Confusing it with methods that measure transmitted or scattered light','Assuming sensitivity without resonant enhancement or careful modulation','Ignoring background sound and thermal noise sources']::text[],ARRAY['Monitoring a trace pollutant gas','Detecting a weak absorber in a clear sample','Measuring low gas concentrations in air']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photothermal acoustic detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c12d1b32-1337-542b-bb47-ccc64150410f','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c12d1b32-1337-542b-bb47-ccc64150410f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c12d1b32-1337-542b-bb47-ccc64150410f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a78b416a-efd6-592a-b8c8-996fb6990f8f','Cavity-enhanced photoacoustic spectroscopy','A photoacoustic technique that places the sample inside a high-finesse optical cavity so the light passes through it many times, greatly increasing the effective optical power and the absorbed energy. The stronger absorption produces a larger photoacoustic signal, improving sensitivity and lowering detection limits for trace species without raising laser power.','Cavity-enhanced photoacoustic spectroscopy boosts the light before it is absorbed. Mirrors trap the light so it bounces many times. Each pass lets the sample absorb more light. This makes a much stronger sound signal. So very small amounts of gas can be measured.','It multiplies the effective optical power seen by the sample, extending photoacoustic detection to lower concentrations without a stronger laser.','It is used for high-sensitivity trace-gas analysis and atmospheric monitoring of very dilute species.','Chemical & Molecular Acoustics',ARRAY['Photoacoustic signal','Optical cavity','Photothermal acoustic detection','Quartz-enhanced photoacoustic spectroscopy','Trace-gas detection']::text[],ARRAY['Assuming higher signal comes from more laser power rather than more passes','Ignoring the tight mirror alignment and stability the cavity needs','Overlooking cavity losses that limit the enhancement']::text[],ARRAY['Measuring an extremely dilute trace gas','Monitoring atmospheric species at low levels','Boosting sensitivity without a more powerful laser']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavity-enhanced photoacoustic spectroscopy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a78b416a-efd6-592a-b8c8-996fb6990f8f','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a78b416a-efd6-592a-b8c8-996fb6990f8f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a78b416a-efd6-592a-b8c8-996fb6990f8f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '63de2871-b2bd-5ddc-aafc-146647ebfdd5','Quartz-enhanced photoacoustic spectroscopy','A photoacoustic method that uses a small quartz tuning fork as a sharply resonant acoustic detector in place of a microphone. Modulated light absorbed by gas between the fork''s tines generates sound at the fork''s resonance, which its high quality factor accumulates into a strong, narrowband signal. The approach is compact, immune to most environmental noise, and highly sensitive.','Quartz-enhanced photoacoustic spectroscopy uses a tiny tuning fork to hear the sound. Light passes between the fork''s two prongs. Gas there absorbs the light and makes sound. The fork rings strongly at its own pitch. Its sharp response builds a strong, low-noise signal.','It replaces the microphone with a sharply tuned quartz fork, giving a compact, noise-immune detector for very sensitive trace-gas sensing.','It is used in portable trace-gas analyzers for environmental, industrial, and medical breath monitoring.','Chemical & Molecular Acoustics',ARRAY['Photoacoustic signal','Quartz tuning fork','Cavity-enhanced photoacoustic spectroscopy','Quality factor','Trace-gas detection']::text[],ARRAY['Confusing the quartz fork''s role in sensing sound with a QCM weighing mass','Assuming any modulation frequency works, when it must match the fork''s resonance','Ignoring how the fork''s sharp resonance rejects broadband noise']::text[],ARRAY['Building a portable trace-gas sensor','Detecting a gas in exhaled breath','Sensing a pollutant with a noise-immune detector']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quartz-enhanced photoacoustic spectroscopy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '63de2871-b2bd-5ddc-aafc-146647ebfdd5','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='63de2871-b2bd-5ddc-aafc-146647ebfdd5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='63de2871-b2bd-5ddc-aafc-146647ebfdd5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '74821861-66e6-53da-a862-2bad01e6ff73','Acoustic relaxation','A frequency-dependent absorption and dispersion of sound arising because a propagating acoustic wave perturbs an equilibrium, such as a chemical, structural, or thermal one, that cannot re-establish instantaneously. The finite relaxation time causes a characteristic peak in absorption per wavelength near the relaxation frequency and a step in sound speed, providing a probe of fast molecular processes.','Acoustic relaxation is a lag between sound and a system''s response. A sound wave squeezes and stretches the medium fast. Some internal process cannot keep up in time. This lag absorbs extra sound energy at certain frequencies. It also slightly changes the sound speed.','It links measurable sound absorption to the timescales of fast molecular and chemical processes, turning acoustics into a kinetic probe.','It is used to study fast reaction and structural kinetics by measuring how absorption peaks with frequency in liquids.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic absorption spectroscopy','Relaxation time','Sound absorption','Dispersion','Relaxation frequency']::text[],ARRAY['Confusing acoustic relaxation with ordinary viscous, Stokes-Kirchhoff absorption','Assuming absorption rises steadily with frequency rather than peaking near a relaxation','Ignoring temperature''s strong effect on the relaxation frequency']::text[],ARRAY['Measuring the rate of a fast reaction in solution','Probing conformational changes by absorption peaks','Explaining excess sound absorption in a liquid']::text[],'advanced','(α/f²) has a relaxation term peaking at f_r = 1/(2πτ)','The absorption divided by frequency squared includes a relaxation contribution that peaks at the relaxation frequency, which equals one divided by two pi times the relaxation time.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic relaxation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '74821861-66e6-53da-a862-2bad01e6ff73','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='74821861-66e6-53da-a862-2bad01e6ff73') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='74821861-66e6-53da-a862-2bad01e6ff73');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24268208-380f-57c8-aaf5-944cb5706495','Ultrasonic absorption spectroscopy','The measurement of acoustic absorption as a function of frequency to characterize a liquid or solution. After accounting for the classical Stokes-Kirchhoff baseline from viscosity and heat conduction, any excess absorption reveals relaxation processes; fitting the spectrum yields relaxation times and amplitudes that report on fast chemical kinetics, association equilibria, and conformational dynamics.','This method measures how a liquid soaks up sound at each pitch. Every liquid soaks up some sound on its own. Extra soaking points to fast changes inside. The way it changes with pitch shows how fast they are. This reveals quick reactions and shape changes.','It extracts the rates of very fast molecular processes from the way a liquid absorbs sound, reaching timescales other methods miss.','It is used in physical chemistry to study reaction kinetics, ion pairing, and conformational changes in solution.','Chemical & Molecular Acoustics',ARRAY['Acoustic relaxation','Stokes-Kirchhoff absorption','Relaxation time','Sound absorption','Reaction kinetics']::text[],ARRAY['Ignoring the classical viscous baseline and attributing all absorption to relaxation','Assuming one relaxation, when several processes may overlap','Overlooking temperature control, which shifts the relaxation frequencies']::text[],ARRAY['Measuring the kinetics of a fast association reaction','Studying ion-pairing dynamics in an electrolyte','Probing conformational changes of a molecule in solution']::text[],'advanced','α_cl = (2π² f² / (ρ c³))·[(4/3)η + η_B + κ(1/c_v − 1/c_p)]','The classical Stokes-Kirchhoff absorption coefficient scales with two pi squared times frequency squared over density times sound speed cubed, multiplied by the sum of four-thirds the shear viscosity, the bulk viscosity, and a heat-conduction term.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic absorption spectroscopy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24268208-380f-57c8-aaf5-944cb5706495','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24268208-380f-57c8-aaf5-944cb5706495') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24268208-380f-57c8-aaf5-944cb5706495');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3c611b35-7175-5306-8738-7c53addb643e','Acoustic spectroscopy','The characterization of a material, often a concentrated suspension or emulsion, by measuring the frequency dependence of sound speed and attenuation. Because these acoustic properties depend on particle size, concentration, and mechanical properties, fitting the spectra to a physical model yields particle-size distributions and other information, even in optically opaque, concentrated systems.','Acoustic spectroscopy studies a material using sound across frequencies. It measures how fast sound travels and how much it fades. These depend on the particles inside the liquid. A model then turns the data into particle sizes. It works even in thick, cloudy mixtures.','It measures particle size and structure in concentrated, opaque systems where light-based methods fail, using sound instead of light.','It is used to size particles and droplets in dense slurries, emulsions, and suspensions without dilution.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic absorption spectroscopy','Acoustic attenuation','Particle-size distribution','Ultrasonic velocity measurement','Suspension characterization']::text[],ARRAY['Assuming samples must be diluted, when the method suits concentrated systems','Ignoring that results depend on the chosen physical model','Confusing attenuation from scattering with true absorption']::text[],ARRAY['Sizing particles in a concentrated slurry','Characterizing an opaque emulsion without dilution','Monitoring particle size during a process']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic spectroscopy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3c611b35-7175-5306-8738-7c53addb643e','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3c611b35-7175-5306-8738-7c53addb643e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3c611b35-7175-5306-8738-7c53addb643e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '40738728-987e-5755-9b2d-28b82490fa5f','Ultrasonic velocity measurement','The determination of the speed of sound in a liquid, commonly by timing a pulse over a known path length or by interferometry. Sound speed depends on the liquid''s density and adiabatic compressibility, so precise velocity measurement yields compressibility, elastic, and thermodynamic properties and can track composition, concentration, and phase changes with high sensitivity.','Ultrasonic velocity measurement finds how fast sound moves in a liquid. A pulse travels a known distance and is timed. The speed follows from the distance and travel time. Sound speed depends on the liquid''s density and stiffness. So it reveals composition and other properties.','It gives a fast, precise probe of a liquid''s compressibility and composition, since sound speed is very sensitive to both.','It is used to monitor concentration, verify composition, and derive compressibility in process and laboratory measurements.','Chemical & Molecular Acoustics',ARRAY['Isentropic compressibility','Acoustic impedance of liquid','Speed of sound','Pulse-echo','Newton-Laplace equation']::text[],ARRAY['Ignoring the strong temperature dependence of sound speed in liquids','Assuming a single measurement identifies a mixture without calibration','Overlooking dissolved gas or bubbles, which distort the reading']::text[],ARRAY['Checking the concentration of a binary solution','Deriving compressibility from speed and density','Monitoring a process stream for composition changes']::text[],'intermediate','c = d / t   (pulse–echo: c = 2d / t)','The speed of sound equals the path length divided by the travel time; in a pulse-echo setup it equals twice the sample thickness divided by the round-trip time.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic velocity measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '40738728-987e-5755-9b2d-28b82490fa5f','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='40738728-987e-5755-9b2d-28b82490fa5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='40738728-987e-5755-9b2d-28b82490fa5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd92108e3-a610-51bb-a9c3-3813347d0b38','Isentropic compressibility','The fractional decrease in volume of a substance per unit increase in pressure under adiabatic, reversible (isentropic) conditions, in which no heat is exchanged and entropy is constant. Because sound propagation in a fluid is effectively adiabatic, the isentropic compressibility is directly related to the speed of sound and density through the Newton-Laplace relation.','Isentropic compressibility says how much a fluid shrinks under pressure with no heat flow. When sound passes, the squeeze happens too fast for heat to move. So it is the compressibility for that no-heat case. It links straight to the sound speed and density. Stiffer fluids have lower compressibility and faster sound.','It is the thermodynamic property that sound speed measures, connecting acoustic velocity to a fluid''s mechanical stiffness.','It is obtained from measured sound speed and density to characterize solutions, mixtures, and molecular interactions.','Chemical & Molecular Acoustics',ARRAY['Newton-Laplace equation','Speed of sound','Adiabatic process','Ultrasonic velocity measurement','Bulk modulus']::text[],ARRAY['Confusing isentropic (adiabatic) with isothermal compressibility','Assuming sound propagation is isothermal rather than adiabatic','Forgetting that density is needed alongside sound speed to compute it']::text[],ARRAY['Computing compressibility from sound speed and density','Studying ion-solvent interactions in solution','Characterizing a liquid mixture''s molecular behaviour']::text[],'advanced','κ_s = −1/V·(∂V/∂p)_S = 1/(ρ c²)','The isentropic compressibility is the negative fractional volume change with pressure at constant entropy, and it equals one divided by the product of density and the square of the sound speed.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Isentropic compressibility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd92108e3-a610-51bb-a9c3-3813347d0b38','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d92108e3-a610-51bb-a9c3-3813347d0b38') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d92108e3-a610-51bb-a9c3-3813347d0b38');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '985832aa-da72-56db-b969-0a559e75a227','Acoustic impedance of liquid','The characteristic acoustic impedance of a liquid, defined as the product of its density and the speed of sound in it. It relates acoustic pressure to particle velocity in a travelling plane wave and governs the transmission and reflection of sound at interfaces; impedance mismatch between two media sets how much acoustic energy is reflected rather than transmitted.','Acoustic impedance of a liquid is its density times the sound speed. It links sound pressure to how fast the particles move. It controls how sound crosses a boundary between materials. A big mismatch at a boundary reflects most of the sound. A close match lets sound pass through.','It quantifies how a liquid opposes acoustic motion and sets the reflection and transmission of sound at boundaries.','It guides transducer coupling, echo interpretation, and material matching in ultrasonic measurement and imaging.','Chemical & Molecular Acoustics',ARRAY['Speed of sound','Density','Impedance matching','Reflection coefficient','Ultrasonic velocity measurement']::text[],ARRAY['Confusing acoustic impedance with electrical impedance','Assuming impedance alone gives sound speed without knowing density','Ignoring impedance mismatch when interpreting strong interface echoes']::text[],ARRAY['Predicting reflection at a liquid-solid boundary','Matching a transducer to a liquid for good coupling','Interpreting echo strength in ultrasonic testing']::text[],'intermediate','Z = ρ·c','The characteristic acoustic impedance equals the density of the liquid multiplied by the speed of sound in it.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic impedance of liquid');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '985832aa-da72-56db-b969-0a559e75a227','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='985832aa-da72-56db-b969-0a559e75a227') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='985832aa-da72-56db-b969-0a559e75a227');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '980024a3-e80f-5e4c-bb42-2b136275cdc7','Brillouin scattering','The inelastic scattering of light by thermally excited acoustic phonons, or sound waves, in a medium. The scattered light is shifted in frequency by the phonon frequency, up or down depending on whether a phonon is absorbed or created. Measuring the Brillouin shift yields the sound velocity and, with density, the elastic moduli of the material without contact.','Brillouin scattering is light bouncing off sound waves in a material. Tiny natural sound waves ripple through the medium. Light hitting them shifts slightly up or down in frequency. That small shift reveals the sound speed inside. From it, scientists find the material''s stiffness.','It provides a contactless optical way to measure sound velocity and elastic properties at gigahertz frequencies, deep inside a sample.','It is used to map elastic moduli in materials, biological tissue, and liquids under extreme pressure in diamond anvil cells.','Chemical & Molecular Acoustics',ARRAY['Brillouin spectroscopy','Acoustic phonon','Inelastic scattering','Sound velocity','Elastic modulus']::text[],ARRAY['Confusing Brillouin scattering from acoustic phonons with Raman scattering from optical phonons','Assuming the frequency shift is large, when it is very small','Ignoring the angle dependence of the measured shift']::text[],ARRAY['Measuring elastic moduli of a transparent solid','Mapping tissue stiffness without contact','Studying sound speed in a sample under high pressure']::text[],'advanced','Δν_B = ±(2 n v / λ_0)·sin(θ/2)','The Brillouin frequency shift equals plus or minus two times the refractive index times the sound velocity, divided by the vacuum wavelength of the light, multiplied by the sine of half the scattering angle.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Brillouin scattering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '980024a3-e80f-5e4c-bb42-2b136275cdc7','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='980024a3-e80f-5e4c-bb42-2b136275cdc7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='980024a3-e80f-5e4c-bb42-2b136275cdc7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2f4fa783-0433-5de2-aaa3-1fe5f412ea31','Brillouin spectroscopy','The experimental technique that analyzes the small frequency shifts of light undergoing Brillouin scattering to determine a material''s acoustic and elastic properties. Using a high-resolution interferometer to resolve the tiny shifts, it yields sound velocities and elastic moduli, and it is applied non-invasively to solids, liquids, thin films, and biological samples.','Brillouin spectroscopy studies a material through Brillouin scattered light. It measures the tiny frequency shift the sound waves cause. A special high-resolution instrument resolves that small shift. From it, the sound speed and stiffness are found. It works without touching or cutting the sample.','It turns Brillouin scattering into a measurement tool for elastic properties, giving non-contact mechanical data on delicate or confined samples.','It is used to characterize elastic moduli of thin films, glasses, tissue, and samples under high pressure.','Chemical & Molecular Acoustics',ARRAY['Brillouin scattering','Acoustic phonon','Elastic modulus','Interferometer','Sound velocity']::text[],ARRAY['Confusing Brillouin spectroscopy with Raman spectroscopy of vibrational modes','Underestimating the very high spectral resolution the small shifts require','Assuming any spectrometer can resolve the Brillouin shift']::text[],ARRAY['Measuring the stiffness of a thin film or glass','Mapping mechanical properties of tissue non-invasively','Studying elasticity of a sample in a diamond anvil cell']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Brillouin spectroscopy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2f4fa783-0433-5de2-aaa3-1fe5f412ea31','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2f4fa783-0433-5de2-aaa3-1fe5f412ea31') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2f4fa783-0433-5de2-aaa3-1fe5f412ea31');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1bbdc248-fb10-5ac0-969c-4800b9ecbd65','Phonon','A quantum of collective vibrational energy in a crystal lattice, that is, the quantized normal mode of atomic vibration. Phonons behave as quasiparticles carrying energy proportional to their frequency and crystal momentum proportional to their wavevector, and they govern a solid''s thermal, acoustic, and many electronic transport properties.','A phonon is a single unit of vibration in a crystal. The atoms in a solid vibrate together in patterns. Each pattern''s energy comes in fixed steps. One such step of vibration is a phonon. Phonons carry heat and sound through the solid.','It lets physicists treat lattice vibrations as countable particles, explaining heat capacity, thermal conduction, and sound in solids.','The phonon concept underpins understanding of heat transport, sound propagation, and scattering in crystalline materials.','Chemical & Molecular Acoustics',ARRAY['Acoustic phonon','Optical phonon','Lattice vibration','Quasiparticle','Dispersion relation']::text[],ARRAY['Treating a phonon as a real particle rather than a quantum of vibration','Assuming phonons carry true momentum instead of crystal momentum','Confusing phonons with photons, which are quanta of light']::text[],ARRAY['Explaining heat conduction in a crystal','Describing sound propagation at the atomic scale','Analyzing phonon scattering that limits conductivity']::text[],'intermediate','E = ħω,   p = ħk','A phonon''s energy equals the reduced Planck constant times its angular frequency, and its crystal momentum equals the reduced Planck constant times its wavevector.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phonon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1bbdc248-fb10-5ac0-969c-4800b9ecbd65','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1bbdc248-fb10-5ac0-969c-4800b9ecbd65') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1bbdc248-fb10-5ac0-969c-4800b9ecbd65');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e59348e8-dcc9-511d-9c2b-129b6f77992f','Acoustic phonon','A phonon branch in which neighbouring atoms in the unit cell vibrate nearly in phase, so the mode corresponds to a propagating sound wave. Near the Brillouin-zone centre its frequency rises linearly with wavevector, and the slope equals the speed of sound; the frequency approaches zero at long wavelengths, distinguishing it from optical branches.','An acoustic phonon is a vibration where nearby atoms move together. Because they move in step, the mode acts like a sound wave. At long wavelengths its frequency drops toward zero. Its frequency rises in a straight line with wavevector. The slope of that line is the sound speed.','It is the lattice mode that carries sound and dominates low-temperature heat transport, linking atomic vibration to bulk sound velocity.','Acoustic phonons appear in Brillouin scattering, thermal conductivity analysis, and studies of sound in crystals.','Chemical & Molecular Acoustics',ARRAY['Phonon','Optical phonon','Dispersion relation','Brillouin scattering','Sound velocity']::text[],ARRAY['Confusing acoustic phonons, where atoms move in phase, with optical phonons','Assuming a linear dispersion holds across the whole Brillouin zone','Forgetting that its frequency goes to zero at long wavelength']::text[],ARRAY['Relating measured sound speed to phonon dispersion','Analyzing low-temperature heat transport','Interpreting Brillouin scattering from acoustic modes']::text[],'advanced','ω ≈ v_s·|k|   (k → 0)','For an acoustic phonon near the zone centre, the angular frequency is approximately the sound speed times the magnitude of the wavevector, so frequency goes to zero as the wavevector goes to zero.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic phonon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e59348e8-dcc9-511d-9c2b-129b6f77992f','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e59348e8-dcc9-511d-9c2b-129b6f77992f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e59348e8-dcc9-511d-9c2b-129b6f77992f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '80e1024b-d1f4-5aa7-8a9d-3f2444727ce4','Optical phonon','A phonon branch in a crystal with more than one atom per unit cell in which neighbouring atoms vibrate out of phase with one another. Its frequency remains finite, and generally near its maximum, at the Brillouin-zone centre, so long-wavelength optical phonons do not vanish. In polar crystals these modes can couple to light and are probed by infrared and Raman spectroscopy.','An optical phonon is a vibration where nearby atoms move against each other. Because they move oppositely, the mode does not act like a simple sound wave. Its frequency stays high even at long wavelengths. In many crystals it can interact with light. Infrared and Raman methods detect these modes.','It describes the high-frequency, out-of-phase lattice modes that couple to light, enabling optical probing of crystal structure and bonding.','Optical phonons are studied by infrared and Raman spectroscopy to identify materials and probe bonding and structure.','Chemical & Molecular Acoustics',ARRAY['Acoustic phonon','Phonon','Raman acoustic mode','Infrared spectroscopy','Dispersion relation']::text[],ARRAY['Confusing optical phonons, with atoms out of phase, with in-phase acoustic phonons','Assuming their frequency goes to zero at long wavelength, when it stays finite','Thinking every crystal has optical phonons, when a single-atom basis has none']::text[],ARRAY['Identifying a material by its Raman optical modes','Probing bonding through infrared-active phonons','Distinguishing optical from acoustic branches in a dispersion curve']::text[],'advanced','ω(k → 0) ≈ ω_0 > 0','For an optical phonon, the angular frequency near the zone centre approaches a finite maximum value greater than zero, rather than going to zero as for an acoustic phonon.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optical phonon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '80e1024b-d1f4-5aa7-8a9d-3f2444727ce4','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='80e1024b-d1f4-5aa7-8a9d-3f2444727ce4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='80e1024b-d1f4-5aa7-8a9d-3f2444727ce4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2716eb4c-b0c0-5ec5-9656-dd5ba0244db0','Raman acoustic mode','A low-frequency, acoustic-like vibrational mode made observable in Raman spectroscopy, typically arising from confined acoustic phonons in nanostructures such as nanoparticles, nanocrystals, and thin films. Spatial confinement quantizes the acoustic vibrations into discrete breathing and quadrupolar modes whose frequencies scale inversely with particle size, so they serve as an optical probe of nanoscale dimensions and elasticity.','A Raman acoustic mode is a low-pitch vibration seen in Raman light scattering. In tiny particles, sound waves get trapped inside. Being trapped forces them into a few set vibrations. These act like the particle ringing as a whole. Their frequency rises as the particle gets smaller.','It provides an optical way to measure nanoparticle size and elastic properties, since confined acoustic vibrations depend on both.','It is used to size nanoparticles and probe their elasticity by reading low-frequency Raman peaks.','Chemical & Molecular Acoustics',ARRAY['Acoustic phonon','Confined acoustic phonon','Raman spectroscopy','Nanoparticle','Lamb mode']::text[],ARRAY['Confusing low-frequency acoustic Raman modes with ordinary high-frequency optical modes','Assuming bulk acoustic phonons appear directly in Raman without confinement','Ignoring how particle size sets the mode frequency']::text[],ARRAY['Estimating nanoparticle size from low-frequency Raman peaks','Probing the elasticity of a nanocrystal','Studying confined vibrations in a thin film']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Raman acoustic mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2716eb4c-b0c0-5ec5-9656-dd5ba0244db0','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2716eb4c-b0c0-5ec5-9656-dd5ba0244db0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2716eb4c-b0c0-5ec5-9656-dd5ba0244db0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '04800102-ff95-5d53-aa04-f18de4c6869a','Photoacoustic','Describing the generation of acoustic waves in a material as a result of its absorption of modulated or pulsed electromagnetic radiation, most often light. The absorbed energy is released as heat through radiationless relaxation, producing rapid, localized thermal expansion that launches a pressure wave in the sound or ultrasound range. The effect underlies photoacoustic spectroscopy, which infers optical absorption and chemical composition from the emitted sound, and photoacoustic imaging, which reconstructs internal structure from the resulting ultrasound. It couples optical excitation to acoustic detection and recurs across chemistry, materials science, biomedical imaging, and astronomical instrumentation.','Photoacoustic means making sound with light. A material soaks up pulses of light. That light energy turns into heat. The heat makes the material swell very fast. The quick swelling sends out a sound wave. Sensors listen to that sound. From it, we learn what the material is or how it looks inside.','It converts light absorption into a detectable sound wave, so optical properties and internal structure can be measured by listening rather than by looking. This lets instruments probe samples that are opaque, strongly scattering, or otherwise hard to image with light alone.','Researchers and technicians meet it in photoacoustic spectrometers that measure trace gases and material absorption, and in photoacoustic imaging systems used for biomedical tissue and vascular imaging. It also appears in non-destructive material testing and in some remote-sensing and astronomical instruments.','Cross-Disciplinary Sonic Sensing',ARRAY['Photoacoustic spectroscopy','Photoacoustic imaging','Thermoelastic expansion','Optoacoustic','Ultrasound transducer']::text[],ARRAY['Assuming the sound comes directly from the light, rather than from heat-driven thermal expansion','Confusing photoacoustic imaging with ordinary ultrasound, which uses transmitted sound instead of light-generated sound','Treating ''photoacoustic'' and ''optoacoustic'' as different effects when they name the same phenomenon']::text[],ARRAY['Measuring trace-gas concentration with a photoacoustic gas analyzer','Imaging blood vessels in tissue using a pulsed laser and an ultrasound sensor','Characterizing a material''s optical absorption without cutting it open']::text[],'advanced',NULL,NULL,'50228531-9071-46f7-b2bb-171a0af621e4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photoacoustic');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '04800102-ff95-5d53-aa04-f18de4c6869a','50228531-9071-46f7-b2bb-171a0af621e4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='04800102-ff95-5d53-aa04-f18de4c6869a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='04800102-ff95-5d53-aa04-f18de4c6869a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '072265f8-17c0-5e25-9ac5-ced6bbf78d92','Acoustic sensing','The use of acoustic energy, meaning sound or mechanical vibration propagating through air, water, solids, or the ground, to detect, locate, measure, or characterize objects, events, or conditions. A sensing system transduces the acoustic field into an electrical signal, then analyzes features such as amplitude, arrival time, frequency content, or waveform shape to infer information about the source or the medium. It encompasses passive approaches, which only receive existing sound, and active approaches, which emit a signal and interpret its return. The concept recurs across ocean science, seismology, industrial monitoring, ecology, security, and biomedical measurement.','Acoustic sensing means using sound to learn about the world. A sensor turns sound or vibration into a signal. The system then studies that signal. It can find where a sound came from. It can also measure what made the sound. Some setups only listen. Others send out a sound and study the echo. Many fields use this idea.','It provides a way to gather information when light or direct contact will not work, because sound travels well through water, soil, and solid structures. By reading the acoustic field, a system can monitor sources and media remotely and continuously.','Technicians meet acoustic sensing in hydrophone and microphone arrays, machine-condition and pipeline monitors, structural and seismic sensors, and fiber-optic distributed sensing along cables. The signals are logged and analyzed to detect events, locate sources, or track changes over time.','Cross-Disciplinary Sonic Sensing',ARRAY['Active acoustic sensing','Passive acoustic monitoring','Transducer','Hydrophone','Distributed acoustic sensing','Acoustic emission']::text[],ARRAY['Assuming acoustic sensing always emits sound, when many systems only listen','Confusing the acoustic sensor itself with the analysis stage that actually extracts the information','Expecting equal performance in every medium, though the speed and loss of sound differ widely between air, water, and solids']::text[],ARRAY['Detecting a gas leak by the ultrasonic hiss it produces','Locating a whale from calls picked up on an underwater array','Monitoring a bridge for cracks through the sounds the structure emits']::text[],'intermediate',NULL,NULL,'50228531-9071-46f7-b2bb-171a0af621e4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic sensing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '072265f8-17c0-5e25-9ac5-ced6bbf78d92','50228531-9071-46f7-b2bb-171a0af621e4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='072265f8-17c0-5e25-9ac5-ced6bbf78d92') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='072265f8-17c0-5e25-9ac5-ced6bbf78d92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44bcbb63-d6f0-565b-9097-c568c083007e','Passive acoustic monitoring','A sensing method in which sound produced naturally within an environment is recorded and analyzed without the observer emitting any acoustic energy. Sensors such as hydrophones or microphones capture the ambient sound field over time, and the recordings are processed to detect, classify, count, or locate the sound-producing sources. Because the system only receives, it does not disturb the animals, geophysical processes, or human activity under study. It is applied widely in marine mammal and wildlife research, fisheries, seismology and volcanology, and long-term environmental surveillance.','Passive acoustic monitoring means listening without making any sound. Microphones or underwater sensors record what is already there. The recordings are studied later. This can show which animals are present. It can also count them or find where they are. Because it stays quiet, it does not disturb what is being watched. Scientists use it over long stretches of time.','It lets observers study sound-producing sources continuously and unobtrusively, including at night, over long periods, or in places people cannot easily reach. Staying silent avoids changing the behavior or process being observed.','Technicians deploy fixed or drifting recorders, then run detection and classification software over the logged audio to find calls, engine noise, or seismic events. It is common in marine mammal surveys, bird and bat studies, fisheries research, and seismic and volcanic observation.','Cross-Disciplinary Sonic Sensing',ARRAY['Passive acoustics','Hydrophone','Bioacoustics','Acoustic sensing','Active acoustic sensing','Soundscape ecology']::text[],ARRAY['Confusing it with active methods such as sonar, which transmit sound','Assuming silence in a recording means no sources are present, when the source may simply be out of range','Underestimating how much storage and automated analysis long recordings require']::text[],ARRAY['Recording a reef for months to track fish and mammal activity','Detecting whale calls along a shipping route to reduce collisions','Listening for small earthquakes near a volcano']::text[],'intermediate',NULL,NULL,'50228531-9071-46f7-b2bb-171a0af621e4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive acoustic monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44bcbb63-d6f0-565b-9097-c568c083007e','50228531-9071-46f7-b2bb-171a0af621e4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44bcbb63-d6f0-565b-9097-c568c083007e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44bcbb63-d6f0-565b-9097-c568c083007e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67a9db27-dac4-5225-82ff-533ecebfb569','Active acoustic sensing','A sensing method in which the observer deliberately transmits a controlled acoustic signal and then analyzes the energy that returns after reflecting from or scattering off targets or boundaries. Properties of the echo, including its delay, amplitude, frequency shift, and shape, reveal the range, size, motion, structure, or composition of whatever the sound encountered. Because the outgoing waveform is known, active systems can measure distance and image structure that passive listening cannot. It underlies sonar, echosounding, sub-bottom profiling, ultrasound imaging, and many industrial and geophysical survey techniques.','Active acoustic sensing means sending out sound on purpose. The system makes a known sound pulse. That pulse hits an object and bounces back. Sensors catch the returning echo. The time it takes tells you how far the object is. The shape of the echo tells you about the object. Sonar and medical ultrasound both work this way.','It measures range and reveals hidden structure by comparing each echo with the known outgoing signal. This gives distance and imaging ability that passive methods, which only listen, cannot provide.','Technicians use it in sonar and echosounders for depth and fish finding, sub-bottom profilers for sediment layers, ultrasound scanners in medicine, and ultrasonic gauges in industry. The system times and processes the returned pulses to build ranges or images.','Cross-Disciplinary Sonic Sensing',ARRAY['Sonar','Echosounder','Passive acoustic monitoring','Acoustic sensing','Ultrasound','Time of flight']::text[],ARRAY['Confusing active sensing with passive listening, though only active systems transmit a signal','Ignoring that the emitted sound can disturb sensitive animals or environments','Forgetting that reverberation and multiple echoes can be mistaken for real targets']::text[],ARRAY['Mapping seafloor depth from a survey vessel','Finding fish schools with a scientific echosounder','Imaging soft tissue with a medical ultrasound probe']::text[],'intermediate',NULL,NULL,'50228531-9071-46f7-b2bb-171a0af621e4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Active acoustic sensing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67a9db27-dac4-5225-82ff-533ecebfb569','50228531-9071-46f7-b2bb-171a0af621e4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67a9db27-dac4-5225-82ff-533ecebfb569') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67a9db27-dac4-5225-82ff-533ecebfb569');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e54d156b-7923-57d7-b3e5-e9189597ac6c','Acoustic fingerprint','A compact, content-based digital summary computed from an audio signal that captures its perceptually salient features so the signal can be identified or matched against a reference database. The fingerprint is derived by analyzing features such as the time-frequency energy pattern, and it is designed to stay stable when the audio is compressed, filtered, resampled, or contaminated by noise, while differing between unrelated recordings. Matching a query fingerprint against stored ones identifies the recording without comparing the full waveform, which keeps lookups small and fast. It is central to music and broadcast identification, copyright monitoring, and content-based audio retrieval.','An acoustic fingerprint is a short digital summary of a sound. It captures the key features of a recording. It is built to survive noise and compression. Two copies of the same song give matching fingerprints. Different recordings give different ones. A system can match a clip against a database. This is how an app can name a song it hears.','It lets a system recognize a specific recording quickly and reliably without storing or comparing the whole audio file. The summary is small, robust to distortion, and easy to look up in a large database.','Engineers meet it in song-identification apps, broadcast and streaming monitoring, and copyright-detection systems that scan uploaded audio. A fingerprint is extracted from a short clip and matched against a reference catalog to name the source.','Cross-Disciplinary Sonic Sensing',ARRAY['Audio fingerprinting','Content-based audio identification','Spectrogram','Feature extraction','Music information retrieval','Acoustic signature']::text[],ARRAY['Confusing an acoustic fingerprint, which identifies a specific recording, with an acoustic signature that broadly characterizes a source','Assuming it stores the actual audio, when it stores only a derived summary','Expecting it to recognize a live cover or re-recording, which produces a different fingerprint']::text[],ARRAY['Naming an unknown song from a phone microphone clip','Detecting copyrighted music in an uploaded video','Logging which tracks a radio station played']::text[],'intermediate',NULL,NULL,'50228531-9071-46f7-b2bb-171a0af621e4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic fingerprint');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e54d156b-7923-57d7-b3e5-e9189597ac6c','50228531-9071-46f7-b2bb-171a0af621e4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e54d156b-7923-57d7-b3e5-e9189597ac6c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e54d156b-7923-57d7-b3e5-e9189597ac6c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d0c3044-1076-58cb-80b9-211e90e362d9','Acoustic-gravity wave','A low-frequency atmospheric or oceanic wave whose restoring forces are both the compressibility of the medium (giving the acoustic character) and gravity acting through buoyancy of stratified fluid (giving the gravity character). Its dispersion is bounded by the acoustic cutoff frequency at the high end and the Brunt-Vaisala (buoyancy) frequency at the low end, so energy can propagate as an acoustic branch above the cutoff and as an internal gravity branch below the buoyancy frequency. Large impulsive sources such as major volcanic eruptions and nuclear explosions launch acoustic-gravity waves that circle the globe.','This is a slow, low pitch wave in air or water. Two forces push it back into place. One is the springiness of the air. The other is gravity pulling on layers of different density. Big blasts, like huge eruptions, make these waves. They can travel around the whole Earth.','It carries pressure energy from very large sources over global distances, linking events at the ground to signals recorded far away in the atmosphere and ocean.','Analysts identify acoustic-gravity waves on barometer and infrasound records after major eruptions or explosions to estimate source energy, timing, and location.','Geologic & Seismoacoustics',ARRAY['Atmospheric acoustic wave','Lamb pulse','Infrasound','Brunt-Vaisala frequency','Internal gravity wave']::text[],ARRAY['Treating the acoustic branch and the gravity branch as unrelated instead of two limits of one wave family','Assuming these waves are audible when their energy sits below the human hearing range','Ignoring atmospheric stratification, which sets the buoyancy frequency that bounds the wave']::text[],ARRAY['Tracking a globe-circling pressure wave after a major explosive eruption','Interpreting long-period barometer signals from a distant nuclear test','Modelling energy coupling from the ground into the stratified atmosphere']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-gravity wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d0c3044-1076-58cb-80b9-211e90e362d9','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d0c3044-1076-58cb-80b9-211e90e362d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d0c3044-1076-58cb-80b9-211e90e362d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'be587188-4915-5b96-b84b-dea08dae539f','Atmospheric acoustic wave','A pressure wave propagating through the atmosphere in which the restoring force is the compressibility of air, spanning audible sound and the sub-audible infrasound band. Propagation is controlled by the vertical profiles of temperature and wind, which set the effective sound speed and refract rays back toward the ground to form ducts and shadow zones. In seismoacoustics it is the airborne counterpart of a ground seismic wave and can couple energy across the air-ground interface.','This is a sound wave that moves through the air. The springiness of the air pushes it along. It can be normal sound or very low pitch infrasound. Wind and temperature bend its path as it travels. That bending can trap it near the ground or leave gaps of silence.','It transports acoustic energy from natural and man-made sources through the atmosphere, providing a signal that arrays can detect, locate, and characterise.','Technicians record atmospheric acoustic waves on microphones and infrasound sensors to monitor explosions, eruptions, storms, and other distant events.','Geologic & Seismoacoustics',ARRAY['Infrasound','Acoustic-gravity wave','Atmospheric ducting','Acoustic shadow zone','Sound speed profile']::text[],ARRAY['Assuming sound travels in straight lines when wind and temperature strongly refract it','Forgetting that the effective sound speed includes the wind component along the path','Treating infrasound as a different phenomenon rather than low-frequency atmospheric sound']::text[],ARRAY['Detecting a distant mining blast on a microphone array','Explaining why a loud event is inaudible in a nearby shadow zone','Modelling how a temperature inversion channels sound along the surface']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Atmospheric acoustic wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'be587188-4915-5b96-b84b-dea08dae539f','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='be587188-4915-5b96-b84b-dea08dae539f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='be587188-4915-5b96-b84b-dea08dae539f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd40f9a66-23be-5014-b6dc-fa5f621b80c6','Lamb pulse','The impulsive wavetrain of the atmospheric Lamb wave, a horizontally propagating acoustic mode trapped near Earth''s surface in which vertical motion is essentially zero and pressure decays with height. It travels along the ground at close to the surface sound speed with little dispersion, so a large impulsive source produces a coherent pressure pulse that can be tracked over intercontinental and global distances. Major explosive volcanic eruptions and large nuclear tests are classic sources.','The Lamb wave is a special air wave that hugs the ground. It moves sideways along the surface, not up and down. It travels at about the speed of sound near the ground. A big blast sends out a sharp pulse of this wave. That pulse can be tracked across whole continents.','It provides a fast, low-loss channel that carries the pressure signature of very large explosions across the globe, aiding source detection and energy estimates.','Analysts pick the Lamb pulse on barograph and infrasound records to confirm and time major eruptions or explosions and to estimate the source strength.','Geologic & Seismoacoustics',ARRAY['Acoustic-gravity wave','Atmospheric acoustic wave','Infrasound','Atmospheric ducting','Volcanic explosion waveform']::text[],ARRAY['Confusing the atmospheric Lamb wave with the elastic Lamb wave in plates or the seismic Rayleigh pulse','Assuming strong dispersion when the Lamb mode is nearly non-dispersive','Expecting large vertical air motion when the mode''s vertical velocity is near zero']::text[],ARRAY['Identifying a globe-circling pressure pulse after a very large eruption','Timing a distant explosion from its Lamb-wave arrival on barometers','Separating the Lamb pulse from later ducted infrasound arrivals']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lamb pulse');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd40f9a66-23be-5014-b6dc-fa5f621b80c6','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d40f9a66-23be-5014-b6dc-fa5f621b80c6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d40f9a66-23be-5014-b6dc-fa5f621b80c6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e8c12ce5-f1ab-5906-ad53-7d2552ed8f51','Volcanic jet noise','Sustained broadband acoustic radiation produced when a high-velocity volcanic jet of gas and pyroclasts exits the vent, closely analogous to the aerodynamic noise of engineered jets. Turbulent mixing of the jet with the atmosphere generates sound over a wide band including infrasound, with amplitude and spectral content scaling with jet velocity and vent geometry. It typically accompanies sustained eruptive columns rather than discrete explosions.','A strong eruption pushes gas and ash out of the vent very fast. This jet mixes roughly with the air. That mixing makes a steady roaring sound. It works much like the roar of a jet engine. Part of the sound is too low to hear.','It signals a sustained, high-speed jet at the vent, so its loudness and spectrum let scientists infer eruption vigour and gas exit speed in real time.','Volcano observatories track jet noise on infrasound and audio sensors to estimate eruption intensity and to distinguish sustained jetting from discrete blasts.','Geologic & Seismoacoustics',ARRAY['Volcanic explosion waveform','Infrasound','Degassing acoustic pulse','Conduit resonance','Eruption column']::text[],ARRAY['Confusing continuous jet noise with the short transient of a single explosion','Assuming all the energy is audible when much of it lies in infrasound','Ignoring how vent shape and jet speed shape the recorded spectrum']::text[],ARRAY['Gauging the vigour of a sustained ash-venting phase from its roar','Separating jet noise from discrete explosion pulses on an infrasound record','Relating jet-noise loudness to modelled gas exit velocity']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volcanic jet noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e8c12ce5-f1ab-5906-ad53-7d2552ed8f51','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e8c12ce5-f1ab-5906-ad53-7d2552ed8f51') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e8c12ce5-f1ab-5906-ad53-7d2552ed8f51');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bce1358a-d47c-5029-8ea9-fdb304782366','Gas slug resonance','Acoustic oscillation set up when a large gas bubble, or slug, rises through and bursts within the magma-filled conduit of a Strombolian system, exciting resonance of the gas volume and the surrounding conduit. The rise, expansion, and rupture of the slug drive pressure oscillations whose frequencies depend on the slug size, gas properties, and conduit geometry, and which radiate as infrasound and couple into the ground as tremor.','In some volcanoes, big gas bubbles rise up the pipe of magma. A large bubble is called a slug. As it grows and bursts, it makes the gas ring like a drum. The size of the bubble and the pipe set the pitch. This ringing shows up as very low sound and ground shaking.','It links a measurable acoustic frequency to the size and behaviour of ascending gas slugs, giving a window into shallow conduit conditions.','Researchers analyse infrasound and seismic tremor at Strombolian volcanoes to infer slug dimensions, gas flux, and conduit geometry.','Geologic & Seismoacoustics',ARRAY['Bubble-burst infrasound','Conduit resonance','Strombolian eruption','Infrasound','Volcanic tremor']::text[],ARRAY['Treating every low-frequency signal as slug resonance without checking source depth','Ignoring gas composition and temperature, which shift the resonant frequency','Assuming the slug bursts only at the surface rather than within the conduit']::text[],ARRAY['Estimating gas-slug size at a Strombolian vent from infrasound tones','Correlating slug bursts with seismic tremor bursts','Modelling conduit gas flux from repeated resonant events']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gas slug resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bce1358a-d47c-5029-8ea9-fdb304782366','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bce1358a-d47c-5029-8ea9-fdb304782366') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bce1358a-d47c-5029-8ea9-fdb304782366');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6a2b4067-8e05-584a-8e24-0a7d50fff317','Conduit resonance','Standing-wave oscillation of the fluid column and gas within a volcanic conduit, in which the conduit acts as an acoustic resonator whose modal frequencies depend on its length, cross-section, end conditions, and the sound speed of the multiphase magma-gas mixture. Excitation by pressure transients produces narrow-band tremor and long-period signals; the very low mixture sound speed can place resonances at seismic and infrasonic frequencies.','A volcanic pipe can ring like an organ pipe. The magma and gas inside form the vibrating column. The length and shape of the pipe set the notes. Sound moves slowly in bubbly magma, so the notes are very low. This ringing appears as steady tremor and long, slow signals.','It relates observed tremor frequencies to conduit dimensions and the physical state of the magma-gas mixture, aiding models of shallow volcanic plumbing.','Seismologists interpret narrow-band tremor and long-period events as conduit resonance to constrain conduit length and mixture properties.','Geologic & Seismoacoustics',ARRAY['Magma conduit resonance','Crack resonance','Volcanic tremor','Long-period event','Gas slug resonance']::text[],ARRAY['Using the pure-melt sound speed instead of the low mixture speed set by bubbles','Assuming fixed end conditions without testing open or closed boundary models','Attributing all tremor to resonance while ignoring source-time and path effects']::text[],ARRAY['Inferring conduit length from a persistent tremor frequency','Distinguishing conduit resonance from crack resonance in long-period signals','Tracking shifts in resonant frequency as the magma column changes']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conduit resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6a2b4067-8e05-584a-8e24-0a7d50fff317','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6a2b4067-8e05-584a-8e24-0a7d50fff317') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6a2b4067-8e05-584a-8e24-0a7d50fff317');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9caced6-66c3-5fd8-a343-12d1450ab4ac','Crack resonance','Resonance of a fluid-filled crack in which a pressure disturbance excites slow interface waves, called crack or Krauklis waves, that travel along the fluid-solid boundary and reflect from the crack tips to set up standing modes. Because these guided waves are much slower than body waves, the resonant frequencies are low and depend on crack length, aperture, fluid properties, and the stiffness contrast, making the model a standard explanation for volcanic long-period events and tremor.','Imagine a thin crack in rock filled with fluid or gas. A pressure kick makes a slow wave run along the crack walls. It bounces off the ends and rings. Because this wave is slow, the ringing is very low pitch. This idea explains many long, slow volcano signals.','It provides a physical source model that ties low-frequency volcanic signals to the size, fill, and geometry of resonating cracks in the plumbing system.','Analysts fit crack-resonance models to long-period events and tremor to estimate crack dimensions and whether the fill is gas, water, or magma.','Geologic & Seismoacoustics',ARRAY['Conduit resonance','Long-period event','Krauklis wave','Volcanic tremor','Hydrothermal tremor']::text[],ARRAY['Confusing the slow crack wave with ordinary body waves in the rock','Ignoring the fluid type, which strongly changes the resonant frequency and damping','Assuming a single mode when real cracks support several closely spaced modes']::text[],ARRAY['Modelling a repeating long-period event as a resonating fluid-filled crack','Judging whether a crack is gas- or water-filled from its damping','Estimating crack length from the fundamental resonant frequency']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Crack resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9caced6-66c3-5fd8-a343-12d1450ab4ac','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9caced6-66c3-5fd8-a343-12d1450ab4ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9caced6-66c3-5fd8-a343-12d1450ab4ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '908da16e-df94-5367-a267-3ad4228b7e7b','Hydrothermal tremor','Sustained, often narrow-band seismic and acoustic ground vibration generated by the flow, boiling, and phase change of water and steam in a hydrothermal system, rather than by magma movement directly. Sources include bubble nucleation and collapse, two-phase flow instabilities, and resonance of fluid-filled cavities and cracks; spectra can be quasi-stable or drift as reservoir pressure and temperature evolve.','Hot water and steam move through cracks under a volcano or geyser field. Boiling and rushing fluid shake the ground steadily. This steady shaking is called hydrothermal tremor. It comes from water and steam, not directly from magma. Its pitch can drift as heat and pressure change.','It offers a non-eruptive signal of subsurface fluid activity, so changes in tremor can flag shifts in a hydrothermal system''s pressure and heat.','Monitoring teams watch hydrothermal tremor at geothermal and volcanic sites to detect boiling crises, unrest, and changes in fluid flow.','Geologic & Seismoacoustics',ARRAY['Volcanic tremor','Geyser infrasound','Fumarole acoustic signal','Crack resonance','Two-phase flow']::text[],ARRAY['Assuming all volcanic tremor is magmatic and overlooking a hydrothermal source','Reading a spectral drift as instrument error rather than reservoir change','Ignoring boiling and bubble collapse as strong tremor generators']::text[],ARRAY['Linking tremor changes to a boiling event in a geothermal field','Separating hydrothermal tremor from magmatic tremor during unrest','Tracking reservoir pressure through slow tremor frequency drift']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hydrothermal tremor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '908da16e-df94-5367-a267-3ad4228b7e7b','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='908da16e-df94-5367-a267-3ad4228b7e7b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='908da16e-df94-5367-a267-3ad4228b7e7b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '82b3de5e-60ef-5dbb-938a-78d16b287303','Geyser infrasound','Sub-audible atmospheric pressure signals radiated by geyser activity, including the pre-eruptive bubbling and boiling, the eruptive jet of water and steam, and post-eruptive recharge. The signals arise from bubble oscillation and collapse, two-phase flow, and the discharge jet, and their timing and amplitude track the phases of the eruption cycle.','A geyser makes very low sound as it works. Before it erupts, water bubbles and boils underground. During the eruption, a jet of water and steam roars out. Sensors pick up this low sound even from far away. The sound follows each stage of the geyser cycle.','It gives a remote, continuous record of a geyser''s internal activity and eruption timing without placing instruments in the hot vent.','Researchers deploy infrasound sensors near geysers to study eruption cycles, forecast intervals, and probe the plumbing without direct contact.','Geologic & Seismoacoustics',ARRAY['Infrasound','Hydrothermal tremor','Bubble-burst infrasound','Fumarole acoustic signal','Two-phase flow']::text[],ARRAY['Assuming the loudest infrasound marks the eruption onset rather than pre-eruptive boiling','Ignoring wind noise, which can mask weak geyser signals','Treating the signal as pure sound of water when steam and bubbles dominate']::text[],ARRAY['Forecasting a geyser''s next eruption from pre-eruptive infrasound','Studying conduit boiling through the low-frequency signature','Combining infrasound with seismic data to map a geyser''s plumbing']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Geyser infrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '82b3de5e-60ef-5dbb-938a-78d16b287303','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='82b3de5e-60ef-5dbb-938a-78d16b287303') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='82b3de5e-60ef-5dbb-938a-78d16b287303');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c763d9da-8e8f-5d07-b92f-b88e9a53e586','Fumarole acoustic signal','Acoustic and infrasonic emission produced by gas and steam venting from a fumarole, generated by turbulent flow through the vent, jetting into the atmosphere, and resonance of the vent cavity. The signal is typically continuous and broadband, and its amplitude and spectrum respond to changes in gas flux, vent geometry, and the gas-steam mixture.','A fumarole is a vent that lets out gas and steam. The rushing gas makes a hissing or roaring sound. Some of it is too low to hear. The sound changes when the gas flow or vent shape changes. Sensors use it to watch the vent from a safe distance.','It provides a remote, continuous proxy for gas output at a vent, so shifts in the sound can indicate changes in degassing.','Field teams record fumarole sound and infrasound to monitor gas flux trends and vent condition without approaching hazardous gases.','Geologic & Seismoacoustics',ARRAY['Degassing acoustic pulse','Volcanic jet noise','Infrasound','Hydrothermal tremor','Conduit resonance']::text[],ARRAY['Reading loudness as gas quantity without accounting for vent geometry','Ignoring wind, which both masks and mimics broadband vent noise','Assuming a single tone when vent flow is usually broadband']::text[],ARRAY['Tracking degassing trends at a fumarole field over time','Detecting a change in vent flow from a shift in the sound spectrum','Monitoring a hazardous vent remotely to avoid toxic-gas exposure']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fumarole acoustic signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c763d9da-8e8f-5d07-b92f-b88e9a53e586','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c763d9da-8e8f-5d07-b92f-b88e9a53e586') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c763d9da-8e8f-5d07-b92f-b88e9a53e586');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3d92f159-e044-5bb8-a670-a1909df8c44a','Degassing acoustic pulse','A discrete acoustic transient radiated when a pocket or slug of pressurised gas is released abruptly at or near a vent, producing a short pressure pulse that is often dominated by infrasound. The waveform commonly shows a sharp compressional onset followed by a rarefaction, and repeated pulses reflect the rhythm of intermittent gas escape from the shallow system.','Sometimes gas escapes a vent in short bursts. Each burst sends out a quick pressure pulse. The pulse starts with a push, then a pull, in the air. Much of it is too low to hear. Repeated bursts show the rhythm of gas leaving the volcano.','It marks individual gas-release events, letting scientists count and time discrete degassing and estimate the gas volume released.','Infrasound arrays record degassing pulses at open-vent volcanoes to quantify puffing behaviour and shallow gas dynamics.','Geologic & Seismoacoustics',ARRAY['Bubble-burst infrasound','Volcanic explosion waveform','Gas slug resonance','Infrasound','Fumarole acoustic signal']::text[],ARRAY['Confusing a small degassing pulse with a full explosion waveform','Counting overlapping pulses as one event in windy conditions','Ignoring the rarefaction phase when interpreting the source']::text[],ARRAY['Counting gas puffs at an open-vent volcano from infrasound pulses','Estimating released gas volume from pulse amplitude','Distinguishing routine degassing from an escalating explosion sequence']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Degassing acoustic pulse');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3d92f159-e044-5bb8-a670-a1909df8c44a','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3d92f159-e044-5bb8-a670-a1909df8c44a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3d92f159-e044-5bb8-a670-a1909df8c44a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8bcb821c-92fc-5d98-a948-1781be98e1e7','Bubble-burst infrasound','Infrasonic pressure signal produced when a large gas bubble bursts at the magma free surface, as in Strombolian activity, rupturing a thin magma film and abruptly releasing pressurised gas to the atmosphere. The characteristic waveform is a short impulse with a compressional onset followed by a rarefaction, and its amplitude scales with the overpressure and bubble size at the moment of rupture.','At some volcanoes, big gas bubbles rise and pop at the surface. Each pop tears a thin skin of magma. Gas then rushes into the air very fast. This makes a short, very low sound pulse. The bigger the bubble and pressure, the stronger the pulse.','It provides a direct acoustic measure of individual bubble bursts, letting scientists estimate bubble size and overpressure at the surface.','Infrasound sensors at Strombolian volcanoes record bubble-burst pulses to quantify explosion rate, gas release, and eruption style.','Geologic & Seismoacoustics',ARRAY['Gas slug resonance','Degassing acoustic pulse','Strombolian eruption','Infrasound','Volcanic explosion waveform']::text[],ARRAY['Assuming the burst is audible when its main energy is infrasonic','Estimating bubble size from amplitude while ignoring source-to-sensor distance','Treating every burst as identical when overpressure varies widely']::text[],ARRAY['Estimating gas overpressure from Strombolian burst pulses','Measuring the rate of bubble bursts during an eruptive episode','Pairing infrasound bursts with video of bursting bubbles']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bubble-burst infrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8bcb821c-92fc-5d98-a948-1781be98e1e7','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8bcb821c-92fc-5d98-a948-1781be98e1e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8bcb821c-92fc-5d98-a948-1781be98e1e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '626d87ff-d454-5e53-9311-d86371b85ad6','Magma conduit resonance','Acoustic resonance of the magma-filled section of a volcanic conduit, where the column of bubbly magma acts as a resonator whose modes are set by conduit length and geometry and by the very low sound speed of the gas-charged melt. Because bubbles sharply reduce the mixture sound speed, resonant frequencies fall into the seismic and infrasonic range, producing long-period events and tremor that track magma level and gas content.','The magma-filled part of a volcanic pipe can ring. Sound travels slowly through bubbly magma. So the ringing is at a very low pitch. The length of the magma column sets the note. As magma rises or gas builds, the note changes.','It ties measurable low-frequency volcanic signals to the length and gas content of the magma column, helping track magma ascent.','Seismologists model long-period events and tremor as magma conduit resonance to infer magma level and degassing state during unrest.','Geologic & Seismoacoustics',ARRAY['Conduit resonance','Crack resonance','Long-period event','Volcanic tremor','Gas slug resonance']::text[],ARRAY['Using a high melt-only sound speed instead of the low bubbly-mixture speed','Assuming the magma column length is fixed during an eruption','Confusing magma resonance with resonance of a purely gas-filled conduit']::text[],ARRAY['Tracking magma rise from a drifting resonant frequency','Estimating gas content in the column from the mixture sound speed','Distinguishing magma resonance from shallow gas or crack resonance']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magma conduit resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '626d87ff-d454-5e53-9311-d86371b85ad6','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='626d87ff-d454-5e53-9311-d86371b85ad6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='626d87ff-d454-5e53-9311-d86371b85ad6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9784d2f0-1889-5757-8631-dd1c4b2027c8','Volcanic explosion waveform','The acoustic pressure time series radiated by a discrete volcanic explosion, typically beginning with a sharp compressional onset followed by a rarefaction and sometimes a coda from secondary sources or path effects. Its peak amplitude, duration, and spectral content are used to estimate source overpressure, vent size, and the energy of the explosion, and it is the acoustic analogue of the seismic source signal.','A volcanic explosion makes a clear pressure signal in the air. It starts with a strong push, then a pull. Sensors record this shape over time. The size and length of the signal show how strong the blast was. Much of the energy is below what people can hear.','It encodes the strength and timing of an explosion at the vent, so its shape and size let scientists estimate energy and overpressure.','Observatories measure explosion waveforms on infrasound sensors to rank blast size, confirm eruptions, and issue timely alerts.','Geologic & Seismoacoustics',ARRAY['Bubble-burst infrasound','Degassing acoustic pulse','Volcanic jet noise','Source time function','Infrasound']::text[],ARRAY['Reading only the peak and ignoring the informative rarefaction and coda','Comparing amplitudes without correcting for distance and wind','Assuming the airborne waveform matches the seismic signal one to one']::text[],ARRAY['Ranking explosion size from peak infrasound pressure','Confirming a discrete blast against continuous jet noise','Estimating source overpressure from waveform shape']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volcanic explosion waveform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9784d2f0-1889-5757-8631-dd1c4b2027c8','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9784d2f0-1889-5757-8631-dd1c4b2027c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9784d2f0-1889-5757-8631-dd1c4b2027c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b50c8c37-f3db-58fe-aff8-61fccaffdde4','Source time function','The time history of energy or momentum release at a seismic or acoustic source, describing how the source strength evolves during rupture or excitation independent of propagation and instrument effects. In seismology it is often the moment-rate function whose integral gives the seismic moment and whose duration and shape reflect rupture size and dynamics; the recorded signal is the source time function convolved with the medium''s response and the instrument response.','This describes how a source gives off energy over time. It is the source by itself, without path or sensor effects. Its length tells you how long the rupture lasted. Its area relates to the total size of the event. The recording is this shape blended with the path and the sensor.','It isolates what the source actually did from distortions added by the Earth and the recording system, enabling fair comparison of event size and dynamics.','Analysts recover the source time function by deconvolution to measure seismic moment, rupture duration, and source complexity of earthquakes and explosions.','Geologic & Seismoacoustics',ARRAY['Seismic moment','Moment-rate function','Deconvolution','Volcanic explosion waveform','Green''s function']::text[],ARRAY['Mistaking the recorded seismogram for the source time function itself','Ignoring the instrument and path response that shape the observed signal','Assuming a simple triangular pulse when real ruptures are complex']::text[],ARRAY['Deconvolving records to estimate an earthquake''s rupture duration','Comparing source time functions of explosions versus earthquakes','Measuring seismic moment from the area of the moment-rate function']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source time function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b50c8c37-f3db-58fe-aff8-61fccaffdde4','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b50c8c37-f3db-58fe-aff8-61fccaffdde4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b50c8c37-f3db-58fe-aff8-61fccaffdde4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef8eb92e-761a-52e7-8374-5cdcb752e9f9','Seismoacoustic coupling','The transfer of energy across the ground-atmosphere interface between seismic waves in the solid Earth and acoustic waves in the air. Coupling operates in both directions: ground motion radiates sound into the atmosphere, and atmospheric pressure waves induce ground motion, with efficiency governed by the impedance contrast, the matching of wave speeds and slownesses, and the source geometry. It underlies the joint interpretation of collocated seismic and infrasound data.','The ground and the air can trade energy at the surface. Ground shaking can push on the air and make sound. Sound in the air can also shake the ground. How well this works depends on the two speeds matching up. Scientists use both signals together to study a source.','It explains why one event appears on both seismic and acoustic sensors and provides the physical basis for combining the two data types.','Analysts exploit seismoacoustic coupling to associate ground and air signals from the same source and to separate local from distant events.','Geologic & Seismoacoustics',ARRAY['Air-to-ground coupling','Ground-to-air coupling','Air-coupled Rayleigh wave','Impedance contrast','Infrasound']::text[],ARRAY['Assuming coupling is one-way when energy transfers in both directions','Ignoring the impedance mismatch that makes coupling generally weak','Expecting identical waveforms in air and ground despite different speeds']::text[],ARRAY['Associating a seismic arrival with its infrasound counterpart','Explaining air-coupled Rayleigh waves from a passing pressure wave','Designing collocated sensor networks for joint analysis']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismoacoustic coupling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef8eb92e-761a-52e7-8374-5cdcb752e9f9','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef8eb92e-761a-52e7-8374-5cdcb752e9f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef8eb92e-761a-52e7-8374-5cdcb752e9f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20e3a32f-ea38-59d9-a9ec-ca862feff9cd','Air-to-ground coupling','The process by which atmospheric pressure waves induce motion in the solid ground at the air-ground interface, converting airborne acoustic energy into seismic waves. A common manifestation is the air-coupled Rayleigh wave, in which a travelling atmospheric pressure disturbance loads the surface and generates a ground wave moving at the acoustic trace velocity; efficiency depends on the impedance contrast and on matching of the horizontal phase speeds.','Sound in the air can shake the ground it passes over. The moving pressure wave presses on the surface. That pressure sets off a wave in the ground. This often appears as a ground wave that keeps pace with the air wave. The effect is usually weak but clearly measurable.','It explains ground signals caused by airborne sources and lets seismometers detect and time atmospheric events such as explosions and eruptions.','Seismologists recognise air-coupled arrivals on seismograms from blasts, thunder, or eruptions and use them to locate airborne sources.','Geologic & Seismoacoustics',ARRAY['Seismoacoustic coupling','Ground-to-air coupling','Air-coupled Rayleigh wave','Apparent velocity','Infrasound']::text[],ARRAY['Mistaking an air-coupled arrival for a genuine subsurface seismic phase','Ignoring that the ground wave travels at the acoustic trace speed','Assuming strong coupling despite the large air-ground impedance contrast']::text[],ARRAY['Identifying air-coupled Rayleigh waves from a quarry blast on seismograms','Using seismometers to detect an atmospheric explosion','Separating airborne-induced ground motion from direct seismic arrivals']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air-to-ground coupling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20e3a32f-ea38-59d9-a9ec-ca862feff9cd','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20e3a32f-ea38-59d9-a9ec-ca862feff9cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20e3a32f-ea38-59d9-a9ec-ca862feff9cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a1868c8-5028-532c-902b-975d707cb334','Ground-to-air coupling','The radiation of acoustic energy into the atmosphere by ground motion at the surface, converting seismic vibration into airborne sound and infrasound. Vertical surface velocity acts as a moving piston on the air, so large-amplitude or broad-area ground motion, as from earthquakes, rockfalls, or explosions, can generate locally recordable air pressure signals; efficiency is limited by the impedance contrast between rock and air.','Shaking ground can push on the air and make sound. The moving surface acts like a giant speaker cone. Strong or wide ground motion makes the most sound. Earthquakes and rockfalls can be heard this way. The effect is weak because rock and air are so different.','It explains airborne signals produced by ground sources and supports detecting seismic events with acoustic and infrasound sensors.','Infrasound arrays record ground-to-air signals from large earthquakes and landslides to complement seismic detection and locate the source.','Geologic & Seismoacoustics',ARRAY['Seismoacoustic coupling','Air-to-ground coupling','Infrasound','Rayleigh wave','Impedance contrast']::text[],ARRAY['Overestimating radiated sound given the weak rock-to-air coupling','Confusing epicentral infrasound from ground motion with the atmospheric source','Ignoring topography, which focuses and scatters the radiated sound']::text[],ARRAY['Detecting infrasound radiated by a large earthquake''s ground motion','Recording air pressure signals from a rockfall or landslide','Locating a seismic event using its radiated acoustic signal']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ground-to-air coupling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a1868c8-5028-532c-902b-975d707cb334','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a1868c8-5028-532c-902b-975d707cb334') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a1868c8-5028-532c-902b-975d707cb334');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6dc5b119-fc60-5323-aa8d-a7bbbaf9793d','Backazimuth','The horizontal direction from a receiver or sensor array back toward the source of a detected wave, measured clockwise from geographic north. In array processing it is estimated from the horizontal slowness vector determined by the time delays of a coherent arrival across the array elements, and together with a distance estimate it constrains the source location.','Backazimuth is the compass direction from a sensor to the source. It is measured clockwise from north. An array of sensors finds it from tiny arrival-time differences. The wave hits nearer sensors first. That pattern points back toward where the signal came from.','It provides the direction to a source, which combined with range or crossing bearings from other arrays yields a location.','Array analysts compute backazimuth for seismic and infrasound arrivals to point toward earthquakes, explosions, and eruptions.','Geologic & Seismoacoustics',ARRAY['Infrasound backazimuth','Apparent velocity','Slowness','Array processing','Beamforming']::text[],ARRAY['Confusing backazimuth (toward the source) with azimuth (toward the receiver)','Reporting the direction the wave travels instead of the direction to the source','Ignoring cross-wind or dipping-layer bias that skews the estimate']::text[],ARRAY['Pointing an array toward an unknown explosion source','Combining backazimuths from two arrays to locate an event','Checking a backazimuth estimate against a known source direction']::text[],'intermediate','beta = atan2(-s_E, -s_N) (mod 360 deg)','Backazimuth equals the compass bearing of the negative horizontal slowness vector, using its east and north components, reduced to the range zero to three hundred sixty degrees.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Backazimuth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6dc5b119-fc60-5323-aa8d-a7bbbaf9793d','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6dc5b119-fc60-5323-aa8d-a7bbbaf9793d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6dc5b119-fc60-5323-aa8d-a7bbbaf9793d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2adc9fae-ea34-59f3-9834-c13b92508ead','Infrasound backazimuth','The backazimuth estimated specifically from an infrasound array, giving the horizontal direction from the array to the source of a coherent low-frequency atmospheric signal, measured clockwise from north. It is derived from the acoustic slowness vector via time delays across the array, but is subject to bias from cross-winds and atmospheric structure that deflect the effective propagation direction.','This is the backazimuth found from an infrasound array. It gives the compass direction to a low-pitch sound source. The array reads the sound''s arrival-time pattern to get it. Wind can bend the sound and shift the direction slightly. Analysts correct for this when they can.','It points toward atmospheric acoustic sources such as explosions and eruptions, supporting detection and location by infrasound networks.','Infrasound analysts compute backazimuth for each detection to associate arrivals and locate distant explosive sources.','Geologic & Seismoacoustics',ARRAY['Backazimuth','Apparent velocity','Infrasonic celerity','Atmospheric ducting','Array processing']::text[],ARRAY['Ignoring cross-wind deflection that biases the measured direction','Treating the backazimuth as exact despite atmospheric bending of rays','Failing to correct for known winds when precise bearing is needed']::text[],ARRAY['Locating a distant eruption from crossing infrasound backazimuths','Correcting a bearing for stratospheric cross-winds','Associating multi-array infrasound detections to one source']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Infrasound backazimuth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2adc9fae-ea34-59f3-9834-c13b92508ead','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2adc9fae-ea34-59f3-9834-c13b92508ead') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2adc9fae-ea34-59f3-9834-c13b92508ead');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53ee5807-7e96-59e2-96ea-d28a5fb6e309','Apparent velocity','The speed at which a wavefront appears to sweep across the surface between sensors, equal to the true wave speed divided by the sine of the angle of incidence measured from the vertical, and equivalently the reciprocal of the horizontal slowness. It is always greater than or equal to the true propagation speed, approaching infinity for vertically incident waves, and is measured directly from arrival-time differences across an array.','This is how fast a wavefront seems to cross the ground between sensors. It depends on the angle the wave arrives at. A steep, near-vertical wave seems to race across very fast. A shallow, grazing wave crosses more slowly. It is always at least as large as the true speed.','It reveals the arrival angle and helps identify wave type and source depth, and it feeds slowness-based location and phase identification.','Array analysts measure apparent velocity to tell steep body-wave arrivals from shallow surface or acoustic arrivals.','Geologic & Seismoacoustics',ARRAY['Slowness','Backazimuth','Angle of incidence','Trace velocity','Array processing']::text[],ARRAY['Confusing apparent velocity with the true wave speed in the medium','Forgetting it grows without bound for near-vertical incidence','Assuming it can be less than the true speed, which it never is']::text[],ARRAY['Separating steep P arrivals from shallow surface waves at an array','Estimating incidence angle from measured apparent velocity','Flagging air-coupled arrivals by their low apparent velocity']::text[],'intermediate','v_app = c / sin(i) = 1 / |p_h|','Apparent velocity equals the true wave speed divided by the sine of the incidence angle from vertical, which also equals one over the horizontal slowness magnitude.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Apparent velocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53ee5807-7e96-59e2-96ea-d28a5fb6e309','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53ee5807-7e96-59e2-96ea-d28a5fb6e309') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53ee5807-7e96-59e2-96ea-d28a5fb6e309');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4df33a41-483d-569e-b238-11fe26b9985a','Infrasonic celerity','The effective horizontal propagation speed of an infrasound arrival along the great-circle path, defined as the source-to-receiver range divided by the total travel time. Because atmospheric arrivals travel via different ducts, celerity groups them into families: near-surface tropospheric arrivals are fastest, stratospheric returns are intermediate, and thermospheric returns are slowest, so celerity is a key discriminant for phase identification.','Celerity is the average speed of an infrasound signal along its path. You get it by dividing the distance by the total travel time. Different sky paths give different speeds. Signals near the ground arrive fastest. Signals that bounce high in the sky arrive slowest.','It sorts infrasound arrivals by the atmospheric path they took, aiding phase identification and source location.','Infrasound analysts compute celerity for each detection to label tropospheric, stratospheric, or thermospheric arrivals and refine locations.','Geologic & Seismoacoustics',ARRAY['Apparent velocity','Atmospheric ducting','Stratospheric duct','Thermospheric duct','Infrasound backazimuth']::text[],ARRAY['Confusing celerity, an along-path average, with local phase or apparent velocity','Using straight-line distance instead of the great-circle range','Ignoring how winds shift celerity ranges for each duct']::text[],ARRAY['Labelling an arrival as stratospheric from its celerity','Refining a source time using celerity-based path assignment','Separating multiple ducted arrivals from one explosion']::text[],'advanced','celerity = D / t','Celerity equals the great-circle distance from source to receiver divided by the total travel time of the arrival.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Infrasonic celerity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4df33a41-483d-569e-b238-11fe26b9985a','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4df33a41-483d-569e-b238-11fe26b9985a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4df33a41-483d-569e-b238-11fe26b9985a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7d922e0-c403-5bfb-a2d5-99a3d2b3ef6a','Atmospheric ducting','The trapping and guiding of acoustic energy within atmospheric layers where the vertical profiles of temperature and wind create a waveguide that refracts rays back toward the ground. When the effective sound speed aloft exceeds that at the source height, downward refraction returns energy to the surface, allowing infrasound to propagate efficiently over long distances between successive ground reflections, while leaving shadow zones where no direct energy arrives.','The atmosphere can act like a channel for sound. Wind and temperature layers bend sound rays back down. The sound then skips along between the ground and the sky. This lets low sounds travel very far. Between the skips there are quiet shadow zones.','It explains how infrasound reaches distant sensors and why arrivals cluster into paths tied to specific atmospheric layers.','Analysts model atmospheric ducting to predict which infrasound arrivals will be observed and to interpret detection ranges.','Geologic & Seismoacoustics',ARRAY['Stratospheric duct','Thermospheric duct','Tropospheric duct','Acoustic shadow zone','Infrasonic celerity']::text[],ARRAY['Assuming sound weakens smoothly with distance instead of ducting to far ranges','Ignoring wind, which can open a duct in one direction and close it in another','Forgetting that ducting creates silent shadow zones between bounces']::text[],ARRAY['Predicting whether a distant array will detect an eruption','Explaining why an event is heard far away but not nearby','Modelling seasonal changes in infrasound detection with wind']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Atmospheric ducting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7d922e0-c403-5bfb-a2d5-99a3d2b3ef6a','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7d922e0-c403-5bfb-a2d5-99a3d2b3ef6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7d922e0-c403-5bfb-a2d5-99a3d2b3ef6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd1e8c4e-587c-57e4-90e8-17d7ec6a7c18','Stratospheric duct','An atmospheric waveguide formed between the ground and the upper stratosphere, near about 50 kilometres altitude, where increasing temperature and the stratospheric wind jet raise the effective sound speed enough to refract infrasound back to the surface. Stratospheric arrivals have intermediate celerity and are strongly controlled by the direction of the stratospheric winds, so the duct is efficient downwind and weak or absent upwind.','This is a sound channel high in the atmosphere. It reaches up to about fifty kilometres. Warm air and strong winds there bend sound back to the ground. These signals arrive at a middle speed. The channel works best when the wind blows toward the sensor.','It provides a common long-range path for infrasound and explains seasonal, wind-controlled changes in detection.','Infrasound analysts identify stratospheric arrivals by celerity and use seasonal wind reversals to interpret detectability.','Geologic & Seismoacoustics',ARRAY['Atmospheric ducting','Thermospheric duct','Tropospheric duct','Infrasonic celerity','Stratospheric wind']::text[],ARRAY['Expecting equal returns upwind and downwind despite wind control','Confusing stratospheric arrivals with slower thermospheric ones','Assuming the duct is present year-round regardless of wind reversal']::text[],ARRAY['Explaining stronger detections downwind of the stratospheric jet','Labelling an arrival as stratospheric from its celerity','Interpreting seasonal detection changes at an infrasound station']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stratospheric duct');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd1e8c4e-587c-57e4-90e8-17d7ec6a7c18','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd1e8c4e-587c-57e4-90e8-17d7ec6a7c18') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd1e8c4e-587c-57e4-90e8-17d7ec6a7c18');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3f898eff-594c-5348-8594-3fea3f45ba0b','Thermospheric duct','An atmospheric path in which infrasound refracts back to the ground from the thermosphere, above roughly 100 to 120 kilometres, where the sharp rise in temperature increases the effective sound speed. Thermospheric returns are almost always present but are strongly attenuated and distorted by the low density and high absorption at those altitudes, giving them the lowest celerity and the most diffuse, low-frequency character.','This is a very high sound path in the atmosphere. Sound bends back from above one hundred kilometres up. The air there is hot but extremely thin. That thin air soaks up much of the sound. So these signals arrive slowest, weak, and smeared out.','It provides an almost ever-present but weak long-range path, filling gaps when lower ducts are closed by winds.','Analysts recognise thermospheric arrivals by their low celerity and diffuse low-frequency shape when interpreting infrasound detections.','Geologic & Seismoacoustics',ARRAY['Atmospheric ducting','Stratospheric duct','Tropospheric duct','Infrasonic celerity','Atmospheric absorption']::text[],ARRAY['Expecting sharp, strong arrivals when thermospheric returns are weak and smeared','Ignoring strong high-altitude absorption of higher frequencies','Confusing the slow thermospheric arrival with a separate later event']::text[],ARRAY['Attributing a weak late arrival to a thermospheric path','Explaining detections when stratospheric ducting is absent','Accounting for high-frequency loss along a thermospheric path']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermospheric duct');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3f898eff-594c-5348-8594-3fea3f45ba0b','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3f898eff-594c-5348-8594-3fea3f45ba0b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3f898eff-594c-5348-8594-3fea3f45ba0b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '386b7732-d708-5088-894c-f049b0cb3829','Tropospheric duct','A low-altitude atmospheric waveguide within the troposphere, typically formed near the surface by a temperature inversion or a low-level wind jet that refracts acoustic energy back downward. Tropospheric ducting confines infrasound close to the ground and gives the fastest arrivals, with the highest celerity, but the duct is shallow, variable, and sensitive to local weather.','This is a low sound channel near the ground. It forms when a warm layer or wind sits just above the surface. That layer bends sound back down. Signals stay close to the ground and arrive fastest. The channel is shallow and changes with the weather.','It explains fast, near-surface infrasound arrivals and short-range guiding controlled by local weather conditions.','Analysts identify tropospheric arrivals by their high celerity and account for local weather when interpreting near-source detections.','Geologic & Seismoacoustics',ARRAY['Atmospheric ducting','Stratospheric duct','Thermospheric duct','Infrasonic celerity','Temperature inversion']::text[],ARRAY['Assuming the tropospheric duct is stable when it shifts with weather','Confusing fast tropospheric arrivals with the direct wave','Ignoring surface inversions that open a shallow near-ground duct']::text[],ARRAY['Explaining a fast near-ground arrival from a nearby blast','Relating a dawn inversion to enhanced short-range infrasound','Labelling an arrival as tropospheric from its high celerity']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tropospheric duct');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '386b7732-d708-5088-894c-f049b0cb3829','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='386b7732-d708-5088-894c-f049b0cb3829') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='386b7732-d708-5088-894c-f049b0cb3829');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96fae574-cd0c-598d-961e-bbbe3c7abea9','Acoustic shadow zone','A region where little or no direct acoustic energy arrives because upward refraction, caused by a decrease of effective sound speed with height, bends rays away from the surface. Shadow zones form between the source and the range where ducted energy returns to the ground; within them signals are weak or absent except for diffracted, scattered, or ducted contributions.','A shadow zone is a quiet gap where sound does not reach directly. It happens when sound speed drops with height. Rays then bend upward and away from the ground. So an area near a loud source can stay silent. Sound returns only farther away where the path bends back.','It explains why a strong source can be inaudible at some ranges and guides expectations for where detections will and will not occur.','Analysts use shadow-zone geometry to explain missing detections and to plan sensor placement around a known source.','Geologic & Seismoacoustics',ARRAY['Atmospheric ducting','Sound speed profile','Infrasound','Refraction','Diffraction']::text[],ARRAY['Assuming a silent zone means no source rather than upward refraction','Ignoring diffracted and scattered energy that leaks into the shadow','Treating the shadow-zone edge as fixed despite changing weather']::text[],ARRAY['Explaining why a nearby eruption is unheard while distant sites detect it','Placing sensors to avoid a predicted shadow zone','Interpreting a gap in detections along a profile']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic shadow zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96fae574-cd0c-598d-961e-bbbe3c7abea9','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96fae574-cd0c-598d-961e-bbbe3c7abea9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96fae574-cd0c-598d-961e-bbbe3c7abea9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12608555-3e03-5300-8b63-40ec4f0e9031','Seismic-acoustic discrimination','The process of distinguishing whether a recorded signal, or a given phase within it, originated as a seismic wave in the ground or as an acoustic wave in the air, and of telling different source types apart using joint seismic and infrasound data. Discriminants include apparent velocity, celerity, frequency content, the time and amplitude relationship between collocated seismic and acoustic channels, and waveform shape.','This means telling ground signals apart from air signals. It also means telling different kinds of sources apart. Analysts compare speed, timing, and pitch across sensors. A ground wave and an air wave behave differently. These clues reveal what really made the signal.','It prevents misidentifying airborne arrivals as subsurface phases and helps separate explosions, eruptions, and earthquakes.','Monitoring analysts combine collocated seismic and infrasound data to classify events and reject air-coupled arrivals from earthquake catalogues.','Geologic & Seismoacoustics',ARRAY['Seismoacoustic coupling','Apparent velocity','Infrasonic celerity','Air-coupled Rayleigh wave','Array processing']::text[],ARRAY['Logging an air-coupled arrival as a genuine seismic phase','Relying on a single discriminant instead of several together','Ignoring the timing offset expected between air and ground channels']::text[],ARRAY['Separating a quarry blast''s air and ground signals','Deciding whether a signal is an eruption or a local earthquake','Cleaning air-coupled arrivals from a seismic catalogue']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismic-acoustic discrimination');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12608555-3e03-5300-8b63-40ec4f0e9031','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12608555-3e03-5300-8b63-40ec4f0e9031') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12608555-3e03-5300-8b63-40ec4f0e9031');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '93b2b216-d87f-5fef-9a57-ce4de2c57b18','Bedload acoustic monitoring','A technique that infers the transport of coarse sediment along a river bed from the seismic or acoustic noise generated by grain impacts and collisions. Passive sensors, such as riverbank seismometers or hydrophones and impact plates, record the self-generated noise whose amplitude and frequency content scale with grain size and transport rate, enabling continuous, non-intrusive estimates of bedload flux.','Rivers drag stones and gravel along the bottom. Those grains hit and knock together. This makes a faint rumble in the ground and water. Sensors on the bank or bed record it. Its strength and pitch reveal how much sediment is moving.','It provides continuous, non-contact measurement of coarse sediment transport that is otherwise very hard to sample directly in flow.','Hydrologists deploy bankside seismometers, hydrophones, or impact plates to monitor bedload during floods and to calibrate transport models.','Geologic & Seismoacoustics',ARRAY['Fluvial acoustic monitoring','Sediment-impact noise','Self-generated noise','Hydrophone','Bedload transport']::text[],ARRAY['Attributing all river noise to bedload while ignoring turbulence and water flow','Assuming a fixed calibration across different grain sizes and channels','Ignoring site effects that change how impact noise reaches the sensor']::text[],ARRAY['Tracking gravel transport during a flood from bankside seismic noise','Calibrating bedload flux against direct sediment samples','Monitoring sediment supply to a reservoir continuously']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bedload acoustic monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '93b2b216-d87f-5fef-9a57-ce4de2c57b18','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='93b2b216-d87f-5fef-9a57-ce4de2c57b18') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='93b2b216-d87f-5fef-9a57-ce4de2c57b18');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11d2e136-e7e1-5515-8ca3-6ee99dd41375','Fluvial acoustic monitoring','The passive recording and analysis of seismic and acoustic signals generated by rivers, including turbulent water flow, bedload grain impacts, and cavitation, to infer discharge, sediment transport, and channel processes. Sensors placed near or in the channel capture broadband noise whose spectral bands separate water-flow turbulence from coarse-sediment impacts, giving continuous proxies for river dynamics.','Rivers make sound and ground vibration as they flow. Rushing water and tumbling stones both add to it. Sensors near the river record this noise. Different pitches come from water and from moving sediment. Scientists use it to track flow and sediment over time.','It turns river-generated noise into continuous, remote estimates of discharge and sediment movement without disturbing the flow.','Researchers install seismometers or hydrophones beside rivers to monitor floods, sediment transport, and channel change.','Geologic & Seismoacoustics',ARRAY['Bedload acoustic monitoring','Sediment-impact noise','Self-generated noise','Turbulent flow noise','Hydrophone']::text[],ARRAY['Mixing water-flow noise and sediment-impact noise into one uninterpreted signal','Assuming the sensor response is flat across the relevant frequency bands','Ignoring rainfall and wind noise that contaminate the record']::text[],ARRAY['Estimating river discharge from flow-turbulence noise','Monitoring a flood''s sediment pulse from bankside sensors','Detecting channel change through shifts in the noise spectrum']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fluvial acoustic monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11d2e136-e7e1-5515-8ca3-6ee99dd41375','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11d2e136-e7e1-5515-8ca3-6ee99dd41375') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11d2e136-e7e1-5515-8ca3-6ee99dd41375');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '820abe28-71be-5807-b0b7-4456849e6567','Sediment-impact noise','The high-frequency seismic and acoustic noise produced by collisions of transported sediment grains with the river bed, with fixed obstacles, and with each other during bedload transport. Each impact radiates a brief elastic and acoustic pulse; the summed noise typically occupies a higher frequency band than water-flow turbulence, and its power scales with grain size and impact rate, making it a proxy for coarse-sediment flux.','Moving grains in a river keep hitting the bed and each other. Every hit sends out a tiny burst of sound. Many hits together make a steady hiss. Bigger grains and faster transport make it louder. Its pitch is higher than the noise of the water itself.','It isolates the acoustic signature of coarse-sediment collisions, letting analysts separate bedload activity from water-flow noise.','Analysts filter for the sediment-impact band in river seismic or hydrophone records to estimate bedload timing and intensity.','Geologic & Seismoacoustics',ARRAY['Bedload acoustic monitoring','Fluvial acoustic monitoring','Self-generated noise','Turbulent flow noise','Bedload transport']::text[],ARRAY['Confusing sediment-impact noise with lower-frequency water-turbulence noise','Assuming amplitude gives grain size without a site calibration','Overlooking that a few large grains can dominate the signal']::text[],ARRAY['Isolating the impact band to time the start of bedload motion','Relating impact-noise power to transported grain size','Distinguishing a debris pulse from steady water flow']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sediment-impact noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '820abe28-71be-5807-b0b7-4456849e6567','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='820abe28-71be-5807-b0b7-4456849e6567') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='820abe28-71be-5807-b0b7-4456849e6567');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7641e617-7518-5728-9a8e-ddf0fec4e88e','Glacial calving acoustic pulse','The seismic and acoustic signal radiated when a block of ice detaches from a glacier or ice-cliff terminus and impacts the water or ground. Calving generates icequakes in the solid Earth and ice, low-frequency underwater sound, and airborne infrasound; pulse amplitude and duration scale with the size and style of the calving event, making the signals a remote proxy for calving flux.','When ice breaks off a glacier front, it makes a strong pulse of sound. The break shakes the ground and the ice. The falling block also thunders into the water. Sensors record the shaking, the underwater boom, and low air sound. Bigger blocks make stronger, longer pulses.','It provides a remote, continuous record of calving events, letting scientists count and size ice loss without watching the cliff directly.','Glaciologists use seismometers, hydrophones, and infrasound sensors to detect and size calving events and to estimate ice-loss rates.','Geologic & Seismoacoustics',ARRAY['Icequake','Ice-shelf flexural wave','Infrasound','Cryoseismology','Calving flux']::text[],ARRAY['Assuming pulse amplitude alone gives calving volume without calibration','Confusing calving signals with ordinary tectonic earthquakes','Ignoring the different signals in ground, water, and air from one event']::text[],ARRAY['Counting calving events at a marine glacier front remotely','Estimating ice-loss rate from calving pulse rate and size','Combining seismic and underwater sound to characterise a calving']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Glacial calving acoustic pulse');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7641e617-7518-5728-9a8e-ddf0fec4e88e','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7641e617-7518-5728-9a8e-ddf0fec4e88e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7641e617-7518-5728-9a8e-ddf0fec4e88e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67c66908-3531-5953-b7da-bbf7af32e9ef','Ice-shelf flexural wave','A flexural-gravity wave that propagates by bending a floating ice shelf resting on water, in which the elastic plate stiffness of the ice and the buoyancy of the underlying ocean jointly provide the restoring force. Excited by ocean swell, infragravity waves, tsunamis, and calving, these long-period waves flex the shelf and can promote fracture; their dispersion depends on ice thickness, elastic properties, and water depth.','A floating ice shelf can bend like a stiff sheet on water. Ocean waves and swells make it flex slowly up and down. This bending wave travels across the shelf. The ice stiffness and the water below control how it moves. Strong flexing can help crack the ice.','It describes how ocean forcing flexes floating ice, linking sea-wave energy to ice-shelf stress, fracture, and stability.','Glaciologists record flexural waves with seismometers on ice shelves to study swell coupling, fracture, and break-up risk.','Geologic & Seismoacoustics',ARRAY['Glacial calving acoustic pulse','Flexural-gravity wave','Infragravity wave','Cryoseismology','Ice-shelf fracture']::text[],ARRAY['Treating the ice as a simple fluid rather than a bending elastic plate','Ignoring water depth and ice thickness in the dispersion','Assuming only local sources excite it, overlooking distant ocean swell']::text[],ARRAY['Linking distant storm swell to ice-shelf flexure','Assessing break-up risk from sustained flexural-wave activity','Interpreting long-period seismometer signals on a floating shelf']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ice-shelf flexural wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67c66908-3531-5953-b7da-bbf7af32e9ef','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67c66908-3531-5953-b7da-bbf7af32e9ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67c66908-3531-5953-b7da-bbf7af32e9ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd9a6fbfd-4785-582e-9752-61c010ee97b9','Firn acoustic propagation','The propagation of seismic and acoustic waves through firn, the porous layer of partially compacted snow that grades into glacial ice with depth. Because density and elastic moduli increase strongly with depth, wave speed rises rapidly through the firn column, producing pronounced velocity gradients that refract rays, trap energy in near-surface waveguides, and strongly disperse surface waves.','Firn is old snow that is packing down into ice. Near the top it is light and full of air. It gets denser and stiffer with depth. So sound speeds up as it goes deeper. This bends waves and can trap sound near the surface.','It governs how seismic and acoustic energy travels near a glacier surface, which is essential for interpreting cryoseismic records and imaging firn structure.','Glaciologists use firn wave speeds and surface-wave dispersion to map firn density and correct locations of icequakes.','Geologic & Seismoacoustics',ARRAY['Firn','Surface wave dispersion','Velocity gradient','Cryoseismology','Waveguide']::text[],ARRAY['Using a single ice velocity and ignoring the strong firn gradient','Overlooking near-surface trapping that distorts recorded waveforms','Assuming firn is homogeneous rather than steadily densifying with depth']::text[],ARRAY['Mapping firn density from surface-wave dispersion','Correcting icequake locations for firn velocity structure','Explaining trapped near-surface arrivals on a glacier']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Firn acoustic propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd9a6fbfd-4785-582e-9752-61c010ee97b9','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d9a6fbfd-4785-582e-9752-61c010ee97b9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d9a6fbfd-4785-582e-9752-61c010ee97b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6170d742-4bb5-5651-ae3e-8982447d2146','Permafrost acoustic emission','Transient elastic waves released within permafrost by microcracking and fracture associated with thermal stress, ice-lens growth, freeze-thaw cycling, and thawing-induced instability. These acoustic emissions are high-frequency, low-energy bursts detectable by sensitive sensors; their rate and character track internal cracking and can serve as an early indicator of ground instability.','Frozen ground can crack as it freezes and thaws. Each tiny crack sends out a small burst of sound. These bursts are faint and high in pitch. Sensitive sensors can count them. A rising count can warn that the ground is becoming unstable.','It offers an early, sensitive indicator of internal cracking in frozen ground, useful for anticipating thaw-related instability.','Engineers and geoscientists monitor permafrost acoustic emission to study freeze-thaw damage and to flag slope or foundation instability.','Geologic & Seismoacoustics',ARRAY['Acoustic emission','Kaiser effect','Rockburst acoustic emission','Freeze-thaw cycling','Cryoseismology']::text[],ARRAY['Confusing faint acoustic-emission bursts with larger seismic events','Ignoring temperature cycles that drive the cracking rate','Assuming a quiet period means stability during ongoing thaw']::text[],ARRAY['Watching a thawing slope for rising acoustic-emission rates','Studying freeze-thaw damage in a permafrost core or wall','Flagging foundation risk in warming frozen ground']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Permafrost acoustic emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6170d742-4bb5-5651-ae3e-8982447d2146','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6170d742-4bb5-5651-ae3e-8982447d2146') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6170d742-4bb5-5651-ae3e-8982447d2146');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '74ab8a71-2c4a-5720-a8e7-1b7a6ac90cad','Rockburst acoustic emission','The acoustic emission and microseismicity generated by the sudden, violent failure of highly stressed rock, as occurs in deep mines and tunnels. Rising stress drives progressive microcracking that radiates elastic waves; a marked increase and clustering of these emissions can precede a rockburst, so their monitoring supports hazard assessment, though bursts can still occur with little warning.','Deep in mines, rock under huge stress can fail suddenly and violently. Before it fails, tiny cracks form and grow. Each crack gives off a burst of elastic waves. A sharp rise in these bursts can warn of danger. But a rockburst can still strike with little or no warning.','It provides a monitored precursor to sudden rock failure, informing hazard assessment and mine-safety decisions in high-stress ground.','Mine geophysicists track acoustic emission and microseismicity to map stress concentration and to assess rockburst hazard.','Geologic & Seismoacoustics',ARRAY['Acoustic emission','Mine seismoacoustic monitoring','Microseismicity','Kaiser effect','Fracture-process zone']::text[],ARRAY['UNSAFE: treating a drop in acoustic emission as proof an area is safe to re-enter','Relying on emissions alone rather than combining several hazard indicators','Assuming every rockburst is preceded by a clear emission increase']::text[],ARRAY['Mapping stress buildup ahead of a deep mine face','Assessing rockburst hazard from clustering microseismicity','Correlating emission surges with support-system loading']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rockburst acoustic emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '74ab8a71-2c4a-5720-a8e7-1b7a6ac90cad','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='74ab8a71-2c4a-5720-a8e7-1b7a6ac90cad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='74ab8a71-2c4a-5720-a8e7-1b7a6ac90cad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e9bd3933-3626-5418-a963-43957783933f','Mine seismoacoustic monitoring','The combined recording of microseismic ground motion and acoustic emission in underground mines to detect, locate, and characterise rock fracturing, stress redistribution, and potential rockbursts. Networks of geophones, accelerometers, and acoustic-emission sensors span a range of frequencies, and event locations and rates are used to map stressed zones and support ground-control and safety decisions.','Mines use sensors to listen to the rock around them. The sensors catch both ground shaking and faint cracking sounds. Software finds where and when the cracks happen. This maps where the rock is most stressed. It helps crews manage ground control and safety.','It gives mine operators a real-time picture of rock behaviour, guiding support design and hazard warnings underground.','Mine geophysicists run geophone and acoustic-emission arrays to locate fracturing, track stress, and manage rockburst hazard.','Geologic & Seismoacoustics',ARRAY['Rockburst acoustic emission','Microseismicity','Acoustic emission','Fracture-process zone','Ground control']::text[],ARRAY['UNSAFE: relying solely on monitoring to declare ground safe without engineering controls','Assuming a fixed velocity model when mining changes the rock mass','Ignoring sensor coverage gaps that bias event locations']::text[],ARRAY['Locating fracturing around a deep mine excavation','Tracking stress redistribution after a blast','Supporting ground-control decisions from event maps']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mine seismoacoustic monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e9bd3933-3626-5418-a963-43957783933f','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e9bd3933-3626-5418-a963-43957783933f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e9bd3933-3626-5418-a963-43957783933f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf3c6ae8-3fe5-5725-bd11-7f8211e9c6d2','Fracture-process zone','The region of distributed microcracking, grain-scale damage, and nonlinear deformation surrounding and ahead of a propagating crack tip, where the material behaviour departs from linear elasticity. In rock, this zone is the primary source of acoustic emission during fracture, and its size and intensity control fracture toughness and the observed clustering of microseismic events near a growing crack.','Ahead of a growing crack, rock does not just split cleanly. A cloud of tiny cracks forms around the tip. This damaged region is the fracture-process zone. It is where most of the small cracking sounds come from. Its size controls how hard the rock is to break.','It explains where and why acoustic emission clusters near a crack tip and links microcracking to bulk fracture strength.','Rock mechanics researchers locate acoustic emission to image the process zone and to study fracture toughness in the lab and field.','Geologic & Seismoacoustics',ARRAY['Acoustic emission','Crack tip','Fracture toughness','Microseismicity','Rockburst acoustic emission']::text[],ARRAY['Treating the crack tip as a sharp point rather than a damaged zone','Assuming linear elasticity holds right up to the tip','Ignoring process-zone size effects when scaling lab results to the field']::text[],ARRAY['Imaging the process zone from clustered acoustic emission','Relating process-zone size to measured fracture toughness','Studying microcracking ahead of a laboratory rock crack']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fracture-process zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf3c6ae8-3fe5-5725-bd11-7f8211e9c6d2','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf3c6ae8-3fe5-5725-bd11-7f8211e9c6d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf3c6ae8-3fe5-5725-bd11-7f8211e9c6d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f3e62e30-1eb2-57a7-9224-f68def919798','Kaiser effect','The phenomenon in which a material under load emits little or no acoustic emission until the stress exceeds the maximum level previously experienced, at which point emission resumes strongly. Because the onset of renewed emission marks the prior peak stress, the effect is used in rock mechanics to estimate in-situ stress from cored samples and to assess a material''s loading history.','Load a rock and it makes cracking sounds. Unload it, then load it again. It stays quiet until you pass the old highest load. Then the cracking sounds return. This memory of past stress is the Kaiser effect.','It gives a way to read a material''s past peak stress from when acoustic emission restarts, revealing loading history.','Rock mechanics labs load cored samples and watch for the emission onset to estimate in-situ stress and prior loading.','Geologic & Seismoacoustics',ARRAY['Acoustic emission','Felicity effect','Felicity ratio','In-situ stress','Rockburst acoustic emission']::text[],ARRAY['Assuming the memory is perfect when time, damage, and rotation degrade it','Confusing the Kaiser effect with its breakdown, the Felicity effect','Ignoring loading-direction sensitivity when estimating stress']::text[],ARRAY['Estimating in-situ stress from cored samples in the lab','Reading a material''s prior peak load from emission onset','Checking whether a structure has been overloaded before']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kaiser effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f3e62e30-1eb2-57a7-9224-f68def919798','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f3e62e30-1eb2-57a7-9224-f68def919798') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f3e62e30-1eb2-57a7-9224-f68def919798');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23814179-0481-556d-bdf8-04f37108d03c','Felicity effect','The breakdown of the Kaiser effect, in which acoustic emission resumes on reloading before the previous maximum stress is reached, indicating accumulated damage or time-dependent weakening. The degree of breakdown is quantified by the Felicity ratio, the stress at emission onset divided by the previous maximum stress; a ratio below one signals significant damage and is used in structural integrity assessment.','Sometimes a loaded material starts cracking again too early. It makes sounds before reaching its old highest load. This early return breaks the usual memory rule. It shows the material has been damaged. Engineers measure how early it happens to judge integrity.','It flags accumulated damage or weakening by showing that emission returns below the prior peak, a key structural-health indicator.','Engineers compute the Felicity ratio during proof loading of pressure vessels and composites to assess damage and integrity.','Geologic & Seismoacoustics',ARRAY['Kaiser effect','Felicity ratio','Acoustic emission','Structural health monitoring','Damage accumulation']::text[],ARRAY['Treating a Felicity ratio near one as damaging when it signals sound material','Confusing the Felicity effect with the intact Kaiser effect','Ignoring rest time and creep that lower the ratio without new loading']::text[],ARRAY['Assessing a pressure vessel''s integrity by its Felicity ratio','Detecting accumulated damage in a composite during proof loading','Distinguishing damaged from intact material by early emission']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Felicity effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23814179-0481-556d-bdf8-04f37108d03c','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23814179-0481-556d-bdf8-04f37108d03c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23814179-0481-556d-bdf8-04f37108d03c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '64a3096c-521f-5866-beb6-15ec71ad4d90','Cosmic acoustic wave','A pressure wave propagating in the tightly coupled photon-baryon plasma of the early universe before recombination. Radiation pressure supplies the restoring force against gravitational compression in dark-matter potential wells, so the plasma oscillates as a relativistic sound wave. These oscillations, frozen in at recombination, imprint the acoustic peaks of the cosmic microwave background and the baryon acoustic feature in the later galaxy distribution.','The early universe was a hot, dense plasma. Gravity pulled matter into clumps. Light pushed back out with pressure. This tug of war made pressure waves. They act like sound waves in the plasma. Their pattern is still visible in the sky today.','It is the fundamental oscillation that links the initial density seeds to the observed CMB peaks and the galaxy clustering scale.','Cosmologists model these waves to predict CMB and large-scale-structure spectra and to extract parameters from survey data.','Astronomical & Cosmological Acoustics',ARRAY['Plasma acoustic oscillation','Pre-recombination sound wave','Sound horizon','Baryon acoustic oscillation','First acoustic peak']::text[],ARRAY['Imagining the wave as audible sound in a vacuum rather than a plasma pressure oscillation','Thinking the wave keeps propagating after recombination instead of leaving a frozen imprint','Confusing the photon-baryon sound wave with dark-matter motion, which does not oscillate']::text[],ARRAY['Explaining the origin of the CMB acoustic peaks','Introducing baryon acoustic oscillations in a survey analysis','Modelling perturbation growth in the pre-recombination plasma']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cosmic acoustic wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '64a3096c-521f-5866-beb6-15ec71ad4d90','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='64a3096c-521f-5866-beb6-15ec71ad4d90') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='64a3096c-521f-5866-beb6-15ec71ad4d90');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39c44d5b-988b-5ded-9357-631d868635b7','Primordial sound speed','The propagation speed of acoustic waves in the pre-recombination photon-baryon fluid. Because photon pressure supplies the restoring force, the speed is close to c/sqrt(3) in the radiation-dominated limit, reduced by the baryon-to-photon momentum-density ratio R = 3*rho_b/(4*rho_gamma). As baryons grow more important toward recombination, R rises and the sound speed falls.','Sound needs a springy medium to move through. In the early plasma, light pressure was the spring. So the wave moved very fast, near light speed over root three. Adding heavy particles slowed it down. Near recombination it was slower.','It sets how far a wave travels per unit time, fixing the sound horizon that calibrates the CMB and BAO rulers.','It enters Boltzmann codes that compute the sound horizon and the acoustic scale used as a standard ruler.','Astronomical & Cosmological Acoustics',ARRAY['Sound horizon','Baryon loading','Cosmic acoustic wave','Primordial plasma','Acoustic angular scale']::text[],ARRAY['Assuming a fixed c/sqrt(3) and ignoring the baryon correction R','Treating it as an ordinary gas sound speed rather than a photon-pressure speed','Forgetting that it changes with time as the universe expands']::text[],ARRAY['Computing the sound horizon at recombination','Studying how baryon density lowers the plasma sound speed','Calibrating the acoustic standard ruler']::text[],'advanced','c_s = c / sqrt(3(1 + R)),  R = 3 rho_b / (4 rho_gamma)','The sound speed equals the speed of light divided by the square root of three times one plus R, where R is three quarters of the baryon-to-photon energy-density ratio.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Primordial sound speed');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39c44d5b-988b-5ded-9357-631d868635b7','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39c44d5b-988b-5ded-9357-631d868635b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39c44d5b-988b-5ded-9357-631d868635b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa7bc9b7-a9bc-5ed1-9578-498308b52ecc','Photon diffusion damping','The exponential suppression of small-scale acoustic oscillations caused by the finite mean free path of photons before recombination, also called Silk damping. As recombination approaches, photons random-walk out of overdense regions, diffusing energy across wavefronts and washing out temperature and density contrasts below a characteristic length. It sets the small-scale, high-multipole cutoff of the CMB power spectrum.','Photons did not move in straight lines. They bounced around like a random walk. This let them leak out of dense spots. The leak smeared out the smallest waves. So the tiniest ripples faded away. This limits the finest detail in the CMB.','It damps the highest-frequency acoustic modes, shaping the falling tail of the CMB spectrum.','The damping tail constrains the baryon density, the helium abundance, and any extra relativistic species.','Astronomical & Cosmological Acoustics',ARRAY['Silk damping','Acoustic damping scale','Mean free path','Last-scattering surface','CMB power spectrum']::text[],ARRAY['Confusing photon diffusion damping with the Doppler smoothing of a thick last-scattering surface','Assuming it affects all scales equally rather than mainly small scales','Ignoring that the diffusion length grows as recombination nears']::text[],ARRAY['Explaining the damping tail of the CMB spectrum','Fitting the helium abundance from small-scale power','Modelling how extra neutrino species change the damping']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photon diffusion damping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa7bc9b7-a9bc-5ed1-9578-498308b52ecc','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa7bc9b7-a9bc-5ed1-9578-498308b52ecc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa7bc9b7-a9bc-5ed1-9578-498308b52ecc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '90e5368d-8114-5001-9d2a-2b30bf5ac6c1','Acoustic damping scale','The characteristic comoving length, with its associated wavenumber k_D and angular scale, below which photon diffusion erases pre-recombination acoustic oscillations. It is set by the distance a photon random-walks by recombination, roughly the geometric mean of the horizon size and the photon mean free path. Modes with wavenumber above k_D are exponentially suppressed in the CMB.','There is a size limit for the waves. Below it, the ripples get erased. This size is set by how far photons wander. It is about the average of two lengths. One is the photon step size. The other is the horizon size. Smaller waves do not survive.','It marks where the CMB damping tail begins, separating surviving from erased modes.','Measuring where power falls off pins down the baryon density and the relativistic content of the universe.','Astronomical & Cosmological Acoustics',ARRAY['Silk scale','Photon diffusion damping','Sound horizon','Damping tail','Mean free path']::text[],ARRAY['Treating it as a sharp cutoff rather than a smooth exponential suppression','Confusing the damping scale with the sound horizon','Assuming it is fixed rather than dependent on recombination physics']::text[],ARRAY['Locating the onset of the CMB damping tail','Comparing damping and sound-horizon scales','Constraining extra radiation from the damping scale']::text[],'advanced','lambda_D ~ sqrt(N) * lambda_mfp ~ sqrt(lambda_mfp * c t)','The damping length is roughly the photon mean free path times the square root of the number of scatterings, which equals the geometric mean of the mean free path and the horizon size.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic damping scale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '90e5368d-8114-5001-9d2a-2b30bf5ac6c1','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='90e5368d-8114-5001-9d2a-2b30bf5ac6c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='90e5368d-8114-5001-9d2a-2b30bf5ac6c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3b63529e-b86e-5e73-995b-dc4c0652db88','Acoustic angular scale','The angle subtended on the sky by the sound horizon at last scattering, which fixes the angular positions of the CMB acoustic peaks. It equals the comoving sound horizon r_s divided by the comoving angular-diameter distance to recombination, and its inverse times pi gives the characteristic peak multipole. It is among the most precisely measured quantities in cosmology.','The sound waves froze at one fixed size. We see that size on the sky as an angle. The angle is the wave size divided by its distance. This angle sets where the CMB peaks sit. We measure it very precisely.','It converts the physical sound-horizon ruler into an observable angle that anchors distance measurements.','Its precise value from Planck fixes the peak spacing and tightly constrains cosmic geometry.','Astronomical & Cosmological Acoustics',ARRAY['Sound horizon','First acoustic peak','Angular diameter distance','CMB power spectrum','Standard ruler']::text[],ARRAY['Confusing the angular scale with the sound horizon length itself','Forgetting it depends on both the ruler and the distance','Reading it as a single peak position rather than the peak spacing']::text[],ARRAY['Deriving the position of the first CMB peak','Testing spatial flatness from the peak angle','Combining CMB and BAO angular scales']::text[],'advanced','theta_A = r_s(z*) / D_A(z*),  l_A = pi / theta_A','The acoustic angular scale equals the sound horizon at recombination divided by the distance to recombination, and the acoustic multipole equals pi divided by that angle.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic angular scale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3b63529e-b86e-5e73-995b-dc4c0652db88','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3b63529e-b86e-5e73-995b-dc4c0652db88') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3b63529e-b86e-5e73-995b-dc4c0652db88');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c99feec9-d7d0-5117-9a67-64ee95ccdfea','CMB power spectrum','The variance of cosmic microwave background temperature or polarization fluctuations as a function of angular scale, expressed as the angular power spectrum C_l versus multipole l. Its series of acoustic peaks and troughs encodes the oscillation phases of the photon-baryon plasma at last scattering, and the heights, spacings, and damping of the peaks constrain the cosmological parameters.','The CMB sky is not perfectly smooth. It has tiny hot and cold spots. The power spectrum measures how strong the spots are at each size. It shows a set of peaks. Those peaks come from the plasma waves. Their shape tells us about the universe.','It compresses the CMB map into a statistic that directly reflects early-universe physics.','Fitting the measured C_l yields the densities of baryons and dark matter and the geometry of space.','Astronomical & Cosmological Acoustics',ARRAY['Acoustic peak','Angular power spectrum','Multipole','Last-scattering surface','Cosmological parameters']::text[],ARRAY['Reading the x-axis as spatial frequency rather than multipole or angular scale','Thinking each peak is a separate physical event rather than an oscillation phase','Ignoring that polarization spectra carry complementary information']::text[],ARRAY['Fitting cosmological parameters to Planck data','Teaching the origin of the acoustic peaks','Comparing temperature and polarization spectra']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='CMB power spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c99feec9-d7d0-5117-9a67-64ee95ccdfea','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c99feec9-d7d0-5117-9a67-64ee95ccdfea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c99feec9-d7d0-5117-9a67-64ee95ccdfea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e063292f-e154-5aa9-8d9b-662a27f89461','First acoustic peak','The most prominent peak in the CMB temperature power spectrum, near multipole l = 220, corresponding to the fundamental mode of the photon-baryon plasma that had just reached maximum compression at last scattering. Its angular position measures the acoustic angular scale and is the primary CMB probe of spatial curvature, while its height reflects the total matter and radiation content.','The plasma waves had a main note. That mode squeezed to its tightest just as the CMB was released. It makes the tallest peak in the spectrum. It sits near multipole 220. Its position tells us space is nearly flat.','It provides the cleanest CMB measurement of the acoustic scale and cosmic geometry.','Its location near multipole 220 is the headline evidence for a spatially flat universe.','Astronomical & Cosmological Acoustics',ARRAY['Acoustic angular scale','Second acoustic peak','Sound horizon','Spatial curvature','CMB power spectrum']::text[],ARRAY['Assuming its exact position is unaffected by the distance to recombination','Treating the peak height as fixed rather than parameter-dependent','Confusing compression peaks with rarefaction peaks']::text[],ARRAY['Measuring spatial flatness','Anchoring the acoustic scale','Introducing the CMB peak structure']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='First acoustic peak');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e063292f-e154-5aa9-8d9b-662a27f89461','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e063292f-e154-5aa9-8d9b-662a27f89461') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e063292f-e154-5aa9-8d9b-662a27f89461');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '06823591-478c-52f9-8bef-793756d01008','Second acoustic peak','The second peak in the CMB temperature power spectrum, near multipole l = 520, arising from the plasma mode that completed a half-oscillation more than the first, reaching maximum rarefaction at last scattering. Its height relative to the first peak is suppressed by baryon loading, so the first-to-second peak ratio is a sensitive measure of the cosmic baryon density.','The next mode swung one step further. It reached its most spread-out state at release. This makes the second peak. Extra baryons push it down compared with the first peak. So the peak ratio measures how many baryons there are.','It calibrates the baryon density through its suppression relative to the first peak.','The first-to-second peak height ratio yields the baryon density, matching that from primordial deuterium.','Astronomical & Cosmological Acoustics',ARRAY['Baryon loading','First acoustic peak','Third acoustic peak','Baryon density','CMB power spectrum']::text[],ARRAY['Thinking all peaks have equal height','Attributing its suppression to damping rather than baryon loading','Confusing rarefaction and compression peaks']::text[],ARRAY['Measuring the baryon density from peak ratios','Cross-checking against big-bang nucleosynthesis','Teaching odd-even peak asymmetry']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Second acoustic peak');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '06823591-478c-52f9-8bef-793756d01008','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='06823591-478c-52f9-8bef-793756d01008') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='06823591-478c-52f9-8bef-793756d01008');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa4e88d7-f038-50a1-8349-f5e2eb90ad00','Third acoustic peak','The third peak in the CMB temperature power spectrum, near multipole l = 800, a compression peak boosted like the first by baryon loading. Its height relative to the second peak is sensitive to the dark-matter density, because the amount of matter present during the radiation era controls how much the gravitational potentials decay and drive the oscillations. A strong third peak is direct evidence for dark matter.','The third mode compressed again at release. Baryons make it a bit taller. Its height depends on how much dark matter there was. More dark matter lifts this peak. So a strong third peak shows dark matter is real.','It probes the dark-matter density and the matter-to-radiation ratio at recombination.','Its measured height provides CMB-based evidence for cold dark matter.','Astronomical & Cosmological Acoustics',ARRAY['Radiation driving','Second acoustic peak','Dark matter density','Baryon loading','CMB power spectrum']::text[],ARRAY['Assuming it only reflects baryons like the first peak','Ignoring the role of potential decay and radiation driving','Treating peak heights as independent of matter content']::text[],ARRAY['Measuring the dark-matter density from the CMB','Demonstrating evidence for dark matter','Fitting the matter-radiation ratio']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Third acoustic peak');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa4e88d7-f038-50a1-8349-f5e2eb90ad00','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa4e88d7-f038-50a1-8349-f5e2eb90ad00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa4e88d7-f038-50a1-8349-f5e2eb90ad00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0c4ff188-bfd3-5545-aeba-bf2dfffca478','Acoustic peak phase shift','A shift in the temporal phase of the pre-recombination acoustic oscillations, most notably the coherent shift induced by free-streaming relativistic neutrinos. Because these neutrinos travel slightly faster than the plasma sound speed, they perturb the gravitational potentials ahead of the sound horizon and pull the oscillation phase, displacing the CMB peaks to slightly larger scales. Measuring it constrains the free-streaming radiation density.','The plasma waves keep a steady beat. Fast, free neutrinos nudge that beat. They run just ahead of the sound waves. This shifts the timing of the peaks. The peaks move to slightly larger scales. Measuring the shift counts the neutrinos.','It provides a clean signature of free-streaming relativistic species in the CMB.','The measured phase shift constrains the effective number of neutrino species.','Astronomical & Cosmological Acoustics',ARRAY['Radiation driving','Neutrino free-streaming','Effective number of neutrinos','CMB power spectrum','Acoustic oscillation phase']::text[],ARRAY['Confusing a phase shift in peak positions with a change in peak amplitude','Assuming only the sound horizon moves the peaks','Ignoring that the effect is a distinctive neutrino signature']::text[],ARRAY['Constraining the neutrino number from CMB peak positions','Testing for extra relativistic species','Modelling neutrino effects on acoustic oscillations']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic peak phase shift');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0c4ff188-bfd3-5545-aeba-bf2dfffca478','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0c4ff188-bfd3-5545-aeba-bf2dfffca478') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0c4ff188-bfd3-5545-aeba-bf2dfffca478');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f2b388ff-b9b7-5b25-8866-fe13ae05a222','Baryon loading','The effect of baryons adding inertia to the photon-baryon fluid, quantified by the ratio R = 3*rho_b/(4*rho_gamma). Extra baryon mass deepens the fluid''s fall into potential wells, enhancing the compression phases of the oscillation relative to the rarefaction phases. In the CMB this raises the odd, compression peaks relative to the even, rarefaction peaks, making the peak-height pattern a baryon-density diagnostic.','Baryons add weight to the plasma. The heavier fluid falls deeper into gravity wells. So the squeeze phase gets stronger than the stretch phase. In the CMB this lifts the odd peaks. It also lowers the even peaks. The pattern reveals the baryon amount.','It explains the odd-even peak asymmetry and ties it to the baryon density.','The enhanced odd peaks let analysts read the baryon density straight from CMB peak heights.','Astronomical & Cosmological Acoustics',ARRAY['Baryon-to-photon ratio','Second acoustic peak','Primordial sound speed','Compression peak','CMB power spectrum']::text[],ARRAY['Confusing baryon loading with photon diffusion damping','Assuming it affects all peaks equally','Forgetting that it also lowers the sound speed']::text[],ARRAY['Explaining odd-even CMB peak heights','Measuring the baryon density','Modelling the photon-baryon fluid inertia']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Baryon loading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f2b388ff-b9b7-5b25-8866-fe13ae05a222','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f2b388ff-b9b7-5b25-8866-fe13ae05a222') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f2b388ff-b9b7-5b25-8866-fe13ae05a222');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9e82d566-9ae9-57a3-a58c-7d074574f40d','Radiation driving','The resonant boosting of acoustic oscillations that occurs when gravitational potentials decay during the radiation-dominated era. As modes enter the horizon while radiation dominates, the self-gravity of the photon-baryon perturbations cannot sustain the potentials, whose decay drives the oscillator near-resonantly and amplifies its amplitude. This enhances the early CMB peaks, especially those oscillating near horizon crossing.','Early on, radiation ran the universe. Gravity wells from the waves could not hold up. They decayed as the wave swung. That decay gave the wave a timely push. The push made the wave bigger. This boosts the early CMB peaks.','It amplifies acoustic modes that cross the horizon during radiation domination, shaping peak heights.','The boost makes early peaks sensitive to the matter-radiation ratio and hence the matter density.','Astronomical & Cosmological Acoustics',ARRAY['Third acoustic peak','Potential decay','Matter-radiation equality','Acoustic peak phase shift','Dark matter density']::text[],ARRAY['Confusing gravitational driving with the pressure restoring force','Assuming the potentials are constant rather than decaying','Ignoring its dependence on the matter-radiation ratio']::text[],ARRAY['Explaining enhanced early CMB peaks','Measuring the matter density','Modelling horizon crossing during radiation domination']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiation driving');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9e82d566-9ae9-57a3-a58c-7d074574f40d','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9e82d566-9ae9-57a3-a58c-7d074574f40d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9e82d566-9ae9-57a3-a58c-7d074574f40d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fd4a0347-9388-51c7-944d-6f63204de10a','Plasma acoustic oscillation','An oscillation of a plasma in which pressure acts as the restoring force against a compression, producing longitudinal acoustic waves. In cosmology it refers to the standing acoustic oscillations of the coupled photon-baryon plasma before recombination, while in space and laboratory plasmas it more generally denotes ion-acoustic modes. The cosmological version is imprinted as the CMB peaks and the baryon acoustic feature.','A plasma can carry pressure waves. Push it together and pressure pushes back. That makes it oscillate. In the early universe the whole plasma rang this way. The ringing left marks in the CMB. Similar waves also occur in other plasmas.','It is the general mechanism behind the acoustic peaks and the baryon acoustic feature.','Cosmologists track these oscillations to model CMB and galaxy-clustering spectra.','Astronomical & Cosmological Acoustics',ARRAY['Cosmic acoustic wave','Ion-acoustic wave','Baryon acoustic oscillation','Pre-recombination sound wave','Sound speed']::text[],ARRAY['Assuming plasma cannot support sound-like waves because it is ionized','Conflating ion-acoustic and electromagnetic plasma waves','Treating the cosmological plasma as an ordinary neutral gas']::text[],ARRAY['Introducing acoustic oscillations in the early plasma','Relating CMB and BAO to the same physics','Comparing cosmological and space-plasma acoustic modes']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Plasma acoustic oscillation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fd4a0347-9388-51c7-944d-6f63204de10a','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fd4a0347-9388-51c7-944d-6f63204de10a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fd4a0347-9388-51c7-944d-6f63204de10a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4e444911-f107-52f0-8cd6-0c5167af4099','Pre-recombination sound wave','An acoustic wave in the photon-baryon plasma during the epoch before recombination, when photons and baryons were tightly coupled by Thomson scattering. Radiation pressure supplied the restoring force and the waves propagated at roughly c/sqrt(3). At recombination the coupling ended, the waves stalled, and the pattern of compressions and rarefactions was frozen into the CMB and the matter distribution.','Before atoms formed, light and matter were locked together. This mix could carry sound waves. Light pressure kept them moving fast. When atoms formed, the link broke. The waves stopped in place. Their frozen pattern is what we see today.','It is the physical wave whose frozen phase produces the CMB peaks and the BAO ruler.','Its propagation distance defines the sound horizon used as a cosmological standard ruler.','Astronomical & Cosmological Acoustics',ARRAY['Sound horizon','Cosmic acoustic wave','Recombination','Last-scattering surface','Baryon acoustic oscillation']::text[],ARRAY['Thinking the waves continued after recombination','Assuming they were audible sound in empty space','Ignoring that tight coupling is what allowed them to propagate']::text[],ARRAY['Explaining the frozen acoustic pattern','Defining the sound horizon','Linking early plasma physics to the BAO feature']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pre-recombination sound wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4e444911-f107-52f0-8cd6-0c5167af4099','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4e444911-f107-52f0-8cd6-0c5167af4099') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4e444911-f107-52f0-8cd6-0c5167af4099');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '535a6ef8-977d-5191-b915-ce6c4cfae875','Last-scattering surface','The effective spherical surface, at redshift near 1090, from which CMB photons last Thomson-scattered off free electrons before the universe became neutral and transparent. It is not infinitely thin but has a finite thickness set by the duration of recombination, which smooths small-scale anisotropies. It is the source screen on which the acoustic oscillations are imaged as the CMB.','Long ago the universe was a glowing fog. Then it cooled and cleared. The photons we see set out from that moment. They come from a shell around us. That shell is the last-scattering surface. It is where the CMB was born.','It defines where and when the CMB pattern was set, fixing the source of the acoustic peaks.','Its distance sets the angular scale of the peaks, and its thickness limits small-scale power.','Astronomical & Cosmological Acoustics',ARRAY['Recombination','Photon diffusion damping','CMB power spectrum','Redshift','Sound horizon']::text[],ARRAY['Picturing it as a real physical wall rather than an observational horizon','Assuming it has zero thickness','Confusing last scattering with the moment of the Big Bang']::text[],ARRAY['Setting the distance for the acoustic angular scale','Explaining CMB smoothing from finite thickness','Teaching the origin of the CMB']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Last-scattering surface');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '535a6ef8-977d-5191-b915-ce6c4cfae875','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='535a6ef8-977d-5191-b915-ce6c4cfae875') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='535a6ef8-977d-5191-b915-ce6c4cfae875');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f0dcade-9708-528e-abf0-bea53bf322a8','Sound-shell model','A model for the stochastic gravitational-wave background generated by acoustic waves following a cosmological first-order phase transition. Expanding bubbles of the new phase set up a thin shell of compression and rarefaction, the sound shell, around each bubble; after bubbles collide the overlapping sound waves persist as long-lived plasma oscillations whose velocity field sources gravitational waves. The model predicts the spectrum shape from the bubble and shell length scales.','A phase change in the early universe can blow bubbles. Each growing bubble pushes a thin shell of sound around it. When bubbles meet, the sound waves keep ringing. Moving plasma then makes gravitational waves. This model predicts the wave signal from those sounds.','It connects sound waves from a phase transition to a predictable gravitational-wave spectrum.','It is used to forecast signals for space-based detectors like LISA from early-universe transitions.','Astronomical & Cosmological Acoustics',ARRAY['First-order phase transition','Acoustic wave','Gravitational-wave background','Bubble nucleation','Plasma velocity field']::text[],ARRAY['Attributing the gravitational waves to bubble collisions alone rather than the lasting sound waves','Assuming the sound waves damp immediately after collision','Confusing it with CMB acoustic oscillations']::text[],ARRAY['Forecasting a LISA phase-transition signal','Modelling gravitational waves from sound waves','Studying early-universe first-order transitions']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-shell model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f0dcade-9708-528e-abf0-bea53bf322a8','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f0dcade-9708-528e-abf0-bea53bf322a8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f0dcade-9708-528e-abf0-bea53bf322a8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f7f474f5-801f-5db5-aa00-1d96db6962f2','BAO reconstruction','A post-processing technique that sharpens the baryon acoustic oscillation feature in galaxy surveys by partially reversing the bulk flows that smear it. Using the observed density field, one estimates the displacement field from gravitational infall and moves galaxies back toward their initial positions, undoing much of the nonlinear degradation. This narrows the BAO peak and improves the precision of the distance measurement.','Gravity pulls galaxies around over time. This blurs the sharp BAO scale. Reconstruction estimates how far each galaxy drifted. It then moves them roughly back. This sharpens the BAO signal again. The distance measurement gets more precise.','It restores the sharpness of the acoustic feature lost to nonlinear structure growth.','Surveys like BOSS and DESI apply it to tighten BAO distance constraints.','Astronomical & Cosmological Acoustics',ARRAY['Baryon acoustic oscillation','Displacement field','Nonlinear structure growth','Standard ruler','Redshift-space distortion']::text[],ARRAY['Expecting it to add new information rather than recover degraded signal','Assuming it removes redshift-space distortions entirely','Treating reconstructed positions as exact initial conditions']::text[],ARRAY['Sharpening the BAO peak in a galaxy survey','Improving distance precision in DESI','Undoing bulk-flow smearing']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BAO reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f7f474f5-801f-5db5-aa00-1d96db6962f2','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f7f474f5-801f-5db5-aa00-1d96db6962f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f7f474f5-801f-5db5-aa00-1d96db6962f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3af2f4a7-9242-5c12-aec5-0993ed0633cc','Isotropic BAO','A baryon acoustic oscillation measurement that uses the spherically averaged clustering signal, combining line-of-sight and transverse information into a single distance scale. It constrains the angle-averaged distance D_V, a combination of the transverse comoving distance and the Hubble distance, in units of the sound horizon. It is used when data are too sparse to separate the radial and transverse directions.','The BAO scale can be measured in all directions at once. You average the clustering over the whole sphere. This gives one combined distance. It mixes the across and along directions. It is used when the data are thin. It still calibrates against the sound horizon.','It provides a single robust distance from the acoustic scale when directional splitting is not feasible.','Early or sparse surveys report the ratio of the isotropic distance to the sound horizon as their BAO result.','Astronomical & Cosmological Acoustics',ARRAY['Anisotropic BAO','Dilation distance','Sound horizon','Baryon acoustic oscillation','Standard ruler']::text[],ARRAY['Assuming it separates the Hubble parameter and the distance, which it does not','Treating the isotropic distance as a purely radial or transverse distance','Ignoring that it needs the sound horizon for calibration']::text[],ARRAY['Reporting a BAO distance from a sparse survey','Combining radial and transverse signals','Building a distance-redshift relation']::text[],'advanced','D_V(z) = [ c z D_M(z)^2 / H(z) ]^(1/3)','The isotropic distance is the cube root of the speed of light times redshift times the transverse comoving distance squared, divided by the Hubble parameter.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Isotropic BAO');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3af2f4a7-9242-5c12-aec5-0993ed0633cc','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3af2f4a7-9242-5c12-aec5-0993ed0633cc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3af2f4a7-9242-5c12-aec5-0993ed0633cc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a4bfa3a-70f7-5948-bdc5-27974b71719e','Anisotropic BAO','A baryon acoustic oscillation analysis that measures the acoustic scale separately along and across the line of sight, exploiting the different physical meaning of the two directions. The radial signal constrains the Hubble parameter through the sound horizon, while the transverse signal constrains the angular-diameter distance; their ratio also gives the Alcock-Paczynski distortion. It yields more cosmological information than the isotropic measurement.','The BAO ruler can be read two ways. One is along our line of sight. The other is across it. The along direction measures the expansion rate. The across direction measures a distance. Splitting them tells us more than averaging.','It separately probes the expansion rate and distance at a given redshift.','Modern surveys report the products of the sound horizon with the Hubble parameter and the distance from anisotropic BAO fits.','Astronomical & Cosmological Acoustics',ARRAY['Radial BAO','Transverse BAO','Alcock-Paczynski effect','Isotropic BAO','Sound horizon']::text[],ARRAY['Assuming it needs no model for redshift-space distortions','Confusing the radial and transverse constraints','Thinking it gives less information than isotropic BAO']::text[],ARRAY['Measuring the expansion rate and distance from one survey','Applying the Alcock-Paczynski test','Constraining dark-energy evolution']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Anisotropic BAO');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a4bfa3a-70f7-5948-bdc5-27974b71719e','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a4bfa3a-70f7-5948-bdc5-27974b71719e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a4bfa3a-70f7-5948-bdc5-27974b71719e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf576f5c-178d-5b0c-8202-183125db05f5','Radial BAO','The component of the baryon acoustic feature measured along the line of sight, where the standard ruler is projected as a redshift interval. Because the observed radial separation depends on the expansion rate, the radial BAO scale directly constrains the Hubble parameter in combination with the sound horizon. It requires accurate redshifts to resolve the small line-of-sight separations.','Along our line of sight, distance is read from redshift. The BAO ruler then appears as a redshift gap. That gap depends on how fast space expands. So the radial BAO measures the expansion rate. It needs precise redshifts to work.','It turns the acoustic ruler into a direct measurement of the Hubble parameter.','Spectroscopic surveys use radial BAO to map the expansion history.','Astronomical & Cosmological Acoustics',ARRAY['Anisotropic BAO','Transverse BAO','Hubble parameter','Sound horizon','Redshift-space distortion']::text[],ARRAY['Confusing radial separation with transverse separation','Using photometric redshifts too coarse to resolve it','Forgetting it constrains the expansion rate, not distance directly']::text[],ARRAY['Measuring the expansion rate at several redshifts','Mapping the expansion history','Requiring spectroscopic redshifts for BAO']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radial BAO');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf576f5c-178d-5b0c-8202-183125db05f5','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf576f5c-178d-5b0c-8202-183125db05f5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf576f5c-178d-5b0c-8202-183125db05f5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f66b4f2-dfc7-5614-a6e4-950e164c2233','Transverse BAO','The component of the baryon acoustic feature measured across the line of sight, where the standard ruler subtends an angle on the sky. The observed angular size depends on the comoving angular-diameter distance, so the transverse BAO scale constrains that distance in units of the sound horizon. It can be measured with photometric redshifts, since it uses angular rather than radial separations.','Across the sky, the BAO ruler shows up as an angle. A smaller angle means the ruler is farther away. So the transverse BAO measures a distance. It uses angles, not redshifts. Even rough redshifts can work for it.','It turns the acoustic ruler into a measurement of angular-diameter distance.','Photometric surveys use transverse BAO to constrain distance versus redshift.','Astronomical & Cosmological Acoustics',ARRAY['Anisotropic BAO','Radial BAO','Angular diameter distance','Sound horizon','Acoustic angular scale']::text[],ARRAY['Confusing the angular scale with a physical length','Assuming it constrains the expansion rate rather than distance','Thinking it always needs spectroscopic redshifts']::text[],ARRAY['Measuring the angular-diameter distance from a photometric survey','Building a distance-redshift relation','Complementing radial BAO']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transverse BAO');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f66b4f2-dfc7-5614-a6e4-950e164c2233','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f66b4f2-dfc7-5614-a6e4-950e164c2233') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f66b4f2-dfc7-5614-a6e4-950e164c2233');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe3a7312-938e-50ef-ac01-1f9db45aeb5a','Alcock-Paczynski effect','A geometric test in which an intrinsically isotropic feature appears distorted along versus across the line of sight if the wrong cosmology is assumed to convert redshifts and angles into distances. For a spherical feature, the ratio of observed radial to transverse extent measures the product of the angular-diameter distance and the Hubble parameter; matching an isotropic shape thus constrains the expansion history and dark energy. The BAO feature and clustering statistics are common applications.','A round feature should look round. If we assume the wrong cosmology, it looks squashed. It stretches one way and shrinks the other. Forcing it back to round fixes the geometry. This links distance and expansion rate. The BAO feature is a common test case.','It uses the isotropy of real features to constrain cosmic geometry and expansion.','Analysts apply it to BAO and full-shape clustering to tighten dark-energy limits.','Astronomical & Cosmological Acoustics',ARRAY['Anisotropic BAO','Redshift-space distortion','Angular diameter distance','Hubble parameter','Dark energy']::text[],ARRAY['Confusing the geometric distortion with dynamical redshift-space distortions','Assuming the feature is truly isotropic without accounting for those distortions','Applying it without a fiducial cosmology check']::text[],ARRAY['Constraining dark energy from clustering anisotropy','Combining the test with BAO','Testing an assumed cosmology']::text[],'advanced','F_AP(z) = D_M(z) H(z) / c','The Alcock-Paczynski parameter equals the transverse comoving distance times the Hubble parameter divided by the speed of light, fixed by requiring an isotropic feature to look isotropic.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Alcock-Paczynski effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe3a7312-938e-50ef-ac01-1f9db45aeb5a','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe3a7312-938e-50ef-ac01-1f9db45aeb5a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe3a7312-938e-50ef-ac01-1f9db45aeb5a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '93e240ce-ad67-537d-8e15-13848dd4691f','Redshift-space distortion','The anisotropy of observed galaxy clustering that arises because peculiar velocities add to the cosmological redshift, displacing galaxies along the line of sight in the inferred map. Coherent infall toward overdensities squashes structures radially on large scales, the Kaiser effect, while random virial motions elongate them into fingers of God on small scales. Its amplitude measures the growth rate of structure.','We get galaxy distances from redshift. But galaxies also move on their own. That extra motion shifts their mapped positions. Infall flattens big structures along our line of sight. Random motion stretches dense clumps. The pattern reveals how fast structure grows.','It encodes the growth rate of cosmic structure, a key test of gravity.','Surveys fit redshift-space distortions to measure the growth rate and test general relativity on large scales.','Astronomical & Cosmological Acoustics',ARRAY['Kaiser effect','Fingers of God','Growth rate','Peculiar velocity','Anisotropic BAO']::text[],ARRAY['Treating redshift purely as distance and ignoring peculiar velocities','Confusing the large-scale squashing with small-scale fingers of God','Mistaking dynamical distortions for the geometric Alcock-Paczynski distortion']::text[],ARRAY['Measuring the growth rate of structure','Testing modified gravity','Modelling anisotropic clustering']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Redshift-space distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '93e240ce-ad67-537d-8e15-13848dd4691f','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='93e240ce-ad67-537d-8e15-13848dd4691f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='93e240ce-ad67-537d-8e15-13848dd4691f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '01cb8aa3-60d4-5d7d-91c0-2ea020ecc210','Matter power spectrum wiggles','The series of small oscillatory features superimposed on the smooth matter power spectrum, the Fourier-space counterpart of the baryon acoustic peak in the correlation function. They arise because baryons, having oscillated as sound waves before recombination, imprint a preferred scale that modulates the clustering amplitude periodically in wavenumber. Their spacing is set by the sound horizon and provides the BAO standard ruler in Fourier space.','Plot clustering strength against scale. Mostly it is a smooth curve. But it has small ripples on top. These ripples come from the early sound waves. Baryons left a favored spacing. That spacing is the BAO ruler in Fourier space.','It carries the acoustic scale into the Fourier-space clustering statistic.','Fitting the wiggle positions in the power spectrum yields the BAO distance scale.','Astronomical & Cosmological Acoustics',ARRAY['Baryon acoustic oscillation','No-wiggle power spectrum','Sound horizon','Transfer function','Correlation function']::text[],ARRAY['Confusing the wiggles with noise in the spectrum','Forgetting they are the Fourier partner of the correlation-function BAO peak','Assuming dark matter alone would produce them']::text[],ARRAY['Measuring BAO in Fourier space','Isolating the wiggle component','Fitting the sound-horizon scale']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Matter power spectrum wiggles');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '01cb8aa3-60d4-5d7d-91c0-2ea020ecc210','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='01cb8aa3-60d4-5d7d-91c0-2ea020ecc210') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='01cb8aa3-60d4-5d7d-91c0-2ea020ecc210');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a38dd97a-a1b4-50bd-bf97-20f5347cd996','No-wiggle power spectrum','A smooth reference matter power spectrum constructed to have the same broadband shape as the full spectrum but with the baryon acoustic oscillations removed. Provided by an analytic fitting formula, it serves as a baseline against which the oscillatory BAO wiggles are defined and extracted. Dividing or differencing the full spectrum by the no-wiggle spectrum isolates the acoustic feature for analysis.','Take the clustering curve and erase the ripples. Keep the overall smooth shape. That is the no-wiggle spectrum. It is a baseline with no BAO. Comparing it with the real curve reveals the wiggles. This makes the BAO easy to isolate.','It provides a smooth baseline that isolates the acoustic wiggles for measurement.','Analysts divide the measured power spectrum by it to extract the BAO signal.','Astronomical & Cosmological Acoustics',ARRAY['Matter power spectrum wiggles','Transfer function','Baryon acoustic oscillation','Broadband shape','Smooth reference spectrum']::text[],ARRAY['Treating it as a physical spectrum rather than a fitting reference','Assuming it captures baryon suppression of small-scale power exactly','Using it where the full transfer function is needed']::text[],ARRAY['Isolating the BAO wiggles','Defining a smooth clustering baseline','Fitting the acoustic feature']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='No-wiggle power spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a38dd97a-a1b4-50bd-bf97-20f5347cd996','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a38dd97a-a1b4-50bd-bf97-20f5347cd996') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a38dd97a-a1b4-50bd-bf97-20f5347cd996');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e6ed399-553d-5c37-8cda-fafa75a8779a','Acoustic oscillation phase','The phase of an acoustic oscillation, meaning how far through its compression-rarefaction cycle a mode is, at a reference epoch such as last scattering. For cosmological plasma modes the phase at recombination determines whether a given wavenumber sits at a peak or trough of the CMB spectrum, so the peak positions encode the oscillation phases. The phase can be shifted by effects such as free-streaming neutrinos or baryon drag.','A wave cycles between squeezed and stretched. Its phase says where it is in that cycle. At recombination each mode was frozen at some phase. Modes caught while squeezed make peaks. The set of phases sets the peak pattern. Some effects can shift the phase.','It links the microphysics of the oscillation to the observed positions of the acoustic peaks.','Analysts use peak positions to infer oscillation phases and test for phase-shifting physics.','Astronomical & Cosmological Acoustics',ARRAY['Acoustic peak phase shift','First acoustic peak','Cosmic acoustic wave','Sound horizon','CMB power spectrum']::text[],ARRAY['Confusing the oscillation phase with the spatial phase of a snapshot','Assuming all modes share the same phase','Ignoring that neutrinos can shift it']::text[],ARRAY['Explaining why the peaks fall where they do','Testing for a neutrino phase shift','Relating phase to peak positions']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic oscillation phase');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e6ed399-553d-5c37-8cda-fafa75a8779a','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e6ed399-553d-5c37-8cda-fafa75a8779a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e6ed399-553d-5c37-8cda-fafa75a8779a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20419fdd-6f9a-5393-8011-26043cbe8909','Solar five-minute oscillation','The Sun''s global acoustic pressure-mode oscillations, whose power is concentrated near a period of five minutes, about 3 millihertz. They are standing sound waves trapped in resonant cavities beneath the photosphere, excited stochastically by near-surface convection. Millions of overlapping modes produce the observed velocity and intensity oscillations that are the foundation of helioseismology.','The Sun''s surface gently rises and falls. The strongest rhythm repeats about every five minutes. These are sound waves trapped inside the Sun. Boiling near the surface sets them ringing. Many modes overlap at once. Studying them reveals the Sun''s interior.','It is the primary observable of global helioseismology, probing the solar interior.','Instruments such as GONG and SDO/HMI measure these oscillations to infer internal structure and rotation.','Astronomical & Cosmological Acoustics',ARRAY['Solar p-mode ridge','Solar oscillation spectrum','Helioseismology','Acoustic mode','Stochastic excitation']::text[],ARRAY['Thinking the five-minute period is a single mode rather than a spectrum of many','Assuming the waves are audible in space','Confusing surface convection, the driver, with the modes themselves']::text[],ARRAY['Introducing helioseismology','Measuring solar internal rotation','Detecting global pressure modes']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Solar five-minute oscillation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20419fdd-6f9a-5393-8011-26043cbe8909','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20419fdd-6f9a-5393-8011-26043cbe8909') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20419fdd-6f9a-5393-8011-26043cbe8909');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d8e829c-0e08-5f9e-a0b7-99d74cb2b32b','Solar p-mode ridge','One of the discrete ridges of concentrated oscillation power seen in the Sun''s diagnostic diagram, where power is plotted against horizontal wavenumber and frequency. Each ridge corresponds to a fixed radial order, tracing how the frequency of pressure modes of that order varies with horizontal wavelength. The ridges reveal the dispersion relation of trapped acoustic waves and constrain the sub-surface sound-speed profile.','Plot the Sun''s waves by size and pitch. The power does not spread evenly. It lines up along curved ridges. Each ridge is one family of modes. The ridge shape shows how the waves behave. It maps the sound speed just below the surface.','It displays the pressure-mode dispersion relation used to probe the outer solar layers.','Helioseismologists fit ridge positions in diagnostic diagrams to infer near-surface structure.','Astronomical & Cosmological Acoustics',ARRAY['Solar five-minute oscillation','Diagnostic diagram','Solar oscillation spectrum','Radial order','Dispersion relation']::text[],ARRAY['Reading a ridge as a single mode rather than a sequence in horizontal wavenumber','Confusing radial order with angular degree','Ignoring that ridges reflect wave trapping']::text[],ARRAY['Interpreting a power diagram of solar waves','Probing near-surface sound speed','Identifying mode order']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Solar p-mode ridge');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d8e829c-0e08-5f9e-a0b7-99d74cb2b32b','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d8e829c-0e08-5f9e-a0b7-99d74cb2b32b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d8e829c-0e08-5f9e-a0b7-99d74cb2b32b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0b7f5210-2d2b-52ff-96da-2da8e04e6b68','Solar oscillation spectrum','The frequency-power spectrum of the Sun''s global oscillations, showing a comb of sharp peaks corresponding to individual acoustic modes labeled by radial order, angular degree, and azimuthal order. The peak frequencies, spacings, and splittings encode the internal sound speed, density, and rotation. It is the primary data product from which the solar interior is inverted.','Turn the Sun''s wobbles into a spectrum. It shows many sharp spikes. Each spike is one oscillation mode. The spacing between spikes carries information. So do tiny splittings within them. From this we map the Sun''s inside.','It packages the mode frequencies used to invert the solar interior.','Frequencies extracted from GONG and HMI spectra feed structure and rotation inversions.','Astronomical & Cosmological Acoustics',ARRAY['Solar five-minute oscillation','Mode linewidth','Rotational splitting','Angular degree','Helioseismology']::text[],ARRAY['Confusing angular degree with radial order when labeling peaks','Ignoring the rotational splitting of the peaks','Treating peak width as noise rather than mode damping']::text[],ARRAY['Extracting mode frequencies','Inverting for internal rotation','Measuring the solar sound-speed profile']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Solar oscillation spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0b7f5210-2d2b-52ff-96da-2da8e04e6b68','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0b7f5210-2d2b-52ff-96da-2da8e04e6b68') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0b7f5210-2d2b-52ff-96da-2da8e04e6b68');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b66d0092-52f4-562d-b290-598efae936d6','Mode inertia','A measure of the total mass effectively set in motion by a stellar oscillation mode, defined as the mode''s kinetic-energy-weighted mass normalized by the surface displacement. Modes with large inertia, such as gravity-dominated mixed modes with significant amplitude in the dense interior, respond weakly to surface excitation and have smaller observed amplitudes and longer lifetimes. It governs how strongly a mode couples to near-surface driving.','Each mode shakes some of the star''s mass. Mode inertia measures how much. A mode reaching deep moves a lot of dense gas. That gives it high inertia. High-inertia modes are hard to excite. They stay small but ring for a long time.','It quantifies how internal versus surface a mode is, controlling its amplitude and lifetime.','Asteroseismologists compute mode inertia to interpret mixed-mode amplitudes in red giants.','Astronomical & Cosmological Acoustics',ARRAY['Mixed mode','Mode lifetime','Avoided crossing','g-mode','Eigenfunction']::text[],ARRAY['Confusing mode inertia with the moment of inertia of the star','Assuming all modes have similar inertia','Ignoring its role in setting observed amplitudes']::text[],ARRAY['Interpreting red-giant mixed-mode amplitudes','Normalizing oscillation eigenfunctions','Predicting which modes are observable']::text[],'advanced','E = integral_V rho |xi|^2 dV / [ M |xi(R)|^2 ]','Mode inertia is the density-weighted integral of the squared displacement over the star, divided by the stellar mass times the squared surface displacement.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode inertia');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b66d0092-52f4-562d-b290-598efae936d6','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b66d0092-52f4-562d-b290-598efae936d6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b66d0092-52f4-562d-b290-598efae936d6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d4fb251-26ba-53d3-a82c-c366d1ca9667','Mode linewidth','The full width at half maximum of an oscillation peak in the power spectrum, reflecting the mode''s damping rate. Because solar-like oscillations are stochastically excited and damped, each mode has a Lorentzian profile whose width is inversely proportional to the mode lifetime. Broader lines indicate stronger damping and make precise frequency determination harder.','A mode peak is not infinitely sharp. It has a width. The width comes from damping. Strong damping makes a wide peak. A wide peak means a short-lived mode. Narrow peaks give more precise frequencies.','It encodes the damping rate and sets the precision of measured mode frequencies.','Fitting Lorentzian linewidths yields damping rates and helps separate crowded spectra.','Astronomical & Cosmological Acoustics',ARRAY['Mode lifetime','Lorentzian profile','Stochastic excitation','Solar oscillation spectrum','Damping rate']::text[],ARRAY['Treating linewidth as measurement noise rather than physical damping','Confusing linewidth with rotational splitting','Assuming all modes share one linewidth']::text[],ARRAY['Fitting Lorentzian peaks','Measuring mode damping','Assessing frequency precision']::text[],'advanced','Gamma = 1 / (pi tau)','The mode linewidth in frequency equals one divided by pi times the mode lifetime.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode linewidth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d4fb251-26ba-53d3-a82c-c366d1ca9667','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d4fb251-26ba-53d3-a82c-c366d1ca9667') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d4fb251-26ba-53d3-a82c-c366d1ca9667');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a8857dcc-7608-593b-be08-3ae2b4e653f2','Mode lifetime','The characteristic e-folding time over which an oscillation mode''s amplitude decays, set by the balance of stochastic driving and damping in solar-like oscillators. It equals the reciprocal of pi times the linewidth of the mode''s Lorentzian peak; long-lived modes appear as narrow peaks and allow high-precision frequency measurement. Lifetimes range from days in the Sun to months in some red giants.','A mode does not ring forever. Its energy slowly fades. The mode lifetime is how long it lasts. Long-lived modes make sharp peaks. Short-lived modes make blurry ones. Longer lifetimes give better frequencies.','It sets how coherent a mode is and how precisely its frequency can be measured.','Lifetimes inferred from linewidths inform seismic frequency uncertainties and excitation models.','Astronomical & Cosmological Acoustics',ARRAY['Mode linewidth','Damping rate','Stochastic excitation','Coherence time','Solar oscillation spectrum']::text[],ARRAY['Confusing lifetime with the star''s age or evolution time','Assuming infinite coherence','Mixing up lifetime and oscillation period']::text[],ARRAY['Estimating frequency precision','Modelling mode excitation and damping','Comparing solar and red-giant lifetimes']::text[],'advanced','tau = 1 / (pi Gamma)','The mode lifetime equals one divided by pi times the mode linewidth in frequency.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode lifetime');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a8857dcc-7608-593b-be08-3ae2b4e653f2','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a8857dcc-7608-593b-be08-3ae2b4e653f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a8857dcc-7608-593b-be08-3ae2b4e653f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6615c94a-6256-5a97-b429-05de6d673d37','Echelle diagram','A diagnostic plot of oscillation frequencies in which the frequency axis is folded modulo the large frequency separation, stacking successive acoustic orders vertically. Modes of the same angular degree line up into nearly vertical ridges, making it easy to identify degrees, measure the large and small separations, and spot departures such as glitches or mixed modes. It is a standard tool in asteroseismology.','Oscillation modes are almost evenly spaced. The echelle diagram folds the spectrum at that spacing. Modes then stack into vertical columns. Each column is one type of mode. Bends or gaps in a column reveal structure. It is a key plot for reading stellar oscillations.','It organizes the mode spectrum to reveal degrees, spacings, and structural signatures.','Asteroseismologists build echelle diagrams from Kepler and TESS data to identify modes.','Astronomical & Cosmological Acoustics',ARRAY['Large frequency separation','Small frequency separation','Mode identification','Avoided crossing','Asteroseismic scaling relation']::text[],ARRAY['Choosing a folding separation that misaligns the ridges','Confusing angular-degree ridges with radial order','Overlooking curvature that carries physical information']::text[],ARRAY['Identifying oscillation modes','Measuring the large and small separations','Detecting mixed modes in red giants']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Echelle diagram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6615c94a-6256-5a97-b429-05de6d673d37','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6615c94a-6256-5a97-b429-05de6d673d37') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6615c94a-6256-5a97-b429-05de6d673d37');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c5166d1c-4b6c-533f-acac-ab71f7f5d9ee','Asteroseismic scaling relation','Approximate relations that link a star''s global oscillation properties to its mass, radius, and temperature. The frequency of maximum power scales with the surface gravity divided by the square root of the effective temperature, while the large frequency separation scales with the square root of the mean density. Combined, they yield near model-independent estimates of stellar mass and radius from the seismic quantities.','A star''s oscillations follow simple rules. The peak-power frequency tracks surface gravity. The mode spacing tracks the star''s density. Put together, they give the mass and radius. This works without a detailed model. It is central to studying many stars.','It provides fast, nearly model-free stellar masses and radii from seismic data.','Kepler and TESS pipelines apply scaling relations to characterize thousands of stars.','Astronomical & Cosmological Acoustics',ARRAY['Large frequency separation','Frequency of maximum power','Mean stellar density','Surface gravity','Echelle diagram']::text[],ARRAY['Applying the relations far from the calibrating solar values without correction','Ignoring known systematic offsets in the large separation','Treating them as exact rather than approximate']::text[],ARRAY['Estimating masses and radii of Kepler stars','Characterizing exoplanet host stars','Population studies of red giants']::text[],'intermediate','nu_max prop g / sqrt(T_eff);  Delta_nu prop sqrt(M / R^3)','The frequency of maximum power scales as surface gravity over the square root of effective temperature, and the large separation scales as the square root of the mean stellar density.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Asteroseismic scaling relation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c5166d1c-4b6c-533f-acac-ab71f7f5d9ee','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c5166d1c-4b6c-533f-acac-ab71f7f5d9ee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c5166d1c-4b6c-533f-acac-ab71f7f5d9ee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4e7ab0bb-ad00-525f-8f8b-af94e2bc6ca0','Acoustic radius','The sound travel time from the stellar center out to a given radius, measured in units of time. Defined as the integral of the reciprocal sound speed along the radius, the total acoustic radius to the surface sets the large frequency separation. Localized features such as ionization zones sit at characteristic acoustic radii, which show up as glitches in the oscillation frequencies.','Measure a star''s inside by sound travel time. The acoustic radius is that time from the center outward. It uses how fast sound moves at each depth. The full trip sets the mode spacing. Features leave marks at set travel times.','It provides a natural time-based coordinate for locating internal features seismically.','Glitch analyses report the acoustic radius of the helium ionization zone and the convection-zone base.','Astronomical & Cosmological Acoustics',ARRAY['Acoustic depth','Large frequency separation','Acoustic glitch','Sound speed','Helium ionization glitch']::text[],ARRAY['Confusing acoustic radius, measured from the center, with acoustic depth, measured from the surface','Treating it as a length rather than a time','Ignoring that it depends on the sound-speed profile']::text[],ARRAY['Locating an ionization zone seismically','Relating travel time to the large separation','Analyzing acoustic glitches']::text[],'advanced','t(r) = integral_0^r dr'' / c(r'')','The acoustic radius is the integral from the center out to a given radius of one over the local sound speed.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic radius');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4e7ab0bb-ad00-525f-8f8b-af94e2bc6ca0','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4e7ab0bb-ad00-525f-8f8b-af94e2bc6ca0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4e7ab0bb-ad00-525f-8f8b-af94e2bc6ca0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96e09db2-ee6e-562d-b2e2-3d7e42421e87','Acoustic depth','The sound travel time from the stellar surface inward to a given layer, the complement of the acoustic radius. Defined as the integral of the reciprocal sound speed from the surface down to the layer, it is the natural coordinate for interpreting acoustic glitches, since a sharp feature imprints an oscillatory signal in the frequencies with a period set by its acoustic depth.','Start at the star''s surface and go inward. The acoustic depth is the sound travel time down to a layer. It is measured in time, not distance. Sharp features sit at a fixed depth. That depth sets the ripple they add to the frequencies.','It provides the surface-referenced timing used to locate glitch-producing features.','The oscillation period of a glitch signal directly gives the feature''s acoustic depth.','Astronomical & Cosmological Acoustics',ARRAY['Acoustic radius','Acoustic glitch','Helium ionization glitch','Convective-envelope glitch','Sound speed']::text[],ARRAY['Swapping acoustic depth, measured from the surface, with acoustic radius, measured from the center','Treating it as a physical depth in length','Ignoring the surface reference point']::text[],ARRAY['Measuring the depth of the convection-zone base','Fitting an acoustic glitch signal','Locating the helium ionization zone']::text[],'advanced','tau(r) = integral_r^R dr'' / c(r'')','The acoustic depth is the integral from a given radius out to the surface of one over the local sound speed.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic depth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96e09db2-ee6e-562d-b2e2-3d7e42421e87','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96e09db2-ee6e-562d-b2e2-3d7e42421e87') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96e09db2-ee6e-562d-b2e2-3d7e42421e87');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '066f11ab-b81a-509c-8b8e-e6a7390256d1','Buoyancy radius','The gravity-mode analog of the acoustic radius, defined by integrating the Brunt-Vaisala buoyancy frequency over the gravity-mode cavity. It sets the characteristic period spacing of gravity modes, just as the acoustic radius sets the frequency spacing of pressure modes. Sharp features in the buoyancy profile, such as chemical-composition gradients, produce buoyancy glitches in the gravity-mode period spacings.','Gravity modes have their own kind of ruler. It comes from the buoyancy frequency, not sound speed. The buoyancy radius adds that up through the g-mode region. It sets the spacing of gravity-mode periods. Sharp features leave marks in that spacing.','It provides the buoyancy-based coordinate that governs gravity-mode period spacings.','It is used to interpret period-spacing patterns and buoyancy glitches in gravity-mode pulsators.','Astronomical & Cosmological Acoustics',ARRAY['Brunt-Vaisala frequency','g-mode','Period spacing','Buoyancy glitch','Acoustic radius']::text[],ARRAY['Confusing the buoyancy radius with the acoustic radius','Assuming it governs pressure modes rather than gravity modes','Ignoring that composition gradients distort it']::text[],ARRAY['Analyzing gravity-mode period spacings','Detecting a buoyancy glitch','Probing near-core chemical gradients']::text[],'advanced','(buoyancy radius) prop integral (N / r) dr  over the g-mode cavity','The buoyancy radius is proportional to the integral of the Brunt-Vaisala frequency divided by radius through the gravity-mode cavity.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Buoyancy radius');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '066f11ab-b81a-509c-8b8e-e6a7390256d1','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='066f11ab-b81a-509c-8b8e-e6a7390256d1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='066f11ab-b81a-509c-8b8e-e6a7390256d1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd1d80b1-9aa6-563f-a0c4-1fd4ee81906c','Avoided crossing','The phenomenon in which two oscillation modes of the same angular degree approach each other in frequency as a star evolves but repel rather than cross, exchanging their physical character. It occurs when a pressure mode and a gravity mode couple, producing mixed modes whose frequencies bend away from a simple crossing. The pattern is a sensitive probe of the deep stellar interior.','As a star ages, two modes drift toward the same frequency. Instead of crossing, they veer apart. They also swap their nature. One becomes more sound-like, the other more gravity-like. The result is mixed modes. Their bends reveal the deep interior.','It signals coupling between pressure and gravity modes, probing the stellar core region.','Avoided crossings in red-giant spectra reveal core structure and evolutionary state.','Astronomical & Cosmological Acoustics',ARRAY['Mixed mode','Mode inertia','g-mode','Mode trapping','Echelle diagram']::text[],ARRAY['Expecting the modes to actually cross in frequency','Ignoring the exchange of mode character','Treating mixed modes as pure pressure or gravity modes']::text[],ARRAY['Interpreting red-giant mixed modes','Distinguishing evolutionary states','Probing the stellar core']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Avoided crossing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd1d80b1-9aa6-563f-a0c4-1fd4ee81906c','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd1d80b1-9aa6-563f-a0c4-1fd4ee81906c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd1d80b1-9aa6-563f-a0c4-1fd4ee81906c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b473ff97-6768-5d60-ac33-a22079d5a7c1','Mode trapping','The confinement of an oscillation mode''s energy to a particular region of a star, so that the mode is partially trapped in one cavity and evanescent elsewhere. Trapping arises from the run of the sound speed and buoyancy frequency, which define resonant cavities separated by evanescent zones. Partially trapped modes, common in evolved and chemically stratified stars, show characteristic amplitude and frequency signatures.','A mode''s energy can be penned into one part of a star. The wave rings there and dies out elsewhere. The trapping comes from how sound speed and buoyancy vary. These make cavities with barriers between them. Trapped modes stand out in the spectrum.','It explains why certain modes carry more information from specific stellar regions.','Mode trapping helps identify modes that probe the core or envelope in pulsating stars.','Astronomical & Cosmological Acoustics',ARRAY['Mixed mode','Avoided crossing','Acoustic cavity','g-mode','Mode inertia']::text[],ARRAY['Assuming all modes sample the whole star equally','Confusing trapping with damping','Ignoring the role of evanescent zones']::text[],ARRAY['Selecting core-probing modes','Interpreting white-dwarf pulsations','Studying chemically stratified stars']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode trapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b473ff97-6768-5d60-ac33-a22079d5a7c1','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b473ff97-6768-5d60-ac33-a22079d5a7c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b473ff97-6768-5d60-ac33-a22079d5a7c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b34225e0-1c9f-5776-be94-53887df0828e','Helium ionization glitch','An oscillatory signature in the acoustic oscillation frequencies produced by the second helium ionization zone, where a localized dip in the first adiabatic exponent sharply perturbs the sound speed. Because this feature is confined to a narrow layer, it imprints a sinusoidal component on the frequencies whose period reflects its acoustic depth and whose amplitude tracks the surface helium abundance.','In a layer where helium loses electrons, the gas changes stiffness. That bump slightly disturbs the sound speed. The disturbance adds a small ripple to the mode frequencies. The ripple''s period gives the layer''s depth. Its size tracks how much helium is there.','It gives a seismic handle on the stellar surface helium abundance.','Fitting the glitch amplitude estimates helium content in stars where spectroscopy cannot.','Astronomical & Cosmological Acoustics',ARRAY['Acoustic glitch','Acoustic depth','First adiabatic exponent','Convective-envelope glitch','Helium abundance']::text[],ARRAY['Confusing the helium glitch with the convection-zone glitch','Assuming it comes from a broad rather than a narrow region','Ignoring its link to helium abundance']::text[],ARRAY['Estimating stellar helium abundance','Fitting acoustic glitches','Calibrating stellar models']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Helium ionization glitch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b34225e0-1c9f-5776-be94-53887df0828e','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b34225e0-1c9f-5776-be94-53887df0828e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b34225e0-1c9f-5776-be94-53887df0828e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e4ae93d7-9ddc-5e97-a2d0-7c6ccb13fda9','Convective-envelope glitch','An oscillatory signature in acoustic oscillation frequencies caused by the sharp transition in the temperature gradient at the base of a star''s convective envelope. The abrupt change in the sound-speed derivative at this boundary acts as an acoustic glitch, adding a sinusoidal component to the frequencies whose period reveals the acoustic depth of the convection-zone base. It constrains the depth of surface convection.','At the bottom of a star''s boiling outer layer, conditions change sharply. That edge slightly disturbs the sound speed. It adds a small ripple to the mode frequencies. The ripple''s period tells how deep the boiling layer reaches. This pins down the convection-zone depth.','It provides a seismic measurement of the convective envelope''s depth.','Its glitch signal constrains convection-zone depth and mixing in stellar models.','Astronomical & Cosmological Acoustics',ARRAY['Acoustic glitch','Acoustic depth','Convection zone','Helium ionization glitch','Sound speed']::text[],ARRAY['Confusing it with the helium ionization glitch','Assuming a smooth rather than sharp boundary','Ignoring its dependence on convection-zone depth']::text[],ARRAY['Measuring the convection-zone base depth','Fitting acoustic glitches','Testing mixing prescriptions']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Convective-envelope glitch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e4ae93d7-9ddc-5e97-a2d0-7c6ccb13fda9','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e4ae93d7-9ddc-5e97-a2d0-7c6ccb13fda9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e4ae93d7-9ddc-5e97-a2d0-7c6ccb13fda9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '51ba9311-c181-5cf0-a3c3-8fca6ac91220','Local helioseismology','The branch of helioseismology that analyzes the full three-dimensional wave field near the solar surface to probe localized subsurface structures and flows, rather than only globally averaged mode frequencies. Techniques include time-distance analysis, ring-diagram analysis, and helioseismic holography, which use travel-time or wavefield perturbations to map flows, sound-speed anomalies, and active regions beneath the surface.','Global methods average over the whole Sun. Local helioseismology zooms in instead. It studies waves in small patches of surface. From these it maps flows and structures just below. It can find hidden features under sunspots. It shows the Sun in three dimensions.','It resolves local subsurface flows and structures that global modes cannot isolate.','It maps subsurface flows, meridional circulation, and active-region structure from SDO/HMI data.','Astronomical & Cosmological Acoustics',ARRAY['Time-distance helioseismology','Ring-diagram analysis','Helioseismic holography','Subsurface flow','Far-side helioseismic imaging']::text[],ARRAY['Assuming it replaces rather than complements global helioseismology','Ignoring the shallow depth range it best probes','Overinterpreting noisy travel-time maps']::text[],ARRAY['Mapping subsurface flows','Studying active-region structure','Measuring meridional circulation']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Local helioseismology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '51ba9311-c181-5cf0-a3c3-8fca6ac91220','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='51ba9311-c181-5cf0-a3c3-8fca6ac91220') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='51ba9311-c181-5cf0-a3c3-8fca6ac91220');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31359f75-15c4-5bdb-9d8b-5d98d90b2ab8','Helioseismic holography','A local-helioseismology technique that computationally propagates the observed surface wavefield backward and forward in time to reconstruct the acoustic sources and scatterers at depth. By phasing together waves that would converge on a chosen subsurface point, it forms an image sensitive to flows, magnetic regions, and sound-speed perturbations there. It is widely used to detect active regions before they rotate into view.','Sound waves from below reach the Sun''s surface. Holography runs those waves back down in a computer. It focuses them on a chosen point inside. This builds an image of what is there. It can spot magnetic regions at depth. It even sees features on the far side.','It images subsurface acoustic sources and scatterers from the surface wavefield.','It underlies far-side active-region monitoring used in space-weather forecasting.','Astronomical & Cosmological Acoustics',ARRAY['Local helioseismology','Far-side helioseismic imaging','Acoustic wavefield','Phase-sensitive holography','Subsurface flow']::text[],ARRAY['Treating the reconstructed image as a direct photograph rather than a wave inference','Ignoring noise and resolution limits','Confusing it with global mode inversion']::text[],ARRAY['Detecting far-side active regions','Imaging subsurface magnetic structure','Space-weather forecasting']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Helioseismic holography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31359f75-15c4-5bdb-9d8b-5d98d90b2ab8','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31359f75-15c4-5bdb-9d8b-5d98d90b2ab8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31359f75-15c4-5bdb-9d8b-5d98d90b2ab8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35bdc985-639d-575d-ba32-a9430738a9a2','Far-side helioseismic imaging','The use of helioseismic holography to detect and monitor active regions on the far hemisphere of the Sun, invisible from Earth, by analyzing acoustic waves that traverse the solar interior and return to the near-side surface. Active regions delay or advance these waves, so their seismic signatures reveal large sunspot groups before solar rotation carries them to the Earth-facing side.','We only see one side of the Sun directly. But sound waves pass through the whole Sun. They carry news from the far side back to us. Big sunspot groups change the wave timing. This lets us map the far side. We see storms before they rotate into view.','It provides advance warning of active regions rotating toward Earth.','Routine far-side maps from SOHO and SDO support space-weather prediction.','Astronomical & Cosmological Acoustics',ARRAY['Helioseismic holography','Local helioseismology','Active region','Space weather','Acoustic travel time']::text[],ARRAY['Expecting an optical-quality image rather than a low-resolution seismic map','Assuming it detects small features','Confusing it with direct far-side spacecraft imaging']::text[],ARRAY['Forecasting the return of active regions','Monitoring far-side sunspots','Supporting space-weather models']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Far-side helioseismic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35bdc985-639d-575d-ba32-a9430738a9a2','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35bdc985-639d-575d-ba32-a9430738a9a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35bdc985-639d-575d-ba32-a9430738a9a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7805dc88-e488-54f0-a8b6-5ffd88aca768','Sunquake','A packet of seismic waves generated in the solar interior by an energetic event, most often a solar flare, seen at the surface as an expanding circular ripple in Doppler velocity. The sudden deposition of energy launches acoustic waves that refract through the interior and resurface as concentric wavefronts. Sunquakes probe the local subsurface structure and the mechanism of energy transport in flares.','A big flare can jolt the Sun. The jolt sends sound waves into the interior. They spread out and come back to the surface. There they appear as growing ripples. These are sunquakes. They act like ripples from a stone in a pond.','It reveals how flare energy couples into the solar interior as seismic waves.','Doppler observations from SDO/HMI detect flare-driven sunquake ripples for analysis.','Astronomical & Cosmological Acoustics',ARRAY['Solar flare','Acoustic wave','Local helioseismology','Doppler velocity','Wavefront']::text[],ARRAY['Assuming every flare produces a detectable sunquake','Confusing the surface ripple with the driving flare','Treating it as an earthquake-like tectonic event']::text[],ARRAY['Studying flare energy transport','Detecting seismic ripples after a flare','Probing subsurface structure locally']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sunquake');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7805dc88-e488-54f0-a8b6-5ffd88aca768','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7805dc88-e488-54f0-a8b6-5ffd88aca768') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7805dc88-e488-54f0-a8b6-5ffd88aca768');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d749985-b0b6-5e47-a1fe-c278fad773ef','Coronal loop oscillation','A transverse or longitudinal oscillation of a magnetized plasma loop in the solar corona, often triggered by a nearby flare or eruption. Transverse kink modes displace the loop sideways, while slow magnetoacoustic longitudinal modes compress plasma along the field. Measuring their periods and damping, the basis of coronal seismology, infers the coronal magnetic field strength and plasma properties.','The Sun''s corona has glowing magnetic loops. A nearby blast can set a loop swaying. Some sway side to side. Others pulse along their length. The way they move reveals hidden properties. It lets us measure the coronal magnetic field.','It enables coronal seismology, inferring magnetic and plasma properties from loop dynamics.','Observations from SDO/AIA track loop oscillations to estimate coronal field strength.','Astronomical & Cosmological Acoustics',ARRAY['Magnetoacoustic wave','Kink mode','Coronal seismology','Alfven speed','Slow magnetoacoustic mode']::text[],ARRAY['Treating all loop oscillations as the same mode type','Ignoring the strong observed damping','Assuming pure acoustic behavior in a magnetized plasma']::text[],ARRAY['Measuring the coronal magnetic field','Interpreting flare-excited loop sway','Applying coronal seismology']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coronal loop oscillation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d749985-b0b6-5e47-a1fe-c278fad773ef','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d749985-b0b6-5e47-a1fe-c278fad773ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d749985-b0b6-5e47-a1fe-c278fad773ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b1b5a498-5f71-5b85-a0d5-9337c4ad5714','Magnetoacoustic wave','A compressive wave in a magnetized plasma whose restoring forces combine gas pressure and magnetic pressure. Depending on the angle to the magnetic field and the ratio of sound to Alfven speed, it separates into a fast mode, where the pressures act together, and a slow mode, where they act in opposition. Magnetoacoustic waves transport energy and are central to solar coronal seismology and heating studies.','In a magnetized plasma, gas and magnetic fields both push back. Their combined push carries waves. When both pressures add, you get a fast wave. When they oppose, you get a slow wave. The field angle sets the speed. These waves help heat the corona.','It describes how energy propagates as compressive waves in a magnetized astrophysical plasma.','It underlies models of coronal heating and the interpretation of coronal loop oscillations.','Astronomical & Cosmological Acoustics',ARRAY['Fast magnetoacoustic mode','Slow magnetoacoustic mode','Alfven speed','Sound speed','Coronal loop oscillation']::text[],ARRAY['Ignoring the field angle that splits the fast and slow speeds','Treating it as a pure sound wave without magnetic pressure','Confusing magnetoacoustic waves with the incompressible Alfven wave']::text[],ARRAY['Modelling coronal energy transport','Interpreting loop oscillations','Studying solar-wind compressive waves']::text[],'advanced','v_ph^2 = (1/2)(c_s^2 + v_A^2) +/- (1/2) sqrt((c_s^2 + v_A^2)^2 - 4 c_s^2 v_A^2 cos^2(theta))','The squared phase speed of the fast and slow modes equals half the sum of the squared sound and Alfven speeds, plus or minus half the square root of that sum squared minus four times the squared sound speed, squared Alfven speed, and squared cosine of the angle to the magnetic field.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnetoacoustic wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b1b5a498-5f71-5b85-a0d5-9337c4ad5714','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b1b5a498-5f71-5b85-a0d5-9337c4ad5714') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b1b5a498-5f71-5b85-a0d5-9337c4ad5714');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '686bc406-bae4-5aba-8de1-7f3171b6e657','Archaeoacoustic survey','A systematic study of the acoustic behaviour of an archaeological site or monument, combining objective acoustic measurement (impulse responses, reverberation time, resonant frequencies) with archaeological and contextual evidence to characterise how the space would have sounded and how sound may have been used there. Surveys record source and receiver positions, measured room-acoustic parameters, and any pronounced resonances, treating acoustics as one line of evidence alongside architecture and material culture.','An archaeoacoustic survey studies how an ancient place sounds. Researchers play test signals and record the echoes. They measure things like echo decay and strong resonances. They map how sound moves through the space. This shows how people may have used sound there. It is done with care to protect the site.','It gathers repeatable acoustic evidence about a heritage space so its sonic character can be studied, compared with other sites, and interpreted alongside other archaeological findings.','Fieldworkers carry out archaeoacoustic surveys in tombs, caves, temples and theatres, capturing impulse responses at set positions to document each site''s acoustics.','Archaeological & Heritage Acoustics',ARRAY['Impulse-response measurement','Acoustic sampling grid','Reverberation time','Auralization','Heritage impulse response']::text[],ARRAY['Treating a striking echo as proof of deliberate ancient design','Ignoring how ruined or altered fabric changes present-day acoustics from the original','Using too few measurement positions to represent the space']::text[],ARRAY['Documenting the acoustics of a Neolithic chamber tomb','Comparing reverberation across several ancient theatres','Recording a cave''s response before access is restricted']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Archaeoacoustic survey');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '686bc406-bae4-5aba-8de1-7f3171b6e657','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='686bc406-bae4-5aba-8de1-7f3171b6e657') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='686bc406-bae4-5aba-8de1-7f3171b6e657');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3bb7782-4c82-54a8-9dc3-f1e83c3d0306','Audibility zone','The area around a sound source within which that source stays audible above the prevailing background, given the source level, ground and atmospheric attenuation, terrain and vegetation. In landscape and soundscape archaeology it is estimated or modelled to explore how far signalling sounds—horns, drums, voices—could have carried, and which places or communities lay within earshot of a given source.','An audibility zone is the area where a sound can still be heard. Past its edge the sound fades into the background. Its size depends on how loud the source is. It also depends on the land, wind and distance. Researchers map it to ask who could hear a horn or drum.','It expresses the spatial reach of a sound, letting researchers reason about who could hear a signal and how sound linked places and people.','Landscape archaeologists model audibility zones for horns, bells or voices to study communication ranges and the placement of gathering or signalling sites.','Archaeological & Heritage Acoustics',ARRAY['Sound catchment','Auditory horizon','Soundscape archaeology','Sound propagation','Processional acoustics']::text[],ARRAY['Assuming a fixed range regardless of wind, terrain and background noise','Confusing the source''s audible area with a listener''s hearing limit','Ignoring seasonal changes in vegetation and weather']::text[],ARRAY['Estimating how far a signalling horn carried across a valley','Assessing whether two settlements lay within earshot','Planning where a test sound could be heard at a site']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audibility zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3bb7782-4c82-54a8-9dc3-f1e83c3d0306','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3bb7782-4c82-54a8-9dc3-f1e83c3d0306') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3bb7782-4c82-54a8-9dc3-f1e83c3d0306');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '81127421-ac51-563d-8e6c-71d5dfed3c38','Auditory horizon','The outer limit of audibility around a listener or a source—the distance or boundary beyond which a given sound can no longer be perceived above the background. Borrowed from the acoustic-horizon concept in soundscape ecology, it is used in sensory and landscape archaeology to describe the shifting edge of the audible world as a person moves through a site or terrain.','The auditory horizon is the edge of what you can hear. Past it, a sound is lost in the background. It shifts as you move or as the source moves. Hills, wind and noise all change where it lies. Archaeologists use it to picture the heard world at a place.','It gives a way to talk about the limit of hearing at a place, helping researchers describe how sound framed experience and movement in the past.','Sensory archaeologists invoke the auditory horizon when tracing how the audible surroundings expanded or shrank along a path or across a landscape.','Archaeological & Heritage Acoustics',ARRAY['Audibility zone','Sound catchment','Soundscape archaeology','Sound propagation','Sensory archaeology']::text[],ARRAY['Treating it as a sharp line rather than a gradual fade','Assuming it stays fixed as weather and background change','Confusing it with the visible horizon']::text[],ARRAY['Describing how sound reaches a walker approaching a monument','Comparing the heard range at exposed and sheltered sites','Discussing how noise shrinks the audible world']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory horizon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '81127421-ac51-563d-8e6c-71d5dfed3c38','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='81127421-ac51-563d-8e6c-71d5dfed3c38') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='81127421-ac51-563d-8e6c-71d5dfed3c38');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ee4dda8-6c33-505a-9ea2-7424bad8a7fc','Sound catchment','By analogy with a watershed or a visual viewshed, the sound catchment of a location is the set of surrounding places from which sound can be heard at that point, or equivalently the area over which a source there can be heard. In landscape archaeology it is often estimated with GIS-based propagation modelling to analyse how a site was connected to its surroundings by audible sound.','A sound catchment is the area a place is linked to by sound. It covers everywhere a listener there could hear, or be heard. It works like a viewshed, but for hearing not sight. Researchers often map it with computer land models. This shows how a site connected to its surroundings.','It turns audibility into a mappable area, so researchers can compare sites by how widely they could send or receive sound across a landscape.','Using GIS propagation tools, archaeologists compute sound catchments for monuments to study their acoustic links with paths, settlements and other sites.','Archaeological & Heritage Acoustics',ARRAY['Audibility zone','Auditory horizon','Soundscape archaeology','Sound propagation','Viewshed']::text[],ARRAY['Copying visual viewshed methods without accounting for how sound bends and is absorbed','Assuming flat, calm conditions that rarely hold outdoors','Treating the catchment edge as exact rather than approximate']::text[],ARRAY['Mapping which valleys lay within earshot of a hilltop site','Comparing the acoustic reach of two monuments','Modelling how sound linked a shrine to nearby routes']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound catchment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ee4dda8-6c33-505a-9ea2-7424bad8a7fc','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ee4dda8-6c33-505a-9ea2-7424bad8a7fc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ee4dda8-6c33-505a-9ea2-7424bad8a7fc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd22d31e9-2227-583b-8c95-244654126cee','Processional acoustics','The study of how acoustic experience changes along a route of movement through a site—an avenue, corridor, passage or sequence of spaces—rather than at a single fixed point. It examines how reverberation, loudness, resonance and the perceived direction of sound shift as a person or procession advances, and how architecture may have shaped a deliberately staged sonic journey.','Processional acoustics looks at sound along a route, not at one spot. As you walk, echoes and loudness change. A tight passage may open into a booming chamber. Researchers study how this shaped a moving crowd''s experience. It links sound to how people passed through a place.','It captures the time-varying sonic experience of movement, helping researchers understand how built spaces may have staged ritual or ceremonial journeys through sound.','Investigators measure impulse responses at successive points along avenues, passages and stairways to chart how the acoustics change during a procession.','Archaeological & Heritage Acoustics',ARRAY['Passage tomb acoustics','Temple acoustics','Archaeoacoustic survey','Reverberation time','Auralization']::text[],ARRAY['Judging a route from one measurement instead of a sequence','Assuming any acoustic change was intended by the builders','Overlooking how crowds of bodies alter the sound']::text[],ARRAY['Charting sound along a temple''s approach avenue','Studying the passage-to-chamber transition in a tomb','Comparing acoustics at stages of a ceremonial route']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Processional acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd22d31e9-2227-583b-8c95-244654126cee','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d22d31e9-2227-583b-8c95-244654126cee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d22d31e9-2227-583b-8c95-244654126cee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '00d842da-6676-5310-acb4-793172314aa6','Oracle chamber acoustics','The acoustic study of chambers linked to oracular or divinatory practice, such as the so-called Oracle Room of the Hal Saflieni Hypogeum in Malta or niches at Greek oracle sites. Work focuses on measurable features—strong resonances, enhanced low-frequency response and reinforcement of the male voice—and asks whether such effects were exploited to make speech seem powerful or disembodied. Claims that particular resonant frequencies (often cited near 110 Hz) carried ritual or neurological significance remain contested and are not established fact.','Oracle chamber acoustics studies rooms linked to prophecy. Some, like Malta''s Oracle Room, strongly boost a deep voice. This can make speech feel powerful or strange. Researchers measure these resonances with care. Some claim a special pitch near 110 hertz mattered. That idea is debated and not proven.','It tests whether the acoustics of divination spaces were used to heighten the impact of the spoken voice, while separating measurable effects from speculative interpretation.','Researchers measure resonances and voice reinforcement in oracle-associated chambers, then weigh whether the effects are strong enough to have been noticed and used.','Archaeological & Heritage Acoustics',ARRAY['Megalithic resonance','Temple acoustics','Passage tomb acoustics','Archaeoacoustic survey','Standing wave']::text[],ARRAY['Presenting the 110 Hz resonance claim as established fact','Assuming a resonance was deliberately engineered rather than incidental','Ignoring how a chamber''s ruined or restored state changes its acoustics']::text[],ARRAY['Measuring voice reinforcement in a rock-cut oracle room','Testing a chamber''s strongest resonant frequencies','Weighing acoustic evidence for divination claims']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oracle chamber acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '00d842da-6676-5310-acb4-793172314aa6','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='00d842da-6676-5310-acb4-793172314aa6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='00d842da-6676-5310-acb4-793172314aa6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e299729b-e2b4-51ea-abaf-c49a290c5c71','Megalithic acoustics','The acoustic investigation of megalithic monuments—chambered tombs, stone circles, passage graves and similar structures built of large stones—covering their reverberation, resonances and sound-reflection behaviour. It combines field measurement, scale modelling and simulation to characterise how these spaces respond to sound, while treating interpretations about intentional acoustic design cautiously.','Megalithic acoustics studies sound in monuments built of huge stones. This includes stone circles and chambered tombs. Researchers measure echoes, resonances and reflections. They use field tests, models and computer tools. Whether builders planned these effects is treated with care.','It documents how large-stone monuments behave acoustically, providing evidence for how sound might have featured in activities held at them.','Acousticians survey chambered tombs and stone circles, capturing impulse responses and testing scale models to characterise their sound behaviour.','Archaeological & Heritage Acoustics',ARRAY['Megalithic resonance','Stone circle acoustics','Passage tomb acoustics','Archaeoacoustic survey','Auralization']::text[],ARRAY['Assuming acoustic effects prove deliberate design','Generalising one monument''s behaviour to all megalithic sites','Forgetting that missing capstones or stones change the acoustics']::text[],ARRAY['Measuring reverberation inside a chambered cairn','Scale-modelling a stone circle''s sound field','Comparing acoustics across related megalithic tombs']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Megalithic acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e299729b-e2b4-51ea-abaf-c49a290c5c71','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e299729b-e2b4-51ea-abaf-c49a290c5c71') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e299729b-e2b4-51ea-abaf-c49a290c5c71');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '94bbff07-7b99-553e-9e92-8da41a34d365','Megalithic resonance','The pronounced resonant behaviour some enclosed or semi-enclosed megalithic structures show at particular low frequencies, where the geometry reinforces standing waves so that a sustained tone or drum can drive the space strongly. Measurable resonances are real; however, widely repeated claims that a shared frequency near 110 Hz was deliberately used, or produced specific neurological or trance effects, remain contested and unproven.','Megalithic resonance is the strong ringing some stone chambers show at certain low pitches. A steady tone or drum can make the room respond powerfully. These resonances can be measured and are real. But claims of a shared magic frequency, or brain effects, are debated. Such claims are not proven.','It describes a genuine acoustic property of some stone chambers while marking where interpretation runs ahead of the evidence.','Researchers excite chambers with tones or drums and measure the frequencies at which they resonate most strongly, comparing results across sites.','Archaeological & Heritage Acoustics',ARRAY['Megalithic acoustics','Oracle chamber acoustics','Passage tomb acoustics','Standing wave','Helmholtz resonance']::text[],ARRAY['Treating a 110 Hz ''ritual frequency'' as an established finding','Confusing a measurable resonance with proof of intended use','Overstating claimed effects on the brain or trance states']::text[],ARRAY['Finding a chamber''s strongest low-frequency resonance','Testing whether a drum drives a tomb strongly','Debating the significance of a measured resonance']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Megalithic resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '94bbff07-7b99-553e-9e92-8da41a34d365','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='94bbff07-7b99-553e-9e92-8da41a34d365') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='94bbff07-7b99-553e-9e92-8da41a34d365');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8c2afb04-fe15-5035-b8c9-12b788f4af00','Stone circle acoustics','The acoustic study of open or partly open stone circles, examining how the ring of standing stones reflects, scatters and reinforces sound within and around it. Because such settings are largely open to the sky, effects are usually subtler than in enclosed chambers—localized reflections, echoes and modest reinforcement—and are studied through field measurement and scale modelling.','Stone circle acoustics studies sound among rings of standing stones. Open to the sky, they echo less than closed rooms. The stones still reflect and scatter sound in noticeable ways. Researchers measure these effects in the field and with models. The results are usually subtle, not dramatic.','It reveals how a ring of stones shapes sound in an open setting, informing ideas about how gatherings there may have sounded.','Acousticians measure reflections and reinforcement inside stone circles, sometimes using scale models to recover effects lost as stones fell or were removed.','Archaeological & Heritage Acoustics',ARRAY['Megalithic acoustics','Archaeoacoustic survey','Sound reflection','Auralization','Impulse-response measurement']::text[],ARRAY['Expecting enclosed-room reverberation from an open circle','Assuming the present ruined layout matches the original','Reading deliberate acoustic intent into ordinary reflections']::text[],ARRAY['Measuring echoes among the stones of a circle','Scale-modelling a circle with its fallen stones restored','Assessing whether speech or music carried within a ring']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stone circle acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8c2afb04-fe15-5035-b8c9-12b788f4af00','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8c2afb04-fe15-5035-b8c9-12b788f4af00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8c2afb04-fe15-5035-b8c9-12b788f4af00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd4e56dd9-f5d3-5130-bac1-c71a57253ac6','Passage tomb acoustics','The acoustic study of passage tombs—Neolithic monuments with a narrow passage leading to one or more stone chambers, such as Newgrange or Maeshowe. Interest centres on strong low-frequency resonances and standing waves the enclosed chamber can support, and on how the confined passage colours sound. Measurable resonances are documented, but interpretations linking them to ritual, chant or altered states are debated rather than settled.','Passage tomb acoustics studies Neolithic tombs with a passage and inner chamber. The closed chamber can ring strongly at low pitches. The narrow passage also shapes the sound. These effects can be measured. But ideas linking them to chanting or trance are debated, not settled.','It characterises how these enclosed monuments respond to sound and provides evidence for debates about the role of sound in their use.','Investigators capture impulse responses in the passage and chamber, identifying resonant frequencies and comparing them across passage tombs.','Archaeological & Heritage Acoustics',ARRAY['Megalithic resonance','Processional acoustics','Archaeoacoustic survey','Standing wave','Reverberation time']::text[],ARRAY['Presenting resonance-driven ritual claims as proven','Ignoring how modern conservation work altered a chamber','Assuming all passage tombs share one acoustic signature']::text[],ARRAY['Measuring chamber resonances in a Neolithic passage tomb','Studying how the passage colours a voice moving inward','Comparing acoustic results across several tombs']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passage tomb acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd4e56dd9-f5d3-5130-bac1-c71a57253ac6','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d4e56dd9-f5d3-5130-bac1-c71a57253ac6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d4e56dd9-f5d3-5130-bac1-c71a57253ac6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e02fc57-d963-5823-9efd-1a1209ce26f9','Temple acoustics','The acoustic study of ancient and historic temples, addressing reverberation, resonance, sound reflection and speech or music intelligibility within sacred architecture. Methods include in-situ impulse-response measurement, scale modelling and computer simulation, applied to structures ranging from Maltese megalithic temples and Egyptian hypostyle halls to Greek, Roman and later religious buildings.','Temple acoustics studies sound inside places of worship from the past. Researchers measure echoes, resonances and how clearly speech carries. They test real buildings and also computer models. The work covers many cultures and periods. It shows how sacred spaces shaped ritual sound.','It reveals how sacred buildings handled speech, chant and music, supporting interpretations of how sound served ritual and worship.','Acousticians measure reverberation and clarity in temple interiors, using models and simulation where the original structure is ruined or altered.','Archaeological & Heritage Acoustics',ARRAY['Processional acoustics','Archaeoacoustic survey','Reverberation time','Auralization','Heritage impulse response']::text[],ARRAY['Assuming the present ruin sounds like the intact building','Overlooking furnishings and crowds that changed the acoustics','Reading modern reverberation tastes into ancient design']::text[],ARRAY['Measuring reverberation in a stone temple interior','Simulating a lost hypostyle hall''s acoustics','Studying how chant carried in a sacred chamber']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temple acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e02fc57-d963-5823-9efd-1a1209ce26f9','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e02fc57-d963-5823-9efd-1a1209ce26f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e02fc57-d963-5823-9efd-1a1209ce26f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '803b27a6-c3b4-5f8b-aeda-ddf5982d22d8','Amphitheater acoustics','The acoustic study of amphitheatres—large elliptical, open-air Roman arenas such as the Colosseum and provincial arenas—examining how their tiered seating, curved walls and open form distributed sound to spectators. Because they are open to the sky and often ruined, analysis relies on measurement of surviving fabric together with scale modelling and simulation to reconstruct how voices and crowd sound behaved.','Amphitheatre acoustics studies big open Roman arenas. Their oval shape and tiered seats spread sound to the crowd. Being open to the sky, they echo differently from closed rooms. Many are now ruins. So researchers use models and simulation as well as measurements.','It explains how these large open venues carried sound to spectators and helps reconstruct the sonic experience of the events held in them.','Acousticians measure surviving arenas and build models to study how announcers, performers and crowds would have been heard across the seating.','Archaeological & Heritage Acoustics',ARRAY['Ancient theater acoustics','Archaeoacoustic survey','Sound reflection','Auralization','Reverberation time']::text[],ARRAY['Confusing an elliptical amphitheatre with a semicircular theatre','Assuming ruined seating reflects sound as the intact tiers did','Expecting enclosed-hall acoustics in an open arena']::text[],ARRAY['Modelling how a voice carried across an arena','Measuring reflections from surviving seating tiers','Reconstructing crowd sound in a Roman amphitheatre']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Amphitheater acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '803b27a6-c3b4-5f8b-aeda-ddf5982d22d8','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='803b27a6-c3b4-5f8b-aeda-ddf5982d22d8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='803b27a6-c3b4-5f8b-aeda-ddf5982d22d8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a522f0d9-7c6a-5c86-8d4c-b7e98ce1124e','Ancient theater acoustics','The acoustic study of ancient Greek and Roman theatres—semicircular, tiered, open-air auditoria with an orchestra and stage building—known for delivering good speech intelligibility to large audiences without amplification. Research examines reflection from the stage building and hillside and effects such as the frequency-filtering action of tiered stone seating, documented most famously at Epidaurus, where the rows suppress low-frequency background sound while passing the higher frequencies of speech.','Ancient theatre acoustics studies open Greek and Roman theatres. Their curved, tiered seats carried speech to huge crowds without microphones. At Epidaurus, the stone rows filter sound. They cut low background noise but pass the higher tones of a voice. This helps distant listeners hear the words.','It explains how open-air theatres achieved wide, clear coverage of the speaking and singing voice, informing both heritage study and modern venue design.','Acousticians measure and model ancient theatres to study speech clarity, seat-row filtering and reflections, and to guide reuse of these venues for performance.','Archaeological & Heritage Acoustics',ARRAY['Amphitheater acoustics','Speech intelligibility','Sound reflection','Archaeoacoustic survey','Reverberation time']::text[],ARRAY['Crediting a single ''secret'' for the acoustics rather than several combined effects','Confusing a semicircular theatre with an elliptical amphitheatre','Assuming ruined seating filters sound exactly as the original did']::text[],ARRAY['Testing speech clarity from the stage of a Greek theatre','Studying seat-row frequency filtering at Epidaurus','Planning a modern performance in an ancient theatre']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ancient theater acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a522f0d9-7c6a-5c86-8d4c-b7e98ce1124e','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a522f0d9-7c6a-5c86-8d4c-b7e98ce1124e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a522f0d9-7c6a-5c86-8d4c-b7e98ce1124e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '38f8444f-5fd3-5e83-b670-2e0e37b86506','Cave impulse response','The measured impulse response of a cave or rock shelter: the time record of how the space responds to a brief acoustic excitation, capturing direct sound, discrete reflections and the decaying reverberant tail produced by irregular rock surfaces. From it, room-acoustic parameters and a convolution reverb can be derived, making it the basic acoustic fingerprint of a subterranean or sheltered site.','A cave impulse response records how a cave answers a short sound. It captures the direct sound, the echoes and the fading tail. Rough rock walls make a complex pattern. From it, researchers get echo-decay figures and reverb effects. It acts as the cave''s sound fingerprint.','It provides the complete acoustic signature of a cave from a single measurement, enabling parameter analysis and faithful auralization of the space.','Fieldworkers capture cave impulse responses with a controlled source and microphones, then derive reverberation times and reverbs for study and playback.','Archaeological & Heritage Acoustics',ARRAY['Impulse-response measurement','Cave reverberation','Rock-shelter acoustics','Convolution reverb','Auralization']::text[],ARRAY['Assuming one position represents the whole irregular cave','Overloading a quiet cave with too high a source level','Neglecting background noise like dripping water in the recording']::text[],ARRAY['Capturing a painted cave''s response for study','Deriving reverberation time from a cave measurement','Building a convolution reverb from a cave''s impulse response']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cave impulse response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '38f8444f-5fd3-5e83-b670-2e0e37b86506','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='38f8444f-5fd3-5e83-b670-2e0e37b86506') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='38f8444f-5fd3-5e83-b670-2e0e37b86506');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e66351af-75f8-5083-a633-c1525fb2f694','Cave reverberation','The persistence of sound in a cave after the source stops, caused by repeated reflection and scattering from irregular rock surfaces; caves can show strong, uneven reverberation and pronounced resonances. Reznikoff and Dauvois reported that decorated locations in some painted caves coincide with points of strong resonance or echo—an influential but debated correlation—while the reverberation itself is a straightforwardly measurable property.','Cave reverberation is sound lingering in a cave after it stops. Rough rock reflects sound many times, so it fades slowly. Some caves also ring at certain pitches. Researchers found paintings often sit where echoes are strong. That link is interesting but still debated.','It characterises how caves sustain and colour sound, and it underlies debates about whether resonant spots guided where ancient people painted or performed.','Researchers measure reverberation and locate resonant, echoing spots in caves, then compare these with the positions of rock art.','Archaeological & Heritage Acoustics',ARRAY['Cave impulse response','Reverberation time','Rock-shelter acoustics','Megalithic resonance','Archaeoacoustic survey']::text[],ARRAY['Treating the art-and-resonance correlation as proven cause and effect','Assuming reverberation is uniform through a branching cave','Ignoring how visitors and fittings change the sound today']::text[],ARRAY['Measuring how long sound lingers in a cave','Checking whether paintings sit at resonant spots','Comparing reverberation between cave chambers']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cave reverberation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e66351af-75f8-5083-a633-c1525fb2f694','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e66351af-75f8-5083-a633-c1525fb2f694') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e66351af-75f8-5083-a633-c1525fb2f694');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4f8bcff5-a468-5e79-83ca-03e4adc6279a','Rock-shelter acoustics','The acoustic study of rock shelters—shallow, partly open recesses beneath overhanging rock—examining how the overhang and rear wall reflect and reinforce sound while the open front limits reverberation. Often studied alongside rock art, this work considers echoes, localized reinforcement and how such places would have sounded to people using them.','Rock-shelter acoustics studies shallow openings under overhanging rock. The back wall and roof reflect sound, but the open front lets it escape. So they echo less than deep caves. Researchers measure these effects, often near rock art. It shows how such spots may have sounded.','It documents the modest but real acoustic effects of sheltered rock settings, supporting study of how they were used and why art was placed there.','Investigators measure reflections and echoes at rock shelters, frequently where rock art is present, to characterise the setting''s sound.','Archaeological & Heritage Acoustics',ARRAY['Cave reverberation','Cave impulse response','Archaeoacoustic survey','Sound reflection','Impulse-response measurement']::text[],ARRAY['Expecting deep-cave reverberation in a shallow shelter','Assuming an echo proves the site was chosen for sound','Overlooking wind and outdoor noise in measurements']::text[],ARRAY['Measuring echoes at a painted rock shelter','Comparing a shelter''s sound with a nearby cave','Testing whether speech is reinforced under an overhang']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rock-shelter acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4f8bcff5-a468-5e79-83ca-03e4adc6279a','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4f8bcff5-a468-5e79-83ca-03e4adc6279a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4f8bcff5-a468-5e79-83ca-03e4adc6279a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e24a6d9-0d0a-5b51-9511-119df874b12f','Acoustic sampling grid','A predefined spatial arrangement of measurement positions—source and receiver points laid out on a regular pattern—used to sample the sound field of a space systematically. Sampling on a grid lets a survey capture how acoustic parameters vary from place to place rather than at a single point, supporting mapping, spatial averaging and repeatable comparison between sites.','An acoustic sampling grid is a set pattern of measuring spots. Researchers take readings at each point, not just one place. This shows how sound changes across the space. It also makes the survey repeatable. Others can measure the same points later.','It ensures a space''s acoustics are sampled evenly and repeatably, so results represent the whole space and can be compared or mapped.','Survey teams mark a grid of source and microphone positions in a chamber or cave, then record an impulse response at each to map the sound field.','Archaeological & Heritage Acoustics',ARRAY['Impulse-response measurement','Archaeoacoustic survey','Spatial averaging','Heritage impulse response','Reverberation time']::text[],ARRAY['Spacing points too coarsely to catch real variation','Placing microphones only where access is easy, biasing results','Failing to record the grid layout for later repeat surveys']::text[],ARRAY['Laying out measurement points across a tomb chamber','Mapping how reverberation varies along a cave','Setting a repeatable grid for a heritage survey']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic sampling grid');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e24a6d9-0d0a-5b51-9511-119df874b12f','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e24a6d9-0d0a-5b51-9511-119df874b12f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e24a6d9-0d0a-5b51-9511-119df874b12f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8afc5070-ca4d-5cdf-991e-8f9c5a6f8462','Impulse-response measurement','The measurement technique that captures a space''s response to a brief, ideally instantaneous excitation, yielding the impulse response from which room-acoustic parameters (reverberation time, clarity, early-to-late energy ratios) are computed. In practice it is obtained with a swept-sine or maximum-length-sequence signal played through a loudspeaker, or with a broadband impulsive source, and is the standard basis for room-acoustic characterisation under the ISO 3382 method.','Impulse-response measurement records how a space answers a short burst of sound. From that record you can calculate reverberation and clarity. It is usually made with a swept tone through a speaker. A sharp impulsive source can also be used. It is the standard way to measure room acoustics.','It provides the complete linear acoustic description of a space in one capture, from which all standard room-acoustic parameters and auralizations follow.','Acousticians run swept-sine or MLS measurements in rooms and heritage sites to obtain impulse responses for parameter analysis and auralization.','Archaeological & Heritage Acoustics',ARRAY['Cave impulse response','Heritage impulse response','Reverberation time','Balloon-pop measurement','Auralization']::text[],ARRAY['Letting background noise swamp the quiet reverberant tail','Overdriving the source into non-linear distortion','Assuming one position describes a large or complex space']::text[],ARRAY['Capturing a chamber''s impulse response with a swept sine','Deriving reverberation time to a recognised standard','Recording a site''s response for later auralization']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impulse-response measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8afc5070-ca4d-5cdf-991e-8f9c5a6f8462','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8afc5070-ca4d-5cdf-991e-8f9c5a6f8462') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8afc5070-ca4d-5cdf-991e-8f9c5a6f8462');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '50ae960e-3b67-502d-843c-5e99e84f7217','Balloon-pop measurement','An impulse-response method that uses a burst balloon as an impromptu broadband impulsive source: popping an inflated balloon produces a short, loud transient that excites the space, from which reverberation and other parameters can be estimated. It is convenient and needs little equipment, but its output is not perfectly repeatable or omnidirectional and its low-frequency content is limited, so it is treated as an approximate alternative to loudspeaker-based methods.','Balloon-pop measurement uses a bursting balloon as the sound source. The pop is loud and short, so it excites the whole space. From the recording you can estimate reverberation. It is quick and needs little gear. But it is less repeatable and weak at low pitches.','It offers a fast, low-equipment way to excite a space for impulse-response capture where a calibrated loudspeaker is impractical.','Fieldworkers pop balloons in caves, ruins or awkward spaces to grab a quick impulse response when carrying a loudspeaker rig is impractical.','Archaeological & Heritage Acoustics',ARRAY['Impulse-response measurement','Cave impulse response','Reverberation time','Heritage impulse response','Archaeoacoustic survey']::text[],ARRAY['Treating balloon pops as fully repeatable and omnidirectional','Trusting the weak low-frequency content it provides','UNSAFE: popping large balloons close to the ears without hearing protection, as the peak level can damage hearing']::text[],ARRAY['Grabbing a quick reverberation estimate in a cave','Measuring a ruin where a loudspeaker cannot be carried','Comparing rough acoustics of several chambers on site']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Balloon-pop measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '50ae960e-3b67-502d-843c-5e99e84f7217','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='50ae960e-3b67-502d-843c-5e99e84f7217') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='50ae960e-3b67-502d-843c-5e99e84f7217');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf93b5a9-a3ef-5a3a-b937-e36fb2407cdc','Heritage impulse response','An impulse response captured at a cultural-heritage site—a historic building, ruin, cave or monument—and archived to document the space''s acoustics for research, conservation and auralization. Such measurements preserve the sonic character of places that may change, decay or become inaccessible, and populate open databases used to convolve dry recordings into the acoustics of the original space.','A heritage impulse response records the acoustics of a historic place. It captures how the site answers a test sound. Researchers store it to preserve the sound of the space. The place may later change or close. The stored response lets people still hear its acoustics.','It preserves a heritage space''s acoustic character as durable, reusable data, guarding against loss and enabling later study and auralization.','Teams record impulse responses in historic churches, ruins and caves for shared databases, then convolve dry audio to place it in those spaces.','Archaeological & Heritage Acoustics',ARRAY['Impulse-response measurement','Cave impulse response','Convolution reverb','Auralization','Virtual acoustic reconstruction']::text[],ARRAY['Archiving a response without noting positions, source and conditions','Assuming one capture represents a large, complex site','Ignoring changes to the fabric since the measurement']::text[],ARRAY['Recording a historic church for an open impulse-response database','Convolving dry speech with a monument''s response','Documenting a site''s acoustics before restoration']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Heritage impulse response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf93b5a9-a3ef-5a3a-b937-e36fb2407cdc','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf93b5a9-a3ef-5a3a-b937-e36fb2407cdc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf93b5a9-a3ef-5a3a-b937-e36fb2407cdc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'acfd21b6-eab4-5134-9282-d8e7e03d1b75','Virtual acoustic reconstruction','The computational rebuilding of the acoustics of a space that no longer exists in its original form—ruined, altered or destroyed—using a geometric or wave-based model informed by archaeological and architectural evidence. Assigning plausible surface properties and geometry, the model yields simulated impulse responses and parameters and supports auralization of how the reconstructed space would have sounded.','Virtual acoustic reconstruction rebuilds a lost space''s sound on a computer. Researchers model its shape and surfaces from evidence. The model predicts how sound echoes and fades. From it, they can make sound you can hear. This brings back sound that no longer exists.','It recovers the likely acoustics of spaces that cannot be measured directly, turning archaeological evidence into testable sonic reconstructions.','Acousticians build computer models of ruined or altered buildings, tune surface properties, and generate impulse responses to auralize the original space.','Archaeological & Heritage Acoustics',ARRAY['Archaeological auralization','Historical sound-field simulation','Auralization','Heritage impulse response','Room acoustic modeling']::text[],ARRAY['Presenting a model''s output as certain rather than a reasoned estimate','Guessing surface materials without archaeological support','Ignoring how uncertain geometry limits accuracy']::text[],ARRAY['Modelling the acoustics of a destroyed church','Reconstructing a ruined hall''s original reverberation','Testing how surface choices change a simulated space']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Virtual acoustic reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'acfd21b6-eab4-5134-9282-d8e7e03d1b75','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='acfd21b6-eab4-5134-9282-d8e7e03d1b75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='acfd21b6-eab4-5134-9282-d8e7e03d1b75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '89507ca3-8918-5d8b-b422-f44afb8ffca1','Archaeological auralization','The rendering of the acoustics of an archaeological space into audible sound, so that a listener can hear how speech, music or ritual sound would have behaved there. It combines a measured or simulated impulse response with anechoic source material through convolution, and is used both to communicate research and to test hypotheses about a site''s sonic use.','Archaeological auralization lets you hear an ancient space. It mixes the site''s echo pattern with a clean recording. The result sounds as if made inside that place. Researchers use it to share and test ideas. It turns measurements into sound you can hear.','It makes a site''s acoustics directly audible, supporting both public communication and the testing of ideas about how sound was used.','Researchers convolve anechoic voice or instrument recordings with a site''s impulse response to demonstrate and study its acoustics.','Archaeological & Heritage Acoustics',ARRAY['Auralization','Virtual acoustic reconstruction','Historical sound-field simulation','Heritage impulse response','Convolution reverb']::text[],ARRAY['Presenting an auralization as an exact record of the past','Using a reverberant source recording instead of an anechoic one','Ignoring uncertainty in the impulse response used']::text[],ARRAY['Letting visitors hear a chant inside a reconstructed tomb','Testing how music would carry in an ancient theatre','Comparing auralizations of a site''s past and present states']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Archaeological auralization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '89507ca3-8918-5d8b-b422-f44afb8ffca1','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='89507ca3-8918-5d8b-b422-f44afb8ffca1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='89507ca3-8918-5d8b-b422-f44afb8ffca1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '214ce8b6-16f4-52cc-afe3-a576a7e53bf7','Historical sound-field simulation','The computer simulation of the sound field within a historical space—how sound propagates, reflects and decays throughout it—using acoustic modelling based on the space''s geometry and surfaces at a chosen period. It produces spatially varying impulse responses and room-acoustic parameters that describe conditions across the space and can drive auralization of a past acoustic state.','Historical sound-field simulation models sound inside a space from the past. A computer predicts how sound spreads and fades throughout it. It uses the building''s shape and surfaces at a chosen time. The result shows conditions at many points. It can also be turned into audible sound.','It predicts how sound behaved across a historical interior, letting researchers study conditions at any position and reconstruct a chosen period''s acoustics.','Acousticians simulate a historic interior at a set date to map clarity and reverberation across seats or stations and to drive auralization.','Archaeological & Heritage Acoustics',ARRAY['Virtual acoustic reconstruction','Archaeological auralization','Room acoustic modeling','Auralization','Reverberation time']::text[],ARRAY['Trusting simulated detail beyond what the input evidence supports','Modelling only one point instead of the whole field','Assuming modern materials match the historical surfaces']::text[],ARRAY['Mapping reverberation across a historic church at a chosen date','Simulating how a lost interior distributed sound','Driving an auralization from a simulated sound field']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Historical sound-field simulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '214ce8b6-16f4-52cc-afe3-a576a7e53bf7','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='214ce8b6-16f4-52cc-afe3-a576a7e53bf7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='214ce8b6-16f4-52cc-afe3-a576a7e53bf7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95921f5e-e6f3-5e77-862f-a4f2c1ebe82d','Lost-space acoustics','The study and recreation of the acoustics of spaces that no longer survive in usable form—demolished, ruined or radically altered buildings and sites—so their former sonic behaviour can be recovered. Working from surviving fabric, plans, images and archaeological evidence, researchers model or reconstruct the space and generate impulse responses and auralizations of its lost acoustics.','Lost-space acoustics recovers the sound of places that are gone. The building may be demolished, ruined or heavily changed. Researchers rebuild its acoustics from plans and evidence. They model the space on a computer. Then they can hear how it once sounded.','It restores access to the acoustics of vanished spaces, letting researchers study and share sonic environments that can no longer be measured.','Researchers reconstruct demolished churches or altered halls in acoustic models, producing impulse responses and auralizations of their former sound.','Archaeological & Heritage Acoustics',ARRAY['Virtual acoustic reconstruction','Historical sound-field simulation','Archaeological auralization','Auralization','Heritage impulse response']::text[],ARRAY['Treating a reconstruction as an exact record of the lost space','Filling evidence gaps with untested assumptions','Ignoring how much the acoustics depend on uncertain surfaces']::text[],ARRAY['Recreating the acoustics of a demolished concert hall','Reconstructing a ruined abbey''s former sound','Auralizing a space known only from plans and images']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lost-space acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95921f5e-e6f3-5e77-862f-a4f2c1ebe82d','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95921f5e-e6f3-5e77-862f-a4f2c1ebe82d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95921f5e-e6f3-5e77-862f-a4f2c1ebe82d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a12630a0-cd6a-5032-80fc-d064ff973246','Intangible acoustic heritage','The aspect of cultural heritage constituted by sound and acoustic experience rather than physical objects—soundscapes, acoustic practices and the sonic character of places—understood within the framework of intangible cultural heritage. It treats how places sounded, and the auditory practices tied to them, as heritage worth documenting, safeguarding and transmitting.','Intangible acoustic heritage is heritage made of sound, not objects. It includes soundscapes and the way places sounded. It also covers sound-based customs and practices. These are seen as worth recording and protecting. The goal is to pass them on to the future.','It frames sound and acoustic experience as protectable heritage, guiding efforts to document and safeguard sonic environments and practices.','Heritage bodies record soundscapes and the acoustics of significant places, archiving them so intangible sonic heritage is not lost.','Archaeological & Heritage Acoustics',ARRAY['Acoustic conservation','Sonic landscape reconstruction','Soundscape archaeology','Heritage impulse response','Museum soundscape reconstruction']::text[],ARRAY['Assuming only physical remains count as heritage','Recording sounds without documenting their context and meaning','Treating a changing soundscape as fixed and unchanging']::text[],ARRAY['Archiving the soundscape of a historic marketplace','Documenting the acoustics of a place of worship as heritage','Safeguarding a traditional sonic practice tied to a site']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intangible acoustic heritage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a12630a0-cd6a-5032-80fc-d064ff973246','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a12630a0-cd6a-5032-80fc-d064ff973246') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a12630a0-cd6a-5032-80fc-d064ff973246');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '02974042-bf9a-5ecb-a01e-1bd8fe460516','Acoustic conservation','The application of conservation principles to the acoustic properties and soundscapes of heritage places—documenting, protecting and, where appropriate, restoring their sonic character alongside their physical fabric. It recognises that interventions, new materials or changed use can alter how a site sounds, and seeks to manage those changes as part of caring for heritage.','Acoustic conservation protects how heritage places sound. It records and cares for a site''s acoustics, not just its stones. Repairs and new uses can change the sound. Conservators try to manage those changes. The aim is to keep the sonic character alongside the building.','It brings acoustics into heritage conservation, ensuring a site''s sonic character is considered when it is documented, altered or restored.','Conservators measure and document a site''s acoustics before work, then choose materials and changes that respect its sonic character.','Archaeological & Heritage Acoustics',ARRAY['Intangible acoustic heritage','Heritage impulse response','Acoustic sampling grid','Sonic landscape reconstruction','Archaeoacoustic survey']::text[],ARRAY['Ignoring acoustic impact when choosing repair materials','Assuming physical restoration automatically preserves the sound','Failing to baseline the acoustics before intervention']::text[],ARRAY['Documenting a church''s acoustics before restoration','Choosing surfaces that preserve a hall''s sonic character','Assessing how new use changes a heritage site''s sound']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic conservation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '02974042-bf9a-5ecb-a01e-1bd8fe460516','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='02974042-bf9a-5ecb-a01e-1bd8fe460516') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='02974042-bf9a-5ecb-a01e-1bd8fe460516');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '418db124-559f-5465-a3ee-f1008387a583','Museum soundscape reconstruction','The recreation of a past or place-specific soundscape for presentation in a museum or heritage-interpretation setting, combining recorded, synthesised or auralized sound to convey how an environment, activity or space sounded. It draws on acoustic measurement, simulation and historical evidence to build an interpretive audio environment for visitors.','Museum soundscape reconstruction recreates past sounds for visitors. It builds an audio scene of a place or activity. The sound may be recorded, synthesised or modelled. Museums use it to make exhibits vivid. It helps people imagine how something once sounded.','It brings historical or environmental sound into exhibitions, helping visitors understand and imagine past acoustic experiences.','Exhibition designers assemble reconstructed soundscapes—market noise, ritual sound, a room''s acoustics—to accompany displays and immersive spaces.','Archaeological & Heritage Acoustics',ARRAY['Sonic landscape reconstruction','Intangible acoustic heritage','Archaeological auralization','Soundscape archaeology','Auralization']::text[],ARRAY['Presenting an interpretive soundscape as an exact historical record','Using sounds not appropriate to the period or place','Overwhelming visitors with unrealistic loudness or density']::text[],ARRAY['Building a market-day soundscape for a history gallery','Adding a reconstructed ritual sound to an exhibit','Recreating a room''s acoustics in an immersive display']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Museum soundscape reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '418db124-559f-5465-a3ee-f1008387a583','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='418db124-559f-5465-a3ee-f1008387a583') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='418db124-559f-5465-a3ee-f1008387a583');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4000e933-2f71-59a4-9b8a-9a08cd1bc00f','Percussive artifact analysis','The study of artifacts that produce sound by being struck—lithophones, rock gongs, struck bells, clappers and similar objects—analysing their acoustic output, wear and use to understand their sound-making role. It combines organological classification, examination of percussion marks, and acoustic testing of originals or replicas to characterise pitch, timbre and function.','Percussive artifact analysis studies objects that make sound when hit. Examples include ringing stones and struck bells. Researchers look at wear marks and the sound produced. They may test originals or copies. This reveals how the objects were played and used.','It identifies and characterises struck sound-producing objects, distinguishing genuine instruments from ordinary tools and recovering their sonic behaviour.','Archaeomusicologists examine percussion marks and test replicas of ringing stones or struck bells to determine their pitch, timbre and use.','Archaeological & Heritage Acoustics',ARRAY['Idiophone artifact','Archaeological organology','Experimental instrument replication','Membranophone artifact','Paleo-organology']::text[],ARRAY['Assuming any marked stone was a musical instrument','Testing fragile originals instead of replicas','Ignoring natural causes of wear or ringing']::text[],ARRAY['Examining a suspected rock gong for percussion wear','Testing a replica lithophone''s pitches','Distinguishing a struck instrument from a tool']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Percussive artifact analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4000e933-2f71-59a4-9b8a-9a08cd1bc00f','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4000e933-2f71-59a4-9b8a-9a08cd1bc00f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4000e933-2f71-59a4-9b8a-9a08cd1bc00f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '469b96b2-b6d2-5c3c-8d29-e88c28b28439','Idiophone artifact','An archaeological object classified, under the Hornbostel–Sachs system, as an idiophone: an instrument that produces sound from the vibration of its own rigid body, without strings or a stretched membrane. Examples recovered archaeologically include rattles, bells, clappers, struck or scraped stones and jingles. Identification rests on form, wear, sound-producing features and context.','An idiophone artifact is an ancient instrument that sounds by its own body vibrating. It has no strings and no drum skin. Rattles, bells and clappers are examples. Researchers identify them by shape, wear and context. They form one class in a standard instrument system.','It names a clear organological category for excavated sound-makers, so self-sounding instruments can be identified and compared across sites.','Archaeologists classify excavated rattles, bells and clappers as idiophones to organise finds and study ancient sound-making.','Archaeological & Heritage Acoustics',ARRAY['Aerophone artifact','Membranophone artifact','Chordophone artifact','Archaeological organology','Percussive artifact analysis']::text[],ARRAY['Assuming every rattle-like object was a musical instrument','Confusing an idiophone with a membrane drum','Classifying from shape alone without wear or context']::text[],ARRAY['Cataloguing an excavated bronze bell as an idiophone','Distinguishing a rattle from a container','Comparing idiophones across related sites']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Idiophone artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '469b96b2-b6d2-5c3c-8d29-e88c28b28439','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='469b96b2-b6d2-5c3c-8d29-e88c28b28439') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='469b96b2-b6d2-5c3c-8d29-e88c28b28439');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b953cd47-401d-5801-a9cd-5f1cec714738','Aerophone artifact','An archaeological object classified, under the Hornbostel–Sachs system, as an aerophone: an instrument that produces sound by making a body of air vibrate, such as flutes, whistles, pipes, panpipes, horns and trumpets. Because their sounding mechanism depends on bore, holes and mouthpiece, surviving examples—often in bone, clay or metal—can sometimes be played or replicated to recover their pitches.','An aerophone artifact is an ancient instrument that sounds by vibrating air. Flutes, whistles and horns are examples. Its sound depends on the tube and finger holes. Some survive in bone, clay or metal. Researchers can sometimes play copies to hear their notes.','It names the organological class of wind instruments among finds, so air-vibrating sound-makers can be identified, studied and compared.','Archaeologists identify bone flutes, clay whistles and metal horns as aerophones and test replicas to recover their scales.','Archaeological & Heritage Acoustics',ARRAY['Idiophone artifact','Membranophone artifact','Chordophone artifact','Archaeological organology','Experimental instrument replication']::text[],ARRAY['Reading modern scales into an ancient wind instrument','Blowing fragile originals instead of replicas','Assuming a holed bone was always a flute']::text[],ARRAY['Classifying a pierced bone as a flute','Testing a replica of a prehistoric whistle','Recovering the pitches of an ancient horn']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aerophone artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b953cd47-401d-5801-a9cd-5f1cec714738','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b953cd47-401d-5801-a9cd-5f1cec714738') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b953cd47-401d-5801-a9cd-5f1cec714738');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '429ad70c-e601-5685-b4e8-2cdf14effa7e','Membranophone artifact','An archaeological object classified, under the Hornbostel–Sachs system, as a membranophone: an instrument that produces sound from a stretched membrane, chiefly drums. Because skins rarely survive, membranophones are usually recognised from their durable frames, shells or bodies and from depictions, with the original membrane inferred rather than preserved.','A membranophone artifact is an ancient drum-type instrument. Its sound came from a stretched skin. The skin itself rarely survives. Researchers recognise it from the surviving body or shell. Pictures and context help confirm what it was.','It names the organological class of membrane instruments, letting researchers identify drums from their surviving parts even when the skin is gone.','Archaeologists identify drum shells and frames as membranophones, using shape, fittings and imagery to infer the lost membrane.','Archaeological & Heritage Acoustics',ARRAY['Idiophone artifact','Aerophone artifact','Chordophone artifact','Archaeological organology','Experimental instrument replication']::text[],ARRAY['Expecting the skin to survive with the body','Confusing a drum shell with a plain vessel','Assuming every drum-shaped find was musical']::text[],ARRAY['Identifying a ceramic drum shell as a membranophone','Inferring a lost skin from a surviving frame','Reading depictions to confirm a drum']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Membranophone artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '429ad70c-e601-5685-b4e8-2cdf14effa7e','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='429ad70c-e601-5685-b4e8-2cdf14effa7e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='429ad70c-e601-5685-b4e8-2cdf14effa7e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45ce2842-3662-56c7-b7c5-683ab6ec5c6b','Chordophone artifact','An archaeological object classified, under the Hornbostel–Sachs system, as a chordophone: an instrument that produces sound from vibrating strings stretched between fixed points, such as lyres, harps, lutes and zithers. Strings and often the wooden body decay, so chordophones are typically recognised from durable parts—bridges, tuning fittings, frames—and from images and context.','A chordophone artifact is an ancient string instrument. Lyres and harps are examples. It made sound from vibrating strings. Strings and wood usually rot away. Researchers recognise it from surviving parts and pictures.','It names the organological class of string instruments, so stringed sound-makers can be identified from their surviving components.','Archaeologists reconstruct lyres and harps from surviving frames, fittings and imagery, classing them as chordophones.','Archaeological & Heritage Acoustics',ARRAY['Idiophone artifact','Aerophone artifact','Membranophone artifact','Archaeological organology','Experimental instrument replication']::text[],ARRAY['Expecting strings and wood to survive intact','Guessing string number or tuning without evidence','Confusing a decorative frame with an instrument']::text[],ARRAY['Reconstructing an excavated lyre as a chordophone','Inferring a harp from surviving fittings','Using imagery to confirm a string instrument']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chordophone artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45ce2842-3662-56c7-b7c5-683ab6ec5c6b','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45ce2842-3662-56c7-b7c5-683ab6ec5c6b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45ce2842-3662-56c7-b7c5-683ab6ec5c6b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fc48d494-31cd-509e-b881-0e6573faf9b5','Archaeological organology','The branch of organology—the systematic study of musical instruments—concerned with instruments recovered archaeologically. It classifies finds (commonly by the Hornbostel–Sachs scheme), analyses their construction and sound-producing mechanisms, and interprets their musical and cultural roles, often alongside experimental replication and archaeomusicology.','Archaeological organology is the study of ancient instruments as objects. It classifies finds by how they make sound. It examines how they were built and played. Researchers often build copies to test them. It links the objects to past music and culture.','It provides the framework for identifying, classifying and interpreting excavated instruments as evidence of past music.','Specialists classify and analyse excavated flutes, lyres and rattles, often testing replicas, to reconstruct ancient musical practice.','Archaeological & Heritage Acoustics',ARRAY['Idiophone artifact','Aerophone artifact','Membranophone artifact','Chordophone artifact','Experimental instrument replication']::text[],ARRAY['Assuming modern instrument categories map neatly onto ancient finds','Interpreting music from an object without wider evidence','Skipping replication that would test how a find sounded']::text[],ARRAY['Classifying a museum''s excavated instruments','Analysing how an ancient flute was made and played','Combining finds with imagery to study past music']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Archaeological organology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fc48d494-31cd-509e-b881-0e6573faf9b5','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fc48d494-31cd-509e-b881-0e6573faf9b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fc48d494-31cd-509e-b881-0e6573faf9b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a4a75e45-d5ab-5069-b5cb-005921bc86c1','Experimental instrument replication','The experimental-archaeology practice of building working replicas of ancient or historical instruments from the evidence of surviving artifacts, using appropriate materials and techniques, in order to study how they were made and played and how they sounded. Playing replicas lets researchers recover pitch, timbre and dynamic range without risking fragile originals.','Experimental instrument replication means building copies of ancient instruments. Researchers use materials and methods like the originals. They then play the copies to hear the sound. This protects fragile finds from harm. It reveals how the instruments were made and used.','It recovers the playable sound and construction of ancient instruments safely, testing ideas that fragile originals cannot support.','Craftspeople and researchers replicate bone flutes, lyres and horns, then play them to measure pitch, timbre and how they were used.','Archaeological & Heritage Acoustics',ARRAY['Archaeological organology','Aerophone artifact','Chordophone artifact','Idiophone artifact','Paleo-organology']::text[],ARRAY['Using modern materials or tools that change the sound','Treating one replica''s sound as the only possible original','Playing originals when a replica should be used']::text[],ARRAY['Building a playable copy of a bone flute','Reconstructing a lyre to test its tuning','Making a horn replica to recover its notes']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Experimental instrument replication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a4a75e45-d5ab-5069-b5cb-005921bc86c1','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a4a75e45-d5ab-5069-b5cb-005921bc86c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a4a75e45-d5ab-5069-b5cb-005921bc86c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5dbd3b12-d56c-5cff-9aea-db58078daf61','Paleo-organology','Organology focused on the earliest and prehistoric musical instruments—their identification, classification, construction and inferred sound—drawing on scarce and fragmentary remains such as bone flutes and possible lithophones. Closely allied to archaeological organology and music archaeology, it emphasises the deep-time end of the instrument record, where evidence is sparse and interpretation cautious.','Paleo-organology studies the oldest known instruments. It looks at prehistoric finds like bone flutes. Researchers classify them and infer their sound. Evidence is scarce and often broken. So conclusions are drawn with care.','It concentrates organological study on prehistoric instruments, framing how the earliest sound-makers are identified and interpreted from fragmentary finds.','Researchers apply paleo-organology to Palaeolithic bone pipes and similar finds, classifying them and cautiously inferring their sound.','Archaeological & Heritage Acoustics',ARRAY['Archaeological organology','Aerophone artifact','Experimental instrument replication','Idiophone artifact','Music archaeology']::text[],ARRAY['Overinterpreting a broken bone as a definite instrument','Assuming a modern scale for a prehistoric find','Ignoring natural processes that mimic tool or use marks']::text[],ARRAY['Assessing a Palaeolithic bone pipe as an instrument','Classifying the earliest possible sound-makers','Cautiously inferring a prehistoric find''s sound']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Paleo-organology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5dbd3b12-d56c-5cff-9aea-db58078daf61','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5dbd3b12-d56c-5cff-9aea-db58078daf61') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5dbd3b12-d56c-5cff-9aea-db58078daf61');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '669a4fa6-a1ac-5fb4-9d80-c41904584437','Sonic landscape reconstruction','The reconstruction of the soundscape of a past landscape or environment—the combined natural, human and built sounds and their propagation across terrain—using acoustic modelling, ecological and archaeological evidence, and audibility analysis. It aims to represent how a whole environment, not just a single building, would have sounded to people within it.','Sonic landscape reconstruction rebuilds the sound of a whole past setting. It covers natural, human and built sounds together. Researchers model how they spread across the land. They use evidence about the site and its life. The result shows how the place once sounded.','It recreates environment-scale past soundscapes, letting researchers study and convey how landscapes sounded rather than only single spaces.','Researchers combine terrain propagation models with archaeological and ecological evidence to reconstruct how a past landscape sounded.','Archaeological & Heritage Acoustics',ARRAY['Soundscape archaeology','Sound catchment','Audibility zone','Museum soundscape reconstruction','Historical sound-field simulation']::text[],ARRAY['Presenting a reconstruction as certain rather than a plausible model','Using species or sounds wrong for the period','Ignoring how terrain and weather shaped sound outdoors']::text[],ARRAY['Reconstructing the soundscape of a prehistoric valley','Modelling how sounds carried across a past settlement','Building an environment-scale soundscape for interpretation']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic landscape reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '669a4fa6-a1ac-5fb4-9d80-c41904584437','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='669a4fa6-a1ac-5fb4-9d80-c41904584437') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='669a4fa6-a1ac-5fb4-9d80-c41904584437');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55aa806b-879c-5037-b627-94159eff2cec','Sonic culture','The shared beliefs, practices, technologies, and meanings that a social group builds around sound and listening. Sonic culture treats sound not as neutral physical energy but as something produced, organised, valued, and interpreted within a specific historical and social setting. It covers how people make, circulate, regulate, and attach significance to sound, from music and speech to noise, silence, and recorded media, and how these patterns express and reproduce a community''s wider values.','Sonic culture is how a group of people deal with sound. It covers what they make, hear, and value. It also covers what they call music or noise. These habits are learned, not natural. They show what the group cares about.','The idea exists to frame sound as cultural rather than merely acoustic, letting scholars study how listening habits, sound-making, and sonic values are learned, shared, and tied to power, place, and identity.','Sound scholars and ethnographers use it to guide fieldwork, comparing how different communities organise music, speech, noise, and silence, and how recording and playback technologies reshape those patterns.','Anthropology & Sound Studies',ARRAY['Aural culture','Soundscape','Acoustemology','Sound studies','Auditory culture']::text[],ARRAY['Treating sound as a purely physical fact rather than something shaped by culture','Assuming sonic culture means only music, ignoring speech, noise, and silence','Reading one''s own listening habits as natural and universal instead of culturally specific']::text[],ARRAY['Comparing how two societies mark public space with sound','Studying how a community distinguishes valued music from unwanted noise','Tracing how recording technology changes a group''s listening habits']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic culture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55aa806b-879c-5037-b627-94159eff2cec','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55aa806b-879c-5037-b627-94159eff2cec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55aa806b-879c-5037-b627-94159eff2cec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3cf5d60f-783e-5aca-9e2a-0d13af498d70','Aural culture','The dimension of culture organised around hearing and listening, studied as a counterpart to the more familiar idea of visual culture. Aural culture, often called auditory culture, examines how societies privilege, train, and interpret the sense of hearing, how sound conveys knowledge and belonging, and how listening practices are historically and socially shaped. It stresses that ways of hearing are learned and carry meaning, rather than being a fixed biological given.','Aural culture is the part of culture built around hearing. It is the sound version of visual culture. It looks at how people learn to listen. Ways of hearing change across time and place. They are taught, not fixed at birth.','It exists to correct a long scholarly bias toward vision, insisting that hearing and listening are central to how people know their world, form groups, and pass on meaning.','Researchers apply it when analysing radio, oral tradition, religious listening, or urban sound, treating the ear as a serious route to cultural knowledge alongside the eye.','Anthropology & Sound Studies',ARRAY['Sonic culture','Visual culture','Auditory culture','Listening','Soundscape']::text[],ARRAY['Assuming hearing is a neutral biological sense with no cultural shaping','Treating aural culture as separate from vision rather than interwoven with it','Using it only for music while ignoring speech, environmental sound, and silence']::text[],ARRAY['Analysing how radio built shared national listening habits','Studying religious traditions that value hearing over seeing','Comparing how societies teach children what to listen for']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aural culture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3cf5d60f-783e-5aca-9e2a-0d13af498d70','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3cf5d60f-783e-5aca-9e2a-0d13af498d70') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3cf5d60f-783e-5aca-9e2a-0d13af498d70');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8bb4b3c0-e8df-5835-8a79-01786fae04a9','Listening culture','The set of shared habits, norms, and techniques of listening that a group treats as normal, skilled, or proper. A listening culture shapes what people attend to, how they focus or filter sound, and what counts as good or improper listening, whether in a concert hall, a place of worship, a workplace, or through headphones. Such cultures are historically produced, often alongside technologies and institutions that train the ear in particular ways.','A listening culture is a group''s shared way of listening. It sets what people notice and ignore. It says what good listening looks like. These rules differ between places like concerts and prayer. New tools like headphones can change them.','The concept lets scholars show that listening is a trained, rule-governed practice, not a passive act, and that different settings and eras cultivate very different ways of hearing.','It guides study of concert etiquette, medical or musical ear training, worship, and headphone use, revealing how institutions and devices teach people how to listen.','Anthropology & Sound Studies',ARRAY['Audile technique','Listening','Aural culture','Modes of listening','Soundscape']::text[],ARRAY['Thinking listening is passive rather than a trained, skilled practice','Assuming everyone in a society listens the same way','Ignoring how technologies and institutions teach particular ways of hearing']::text[],ARRAY['Explaining why silent concert listening became expected in Western halls','Studying how medical students learn to listen through a stethoscope','Comparing worship traditions that value loud versus quiet listening']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Listening culture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8bb4b3c0-e8df-5835-8a79-01786fae04a9','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8bb4b3c0-e8df-5835-8a79-01786fae04a9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8bb4b3c0-e8df-5835-8a79-01786fae04a9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a0093155-3067-5905-bedf-bb86c3f0bc77','Auditory anthropology','The branch of anthropology that studies sound, hearing, and listening as central to human social and cultural life. Also called the anthropology of sound, it uses ethnographic fieldwork to understand how communities produce, organise, and interpret sound, how listening shapes knowledge and social relations, and how sonic practices connect people to place, memory, and power. It sits within sensory anthropology and both draws on and feeds the wider field of sound studies.','Auditory anthropology studies sound across human cultures. It asks how people make and hear sound together. It uses long-term fieldwork and careful listening. It treats hearing as a key way people know their world. It is part of the wider study of the senses.','It exists to bring the ear into anthropology, correcting a bias toward vision and text, and to show how sound and listening organise social life, knowledge, and belonging.','Researchers practise it through fieldwork that records, describes, and analyses local soundscapes, musical life, speech, ritual sound, and listening habits in specific communities.','Anthropology & Sound Studies',ARRAY['Anthropology of sound','Acoustemology','Sensory anthropology','Ethnomusicology','Sound studies']::text[],ARRAY['Confusing it with ethnomusicology, which centres on music rather than sound broadly','Assuming it studies only exotic or distant societies','Treating recordings as neutral data rather than shaped by the researcher''s choices']::text[],ARRAY['Fieldwork on how a rainforest community reads its acoustic environment','Studying how a city''s calls to prayer structure daily life','Analysing listening and sound in a factory or market']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory anthropology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a0093155-3067-5905-bedf-bb86c3f0bc77','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a0093155-3067-5905-bedf-bb86c3f0bc77') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a0093155-3067-5905-bedf-bb86c3f0bc77');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd077645b-edec-5a95-9b98-51b59cb0f0b7','Sonic sociality','The ways in which social relationships, group belonging, and shared experience are formed and sustained through sound. Sonic sociality draws on the anthropological concept of sociality to describe how making, sharing, and listening to sound binds people together, coordinates action, and produces a sense of collective presence. It spans music-making, ritual, conversation, and mediated sound, treating sonic participation as a genuine mode of social life rather than mere background.','Sonic sociality is how sound brings people together. Shared music or talk can make a group feel joined. Sound helps people act as one. It builds a sense of being together. This works in person and through media.','The idea highlights sound as an active force in creating social bonds, letting researchers analyse togetherness that is felt and heard rather than only spoken or seen.','It informs studies of concerts, dance floors, religious gatherings, and online audio, showing how shared listening and sounding create belonging and coordinate groups.','Anthropology & Sound Studies',ARRAY['Sociality','Sonic culture','Participatory listening','Acoustic community','Sonic intimacy']::text[],ARRAY['Treating sound as mere background to social life rather than a maker of it','Assuming only music, not everyday sound and speech, builds sonic bonds','Ignoring that shared sound can also exclude and divide groups']::text[],ARRAY['Studying how a crowd becomes one through chanting at a match','Analysing belonging on a dance floor built by shared bass','Examining online listening groups that feel present together']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic sociality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd077645b-edec-5a95-9b98-51b59cb0f0b7','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d077645b-edec-5a95-9b98-51b59cb0f0b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d077645b-edec-5a95-9b98-51b59cb0f0b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '51213fe3-a44a-5990-b183-b3969a03da68','Sonic identity','The dimension of personal or collective identity that is expressed, constructed, and recognised through sound. Sonic identity covers the characteristic sounds, voices, musics, accents, and sonic styles by which individuals, communities, places, or institutions are known and distinguish themselves. Studied in anthropology and sound studies, it treats sound as a resource through which belonging and difference are performed and read, rather than a mere surface feature.','Sonic identity is who you are as shown through sound. It includes your voice, accent, and music. Groups and places have it too. People use these sounds to show belonging. Others use them to tell groups apart.','It gives scholars a way to study how identity is heard, showing that voices, accents, and musical styles carry and signal who people take themselves and others to be.','It appears in studies of accent and dialect, national or regional music, subcultural styles, and the crafted sonic identities of brands, cities, and institutions.','Anthropology & Sound Studies',ARRAY['Vocal identity','Sonic branding','Sonic culture','Soundmark','Acoustic community']::text[],ARRAY['Reducing sonic identity to commercial sound branding alone','Treating it as fixed rather than performed and changing across settings','Assuming a sound naturally belongs to a group rather than being made to signify it']::text[],ARRAY['Studying how an accent marks regional belonging','Analysing a city known by a distinctive musical style','Examining how a broadcaster builds a recognisable sonic signature']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic identity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '51213fe3-a44a-5990-b183-b3969a03da68','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='51213fe3-a44a-5990-b183-b3969a03da68') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='51213fe3-a44a-5990-b183-b3969a03da68');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1cfe7a9-c776-51eb-8b53-2e26c940c8b5','Vocal identity','The set of relatively stable, distinctive characteristics of a person''s voice by which they can be recognised and told apart from others. Vocal identity arises from anatomical features such as vocal tract and vocal fold dimensions together with learned habits of pronunciation, rhythm, and expression. Studied in phonetics, linguistic anthropology, and forensic speaker analysis, it also carries social meaning, signalling a speaker''s background, group membership, and self-presentation.','Vocal identity is what makes your voice yours. It comes from your body and your habits. People can often tell who is speaking by ear. A voice can also hint at where someone is from. It carries both a person and a background.','The concept lets researchers treat the voice as a marker of the individual, supporting work on recognition, on how voices signal social background, and on how speakers craft a self through sound.','It underlies forensic speaker comparison, phonetic study of individual variation, and anthropological work on how people use voice to project background, gender, and status.','Anthropology & Sound Studies',ARRAY['Sonic identity','Speaker recognition','Grain of the voice','Prosody','Voice']::text[],ARRAY['Assuming a voice is a foolproof identifier like a fingerprint','Ignoring how illness, emotion, and setting change the voice','Treating vocal traits as purely physical and not also learned and social']::text[],ARRAY['Comparing a suspect recording with a known voice in forensics','Studying how speakers shift voice to signal group belonging','Analysing what makes a broadcaster''s voice instantly recognisable']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vocal identity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1cfe7a9-c776-51eb-8b53-2e26c940c8b5','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1cfe7a9-c776-51eb-8b53-2e26c940c8b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1cfe7a9-c776-51eb-8b53-2e26c940c8b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '41b5fd3f-e191-561b-a47f-ec4acd4973b6','Sonic embodiment','The idea that sound is produced, sensed, and made meaningful through the whole body rather than the ears alone. Sonic embodiment draws on theories of embodiment to stress that hearing is entangled with vibration felt on the skin and in the chest, with breath and vocal effort in sound-making, and with bodily movement and memory. It treats sonic experience as a corporeal, situated practice, shaped by the specific body and its cultural training.','Sonic embodiment means sound lives in the body. We do not only hear it. We feel it as vibration in the chest and skin. Making sound uses breath and muscles. Bodies are trained to feel and make sound in learned ways.','It exists to counter a narrow view of hearing as a purely mental, ear-based act, showing that bodies produce and register sound and that this shapes what sound means.','It informs research on singing and vocal effort, on dance and deaf experience of vibration, and on how loud low-frequency sound is felt physically at events.','Anthropology & Sound Studies',ARRAY['Embodied listening','Vibrational practice','Sonic experience','Proprioception','Acoustemology']::text[],ARRAY['Assuming hearing happens only in the ears and brain','Overlooking that deaf and hard-of-hearing people sense sound through vibration','Separating sound-making from the breathing, moving body that produces it']::text[],ARRAY['Studying how singers feel resonance while performing','Analysing how club bass is felt in the body, not just heard','Examining how deaf dancers sense rhythm through vibration']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic embodiment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '41b5fd3f-e191-561b-a47f-ec4acd4973b6','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='41b5fd3f-e191-561b-a47f-ec4acd4973b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='41b5fd3f-e191-561b-a47f-ec4acd4973b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0b6fa20d-d6ea-5744-b97b-1e5609efa316','Embodied listening','An approach to listening that treats it as a whole-body, situated activity rather than a passive registering of sound in the ear and mind. Embodied listening emphasises that a listener''s posture, movement, felt vibration, emotional state, and cultural training all shape what is heard and how it is understood. It positions the listening body as an active participant that helps produce sonic meaning, drawing on phenomenology and theories of embodiment within sound studies.','Embodied listening means we listen with the whole body. Your posture, movement, and mood shape what you hear. Felt vibration is part of it too. Listening is active, not just receiving sound. Training and culture guide how you listen.','It exists to reframe listening as an active bodily practice, helping scholars explain why the same sound is heard differently by differently trained and situated bodies.','It guides research on music and dance, on field recording practice, and on designing listening exercises that ask people to attend with the whole body.','Anthropology & Sound Studies',ARRAY['Sonic embodiment','Deep listening','Situated listening','Vibrational practice','Phenomenology of listening']::text[],ARRAY['Treating listening as passive reception rather than active bodily work','Ignoring how mood, posture, and movement change what is heard','Assuming listening is the same for every body and culture']::text[],ARRAY['Guiding a listening exercise that includes movement and breath','Studying how dancers listen through their whole bodies','Analysing how a field recordist''s stance shapes what they attend to']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Embodied listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0b6fa20d-d6ea-5744-b97b-1e5609efa316','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0b6fa20d-d6ea-5744-b97b-1e5609efa316') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0b6fa20d-d6ea-5744-b97b-1e5609efa316');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4e1aeca2-5583-51ab-8b0e-0ddb71319665','Situated listening','An approach that treats listening as always bound to a particular place, body, moment, and social position, rather than as a neutral or universal act. Situated listening draws on the idea of situated knowledge to argue that where and who a listener is shapes what they can hear and how they interpret it. It foregrounds context, standpoint, and power, insisting that there is no view from nowhere in hearing, only located, partial acts of listening.','Situated listening means listening always happens somewhere. Your place, body, and background shape what you hear. There is no neutral outside spot to listen from. Two people can hear one sound differently. Context and power matter.','The concept exists to reject the idea of a detached, universal listener, pushing researchers to account for standpoint, location, and power in every act of hearing.','It shapes reflexive field recording and ethnography, prompting researchers to note where they stood, who they were, and how that shaped what they heard.','Anthropology & Sound Studies',ARRAY['Situated knowledge','Embodied listening','Acoustemology','Standpoint','Positionality']::text[],ARRAY['Assuming a listener can occupy a neutral, view-from-nowhere position','Ignoring how a researcher''s identity shapes what they hear and record','Treating recorded sound as context-free evidence']::text[],ARRAY['A researcher noting their standpoint while recording a ritual','Comparing how insiders and outsiders hear the same street','Reflecting on how gender shapes access to certain sounds in fieldwork']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Situated listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4e1aeca2-5583-51ab-8b0e-0ddb71319665','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4e1aeca2-5583-51ab-8b0e-0ddb71319665') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4e1aeca2-5583-51ab-8b0e-0ddb71319665');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ed1f7073-9fc3-5594-ada4-d585a7b784e2','Deep listening','A practice and philosophy of listening developed by composer Pauline Oliveros that cultivates heightened, sustained, and inclusive attention to all sound, including music, environmental sound, and silence. Deep listening distinguishes hearing, a passive physiological event, from listening, an active and trainable awareness, and uses meditation, bodywork, and improvisation to expand it. It aims to open the listener to the full sonic field, treating focused and global attention to sound as an ethical and creative discipline.','Deep listening is a practice made by Pauline Oliveros. It trains you to notice all sound and silence. Hearing just happens, but listening takes work. It uses meditation, movement, and improvising. The goal is full, open awareness of sound.','It exists to develop listening as a deliberate, expandable skill and an ethical stance, opening people to sounds they usually filter out and to one another.','Musicians, sound artists, and educators use its exercises in workshops and performance to sharpen awareness, improvise together, and reconnect people with their sonic surroundings.','Anthropology & Sound Studies',ARRAY['Sonic Meditations','Embodied listening','Soundwalk','Acoustic ecology','Listening']::text[],ARRAY['Using deep listening loosely for any careful listening, ignoring Oliveros''s specific practice','Confusing hearing as a passive event with listening as active attention','Assuming it applies only to music rather than to all sound and silence']::text[],ARRAY['Leading a group through listening and breathing meditations','Using its methods to prepare musicians for free improvisation','Running a workshop that reconnects people with everyday sounds']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Deep listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ed1f7073-9fc3-5594-ada4-d585a7b784e2','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ed1f7073-9fc3-5594-ada4-d585a7b784e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ed1f7073-9fc3-5594-ada4-d585a7b784e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e180ec5-752f-5950-ab39-2762fc3de79d','Participatory listening','A mode of listening in which hearing is inseparable from taking part in the making of sound, characteristic of participatory music and ritual where the line between performer and audience is blurred. Drawing on ethnomusicological accounts of participatory performance, it describes an engaged, responsive listening that guides one''s own contribution, such as clapping, singing, or dancing, rather than the detached appraisal typical of a concert audience. The listener is a co-producer of the sonic event.','Participatory listening is listening while joining in. You hear in order to take part. You might clap, sing, or dance along. There is little split between player and crowd. The listener helps make the sound.','It highlights forms of listening tied to doing, letting scholars distinguish engaged, co-producing listeners from the still, judging audience of the concert tradition.','It informs study of communal singing, drumming circles, worship, and dance events, where listening steers each person''s ongoing contribution to the shared sound.','Anthropology & Sound Studies',ARRAY['Participatory music','Sonic sociality','Presentational performance','Listening culture','Groove']::text[],ARRAY['Assuming all listening resembles the silent concert audience','Treating participants as a passive crowd rather than co-producers of sound','Confusing it with simply listening in a group without taking part']::text[],ARRAY['Studying a drum circle where players listen and respond as one','Analysing congregational singing that guides each voice','Examining a dance event where listening shapes movement']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Participatory listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e180ec5-752f-5950-ab39-2762fc3de79d','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e180ec5-752f-5950-ab39-2762fc3de79d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e180ec5-752f-5950-ab39-2762fc3de79d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0399c2be-a819-5152-8f4e-166f9e99c37a','Sound diary','A kept record in which a person logs the sounds they notice over a period, often with notes on time, place, source, and personal response. Used in acoustic ecology, education, and ethnographic fieldwork, the sound diary trains attention to the everyday soundscape and yields data on how sonic environments are experienced. It may be written, drawn, or made with recordings, and it treats routine listening as a source of reflective, documentable knowledge.','A sound diary is a log of sounds you hear. You note what you heard, where, and when. You can add how it made you feel. It can use words, drawings, or recordings. It trains you to notice everyday sound.','It exists to sharpen listening and to capture how people actually experience their sonic surroundings over time, turning ordinary hearing into reflective, shareable evidence.','Teachers, acoustic ecologists, and researchers assign sound diaries to build listening skills and to gather grounded accounts of everyday soundscapes.','Anthropology & Sound Studies',ARRAY['Soundscape','Soundwalk','Acoustic ecology','Field recording','Listening']::text[],ARRAY['Logging only loud or unusual sounds and missing the constant background','Recording sources without noting place, time, or personal response','Treating it as a neutral record rather than a personal, selective account']::text[],ARRAY['Students keeping a week-long log of sounds at home','A researcher tracking how a neighbourhood sounds across a day','An artist gathering material for a soundscape composition']::text[],'beginner',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound diary');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0399c2be-a819-5152-8f4e-166f9e99c37a','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0399c2be-a819-5152-8f4e-166f9e99c37a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0399c2be-a819-5152-8f4e-166f9e99c37a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eb5cacb4-b44d-51cd-9898-d1f567249fbf','Listening walk','A walk taken with attention deliberately focused on the sounds of the surrounding environment, closely related to the soundwalk developed within acoustic ecology and the World Soundscape Project. On a listening walk, participants move through a place while noticing its sonic character, sources, textures, and changes, sometimes in silence and sometimes guided by prompts. It is used to heighten sonic awareness, document soundscapes, and reflect on the relationship between people, place, and sound.','A listening walk is a walk that focuses on sound. You move through a place and listen closely. You notice what you hear and how it changes. It is often done quietly. It builds awareness of a place''s sounds.','It exists to open ears to the everyday soundscape, giving participants direct, moving experience of how a place sounds and how listening shapes their sense of it.','Educators, artists, and acoustic ecologists lead listening walks and soundwalks to teach attentive listening and to gather first-hand knowledge of local soundscapes.','Anthropology & Sound Studies',ARRAY['Soundwalk','Soundscape','Acoustic ecology','Deep listening','Sound diary']::text[],ARRAY['Talking or playing music during the walk and missing the environment''s sound','Treating it as a hike with a view rather than a focus on hearing','Assuming there is nothing to hear in quiet or ordinary places']::text[],ARRAY['A class walking a campus in silence to map its sounds','An artist leading a soundwalk through a market','Residents walking a street to document changing noise']::text[],'beginner',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Listening walk');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eb5cacb4-b44d-51cd-9898-d1f567249fbf','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eb5cacb4-b44d-51cd-9898-d1f567249fbf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eb5cacb4-b44d-51cd-9898-d1f567249fbf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '72470806-3bb9-5664-bccc-d4a3b27a6734','Sonic mapping','The practice of representing the sounds of a place, community, or region in spatial form, typically by locating recordings, descriptions, or sonic features on a map. Sonic mapping, or sound mapping, is used in acoustic ecology, geography, and the arts to document soundscapes, reveal how sound is distributed and changes across space, and make listening the basis of spatial knowledge. Maps may be physical, digital, or interactive, combining audio with location and annotation.','Sonic mapping shows the sounds of a place on a map. Recordings or notes are pinned to locations. It reveals where sounds happen and how they differ. Maps can be paper or online. It turns listening into a map of a place.','It exists to make sound spatial and shareable, letting people see where sounds occur, compare areas, and track how soundscapes shift over time and place.','Researchers and artists build sound maps to document neighbourhoods, monitor noise, preserve disappearing sounds, and invite the public to explore places by ear.','Anthropology & Sound Studies',ARRAY['Community sound map','Soundscape','Field recording','Acoustic ecology','Counter-mapping sound']::text[],ARRAY['Treating a sound map as a complete, objective record rather than a selective one','Ignoring how the mapmaker''s choices shape what is included','Assuming a single recording captures a place''s whole soundscape']::text[],ARRAY['Pinning field recordings to an online city map','Mapping how noise levels vary across a district','Documenting seasonal sounds of a rural area']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '72470806-3bb9-5664-bccc-d4a3b27a6734','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='72470806-3bb9-5664-bccc-d4a3b27a6734') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='72470806-3bb9-5664-bccc-d4a3b27a6734');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1bafd15d-d2f5-59ed-aafc-ccc677ff0c5f','Community sound map','A sound map created with or by the members of a community to document, share, and reflect on the sounds of their own environment. Building on sound mapping methods, a community sound map foregrounds local participation, gathering residents'' recordings and descriptions of meaningful, everyday, or threatened sounds. It serves both as a record of a place''s sonic life and as a participatory process that can strengthen belonging, raise awareness, and support advocacy around local soundscapes.','A community sound map is made by local people. They record and add the sounds of their area. It captures sounds they care about. Making it together can build pride and awareness. It can also support local causes.','It exists to put mapping in residents'' hands, valuing local knowledge of sound and using the shared process to build connection and support action on a place''s soundscape.','Community groups, artists, and researchers run projects where residents record and map neighbourhood sounds, often to celebrate, preserve, or defend local sonic life.','Anthropology & Sound Studies',ARRAY['Sonic mapping','Soundscape','Participatory research','Acoustic community','Counter-mapping sound']::text[],ARRAY['Assuming residents'' recordings need no guidance on consent and context','Letting one group''s sounds stand for a whole diverse community','Treating the map as a product only, ignoring the value of the shared process']::text[],ARRAY['Residents mapping the sounds of a threatened market','A neighbourhood recording sounds it wants preserved','A group using its sound map to argue against a noisy development']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Community sound map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1bafd15d-d2f5-59ed-aafc-ccc677ff0c5f','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1bafd15d-d2f5-59ed-aafc-ccc677ff0c5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1bafd15d-d2f5-59ed-aafc-ccc677ff0c5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11601f69-693d-5e93-b85d-29ffbd5ef74e','Counter-mapping sound','The use of sound mapping to challenge official, dominant, or expert representations of a place by centring the sonic knowledge and experience of marginalised or overlooked groups. Drawing on counter-mapping in critical cartography, counter-mapping sound treats maps as claims about space and uses community-gathered recordings and listening to contest whose sounds count, to make silenced experiences audible, and to support claims to land, presence, or rights. It is an explicitly political, participatory practice.','Counter-mapping sound uses sound maps to push back. Official maps often ignore some people''s sounds. This method centres those left out. It makes their sounds count on the map. It is used to support their claims and rights.','It exists to turn sound mapping into a tool of contestation, letting groups challenge dominant accounts of a place and assert presence, memory, and rights through what is heard.','Activists and researchers use it to map sounds ignored by authorities, to evidence a community''s presence, or to contest noise, development, or displacement.','Anthropology & Sound Studies',ARRAY['Sonic mapping','Community sound map','Counter-mapping','Acoustic citizenship','Noise politics']::text[],ARRAY['Assuming any sound map is neutral rather than a political claim','Ignoring risks to communities whose sounds are made public','Treating counter-maps as objective truth rather than situated counter-claims']::text[],ARRAY['Mapping a community''s sounds to contest an official redevelopment plan','Making audible the sounds of a group erased from planning records','Using sound to evidence long-standing presence on contested land']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Counter-mapping sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11601f69-693d-5e93-b85d-29ffbd5ef74e','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11601f69-693d-5e93-b85d-29ffbd5ef74e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11601f69-693d-5e93-b85d-29ffbd5ef74e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff3d8d26-3a64-57d2-95fe-9df09ae1926a','Acoustic commons','The shared sonic environment understood as a common resource that a community collectively inhabits, shapes, and has a stake in, by analogy with shared land or water. Rooted in acoustic ecology and communication theory, the acoustic commons frames the soundscape as public and relational, where each sound-maker affects the shared field and where noise can be seen as a kind of pollution or enclosure. It raises questions of access, responsibility, and fairness in who gets to sound and to be heard.','The acoustic commons is the shared world of sound. Like shared land, everyone lives in it. Each sound you make affects others. Too much noise can spoil it for all. It raises questions of fairness in sound.','The idea exists to treat sound as public and shared, supporting arguments about noise, fairness, and responsibility, and about who has the right to make and to hear sound.','It informs acoustic ecology, community radio, noise policy debate, and art that frames the soundscape as a shared resource needing care.','Anthropology & Sound Studies',ARRAY['Sonic commons','Soundscape','Acoustic ecology','Noise pollution','Acoustic community']::text[],ARRAY['Assuming sound is private and affects only the person making it','Treating quiet as empty rather than a shared, valued condition','Ignoring that power shapes whose sounds dominate the commons']::text[],ARRAY['Debating fair use of shared sound in a dense neighbourhood','Framing community radio as tending a shared sonic resource','Arguing that constant noise encloses a public soundscape']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic commons');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff3d8d26-3a64-57d2-95fe-9df09ae1926a','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff3d8d26-3a64-57d2-95fe-9df09ae1926a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff3d8d26-3a64-57d2-95fe-9df09ae1926a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '27077096-87f7-5610-8646-6a4af986bc13','Sonic commons','The shared world of sound regarded as a collective resource that a group holds and shapes together, used closely alongside the term acoustic commons. Sonic commons emphasises that the soundscape is public and relational: audible to all within range, altered by every sound-maker, and subject to questions of access, fairness, and care. The concept supports thinking about noise, silence, and the right to sound as matters of shared rather than purely private concern.','The sonic commons is the shared space of sound. It works like the idea of an acoustic commons. Everyone in range shares it. Each sound changes it for others. It raises questions about fairness and noise.','It exists to frame the soundscape as a shared holding, grounding claims about noise, silence, and fair access to making and hearing sound in public life.','It appears in sound art, acoustic ecology, and debates over noise and public space, wherever the soundscape is treated as something held and shaped in common.','Anthropology & Sound Studies',ARRAY['Acoustic commons','Soundscape','Acoustic ecology','Sonic public space','Noise pollution']::text[],ARRAY['Treating it as wholly distinct from the acoustic commons rather than a close variant','Assuming the shared soundscape is equally open to all in practice','Overlooking silence as part of what the commons holds']::text[],ARRAY['Framing a shared courtyard''s sound as held in common','Discussing fair access to sound in public space','Art projects that treat the soundscape as a shared resource']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic commons');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '27077096-87f7-5610-8646-6a4af986bc13','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='27077096-87f7-5610-8646-6a4af986bc13') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='27077096-87f7-5610-8646-6a4af986bc13');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '535304ea-b106-5839-af23-d02e8b6b33c0','Acoustic public sphere','The domain of public life as constituted, shaped, and contested through sound, voice, and hearing, by analogy with the idea of the public sphere as a space of shared discussion. The acoustic public sphere draws attention to how broadcast speech, amplified religious or political sound, music, and noise create publics, circulate ideas, and mark who may be heard in common space. It treats listening and sounding as means of participation, exclusion, and the making of collective life.','The acoustic public sphere is public life made through sound. Speeches, broadcasts, and music reach many people at once. They help form groups and share ideas. Who gets to be heard is a real question. Listening is a way of taking part.','It exists to bring sound into thinking about public life, showing that being heard, and hearing others, is central to how publics form and how people are included or shut out.','It informs study of radio, public address, amplified worship, protest chants, and street sound as means by which publics are made and contested.','Anthropology & Sound Studies',ARRAY['Public sphere','Sonic public space','Acoustic citizenship','Soundscape','Noise politics']::text[],ARRAY['Assuming public debate is only textual and visual, not sonic','Treating access to being heard as equal for all groups','Ignoring how amplified sound can dominate and exclude in shared space']::text[],ARRAY['Studying how radio built a national listening public','Analysing amplified calls to prayer or sermons in shared space','Examining protest chants as claims to be heard in public']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic public sphere');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '535304ea-b106-5839-af23-d02e8b6b33c0','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='535304ea-b106-5839-af23-d02e8b6b33c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='535304ea-b106-5839-af23-d02e8b6b33c0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af325d1d-9492-5e69-91f2-2df5823822f6','Sonic public space','The sonic dimension of shared, publicly accessible space: the ways sound fills, defines, animates, and is contested within streets, squares, transit, and other common areas. Sonic public space attends to how music, speech, noise, signals, and silence shape the experience and use of public places, mark territory, and include or exclude different users. It treats sound as an active force in the making of public space rather than a mere by-product of activity there.','Sonic public space is the sound side of shared places. Streets and squares are full of sound. That sound shapes how the place feels and works. It can welcome some people and push others out. Sound helps mark who belongs.','The idea exists to show that public space is made and claimed sonically, not just visually, and that control over sound is a way of controlling shared places.','It guides study and design of streets, transit, and squares, and analysis of buskers, protests, vendors, and noise rules that shape who uses public space.','Anthropology & Sound Studies',ARRAY['Acoustic territories','Acoustic public sphere','Soundscape','Acoustic commons','Sound policing']::text[],ARRAY['Treating public sound as background noise rather than a shaping force','Assuming everyone experiences a place''s sound the same way','Ignoring how sound is used to claim or defend territory']::text[],ARRAY['Studying how buskers and traffic define a square''s feel','Analysing amplified sound used to move on loiterers','Examining how transit announcements order a station']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic public space');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af325d1d-9492-5e69-91f2-2df5823822f6','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af325d1d-9492-5e69-91f2-2df5823822f6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af325d1d-9492-5e69-91f2-2df5823822f6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a6666e3b-c916-5149-8e8f-8a73d97f1fdc','Acoustic citizenship','The forms of belonging, participation, and rights that are claimed and enacted through sound in shared social and political life. Acoustic citizenship, closely related to ideas of sonic or aural citizenship, concerns who is allowed to make sound, whose sounds are heard as legitimate, and how listening and voicing express membership in a community or polity. It links everyday sonic practices, from music to noise to speech, to questions of inclusion, recognition, and the right to be present and heard.','Acoustic citizenship is belonging shown through sound. It asks who may make sound in public. It asks whose sounds are treated as fine. Being heard can be a form of taking part. Being silenced can mean being shut out.','It exists to connect sound to membership and rights, letting scholars analyse how sounding and being heard mark full participation, and how sonic control marks exclusion.','It appears in studies of noise complaints, migrant and minority soundscapes, protest, and public music, where the right to sound signals belonging or its denial.','Anthropology & Sound Studies',ARRAY['Acoustic public sphere','Sonic public space','Noise politics','Sound policing','Right to quiet']::text[],ARRAY['Assuming sound is politically neutral rather than tied to belonging','Treating noise complaints as purely technical, not social','Ignoring how minorities'' sounds are more often policed as noise']::text[],ARRAY['Studying how migrant music is welcomed or policed in a city','Analysing protest sound as a claim to be heard','Examining whose worship sound is treated as noise']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic citizenship');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a6666e3b-c916-5149-8e8f-8a73d97f1fdc','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a6666e3b-c916-5149-8e8f-8a73d97f1fdc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a6666e3b-c916-5149-8e8f-8a73d97f1fdc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '217a345b-ded4-530b-b01c-f2fa27f1b27a','Right to quiet','The asserted right of individuals or communities to be free from intrusive, unwanted noise, framing quiet as a condition worth protecting rather than a mere preference. Advanced by acoustic ecologists, health researchers, and anti-noise advocates, the right to quiet links excessive noise to harms such as sleep disturbance, stress, and hearing damage, and grounds claims for regulation, quiet areas, and redress. It treats freedom from noise as a matter of health, wellbeing, and fairness in the shared sonic environment.','The right to quiet is the right to avoid unwanted noise. It treats quiet as worth protecting. Loud noise can harm sleep and health. So people ask for limits and quiet areas. It frames noise as a fairness and health issue.','It exists to give people a claim against harmful noise, supporting rules, quiet zones, and complaints by treating freedom from unwanted sound as a protectable interest.','It underlies noise ordinances, quiet-area designations, complaints, and public-health arguments about traffic, nightlife, and industrial noise.','Anthropology & Sound Studies',ARRAY['Noise pollution','Acoustic commons','Noise politics','Soundscape','Acoustic citizenship']::text[],ARRAY['Treating quiet as a luxury rather than a health and fairness issue','Assuming the right to quiet always outweighs others'' right to make sound','Ignoring that quiet and noisy areas are unevenly distributed by wealth and power']::text[],ARRAY['Residents invoking it against late-night venue noise','Designating quiet zones near hospitals or parks','Public-health arguments for limiting traffic noise']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Right to quiet');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '217a345b-ded4-530b-b01c-f2fa27f1b27a','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='217a345b-ded4-530b-b01c-f2fa27f1b27a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='217a345b-ded4-530b-b01c-f2fa27f1b27a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ae7ad51d-9675-569b-b9a5-8a914f1a11ad','Acoustic gentrification','The process by which gentrification reshapes the soundscape of a neighbourhood, typically by quieting, sanitising, or standardising it and by marginalising the sounds associated with prior, often lower-income or minority, residents. Also discussed as sonic gentrification, it describes how noise complaints, regulation, and changing tastes can silence music, street life, and cultural sound, so that sonic change both signals and drives social displacement. It links the politics of noise to wider struggles over urban space and belonging.','Acoustic gentrification is how change reshapes a place''s sound. New, richer residents often want it quieter. Old street life and music get treated as noise. Rules and complaints then silence them. Sound change pushes out earlier communities.','The concept exists to show that gentrification is also sonic, letting researchers trace how controlling and cleaning up sound helps displace communities and their cultural life.','It informs urban studies and sound scholarship on noise complaints, nightlife rules, and the fate of street music as neighbourhoods change.','Anthropology & Sound Studies',ARRAY['Gentrification','Noise politics','Sound policing','Soundscape','Acoustic citizenship']::text[],ARRAY['Treating noise complaints as neutral rather than tied to social change','Assuming a quieter neighbourhood is simply an improvement for all','Separating sonic change from the displacement of people and culture']::text[],ARRAY['Studying how new residents'' complaints silence a music venue','Tracing how street vendors'' calls vanish as an area gentrifies','Analysing nightlife curfews that follow upscale development']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic gentrification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ae7ad51d-9675-569b-b9a5-8a914f1a11ad','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ae7ad51d-9675-569b-b9a5-8a914f1a11ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ae7ad51d-9675-569b-b9a5-8a914f1a11ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0297e991-c23a-5d52-8281-a6b4e34a882d','Noise politics','The field of contestation over what counts as noise, whose sounds are treated as legitimate, and how sound is regulated in shared life. Noise politics examines how labelling sound as noise is never neutral but bound up with power, class, race, and morality, so that regulation, complaints, and campaigns against noise often target particular groups and practices. It also covers the political use of noise itself, from protest to disruption, treating the line between sound and noise as a social struggle.','Noise politics is the fight over what counts as noise. Calling a sound noise is never neutral. It often targets certain groups. Rules and complaints can carry bias. Noise can also be used to protest and disrupt.','It exists to show that noise is a judgement, not a fact, revealing how the power to define and control noise shapes who may sound and who is silenced.','It informs analysis of noise laws, complaint patterns, protest sound, and disputes over music, worship, and street life in shared space.','Anthropology & Sound Studies',ARRAY['Noise pollution','Sound policing','Acoustic gentrification','Sonic public space','Acoustic citizenship']::text[],ARRAY['Assuming noise is a purely objective, measurable category','Ignoring how class and race shape which sounds are called noise','Treating noise only as a nuisance and never as a tool of protest']::text[],ARRAY['Studying whose music draws noise complaints in a city','Analysing protest tactics that use disruptive sound','Examining bias in the enforcement of noise laws']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise politics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0297e991-c23a-5d52-8281-a6b4e34a882d','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0297e991-c23a-5d52-8281-a6b4e34a882d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0297e991-c23a-5d52-8281-a6b4e34a882d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '81e5005e-2a96-59ff-a8b5-6d0d945fd904','Aural regime','A historically and culturally specific ordering of listening and hearing, by analogy with the idea of a scopic regime for vision. An aural regime organises what is heard, how it is classified and valued, and whose ways of listening count as authoritative, often through institutions, technologies, and forms of knowledge. Used in sound studies and the anthropology of listening, the concept shows that hearing is governed by shifting rules and relations of power rather than being a fixed, natural capacity.','An aural regime is a set order of listening. It sets what gets heard and how it is judged. It says whose way of listening counts. These orders come from institutions and tools. They change across history and carry power.','It exists to treat listening as governed and historical, letting scholars analyse how power shapes what is heard, how it is classified, and whose hearing is authoritative.','It guides historical and ethnographic work on how colonial, scientific, religious, or media institutions trained and ranked ways of listening.','Anthropology & Sound Studies',ARRAY['Aurality','Scopic regime','Listening culture','Sonic governance','Acoustemology']::text[],ARRAY['Assuming ways of listening are natural rather than historically ordered','Treating one culture''s listening as the universal standard','Ignoring the institutions and technologies that shape a regime']::text[],ARRAY['Studying how colonial science ranked local ways of listening','Analysing how recording technology reordered valued listening','Examining a religious tradition''s authorised way of hearing']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aural regime');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '81e5005e-2a96-59ff-a8b5-6d0d945fd904','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='81e5005e-2a96-59ff-a8b5-6d0d945fd904') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='81e5005e-2a96-59ff-a8b5-6d0d945fd904');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef66e6a7-9e54-5ecd-94fc-785d2f666a75','Sonic governance','The regulation and management of sound in shared space, and the use of sound as an instrument of governing conduct. Sonic governance covers noise ordinances, curfews, zoning, and standards that set acceptable sound, as well as the deployment of sound, such as signals, announcements, or deterrent devices, to order behaviour and movement. It treats the control of sound as a technique of power exercised by states, institutions, and property owners over populations and public life.','Sonic governance is how sound is ruled and used to rule. Laws set what sound is allowed and when. Sound is also used to guide behaviour. Alarms and announcements move and order people. It is a way power works through sound.','It exists to name how authorities order life through sound, both by limiting sound and by using it, making the control of sound a visible technique of power.','It informs study of noise laws, curfews, transit and public announcements, and sonic deterrent devices used to manage crowds and public space.','Anthropology & Sound Studies',ARRAY['Sound policing','Noise politics','Sonic control','Aural regime','Sonic public space']::text[],ARRAY['Seeing noise rules as purely technical rather than exercises of power','Ignoring the use of sound itself to direct behaviour','Assuming sonic governance affects all groups equally']::text[],ARRAY['Analysing curfews and noise limits in a nightlife district','Studying deterrent sound devices aimed at loitering youth','Examining how transit sound orders passenger flow']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic governance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef66e6a7-9e54-5ecd-94fc-785d2f666a75','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef66e6a7-9e54-5ecd-94fc-785d2f666a75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef66e6a7-9e54-5ecd-94fc-785d2f666a75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11de1733-70d7-57ca-b199-b33cac9630b8','Sonic control','The deliberate use of sound to control, direct, deter, or manage people, behaviour, and spaces. Sonic control ranges from background music and signals that shape mood and movement to high-intensity or irritating sound used to deter, disperse, or exclude, such as anti-loitering devices and acoustic hailing or deterrent systems. Studied in sound studies and cultural theory, it treats sound as a technology of power that acts on bodies and conduct, sometimes below conscious awareness.','Sonic control is using sound to steer people. Soft music can calm shoppers and guide flow. Harsh or piercing sound can drive people away. Some devices target certain groups. Sound becomes a tool that acts on bodies.','It exists to highlight sound as an active means of shaping conduct, explaining how music, signals, and painful sound are used to attract, calm, deter, or exclude.','It appears in studies of retail music, transit and crowd management, anti-loitering deterrents, and sound used by security and military forces.','Anthropology & Sound Studies',ARRAY['Sonic warfare','Sonic governance','Sonic violence','Sound policing','Acoustic deterrent']::text[],ARRAY['Assuming background music is neutral rather than designed to shape behaviour','Treating sound as too weak to be a real tool of control','UNSAFE: using high-intensity deterrent or acoustic hailing sound on people without regard for hearing-damage thresholds']::text[],ARRAY['Analysing store music designed to guide shopper mood','Studying anti-loitering devices aimed at young people','Examining acoustic deterrents used in crowd control']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11de1733-70d7-57ca-b199-b33cac9630b8','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11de1733-70d7-57ca-b199-b33cac9630b8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11de1733-70d7-57ca-b199-b33cac9630b8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c92b293e-08a4-573a-827a-0d9e25061806','Sound policing','The enforcement of norms and rules about what sound is acceptable, where, and from whom, including formal policing through noise laws and complaints and informal social pressure. Sound policing examines how the regulation of sound frequently falls unequally, with the music, gatherings, worship, or speech of minority and marginalised groups more readily heard and treated as noise or threat. It links the control of sound to broader patterns of surveillance, discipline, and exclusion in public and private life.','Sound policing is controlling which sounds are allowed. It works through noise laws and complaints. It also works through social pressure. Minority groups'' sounds are often targeted more. Their music or prayer gets called noise.','It exists to reveal that controlling sound is a form of social control, showing how noise enforcement can discipline and exclude particular communities.','It informs study of noise complaints, permits, and policing of music, parties, worship, and street life, especially in diverse or contested neighbourhoods.','Anthropology & Sound Studies',ARRAY['Noise politics','Acoustic gentrification','Sonic governance','Acoustic citizenship','Sonic control']::text[],ARRAY['Treating noise enforcement as evenhanded across all groups','Assuming a noise complaint is only about volume, not about who is sounding','Separating sound policing from wider patterns of surveillance and exclusion']::text[],ARRAY['Studying uneven noise enforcement against minority music','Analysing complaints used to shut down community gatherings','Examining how worship sound is policed as disturbance']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound policing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c92b293e-08a4-573a-827a-0d9e25061806','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c92b293e-08a4-573a-827a-0d9e25061806') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c92b293e-08a4-573a-827a-0d9e25061806');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '49855969-6d71-5cfc-8d50-f68d835e85e3','Sonic violence','Harm inflicted through sound, ranging from the weaponised use of intense or painful sound to the sustained sonic assault of an environment on those within it. Sonic violence includes acoustic weapons and deterrents, the use of loud music in interrogation and torture, and the damaging, disorienting, or terrorising effects of war, industrial, or carceral soundscapes. Studied in sound studies and the anthropology of conflict, it treats sound as capable of real bodily and psychological injury, not merely nuisance.','Sonic violence is harm done through sound. Very loud or painful sound can be a weapon. Loud music has been used in torture. War and prison sound can wound and terrify. Sound can truly injure body and mind.','It exists to take seriously that sound can wound, letting scholars analyse how sound is used as a weapon and how harmful soundscapes damage those exposed to them.','It informs research on acoustic weapons, music in detention and torture, and the sonic conditions of war zones, prisons, and heavy industry.','Anthropology & Sound Studies',ARRAY['Sonic warfare','Acoustic trauma','Sonic control','Acoustic weapon','Noise politics']::text[],ARRAY['Dismissing sound as mere nuisance that cannot truly harm','Assuming only extreme volume, not sustained exposure, causes harm','UNSAFE: treating loud music or sonic deterrents as harmless coercion despite real hearing and psychological damage']::text[],ARRAY['Studying loud music used in interrogation','Analysing acoustic weapons for crowd dispersal','Examining the sonic toll of living beside constant industrial noise']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic violence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '49855969-6d71-5cfc-8d50-f68d835e85e3','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='49855969-6d71-5cfc-8d50-f68d835e85e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='49855969-6d71-5cfc-8d50-f68d835e85e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9133615-6016-5359-ad59-8ee866d1f4a6','Acoustic trauma','Sudden damage to the hearing system caused by exposure to intense sound, typically a single or brief high-level event such as a blast, gunshot, or explosion. Acoustic trauma can injure delicate structures of the inner ear, producing immediate hearing loss, tinnitus, or a sense of fullness, which may be temporary or permanent. A clinical and audiological term, it is distinguished from noise-induced hearing loss that develops gradually, and it underpins the case for hearing protection in loud environments.','Acoustic trauma is sudden ear damage from very loud sound. A blast or gunshot can cause it. It can bring instant hearing loss or ringing. The harm may be lasting. This is why loud settings need ear protection.','The term names a specific, sudden mode of hearing injury, helping distinguish it from gradual noise damage and grounding the need for protection against intense sound.','It is used in audiology, occupational health, and hearing conservation to explain injury from blasts, gunfire, and other sudden loud events and to justify protection.','Anthropology & Sound Studies',ARRAY['Noise-induced hearing loss','Tinnitus','Hearing conservation','Sound exposure','Sonic violence']::text[],ARRAY['Confusing sudden acoustic trauma with slow noise-induced hearing loss','Assuming a single very loud event cannot cause permanent damage','UNSAFE: treating brief exposure to gunfire or blasts as safe without hearing protection']::text[],ARRAY['Assessing hearing loss after a nearby explosion','Explaining why shooters need ear protection','Evaluating sudden tinnitus after a loud blast']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic trauma');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9133615-6016-5359-ad59-8ee866d1f4a6','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9133615-6016-5359-ad59-8ee866d1f4a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9133615-6016-5359-ad59-8ee866d1f4a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3782df1-508d-5f5c-aa48-2a6472db0791','Sonic intimacy','The sense of closeness, connection, and shared inner space produced through sound and especially the voice. Theorised in sound studies, sonic intimacy concerns how sound can feel near and personal, drawing listeners into relationships of trust, presence, or belonging, whether through a whispering voice, a shared frequency, or a mediated audio channel. Scholars use it both to describe warm, connective experiences and to analyse how media and markets stage and exploit feelings of intimacy through sound.','Sonic intimacy is closeness made through sound. A soft voice can feel very near. Shared sound can build trust and warmth. Radio and headphones can feel personal. Media can also stage this closeness on purpose.','The concept lets scholars explain the peculiar nearness of sound and voice, and how that felt intimacy is created, valued, and sometimes manufactured through media.','It appears in study of radio, podcasts, ASMR, phone and voice media, and intimate performance, where sound stages closeness between voice and listener.','Anthropology & Sound Studies',ARRAY['Vocal intimacy','Grain of the voice','Sonic sociality','Acousmatic voice','Sonic embodiment']::text[],ARRAY['Assuming intimacy comes only from words, not from sound qualities','Treating mediated intimacy as automatically false or shallow','Ignoring how markets and media deliberately craft sonic closeness']::text[],ARRAY['Analysing how a podcast host''s voice feels personal','Studying ASMR audio designed to feel close','Examining late-night radio''s sense of one-to-one contact']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic intimacy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3782df1-508d-5f5c-aa48-2a6472db0791','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3782df1-508d-5f5c-aa48-2a6472db0791') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3782df1-508d-5f5c-aa48-2a6472db0791');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c73c175-a0a7-59a4-9947-598553526ae6','Vocal intimacy','The closeness, warmth, and personal connection created specifically through the qualities of the human voice, such as breath, softness, proximity, and grain. A focused form of sonic intimacy, vocal intimacy concerns how a voice can feel as if it addresses a listener alone and enters their personal space, especially when amplified or recorded close to the mouth. Studied in voice and media scholarship, it is central to radio, telephony, whispering performance, and other close-miked or private vocal encounters.','Vocal intimacy is closeness made by the voice itself. Breath and softness make a voice feel near. A close mic can feel like a private whisper. It seems to speak to you alone. Radio and phones often create this.','It exists to isolate how the voice, apart from its words, produces felt closeness, helping explain the pull of close-miked, whispered, or private vocal sound.','It informs work on radio and telephone voice, close-miked singing, ASMR, and voice acting, where vocal qualities create a sense of personal address.','Anthropology & Sound Studies',ARRAY['Sonic intimacy','Grain of the voice','Close-miking','Acousmatic voice','Voice']::text[],ARRAY['Assuming intimacy is in the words rather than the voice''s texture','Ignoring how microphones and media manufacture vocal closeness','Treating all close vocal sound as sincere rather than sometimes staged']::text[],ARRAY['Studying how close-miked crooning feels personal','Analysing whispered ASMR performance','Examining the intimate address of late-night radio voices']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vocal intimacy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c73c175-a0a7-59a4-9947-598553526ae6','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c73c175-a0a7-59a4-9947-598553526ae6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c73c175-a0a7-59a4-9947-598553526ae6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9d87170f-af5d-5453-b8b0-ef3c85965562','Vocal archive','A collection that preserves recordings of human voices for study, memory, or heritage, and, more conceptually, the notion of the voice as a store of individual and cultural memory. Vocal archives range from oral-history and dialect collections to institutional and colonial sound archives holding voices recorded under unequal conditions. Studied in sound studies and anthropology, the concept raises questions about consent, ownership, power, and care in preserving, accessing, and returning recorded voices.','A vocal archive is a store of recorded voices. It keeps speech and song for the future. Some were made long ago under unfair power. Who owns and hears them matters. The voice itself can also hold memory.','It exists to preserve voices and to raise the ethical and political questions that recorded voices carry, about consent, ownership, access, and return.','It appears in oral-history projects, language documentation, and museum and colonial sound collections, and in debates over access and repatriation of recordings.','Anthropology & Sound Studies',ARRAY['Sonic repatriation','Sound archive','Oral history','Voice','Restricted listening']::text[],ARRAY['Treating archived voices as neutral data free of power and consent issues','Assuming old recordings can be freely used and published','Ignoring communities'' claims over voices recorded from them']::text[],ARRAY['Managing consent for an oral-history voice collection','Handling colonial-era recordings of a community''s speech','Debating access to a dialect and song archive']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vocal archive');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9d87170f-af5d-5453-b8b0-ef3c85965562','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9d87170f-af5d-5453-b8b0-ef3c85965562') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9d87170f-af5d-5453-b8b0-ef3c85965562');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fcc25897-1d7c-5748-8d4c-57b4ac1ee0be','Sonic repatriation','The return of sound recordings, or of access to and control over them, to the communities and descendants from whom they originated, often decades after collection. Practised in ethnomusicology and sound archiving, sonic repatriation, sometimes called the repatriation of recordings, responds to histories in which songs, voices, and knowledge were recorded and held by outside institutions. It ranges from giving back copies to full transfers of rights and stewardship, and it raises questions of ownership, cultural protocol, and repair.','Sonic repatriation means giving recordings back. Old songs and voices were often taken by outsiders. This work returns them to their communities. It can mean copies or full control. It tries to repair past wrongs.','It exists to return recorded heritage and its control to source communities, addressing past extraction and supporting cultural continuity, rights, and repair.','Archives, ethnomusicologists, and communities carry it out by returning digitised recordings, transferring rights, and following cultural rules on access and use.','Anthropology & Sound Studies',ARRAY['Vocal archive','Sound archive','Restricted listening','Culturally sensitive recording','Repatriation']::text[],ARRAY['Assuming handing over a digital copy settles all questions of ownership','Ignoring cultural rules that restrict who may hear certain recordings','Treating repatriation as a favour rather than a matter of rights and repair']::text[],ARRAY['An archive returning early recordings to a descendant community','Transferring rights over ceremonial songs back to their owners','Following access rules when returning restricted recordings']::text[],'advanced',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic repatriation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fcc25897-1d7c-5748-8d4c-57b4ac1ee0be','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fcc25897-1d7c-5748-8d4c-57b4ac1ee0be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fcc25897-1d7c-5748-8d4c-57b4ac1ee0be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2289319a-e81d-53ce-ab71-ac58561f921c','Restricted listening','The condition, governed by cultural rules or protocols, in which particular sounds, songs, or recordings may be heard only by certain people or under certain circumstances. Common in traditions where knowledge is restricted by gender, age, initiation, kinship, or sacred status, restricted listening means access to sound is controlled rather than open. It is central to ethical fieldwork and archiving, where researchers and institutions must respect limits on who may record, hold, hear, or circulate such material.','Restricted listening means some sounds are not for everyone. Rules may limit who can hear certain songs. Access can depend on age, gender, or status. Some sounds are sacred or secret. Researchers must respect these limits.','The concept names culturally controlled access to sound, guiding respectful research and archiving where certain songs or recordings must not be freely heard or shared.','It shapes fieldwork consent, archive access rules, and repatriation, wherever traditions restrict who may hear or hold particular recordings.','Anthropology & Sound Studies',ARRAY['Culturally sensitive recording','Sonic repatriation','Vocal archive','Cultural protocol','Secret-sacred']::text[],ARRAY['Assuming all recorded sound can be openly shared and published','Treating restrictions as obstacles rather than rights to respect','Ignoring that access rules may differ by gender, age, or status']::text[],ARRAY['Respecting rules that only initiated members may hear certain songs','Setting archive access limits on sacred recordings','Planning fieldwork around sounds that outsiders may not hear']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Restricted listening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2289319a-e81d-53ce-ab71-ac58561f921c','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2289319a-e81d-53ce-ab71-ac58561f921c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2289319a-e81d-53ce-ab71-ac58561f921c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ae9bef3e-b902-5317-b2ea-8e5cbf30c639','Culturally sensitive recording','An approach to capturing sound in the field that respects the cultural rules, values, consent, and rights of the people and communities being recorded. Culturally sensitive recording means seeking informed and ongoing consent, honouring protocols about what may be recorded and by whom, agreeing on ownership, access, and future use, and being alert to the power imbalances that recording can involve. Central to ethical ethnomusicology and anthropology, it treats recording as a relationship and responsibility, not merely a technical act.','Culturally sensitive recording respects the people being recorded. It means asking real permission first. It follows local rules about what may be recorded. It agrees on who owns and uses the sound. Recording is a relationship, not just a tool.','It exists to make field recording ethical and respectful, protecting communities'' consent, rights, and protocols and acknowledging the power that recording carries.','Ethnographers, ethnomusicologists, and archivists apply it when planning consent, agreeing access and ownership, and following cultural rules during fieldwork.','Anthropology & Sound Studies',ARRAY['Restricted listening','Sonic repatriation','Vocal archive','Informed consent','Field recording']::text[],ARRAY['Treating a one-time consent form as enough for all future uses','Assuming the recordist automatically owns what they capture','Ignoring local rules about who and what may be recorded']::text[],ARRAY['Negotiating consent and ownership before recording a ceremony','Following community rules on which songs may be captured','Agreeing future access terms with recorded participants']::text[],'intermediate',NULL,NULL,'d64162b5-13a1-46cf-bb3d-a744183f036e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Culturally sensitive recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ae9bef3e-b902-5317-b2ea-8e5cbf30c639','d64162b5-13a1-46cf-bb3d-a744183f036e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ae9bef3e-b902-5317-b2ea-8e5cbf30c639') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ae9bef3e-b902-5317-b2ea-8e5cbf30c639');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '871ed006-04f8-5f08-a90b-947ecb3a749b','Acoustic chemistry','The study and use of chemical effects produced when sound waves, usually ultrasound, pass through a liquid, driven mainly by acoustic cavitation: the nucleation, growth, and violent collapse of gas or vapour bubbles. Bubble collapse generates transient extreme local temperatures and pressures, shock waves, liquid microjets, and reactive radical species. Effectively synonymous with sonochemistry, it spans radical reactions, catalysis, and materials synthesis, as well as physical effects such as emulsification and particle dispersion.','Acoustic chemistry studies how sound changes chemistry. Strong sound waves in a liquid make tiny bubbles. These bubbles grow and then collapse hard. The collapse makes intense heat and pressure in tiny spots. That energy drives chemical reactions. It is also called sonochemistry.','It gives a way to drive and control chemical reactions with acoustic energy instead of, or alongside, heat and conventional reagents, exploiting cavitation to reach conditions and reaction pathways hard to achieve by ordinary means.','Chemists meet it when using ultrasonic baths and probe sonicators to speed reactions, make nanoparticles, initiate radical chemistry, emulsify or disperse solids, and clean or activate surfaces.','Chemical & Molecular Acoustics',ARRAY['Sonochemistry','Acoustic cavitation','Ultrasonic chemistry','Sonoluminescence','High-power ultrasound']::text[],ARRAY['Assuming the sound itself reacts with molecules, rather than cavitation being the true driver','Confusing gentle low-intensity ultrasound with reaction-driving high-power ultrasound','UNSAFE: running high-power sonicators without hearing protection and without skin and eye shielding near the tip']::text[],ARRAY['Using an ultrasonic probe to speed a radical reaction','Making metal nanoparticles by sonicating a salt solution','Emulsifying two immiscible liquids without a chemical surfactant']::text[],'beginner',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic chemistry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '871ed006-04f8-5f08-a90b-947ecb3a749b','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='871ed006-04f8-5f08-a90b-947ecb3a749b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='871ed006-04f8-5f08-a90b-947ecb3a749b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2e597dc0-9778-5c6b-be22-9eaa7f97ba92','Ultrasonic chemistry','Chemistry carried out or induced with ultrasound (frequencies above roughly 20 kHz), in which acoustic cavitation in the liquid produces localized hot spots, high pressures, shock waves, and radicals that initiate or accelerate reactions. The term is used interchangeably with sonochemistry. Low-frequency, high-power ultrasound in the tens of kilohertz is most common for driving reactions and mechanical effects, while higher frequencies tend to favour radical yields.','Ultrasonic chemistry uses ultrasound to drive chemistry. Ultrasound is sound too high for people to hear. In a liquid it makes bubbles that collapse hard. The collapse creates heat, pressure, and reactive pieces called radicals. These start or speed up reactions. It means much the same as sonochemistry.','It applies ultrasound as an energy source for chemistry, using cavitation to supply heat, pressure, and radicals so reactions proceed faster, under milder bulk conditions, or by pathways heat alone cannot easily reach.','Technicians and chemists apply it with ultrasonic baths, horns, and flow cells for synthesis, extraction, emulsification, degassing, and cleaning, choosing frequency and power to suit the target effect.','Chemical & Molecular Acoustics',ARRAY['Sonochemistry','Acoustic cavitation','High-power ultrasound','Radical formation','Sonochemical reactor']::text[],ARRAY['Believing higher frequency always means stronger effects, when mechanical and erosive effects fall as frequency rises','Treating all ultrasound as reaction-driving, when low-intensity ultrasound only probes or measures','UNSAFE: assuming an ultrasonic bath or horn is harmless, when airborne ultrasound and probe contact both cause hazards']::text[],ARRAY['Choosing a low frequency for strong mixing versus a high frequency for radical yield','Speeding an extraction from plant material in an ultrasonic bath','Degassing a solvent before an experiment']::text[],'beginner',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic chemistry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2e597dc0-9778-5c6b-be22-9eaa7f97ba92','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2e597dc0-9778-5c6b-be22-9eaa7f97ba92') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2e597dc0-9778-5c6b-be22-9eaa7f97ba92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c85f3f9e-cc0f-554e-b2b8-24d7077a5bd2','High-power ultrasound','Ultrasound applied at intensities high enough to produce acoustic cavitation and pronounced mechanical effects in a medium, in contrast to low-intensity diagnostic or analytical ultrasound. It is usually generated at low ultrasonic frequencies (about 20 to 100 kHz) by magnetostrictive or piezoelectric transducers driving horns or baths. It delivers the cavitation, acoustic streaming, microjets, and heating that underlie sonochemistry, cleaning, emulsification, and cell disruption.','High-power ultrasound is strong, high-energy ultrasound. It carries enough energy to make bubbles form and collapse. This is called cavitation. The collapse creates heat, jets, and mixing. It powers cleaning, mixing, and chemistry. It is far stronger than the ultrasound used for medical scans.','It delivers concentrated mechanical and thermal energy into a liquid or tissue to drive cavitation-based processes such as reactions, mixing, particle breakup, and cleaning that low-intensity ultrasound cannot achieve.','It is met as probe and horn sonicators and high-power baths in labs and industry for sonochemistry, cell lysis, degassing, emulsification, plastic welding, and cleaning.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic intensity','Acoustic cavitation','Sonication','Ultrasonic horn','Low-intensity ultrasound']::text[],ARRAY['Confusing it with low-intensity diagnostic ultrasound, which is kept below the cavitation threshold','Assuming more power always helps, when excess power causes decoupling and cavitation shielding at the tip','UNSAFE: touching or looking into an operating horn tip, or running it without hearing protection and eye and skin shielding']::text[],ARRAY['Lysing cells with a probe sonicator to release their contents','Degassing a liquid before precise density or speed-of-sound measurement','Driving a sonochemical reaction in a horn reactor']::text[],'beginner',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='High-power ultrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c85f3f9e-cc0f-554e-b2b8-24d7077a5bd2','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c85f3f9e-cc0f-554e-b2b8-24d7077a5bd2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c85f3f9e-cc0f-554e-b2b8-24d7077a5bd2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'acee8807-6a9c-5b96-bec7-e94c921536a4','Low-intensity ultrasound','Ultrasound applied at intensities below the cavitation and strong-effect threshold, used to interrogate or gently stimulate a medium without driving violent cavitation or significant heating. In physical and analytical acoustics it underlies non-destructive measurement of sound speed, attenuation, and impedance, and gentle biological stimulation. It contrasts with high-power ultrasound, which is used to drive sonochemistry and disruption.','Low-intensity ultrasound is gentle, low-energy ultrasound. It is too weak to make bubbles collapse violently. So it does not drive strong chemistry or heating. Instead it is used to measure or lightly stimulate. Medical scans and material tests use it.','It lets ultrasound probe or gently act on a system, measuring properties or stimulating tissue, while avoiding the cavitation, heating, and damage that high-power ultrasound causes.','It appears in ultrasonic velocity and attenuation measurement, non-destructive testing, particle sizing, diagnostic imaging, and low-intensity therapeutic stimulation.','Chemical & Molecular Acoustics',ARRAY['High-power ultrasound','Ultrasonic interferometry','Acoustic attenuation','Non-destructive testing','Ultrasonic intensity']::text[],ARRAY['Assuming ultrasound always means powerful cavitation, when most analytical ultrasound is deliberately low-intensity','Overdriving a measurement until cavitation begins, corrupting attenuation and velocity readings']::text[],ARRAY['Measuring the speed of sound in a solution to find its composition','Inspecting a weld for flaws without damaging it','Sizing suspended particles by how they scatter ultrasound']::text[],'beginner',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-intensity ultrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'acee8807-6a9c-5b96-bec7-e94c921536a4','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='acee8807-6a9c-5b96-bec7-e94c921536a4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='acee8807-6a9c-5b96-bec7-e94c921536a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5c29297-f1d6-5984-89c9-e3e488cca748','Acoustic pressure amplitude','The peak deviation of local pressure from ambient produced by a sound wave, that is, the maximum value of the oscillating acoustic pressure. In a plane progressive wave it relates to intensity by I = P_A squared divided by twice the product of density and sound speed. In cavitation studies the acoustic pressure amplitude, relative to ambient pressure and the liquid''s vapour and tensile behaviour, sets whether and how violently cavitation bubbles grow and collapse.','Acoustic pressure amplitude is the peak pressure swing in a sound wave. Sound makes pressure rise and fall around the normal value. The amplitude is how far it swings at most. Bigger swings carry more energy. In liquids, large swings make bubbles collapse harder.','It quantifies the strength of the sound field driving a medium; it is the key control variable that sets cavitation onset and violence and links directly to acoustic intensity.','Technicians set and measure it with calibrated hydrophones to control cavitation in sonoreactors, and use the intensity relation to convert between pressure, intensity, and power.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic intensity','Acoustic cavitation','Cavitation threshold','Sound pressure level','Hydrophone']::text[],ARRAY['Confusing peak amplitude with root-mean-square pressure, which differ by the square root of two for a sinusoid','Forgetting that the driving pressure amplitude, not just frequency, sets the cavitation threshold']::text[],ARRAY['Mapping the pressure field in a reactor with a calibrated hydrophone','Raising the drive until the pressure amplitude passes the cavitation threshold','Converting a measured pressure amplitude into acoustic intensity']::text[],'intermediate','I = P_A^2 / (2ρc)','Acoustic intensity equals the pressure amplitude squared divided by twice the medium''s density times its sound speed.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic pressure amplitude');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5c29297-f1d6-5984-89c9-e3e488cca748','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5c29297-f1d6-5984-89c9-e3e488cca748') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5c29297-f1d6-5984-89c9-e3e488cca748');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5db9f3bd-bc18-5d74-bff6-700567f34797','Ultrasonic intensity','The time-averaged acoustic power carried by an ultrasonic wave per unit area normal to propagation, expressed in watts per square metre or watts per square centimetre. For a plane progressive wave it equals the pressure amplitude squared divided by twice the product of density and sound speed. It measures how strongly a field drives a medium and, above a threshold, governs cavitation activity and sonochemical rate.','Ultrasonic intensity is the sound power flowing through an area. It says how much energy the beam delivers each second per unit area. Higher intensity means a stronger effect. Above a certain level, it makes bubbles form and collapse. That drives cavitation and chemistry.','It measures the energy flux that drives a process, letting cavitation, heating, and sonochemical effects be specified, compared, and kept above the cavitation threshold.','It is estimated by radiation-force balance, calorimetry, or hydrophone mapping to specify and compare sonochemical and cleaning systems and to confirm the field exceeds the cavitation threshold.','Chemical & Molecular Acoustics',ARRAY['Acoustic pressure amplitude','Acoustic intensity','Calorimetric power measurement','Cavitation threshold','High-power ultrasound']::text[],ARRAY['Quoting electrical input power as acoustic intensity, ignoring transducer and coupling losses','Assuming intensity is uniform across a reactor, when the field is highly non-uniform']::text[],ARRAY['Reporting delivered intensity from a calorimetric power measurement','Comparing two horns by acoustic intensity rather than nameplate wattage','Checking that a cleaning tank exceeds the cavitation threshold']::text[],'intermediate','I = P_A^2 / (2ρc)','Ultrasonic intensity equals the acoustic pressure amplitude squared divided by twice the density times the sound speed.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5db9f3bd-bc18-5d74-bff6-700567f34797','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5db9f3bd-bc18-5d74-bff6-700567f34797') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5db9f3bd-bc18-5d74-bff6-700567f34797');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8fa1af84-0ee2-5af9-9019-e35c8603f5b8','Sonochemical reactor','A vessel and transducer system designed to expose a liquid and its reactants to controlled ultrasonic fields so acoustic cavitation drives chemistry. Configurations include the ultrasonic bath, the immersed probe or horn reactor, the cup-horn, and specialized designs such as push-pull, hexagonal, and tubular reactors. Design controls frequency, delivered acoustic power, temperature, cavitation distribution, and mass transfer; delivered power is commonly quantified by calorimetry.','A sonochemical reactor is a tank that uses sound to drive chemistry. A driver sends strong sound into the liquid. This makes tiny bubbles that collapse and power reactions. The design sets the power, pitch, and heat. Baths and probe units are common types.','It provides a controlled, repeatable way to deliver ultrasonic energy to a reacting liquid, setting frequency, power, temperature, and flow so cavitation-driven chemistry can be studied or scaled.','It is used in labs and pilot plants for sonochemical synthesis, extraction, emulsification, and effluent treatment, chosen and characterized by frequency, geometry, and calorimetric power.','Chemical & Molecular Acoustics',ARRAY['Flow-through sonochemical reactor','Ultrasonic horn','Cup-horn reactor','Calorimetric power measurement','Acoustic cavitation']::text[],ARRAY['Comparing reactors by electrical rating instead of calorimetrically measured acoustic power','Ignoring erosion of the horn tip, which sheds metal particles into the mixture','UNSAFE: operating an open horn reactor without hearing protection, splash and aerosol containment, and cooling, and touching hot or vibrating surfaces']::text[],ARRAY['Selecting a cup-horn to sonicate sealed vials without probe contact','Reporting a reactor''s delivered power by calorimetry before a study','Scaling a bath process up to a larger sonoreactor']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonochemical reactor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8fa1af84-0ee2-5af9-9019-e35c8603f5b8','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8fa1af84-0ee2-5af9-9019-e35c8603f5b8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8fa1af84-0ee2-5af9-9019-e35c8603f5b8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71c20d31-2ea8-57d3-a969-bdc54056a798','Flow-through sonochemical reactor','A continuous sonochemical reactor in which the reacting liquid flows through an ultrasonically irradiated zone rather than being treated as a static batch. It is typically a tube, cell, or loop coupled to one or more transducers, or a recirculating horn or cup-horn. It enables continuous processing, better heat removal, more uniform cavitation exposure, and scale-up through control of residence time and flow rate.','A flow-through sonochemical reactor treats liquid as it flows past. The liquid moves through a zone filled with ultrasound. Cavitation acts on it as it passes. This allows continuous, non-stop processing. It also spreads the treatment more evenly and removes heat better.','It enables continuous, scalable sonochemical processing with more uniform exposure and good thermal control, overcoming the limited, non-uniform treatment of a static batch reactor.','It is used for continuous extraction, emulsification, water and effluent treatment, and crystallization control, where throughput and consistent cavitation dose per pass matter.','Chemical & Molecular Acoustics',ARRAY['Sonochemical reactor','Cavitation dose','Residence time','Ultrasonic flow cell','Acoustic cavitation']::text[],ARRAY['Assuming a single pass gives full conversion, when throughput trades against cavitation dose per pass','Neglecting standing waves and dead zones that make exposure non-uniform across the cross-section','UNSAFE: running pressurized or heated flow cells without pressure relief, containment, and hearing protection']::text[],ARRAY['Recirculating an effluent stream through a sonicated loop for pollutant breakdown','Setting flow rate to fix the cavitation dose each pass receives','Cooling a continuous process by removing heat between passes']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flow-through sonochemical reactor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71c20d31-2ea8-57d3-a969-bdc54056a798','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71c20d31-2ea8-57d3-a969-bdc54056a798') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71c20d31-2ea8-57d3-a969-bdc54056a798');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d10c57c-672f-57c8-bfc2-3b4d6795692e','Calorimetric power measurement','A method to determine the acoustic power a transducer actually delivers to a liquid by measuring the initial rate of temperature rise of a known mass of liquid under sonication and applying power equals mass times specific heat capacity times the initial rate of temperature rise. Because it captures dissipated acoustic energy rather than electrical input, it is the standard way to report delivered ultrasonic power and intensity in sonochemistry.','Calorimetric power measurement finds the real ultrasound power in a liquid. The ultrasound heats the liquid as its energy turns to heat. You measure how fast the temperature rises at first. From the mass and heat capacity you get the power. It shows true delivered power, not just electrical input.','It gives a transducer-independent, standardized measure of the acoustic power dissipated in the liquid, so different sonochemical systems can be compared on delivered energy rather than electrical rating.','It is done routinely by sonicating a known volume, logging temperature versus time, taking the initial slope, and reporting delivered power and derived intensity for a reactor.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic calorimetry','Ultrasonic intensity','Delivered acoustic power','Sonochemical reactor','Specific heat capacity']::text[],ARRAY['Using a late-time slope after heat losses grow, instead of the initial near-adiabatic rate','Neglecting insulation and stirring, so heat loss makes the measured power read too low']::text[],ARRAY['Calibrating a new probe by its initial heating slope in water','Comparing two reactors on delivered watts rather than nameplate power','Converting delivered power into intensity for a reactor cross-section']::text[],'intermediate','P = m·c_p·(dT/dt)','Delivered acoustic power equals the liquid mass times its specific heat capacity times the initial rate of temperature rise.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Calorimetric power measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d10c57c-672f-57c8-bfc2-3b4d6795692e','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d10c57c-672f-57c8-bfc2-3b4d6795692e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d10c57c-672f-57c8-bfc2-3b4d6795692e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e8570dd-4bf5-5f3a-8cd0-983a8008ab8f','Ultrasonic calorimetry','The use of calorimetry, measuring heat or temperature change, to quantify ultrasonic energy dissipated in a system, most commonly to determine the delivered acoustic power via the initial temperature-rise rate and hence the intensity, and sometimes to study thermal effects of sonication. It provides an absolute, transducer-independent energy measure and is the accepted basis for reporting sonochemical power.','Ultrasonic calorimetry finds sound energy from heat. The sound energy turns into heat in the liquid. You track how much the liquid warms up. That shows the energy the sound put in. It is mostly used to find the real power.','It supplies an absolute measure of ultrasonic energy input based on heat, underpinning power and intensity reporting and letting systems be compared and scaled on delivered energy.','It is applied to calibrate and compare sonoreactors and probes and to normalize sonochemical rates per unit of delivered energy.','Chemical & Molecular Acoustics',ARRAY['Calorimetric power measurement','Ultrasonic intensity','Delivered acoustic power','Cavitation yield','Sonochemical reactor']::text[],ARRAY['Treating the measured heat as cavitation energy alone, when it includes all dissipation, including viscous and absorptive losses','Assuming the result equals electrical input efficiency without accounting for coupling losses']::text[],ARRAY['Reporting a system''s delivered acoustic power for a publication','Normalizing a reaction rate to joules of ultrasound delivered','Checking whether a probe still delivers its rated power over time']::text[],'intermediate','P = m·c_p·(dT/dt)','Ultrasonic power dissipated equals mass times specific heat capacity times the initial rate of temperature increase.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic calorimetry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e8570dd-4bf5-5f3a-8cd0-983a8008ab8f','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e8570dd-4bf5-5f3a-8cd0-983a8008ab8f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e8570dd-4bf5-5f3a-8cd0-983a8008ab8f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '768aba52-66c5-50ef-b74e-e78877e6974e','Cavitation yield','A measure of the chemical output of cavitation, expressed as the amount of a product, such as radicals or a dosimeter reaction product, formed per unit of ultrasonic energy delivered or per unit time. Closely related to sonochemical efficiency, it links cavitation activity to useful chemical change and is used to compare frequencies, powers, and reactor designs. Chemical dosimeters such as iodide, Fricke, and terephthalate quantify it.','Cavitation yield measures how much chemistry cavitation produces. It compares product made to energy put in. A high yield means energy is used well. It helps compare different ultrasound settings. Chemists measure it with special test reactions.','It quantifies how effectively delivered acoustic energy is converted into chemical change, enabling optimization and fair comparison of sonochemical conditions and reactors.','It is measured with chemical dosimeters such as iodide, Fricke, and terephthalate to benchmark frequency, power, and geometry and to report reactor efficiency.','Chemical & Molecular Acoustics',ARRAY['Sonochemical efficiency','Cavitation dose','Dosimetry','Sonochemical reactor','Radical formation']::text[],ARRAY['Reporting yield without normalizing to delivered calorimetric energy, so systems cannot be compared','Assuming the highest power gives the highest yield, when excess power can lower it through bubble shielding']::text[],ARRAY['Finding the frequency that gives the best radical yield per joule','Using a terephthalate dosimeter to compare two reactors','Optimizing power for maximum product per unit energy']::text[],'intermediate','Y = n_product / E_acoustic','Cavitation yield equals the amount of product formed divided by the acoustic energy delivered.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavitation yield');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '768aba52-66c5-50ef-b74e-e78877e6974e','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='768aba52-66c5-50ef-b74e-e78877e6974e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='768aba52-66c5-50ef-b74e-e78877e6974e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ae3a565-96b0-547d-b4aa-730eaa48f424','Cavitation dose','The cumulative amount of cavitation activity a sample or region receives, that is, cavitation exposure integrated over time, conceptually the time integral of a cavitation-activity metric. Metrics include broadband acoustic emission, subharmonic and harmonic energy, sonochemiluminescence, or dosimeter product. It is used to correlate an outcome such as cleaning, cell lysis, reaction extent, or bioeffect with the cavitation actually delivered rather than with nominal power or time alone.','Cavitation dose is the total cavitation a sample receives. It adds up how much cavitation acts over the whole time. More activity or more time gives a larger dose. It links results to real cavitation, not just power. Sensors track the cavitation to estimate it.','It provides an exposure measure that ties outcomes to the cavitation actually received, so processes can be controlled and reproduced even when field and bubble activity vary in space and time.','It is used in ultrasonic cleaning, sonoprocessing, and biomedical ultrasound, where cavitation sensors log emission over time to ensure a target dose per item or per pass.','Chemical & Molecular Acoustics',ARRAY['Cavitation yield','Cavitation activity','Broadband emission','Sonochemiluminescence','Flow-through sonochemical reactor']::text[],ARRAY['Equating exposure time or nominal power with dose, ignoring how much cavitation actually occurred','Assuming a single sensor location represents the dose across a non-uniform field']::text[],ARRAY['Logging broadband emission to confirm each part received a target dose','Comparing cleaning outcomes by cavitation dose rather than run time','Controlling a flow reactor to a fixed dose per pass']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavitation dose');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ae3a565-96b0-547d-b4aa-730eaa48f424','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ae3a565-96b0-547d-b4aa-730eaa48f424') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ae3a565-96b0-547d-b4aa-730eaa48f424');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '106a8b52-015c-5c71-b051-a3def2982613','Cavitation erosion','Progressive material damage, seen as pitting, mass loss, and roughening, caused by repeated collapse of cavitation bubbles near a solid surface. Asymmetric collapse produces high-speed liquid microjets and shock waves that impose intense, localized, repeated stresses that fatigue and remove material. It limits the life of ultrasonic horns, pumps, propellers, and hydraulic parts, and in sonochemistry it can shed transducer-tip metal into the reaction mixture.','Cavitation erosion is surface damage from collapsing bubbles. Bubbles near a solid collapse unevenly. This shoots a fast liquid jet at the surface. Repeated hits pit and wear the material away. It damages horns, pumps, and propellers.','It names the wear mechanism so it can be predicted and mitigated through materials and geometry choices, or, in cleaning, deliberately exploited to remove surface contaminants.','It shows up as eroded ultrasonic horn tips, damaged pump impellers, and pitted ship propellers, managed with erosion-resistant alloys and monitored where tip wear contaminates sonochemical products.','Chemical & Molecular Acoustics',ARRAY['Acoustic cavitation','Microjet','Cavitation cloud','Ultrasonic horn','Shock wave']::text[],ARRAY['Blaming chemical corrosion for damage that is actually mechanical cavitation erosion','Assuming a horn tip lasts indefinitely, when eroded tips lose amplitude and shed metal particles','UNSAFE: continuing to run a badly eroded horn, risking tip failure and metal contamination of the sample']::text[],ARRAY['Inspecting a worn horn tip that has lost output amplitude','Selecting an erosion-resistant alloy for a pump impeller','Tracing metal particles in a product to horn-tip erosion']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavitation erosion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '106a8b52-015c-5c71-b051-a3def2982613','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='106a8b52-015c-5c71-b051-a3def2982613') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='106a8b52-015c-5c71-b051-a3def2982613');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e6f45c52-7e88-5c53-b480-2f0e39d2eaa7','Cavitation cloud','A dense, dynamic cluster of many cavitation bubbles that forms in an intense acoustic field, for example beneath a horn tip or at a pressure antinode. The bubbles interact through radiated pressure and Bjerknes forces, forming filamentary or conical structures. The cloud collectively scatters and absorbs the sound and can shield the field, and its collective collapse governs erosion and sonochemical activity.','A cavitation cloud is a thick cluster of many bubbles. It forms where the sound field is strong. The bubbles push and pull on each other. They gather into clumps and streamers. The whole cloud can block sound and cause strong effects together.','It describes the collective bubble behaviour that actually delivers cavitation effects, and it explains shielding, structure formation, and the non-linear link between drive level and activity.','It is observed under sonicator horns and in cleaning tanks, where its shielding limits how much power reaches the bulk and so informs horn and reactor design.','Chemical & Molecular Acoustics',ARRAY['Bubble cloud dynamics','Acoustic cavitation','Bjerknes force','Cavitation erosion','Acoustic shielding']::text[],ARRAY['Treating cavitation as isolated single bubbles when clouds dominate at high power','Assuming more power means more useful cavitation, ignoring cloud shielding that caps activity']::text[],ARRAY['Imaging the cone of bubbles beneath a driven horn tip','Explaining why activity saturates as drive power rises','Relating an erosion zone to where the cloud collapses']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavitation cloud');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e6f45c52-7e88-5c53-b480-2f0e39d2eaa7','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e6f45c52-7e88-5c53-b480-2f0e39d2eaa7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e6f45c52-7e88-5c53-b480-2f0e39d2eaa7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '01cda203-3a83-5bf1-b414-cf0ef611ad45','Bubble cloud dynamics','The collective behaviour of a population of interacting cavitation bubbles: their coupled oscillation, translation, structure formation, coalescence, fragmentation, and collapse, arising from acoustic driving together with mutual secondary Bjerknes interactions and multiple scattering. Clouds show emergent phenomena such as filaments, cones, shielding, and collective resonance that single-bubble models do not predict, and these set real-world cavitation activity and erosion.','Bubble cloud dynamics is how a group of bubbles behaves together. The bubbles pulse and move as one system. They pull each other into streamers and clumps. They can merge, split, and collapse together. The group acts differently from one lone bubble.','It explains and predicts how real cavitation fields, which always contain many interacting bubbles, evolve, so activity, structure, and shielding can be understood beyond single-bubble theory.','It is modelled and imaged with high-speed video and acoustic emission to design sonoreactors, predict erosion zones, and control cavitation in cleaning and therapy.','Chemical & Molecular Acoustics',ARRAY['Cavitation cloud','Secondary Bjerknes force','Bubble coalescence','Bubble fragmentation','Multiple scattering']::text[],ARRAY['Applying single-bubble Rayleigh-Plesset predictions directly to a dense cloud','Ignoring inter-bubble forces and shielding that reshape the field and the activity']::text[],ARRAY['Simulating streamer formation in a strongly driven reactor','Explaining collective collapse timing from acoustic emission','Predicting where erosion concentrates in a cavitating field']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bubble cloud dynamics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '01cda203-3a83-5bf1-b414-cf0ef611ad45','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='01cda203-3a83-5bf1-b414-cf0ef611ad45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='01cda203-3a83-5bf1-b414-cf0ef611ad45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c486c5b-82a0-5094-a9da-8b255f06d465','Rectified diffusion','The slow net growth of an oscillating gas bubble in a sound field caused by asymmetric mass transfer over each cycle. During expansion, when internal pressure is low and surface area large, gas diffuses inward faster than it diffuses outward during compression, through the combined area and shell effects. A bubble driven above a threshold amplitude therefore gains gas over many cycles. It governs how stable cavitation nuclei grow to resonant, active sizes.','Rectified diffusion is slow bubble growth from sound. A bubble swells and shrinks with each sound cycle. When it swells, gas moves in through its larger surface. When it shrinks, less gas moves back out. Over many cycles it slowly gains gas and grows.','It explains how tiny gas nuclei grow into active cavitation bubbles under sound, setting cavitation thresholds and the supply of bubbles for stable cavitation.','It is relevant to degassing, to bubble growth in sonochemistry and therapeutic ultrasound, and to keeping or removing bubbles in liquids under sound.','Chemical & Molecular Acoustics',ARRAY['Stable cavitation','Acoustic cavitation','Bubble dynamics','Gas diffusion','Acoustic nucleation']::text[],ARRAY['Thinking any oscillating bubble grows, when growth needs the drive above a threshold amplitude','Confusing net rectified growth with the simple back-and-forth volume oscillation']::text[],ARRAY['Explaining how micro-nuclei grow to resonant size under sound','Predicting bubble growth that seeds stable cavitation','Understanding why a degassing field both grows and removes bubbles']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rectified diffusion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c486c5b-82a0-5094-a9da-8b255f06d465','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c486c5b-82a0-5094-a9da-8b255f06d465') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c486c5b-82a0-5094-a9da-8b255f06d465');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f950137c-0a9e-5db5-9d80-470ed70826bc','Bjerknes force','A time-averaged force exerted on a pulsating gas bubble in an acoustic pressure field, arising because the bubble''s volume oscillation is correlated with the pressure, or pressure gradient, it experiences. The primary Bjerknes force comes from the external field and pushes bubbles toward pressure antinodes or nodes depending on whether they are driven below or above resonance; the secondary Bjerknes force is the mutual force between two pulsating bubbles.','A Bjerknes force is a steady push on a pulsing bubble from sound. The bubble grows and shrinks as pressure changes. Because these line up, a small net force builds over each cycle. One kind moves a bubble through the sound field. Another kind pulls or pushes two bubbles together.','It explains how sound fields transport and cluster cavitation bubbles, shaping cavitation structures, streamers, and clouds.','It is used to interpret bubble migration to antinodes, filament and streamer formation, and bubble clustering in sonoreactors and acoustic traps.','Chemical & Molecular Acoustics',ARRAY['Primary Bjerknes force','Secondary Bjerknes force','Acoustic radiation force','Bubble cloud dynamics','Standing wave']::text[],ARRAY['Confusing the primary field-on-bubble force with the secondary bubble-on-bubble force','Assuming bubbles always move to antinodes, when the direction reverses above the resonance size']::text[],ARRAY['Explaining why bubbles collect at pressure antinodes in a standing wave','Interpreting bubble streamers as Bjerknes-driven structures','Trapping a single bubble for sonoluminescence study']::text[],'advanced','F = -⟨V∇p⟩','The Bjerknes force equals the negative time-average of bubble volume times the acoustic pressure gradient.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bjerknes force');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f950137c-0a9e-5db5-9d80-470ed70826bc','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f950137c-0a9e-5db5-9d80-470ed70826bc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f950137c-0a9e-5db5-9d80-470ed70826bc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '060ab998-119e-5865-b7bf-72718e4d5fcf','Primary Bjerknes force','The time-averaged force exerted on a single pulsating bubble by an external acoustic field, equal to the negative time-average of bubble volume times the driving-pressure gradient. In a standing wave it drives sub-resonant bubbles toward pressure antinodes and larger, above-resonance bubbles toward nodes, because the volume-pressure phase relation reverses through resonance. It sets where bubbles collect in a sound field.','The primary Bjerknes force is the push of a sound field on one bubble. The bubble pulses as the pressure changes. This makes a steady force along the field. Small bubbles move toward high-pressure spots. Larger bubbles move the other way, toward low-pressure spots.','It explains and predicts where bubbles migrate and accumulate in an acoustic field, which is key to trapping bubbles and forming cavitation structures.','It explains bubbles collecting at antinodes in standing-wave reactors and single-bubble sonoluminescence traps, and it guides field design to position cavitation.','Chemical & Molecular Acoustics',ARRAY['Secondary Bjerknes force','Bjerknes force','Resonance size','Standing wave','Acoustic trapping']::text[],ARRAY['Assuming bubbles always gather at pressure antinodes, ignoring the reversal above resonance','Confusing it with the bubble-to-bubble secondary Bjerknes force']::text[],ARRAY['Positioning a trapped bubble at a pressure antinode','Explaining why large bubbles migrate to nodes','Designing a standing-wave field to collect bubbles where wanted']::text[],'advanced','F_B1 = -⟨V(t)∇p(t)⟩','The primary Bjerknes force equals minus the time-average of bubble volume times the driving-pressure gradient.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Primary Bjerknes force');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '060ab998-119e-5865-b7bf-72718e4d5fcf','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='060ab998-119e-5865-b7bf-72718e4d5fcf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='060ab998-119e-5865-b7bf-72718e4d5fcf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc02f5bf-4a39-59fd-bca7-04ed07d9fa95','Secondary Bjerknes force','The mutual, time-averaged force between two or more bubbles pulsating in a shared sound field, produced by the pressure each radiates at the other. Its sign depends on the phase relation of their volume pulsations: bubbles oscillating in phase attract, while those out of phase repel. Its magnitude scales with the product of their pulsation strengths and falls with the square of their separation. It drives coalescence, chaining, and cluster formation.','The secondary Bjerknes force acts between two pulsing bubbles. Each bubble''s pulsing sends pressure to the other. If they pulse in step, they pull together. If they pulse out of step, they push apart. The force grows weaker as they move farther apart.','It explains how bubbles attract, chain, and coalesce, or repel, governing cavitation cloud structure and the evolution of the bubble population.','It explains bubble streamers, chains, and clusters in cavitation fields, and inter-bubble behaviour in cloud models and sonoreactor design.','Chemical & Molecular Acoustics',ARRAY['Primary Bjerknes force','Bubble coalescence','Bubble cloud dynamics','Cavitation cloud','Bjerknes force']::text[],ARRAY['Assuming bubbles always attract, when out-of-phase pulsation gives repulsion','Neglecting it in clouds, where bubble-to-bubble forces reshape the whole structure']::text[],ARRAY['Explaining why nearby bubbles merge into chains','Modelling cluster formation from mutual bubble forces','Predicting repulsion between bubbles driven out of phase']::text[],'advanced','F ∝ ⟨V̇₁ V̇₂⟩ / d²','The secondary Bjerknes force scales with the time-averaged product of the two bubbles'' volume-change rates, divided by the square of their separation.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Secondary Bjerknes force');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc02f5bf-4a39-59fd-bca7-04ed07d9fa95','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc02f5bf-4a39-59fd-bca7-04ed07d9fa95') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc02f5bf-4a39-59fd-bca7-04ed07d9fa95');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '877f7921-b963-571d-9aa5-f1bb626f9f16','Bubble coalescence','The merging of two or more bubbles into a single larger bubble when the liquid film between them thins and ruptures. In acoustic fields it is promoted by secondary Bjerknes attraction and collisions and opposed by factors that stabilize the film, such as surfactants and certain electrolytes. Coalescence shifts the bubble size distribution toward larger, more buoyant bubbles, affecting degassing, cavitation activity, and foam behaviour.','Bubble coalescence is two bubbles joining into one. The thin liquid layer between them drains away. When it breaks, the bubbles merge. Sound can push bubbles together to make this happen. The result is fewer, bigger bubbles.','It determines how bubble size and number evolve in a liquid, shaping degassing, cavitation activity, mass transfer, and foam stability.','It matters in ultrasonic degassing, sonoreactor bubble management, froth flotation, and food and foam processing, where it is promoted or suppressed by additives.','Chemical & Molecular Acoustics',ARRAY['Bubble fragmentation','Secondary Bjerknes force','Film drainage','Degassing','Surfactant']::text[],ARRAY['Assuming all electrolytes and surfactants promote coalescence, when many inhibit it by stabilizing the film','Ignoring that coalescence and fragmentation together set the steady-state size distribution']::text[],ARRAY['Adding a surfactant to suppress coalescence and keep bubbles small','Explaining faster degassing when bubbles merge and rise','Managing bubble size to sustain cavitation in a reactor']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bubble coalescence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '877f7921-b963-571d-9aa5-f1bb626f9f16','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='877f7921-b963-571d-9aa5-f1bb626f9f16') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='877f7921-b963-571d-9aa5-f1bb626f9f16');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b63318d-5c16-5794-8212-4b46405b60f5','Bubble fragmentation','The break-up of a single bubble into smaller daughter bubbles, driven in acoustic fields by shape, or surface-mode, instabilities during large-amplitude or unstable oscillation, by jetting, or by shear. It counteracts coalescence, replenishes small active nuclei, and sustains bubble populations and cavitation clouds by recycling nuclei that keep cavitation going.','Bubble fragmentation is one bubble splitting into smaller ones. Strong sound makes a bubble wobble and pinch. It can break into several tiny bubbles. These small bubbles can seed new cavitation. This keeps the bubble population going.','It provides a source of fresh small nuclei that sustains cavitation activity and, together with coalescence, sets the bubble size distribution.','It explains how cavitation self-seeds and persists in sonoreactors and how bubble populations stay active during continuous sonication.','Chemical & Molecular Acoustics',ARRAY['Bubble coalescence','Surface mode instability','Acoustic nucleation','Cavitation cloud','Bubble cloud dynamics']::text[],ARRAY['Assuming bubbles only grow or collapse, overlooking splitting into daughter bubbles','Confusing shape-instability fragmentation with the final inertial collapse']::text[],ARRAY['Explaining how a driven bubble seeds many smaller ones','Understanding why cavitation persists without added nuclei','Linking surface-mode instability to bubble break-up']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bubble fragmentation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b63318d-5c16-5794-8212-4b46405b60f5','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b63318d-5c16-5794-8212-4b46405b60f5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b63318d-5c16-5794-8212-4b46405b60f5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bc88c751-564a-53ad-b68e-853851a95ece','Acoustic nucleation','The initiation of new bubbles or cavities in a liquid by an acoustic field, that is, the sound-induced onset of the vapour or gas cavities that seed cavitation. During the rarefaction, or tension, phase the acoustic pressure can lower local pressure enough to activate pre-existing weak spots, such as gas pockets trapped in crevices or on particles, which is heterogeneous nucleation, or, at extreme tensions, to tear the liquid itself, which is homogeneous nucleation. It sets the cavitation threshold and where cavitation starts.','Acoustic nucleation is sound starting new bubbles. As sound pulls the liquid apart, the pressure drops. Where it drops enough, a tiny cavity opens. Most start from trapped gas on specks or surfaces. Very strong sound can even tear clean liquid.','It explains where and when cavitation begins, setting the cavitation threshold and the role of impurities and dissolved gas as nuclei.','It guides seeding or suppressing cavitation, by adding nuclei or particles to lower the threshold, or by degassing and filtering to raise it, in sonochemistry and cleaning.','Chemical & Molecular Acoustics',ARRAY['Cavitation threshold','Acoustic cavitation','Rectified diffusion','Cavitation nuclei','Rarefaction']::text[],ARRAY['Assuming cavitation starts from perfectly clean liquid, when real nucleation is almost always heterogeneous','Ignoring dissolved gas and particles that dominate where and when bubbles appear']::text[],ARRAY['Degassing and filtering a liquid to raise its cavitation threshold','Adding particles to seed cavitation at a lower drive level','Explaining why cavitation starts at container walls and specks']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic nucleation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bc88c751-564a-53ad-b68e-853851a95ece','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bc88c751-564a-53ad-b68e-853851a95ece') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bc88c751-564a-53ad-b68e-853851a95ece');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5e56286-17ec-5120-a956-ad819e73b092','Sonofragmentation','The size reduction of solid particles, especially molecular and pharmaceutical crystals, by ultrasound, in which cavitation-generated shock waves and microjets, together with particle-particle and particle-wall collisions, break crystals without necessarily eroding their surfaces. Distinct from surface attrition and from sonocrystallization, it reduces and narrows particle-size distributions and is studied for controlling crystal size in pharmaceuticals and fine chemicals.','Sonofragmentation is ultrasound breaking solid particles smaller. Cavitation makes shock waves and fast jets in the liquid. These hit and crack the particles. Particles also smash into each other. This makes them smaller and more even in size.','It provides a way to reduce and narrow particle and crystal size using cavitation energy, improving uniformity without grinding media.','It is used in pharmaceutical and fine-chemical crystallization to control crystal size and habit and to break up agglomerates in slurries.','Chemical & Molecular Acoustics',ARRAY['Sonocrystallization','Acoustic cavitation','Microjet','Shock wave','Bubble fragmentation']::text[],ARRAY['Confusing sonofragmentation, which breaks particles, with sonocrystallization, which nucleates crystals','Assuming particles erode surface-first, when fracture through the body often dominates','UNSAFE: sonicating slurries of hazardous or reactive solids without containment and hearing protection']::text[],ARRAY['Narrowing a crystal size distribution before formulation','Breaking agglomerates in a pigment or catalyst slurry','Studying how shock waves fracture organic crystals']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonofragmentation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5e56286-17ec-5120-a956-ad819e73b092','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5e56286-17ec-5120-a956-ad819e73b092') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5e56286-17ec-5120-a956-ad819e73b092');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0ae28a27-4902-5a8b-ab13-118c221bac56','Sonoexfoliation','The use of ultrasonic cavitation to exfoliate layered materials, separating a bulk layered solid such as graphite, boron nitride, or a transition-metal dichalcogenide into few-layer or single-layer two-dimensional sheets in a liquid. Cavitation shock waves, microjets, and shear overcome the weak interlayer van der Waals bonding, while the liquid stabilizes the exfoliated sheets. It is a common liquid-phase route to two-dimensional nanomaterials.','Sonoexfoliation uses ultrasound to peel layered solids apart. Some solids are stacks of weakly bonded sheets. Cavitation makes jets and shocks in the liquid. These forces slide and split the sheets apart. The result is very thin, few-layer flakes.','It provides a scalable liquid-phase route to peel layered crystals into two-dimensional sheets, using cavitation forces to overcome weak interlayer bonding.','It is used to make graphene and other two-dimensional-material dispersions from graphite and layered crystals in solvents or surfactant solutions.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic exfoliation','Liquid-phase exfoliation','Acoustic cavitation','Two-dimensional materials','Sonofragmentation']::text[],ARRAY['Expecting only clean sheets, when sonication also fragments flakes and reduces their lateral size','Ignoring solvent and surfactant matching, without which sheets restack and aggregate','UNSAFE: prolonged probe sonication of nanomaterial dispersions without fume and aerosol control and hearing protection']::text[],ARRAY['Producing few-layer graphene from graphite in a matched solvent','Exfoliating boron nitride into thin insulating sheets','Balancing sonication time against flake size and defects']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonoexfoliation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0ae28a27-4902-5a8b-ab13-118c221bac56','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0ae28a27-4902-5a8b-ab13-118c221bac56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0ae28a27-4902-5a8b-ab13-118c221bac56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fdf38bcd-5794-50f2-9389-ead01ffc2fae','Ultrasonic exfoliation','The exfoliation of layered materials into thin, few-layer or single-layer nanosheets by ultrasonication of the bulk solid dispersed in a liquid, a principal form of liquid-phase exfoliation. Acoustic cavitation supplies the shear, microjets, and shock forces that overcome interlayer van der Waals attraction, while solvent surface-energy matching or surfactants stabilize the sheets against restacking. It is widely used to produce graphene and other two-dimensional materials.','Ultrasonic exfoliation peels layered solids into thin sheets with ultrasound. The solid is stirred into a liquid. Ultrasound makes cavitation that pulls the layers apart. The liquid keeps the thin sheets from sticking back. It is a common way to make graphene.','It offers a simple, scalable way to make two-dimensional-material dispersions from layered crystals, using cavitation to separate layers in a liquid.','It is a standard bench and pilot route to graphene, hexagonal boron nitride, and molybdenum disulfide dispersions for coatings, inks, and composites.','Chemical & Molecular Acoustics',ARRAY['Sonoexfoliation','Liquid-phase exfoliation','Acoustic cavitation','Graphene','Surfactant']::text[],ARRAY['Assuming longer sonication only thins sheets, when it also cuts them smaller and can add defects','Using a solvent whose surface energy is mismatched, causing rapid restacking','UNSAFE: extended probe sonication without hearing protection and control of solvent vapours and aerosols']::text[],ARRAY['Making a graphene ink from graphite for printing','Choosing a solvent by surface energy to prevent restacking','Producing molybdenum disulfide flakes for a composite']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic exfoliation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fdf38bcd-5794-50f2-9389-ead01ffc2fae','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fdf38bcd-5794-50f2-9389-ead01ffc2fae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fdf38bcd-5794-50f2-9389-ead01ffc2fae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac71643d-d1db-57c3-a84d-1555a4a206f5','Sonochemical reduction','A sonochemically driven reduction reaction in which ultrasound, through cavitation, generates reducing species, principally hydrogen atoms and secondary radicals from water sonolysis, or radicals from added organic scavengers, that reduce metal ions to metal nanoparticles or to lower oxidation states. It is widely used to synthesize metal and alloy nanoparticles without an added chemical reductant, with cavitation providing both the reductant and the mixing.','Sonochemical reduction uses sound to add electrons to metals. The sound makes bubbles that collapse hard. That collapse splits water into tiny active bits. Some bits are good at adding electrons. They turn metal ions into small metal grains.','It provides a reagent-light route to reduce ions, especially to grow metal nanoparticles, using cavitation-made radicals as both the reductant and the mixing agent.','It is used to synthesize gold, silver, platinum, and alloy nanoparticles and to deposit metals on supports, without adding conventional reducing chemicals.','Chemical & Molecular Acoustics',ARRAY['Sonochemical oxidation','Water sonolysis','Radical formation','Nanoparticle synthesis','Acoustic cavitation']::text[],ARRAY['Assuming ultrasound directly reduces the ions, when radicals from sonolysis do the chemistry','Ignoring the dissolved gas choice, such as argon versus air, which strongly changes radical yields','UNSAFE: running an open probe in a metal-salt or nanoparticle solution without aerosol containment, gloves, and hearing protection']::text[],ARRAY['Making silver nanoparticles without a chemical reducing agent','Sparging argon to boost radical yield during a reduction','Depositing platinum on a carbon support by sonication']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonochemical reduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac71643d-d1db-57c3-a84d-1555a4a206f5','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac71643d-d1db-57c3-a84d-1555a4a206f5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac71643d-d1db-57c3-a84d-1555a4a206f5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b01f120e-ab7c-5c8a-8014-5964536a6bd2','Sonochemical oxidation','A sonochemically driven oxidation in which cavitation-produced oxidizing species, chiefly hydroxyl radicals and hydrogen peroxide from water sonolysis, along with other reactive oxygen species, oxidize dissolved substances. It is central to sonochemical advanced-oxidation processes for degrading organic pollutants and to oxidative synthesis, and its rate depends on frequency, gas atmosphere, and the volatility of the target.','Sonochemical oxidation uses sound to strip electrons from chemicals. The sound makes bubbles that collapse hard. That collapse splits water into tiny active bits. Some bits pull electrons away from other molecules. This breaks the target molecules down. It is often used to clean up water.','It uses cavitation-generated oxidants to break down or transform compounds, underpinning water treatment by advanced oxidation and oxidative sonochemistry.','It is applied to degrade dyes, pharmaceuticals, and other micropollutants in water, often combined with ozone, ultraviolet light, or catalysts.','Chemical & Molecular Acoustics',ARRAY['Sonochemical reduction','Hydroxyl radical','Sonodegradation','Advanced oxidation process','Water sonolysis']::text[],ARRAY['Assuming volatile and non-volatile pollutants react the same way, when their reaction sites differ','Expecting higher power to always help, when over-gassing and shielding can cut radical yield','UNSAFE: sonicating volatile or reactive mixtures that build up oxidants and heat without cooling, venting, and hearing protection']::text[],ARRAY['Degrading a dye in wastewater with ultrasound and a catalyst','Combining ultrasound with ozone for stronger oxidation','Choosing a gas atmosphere to maximize hydroxyl-radical output']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonochemical oxidation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b01f120e-ab7c-5c8a-8014-5964536a6bd2','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b01f120e-ab7c-5c8a-8014-5964536a6bd2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b01f120e-ab7c-5c8a-8014-5964536a6bd2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '982dcc74-c6cb-54c1-b7cd-1c428cb208c6','Sonodegradation','The breakdown of chemical compounds, typically dissolved organic pollutants or polymers, under ultrasound through combined pathways: pyrolytic decomposition inside or near the hot cavitation bubble for volatile species, hydroxyl-radical attack in the bulk for non-volatile species, and mechanical scission for macromolecules. It is the basis of ultrasonic and hybrid advanced-oxidation water treatment.','Sonodegradation is sound breaking down compounds. The sound makes bubbles that collapse hard. This makes tiny hot spots and active bits. Some molecules burn up inside the hot bubbles. Others are hit by the active bits. Big molecules can be torn apart too.','It provides a route to destroy pollutants and break down molecules using cavitation''s heat, radicals, and shear, alone or combined with other oxidation methods.','It is used to degrade dyes, pesticides, pharmaceuticals, and endocrine disruptors in water and effluent, often in hybrid sono-photocatalytic systems.','Chemical & Molecular Acoustics',ARRAY['Sonochemical oxidation','Hydroxyl radical','Advanced oxidation process','Ultrasonic depolymerization','Acoustic cavitation']::text[],ARRAY['Assuming a single mechanism, when volatile and non-volatile compounds degrade by different pathways','Expecting quick, complete mineralization, when ultrasound alone is often slow and best combined with other methods','UNSAFE: sonicating toxic or volatile pollutants without fume containment, since ultrasound can aerosolize and volatilize them']::text[],ARRAY['Breaking down a pesticide in water with ultrasound and ultraviolet light','Treating a volatile solvent that decomposes inside the bubbles','Combining ultrasound with a catalyst to speed pollutant removal']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonodegradation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '982dcc74-c6cb-54c1-b7cd-1c428cb208c6','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='982dcc74-c6cb-54c1-b7cd-1c428cb208c6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='982dcc74-c6cb-54c1-b7cd-1c428cb208c6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '54c15c3c-2e50-5e8b-9a76-f96915420401','Ultrasonic depolymerization','The reduction of polymer molecular weight by ultrasound in solution, driven mainly by mechanical, or mechanochemical, chain scission. Cavitation creates strong, localized shear and elongational flow near collapsing bubbles and jets that stretches and breaks polymer backbones, preferentially near the chain midpoint, down to a limiting molecular weight. Radical pathways can also contribute. It is used to control molecular weight and to study polymer mechanochemistry.','Ultrasonic depolymerization uses sound to shorten polymer chains. The sound makes strong pulling flows in the liquid. These flows stretch the long chains. The chains snap, most often near the middle. This makes the chains shorter and lighter.','It provides a controllable way to cut polymer chains and lower molecular weight, and a tool to study force-driven, mechanochemical bond breaking.','It is used to trim and narrow polymer molecular-weight distributions and to activate mechanophores in polymer mechanochemistry research.','Chemical & Molecular Acoustics',ARRAY['Polymer sonochemistry','Mechanochemical sonication','Chain scission','Limiting molecular weight','Acoustic cavitation']::text[],ARRAY['Thinking scission is random along the chain, when it is biased toward the midpoint','Assuming chains shrink indefinitely, when scission stops at a limiting molecular weight','UNSAFE: probe-sonicating volatile or flammable polymer solvents without aerosol and vapour control and hearing protection']::text[],ARRAY['Lowering a polymer''s molecular weight to a target value','Studying midpoint scission of a long chain under sound','Narrowing a broad molecular-weight distribution']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic depolymerization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '54c15c3c-2e50-5e8b-9a76-f96915420401','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='54c15c3c-2e50-5e8b-9a76-f96915420401') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='54c15c3c-2e50-5e8b-9a76-f96915420401');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e8cc85d-8d75-5ba2-8480-e9123582f959','Polymer sonochemistry','The branch of sonochemistry concerned with polymers under ultrasound, covering cavitation-driven chain scission and controlled depolymerization, mechanochemical activation of force-responsive groups called mechanophores, ultrasonically initiated polymerization, and block-copolymer and graft formation. It exploits the intense localized shear near collapsing bubbles to apply mechanical force to macromolecules and to generate radicals.','Polymer sonochemistry studies polymers under sound. The sound makes strong pulling forces and active bits. These can cut chains or start reactions. They can also trip special force-sensitive groups. It is used to change and study polymers.','It applies cavitation''s mechanical force and radical chemistry to make, break, join, and activate polymers in controlled ways.','It is used to control molecular weight, trigger mechanophores, initiate polymerizations, and build block and graft copolymers in research and specialty synthesis.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic depolymerization','Mechanochemical sonication','Sonomechanochemistry','Mechanophore','Chain scission']::text[],ARRAY['Reducing it to degradation only, ignoring synthesis and mechanophore activation','Overlooking that effects are mechanical, from shear, as much as radical-chemical','UNSAFE: extended probe sonication of organic polymer solutions without vapour and aerosol control and hearing protection']::text[],ARRAY['Activating a mechanophore that changes colour under force','Initiating a polymerization with ultrasound instead of a chemical initiator','Building a block copolymer by ultrasonic coupling']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polymer sonochemistry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e8cc85d-8d75-5ba2-8480-e9123582f959','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e8cc85d-8d75-5ba2-8480-e9123582f959') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e8cc85d-8d75-5ba2-8480-e9123582f959');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1bed40da-1b94-5a1b-8762-6a8b1af74132','Mechanochemical sonication','The use of ultrasound to drive mechanochemistry, that is, chemistry activated by mechanical force rather than by heat or light. Cavitation-generated elongational flow applies tensile force to molecules, typically polymer-tethered mechanophores, selectively breaking or rearranging bonds and releasing reactive sites. It is a key tool of polymer mechanochemistry for probing and exploiting force-responsive chemistry.','Mechanochemical sonication uses ultrasound to drive force-based chemistry. Cavitation makes strong pulling flows in the liquid. These flows tug on molecules with real force. The force breaks or changes chosen bonds. It works without added heat or light.','It delivers controlled mechanical force to molecules through cavitation, enabling force-triggered reactions and the study of how molecules respond to stress.','It is used to activate mechanophores, trigger colour or reactivity changes, and study bond scission under force in polymer solutions.','Chemical & Molecular Acoustics',ARRAY['Sonomechanochemistry','Polymer sonochemistry','Mechanophore','Ultrasonic depolymerization','Chain scission']::text[],ARRAY['Confusing force-driven mechanochemical activation with purely thermal or radical chemistry','Assuming small molecules activate readily, when long polymer tethers are usually needed to transmit force','UNSAFE: sonicating volatile organic solutions without vapour and aerosol control, cooling, and hearing protection']::text[],ARRAY['Triggering a force-sensitive group tethered to a polymer chain','Comparing ultrasonic force activation with grinding methods','Studying selective bond scission under cavitation shear']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanochemical sonication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1bed40da-1b94-5a1b-8762-6a8b1af74132','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1bed40da-1b94-5a1b-8762-6a8b1af74132') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1bed40da-1b94-5a1b-8762-6a8b1af74132');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c316d45a-ff2a-5daa-821c-dabc57377214','Sonomechanochemistry','The field and approach that combine ultrasound with mechanochemistry, using acoustic cavitation as the force source to drive mechanically activated reactions in solution. It spans mechanophore activation, polymer chain scission, and force-accelerated transformations, and it is distinguished from milling and grinding mechanochemistry by delivering force through cavitation in a liquid rather than through solid-state impact.','Sonomechanochemistry joins ultrasound and force-based chemistry. It uses cavitation as the source of force. That force drives special reactions in liquid. It differs from grinding or milling methods. It works in solution instead.','It frames ultrasound as a controllable force source for mechanochemistry in solution, complementing solid-state grinding and milling routes.','It is used in research to activate mechanophores, perform force-accelerated catalysis and selective scission, and study solution-phase mechanochemistry.','Chemical & Molecular Acoustics',ARRAY['Mechanochemical sonication','Polymer sonochemistry','Mechanophore','Acoustic cavitation','Chain scission']::text[],ARRAY['Equating it with grinding or ball-mill mechanochemistry, when here the force comes from cavitation in a liquid','Assuming the effect is thermal rather than force-driven','UNSAFE: driving high-power cavitation in flammable solvents without vapour control, cooling, and hearing protection']::text[],ARRAY['Driving a force-accelerated reaction with an ultrasonic probe','Comparing solution cavitation force with ball-mill impact','Activating a mechanophore to catalyze a transformation']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonomechanochemistry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c316d45a-ff2a-5daa-821c-dabc57377214','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c316d45a-ff2a-5daa-821c-dabc57377214') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c316d45a-ff2a-5daa-821c-dabc57377214');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b1bc547-e29e-5b3a-b3bb-7c739458dfea','Acoustic droplet ejection','A drop-on-demand technique that uses a focused acoustic pulse to eject a small, precise droplet from a free liquid surface without any nozzle. A transducer focuses ultrasound at the meniscus, and acoustic radiation pressure raises a mound that pinches off a droplet whose size scales with the acoustic wavelength and frequency. Nozzle-free operation avoids clogging and cross-contamination and is widely used for nanolitre liquid handling.','Acoustic droplet ejection shoots tiny drops using focused sound. Sound is focused at a liquid''s surface from below. The push lifts a small mound of liquid. A precise droplet pinches off and flies up. No nozzle is used, so nothing clogs.','It provides precise, nozzle-free, non-contact transfer of very small liquid volumes, avoiding clogging and cross-contamination.','It is used in lab automation for nanolitre dispensing in drug screening, genomics, and assay setup, and in some printing applications.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic atomization','Acoustic radiation force','Drop-on-demand','Microfluidics','Ultrasonic nebulization']::text[],ARRAY['Assuming it needs a nozzle like an inkjet, when ejection is nozzle-free from a focused sound spot','Ignoring that droplet size is set mainly by the acoustic frequency and wavelength']::text[],ARRAY['Transferring nanolitre samples between plates in drug screening','Dispensing reagents without a nozzle to avoid cross-contamination','Setting up assays with precise, small liquid volumes']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic droplet ejection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b1bc547-e29e-5b3a-b3bb-7c739458dfea','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b1bc547-e29e-5b3a-b3bb-7c739458dfea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b1bc547-e29e-5b3a-b3bb-7c739458dfea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd974ea01-5e7a-520a-ba59-a40ad8a7f287','Ultrasonic atomization','The breakup of a liquid into a fine spray of droplets by ultrasound, principally through the capillary-wave mechanism: ultrasonic vibration of a surface, or of a liquid film on it, raises standing capillary waves whose crests eject droplets when the amplitude is high enough, with cavitation also contributing at high intensity. The median droplet diameter follows Lang''s relation to the capillary wavelength, giving fine, narrow-sized sprays at low velocity.','Ultrasonic atomization turns liquid into a fine mist with ultrasound. Fast vibration shakes a thin liquid film. This raises tiny waves on the surface. When the waves are steep enough, drops fly off. Higher frequency makes smaller drops.','It produces fine, uniform, low-velocity sprays whose droplet size is set by frequency, useful where gentle, controllable atomization is needed.','It is used in medical nebulizers, humidifiers, spray coating, spray drying, and combustion research, and to feed ultrasonic spray pyrolysis.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic nebulization','Capillary wave','Aerosol sonochemistry','Acoustic droplet ejection','Surface tension']::text[],ARRAY['Assuming cavitation is the only mechanism, when capillary, or Faraday, waves dominate at typical conditions','Expecting velocity-driven sprays, when ultrasonic mists are fine and slow-moving','UNSAFE: atomizing flammable or toxic liquids without vapour and aerosol control, since fine mists inhale easily and can ignite']::text[],ARRAY['Generating a fine drug mist in a medical nebulizer','Coating a surface with a fine, even spray','Feeding droplets into a spray-pyrolysis furnace']::text[],'intermediate','d ≈ 0.34·(8πσ / ρf²)^(1/3)','The median droplet diameter is about 0.34 times the cube root of eight pi times surface tension divided by liquid density times frequency squared.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic atomization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd974ea01-5e7a-520a-ba59-a40ad8a7f287','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d974ea01-5e7a-520a-ba59-a40ad8a7f287') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d974ea01-5e7a-520a-ba59-a40ad8a7f287');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4f5a81b6-9965-53d9-a306-04fc5cf01921','Ultrasonic nebulization','Ultrasonic atomization applied to convert a liquid into an aerosol, or mist, of fine droplets for delivery, especially of a drug or of a sample. A high-frequency transducer raises capillary waves, and sometimes cavitation, that shed micron-scale droplets; higher frequency yields smaller droplets suitable for inhalation or for introducing samples into analytical instruments.','Ultrasonic nebulization makes a fine mist for delivery. A high-frequency vibrator shakes the liquid. Tiny droplets lift off the surface. The mist can be breathed in or fed to an instrument. Higher frequency gives smaller droplets.','It turns a liquid into an inhalable or analyzable fine aerosol, with droplet size controlled by frequency and without high-pressure gas.','It is used in medical nebulizers for aerosol drug delivery, in room humidifiers, and for sample introduction in spectrometry, such as inductively coupled plasma nebulizers.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic atomization','Aerosol','Capillary wave','Nebulizer','Aerosol sonochemistry']::text[],ARRAY['Assuming droplet size is set by liquid volume, when frequency mainly sets it','Assuming any drug can be nebulized this way, when heat build-up and shear can degrade sensitive biologics','UNSAFE: nebulizing toxic or non-approved solutions for inhalation, since the fine mist is easily breathed deep into the lungs']::text[],ARRAY['Delivering an inhaled medicine as a fine mist','Introducing a sample aerosol into a plasma spectrometer','Humidifying a room with a high-frequency mist maker']::text[],'intermediate',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic nebulization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4f5a81b6-9965-53d9-a306-04fc5cf01921','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4f5a81b6-9965-53d9-a306-04fc5cf01921') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4f5a81b6-9965-53d9-a306-04fc5cf01921');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '90d8608d-7cff-5705-807b-c917307cf723','Aerosol sonochemistry','The study of chemical reactions in acoustically generated aerosol droplets, or of sonochemistry occurring within sprayed microdroplets. Ultrasonic atomization produces micro-droplets that act as tiny reactors with large surface-to-volume ratios; in ultrasonic spray pyrolysis they are carried through a hot zone to form particles. The field also covers reactive chemistry unique to the air-droplet interface, enabling materials synthesis and studies of confined and interfacial reactions.','Aerosol sonochemistry studies chemistry inside sprayed droplets. Ultrasound makes a fine mist of tiny droplets. Each droplet acts like a small reactor. Their large surface helps reactions happen. Heating the mist can turn droplets into solid particles.','It uses ultrasonically made droplets as microreactors for synthesis and for studying reactions at the droplet surface and under confinement.','It is central to ultrasonic spray pyrolysis for making oxide, metal, and composite particles, and to studies of atmospherically relevant droplet chemistry.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic atomization','Ultrasonic spray pyrolysis','Aerosol','Ultrasonic nebulization','Microreactor']::text[],ARRAY['Confusing reactions inside droplets with cavitation-driven bulk-liquid sonochemistry','Overlooking that the large droplet surface makes interfacial chemistry important','UNSAFE: generating aerosols of hazardous precursors or nanoparticles without containment and respiratory protection']::text[],ARRAY['Making oxide nanoparticles by spraying droplets through a furnace','Studying reactions confined inside micron-sized droplets','Comparing droplet chemistry with bulk-solution sonochemistry']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aerosol sonochemistry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '90d8608d-7cff-5705-807b-c917307cf723','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='90d8608d-7cff-5705-807b-c917307cf723') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='90d8608d-7cff-5705-807b-c917307cf723');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c830ca22-66a0-5189-8ec6-9089d9fe9d8f','Acoustic impedance spectroscopy','A characterization technique that measures a system''s acoustic impedance, the ratio of acoustic pressure to particle velocity, as a function of frequency to infer material or interfacial properties such as density, sound speed, viscoelasticity, layer thickness, or bonding. It is often implemented with piezoelectric resonators or transducers whose electrical response encodes the acoustic load, and it is used to probe fluids, films, and coatings.','Acoustic impedance spectroscopy studies how sound moves in a material. It measures the sound impedance at many pitches. Impedance links sound pressure to how the parts move. The results show what the stuff is made of. They reveal its density, stiffness, and layer thickness. Sensors often use a vibrating crystal for this.','It extracts material and interface properties from the frequency dependence of acoustic impedance, giving a non-destructive probe of fluids, films, and bonds.','It is used to characterize coatings, adhesive bonds, fluid properties, and thin films, and as the readout principle behind some acoustic sensors.','Chemical & Molecular Acoustics',ARRAY['Acoustic impedance','Ultrasonic interferometry','Bulk acoustic wave sensor','Viscoelastic acoustic response','Ultrasonic spectroscopy']::text[],ARRAY['Confusing acoustic impedance with electrical impedance, though a piezoelectric sensor links the two','Assuming a single-frequency reading suffices, when the frequency dependence carries the information']::text[],ARRAY['Checking an adhesive bond by its acoustic-impedance spectrum','Characterizing a coating''s thickness and stiffness non-destructively','Reading out a piezoelectric sensor loaded by a fluid film']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic impedance spectroscopy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c830ca22-66a0-5189-8ec6-9089d9fe9d8f','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c830ca22-66a0-5189-8ec6-9089d9fe9d8f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c830ca22-66a0-5189-8ec6-9089d9fe9d8f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '177a10f5-fed5-5e94-b668-6c316661be29','Ultrasonic interferometry','A precise method to measure the speed and attenuation of sound, and thence material properties, in a fluid or solid using interference of ultrasonic waves. In a fixed-path interferometer a transducer and reflector form a resonant cavity; as frequency or path length varies, standing-wave resonances, the interference maxima and minima, are counted to obtain the wavelength and hence the sound speed from the product of frequency and wavelength, while their sharpness gives the attenuation. It is a classic tool of molecular acoustics.','Ultrasonic interferometry measures sound speed using wave interference. Sound bounces between a source and a reflector. Waves overlap and form a standing pattern. Peaks appear at set spacings tied to the wavelength. From wavelength and frequency you get the sound speed.','It provides accurate sound-speed and attenuation data, from which compressibility, molecular relaxation, and interaction properties of liquids are derived.','It is used to measure sound velocity in liquids and solutions for physical and molecular acoustics, composition sensing, and relaxation studies.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic relaxation','Acoustic impedance spectroscopy','Sound speed','Molecular relaxation absorption','Acoustic attenuation']::text[],ARRAY['Ignoring diffraction and non-parallelism, which bias the measured wavelength','Assuming a constant path, when temperature drift changes both path length and sound speed']::text[],ARRAY['Measuring the speed of sound in a solution to find its composition','Studying molecular relaxation from sound speed versus frequency','Determining compressibility from precise velocity data']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic interferometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '177a10f5-fed5-5e94-b668-6c316661be29','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='177a10f5-fed5-5e94-b668-6c316661be29') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='177a10f5-fed5-5e94-b668-6c316661be29');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e7b783b-2bf4-5bda-a6a8-4cd57beb0f23','Ultrasonic relaxation','A frequency-dependent process in which an ultrasonic wave''s compression and rarefaction drive a system slightly out of equilibrium, whether chemical, structural, thermal, or conformational, and energy is lost as it relaxes back with a characteristic relaxation time. Excess absorption and a small increase in sound speed, the dispersion, peak near the relaxation frequency, which equals one over two pi times the relaxation time. Measuring them reveals fast reaction kinetics and molecular dynamics in liquids.','Ultrasonic relaxation is a lag between sound and a system''s response. Sound squeezes and stretches the liquid very fast. Some internal change cannot keep up perfectly. This lag absorbs extra sound energy. The effect peaks at a certain frequency.','It provides a window into very fast equilibria and molecular motions, since the relaxation frequency and absorption reveal their rates and energetics.','It is used to study fast chemical equilibria, ion pairing, hydrogen bonding, and conformational changes in solutions by measuring absorption and velocity versus frequency.','Chemical & Molecular Acoustics',ARRAY['Molecular relaxation absorption','Ultrasonic interferometry','Relaxation time','Acoustic absorption','Sound dispersion']::text[],ARRAY['Assuming absorption always rises with frequency, when relaxational absorption per wavelength peaks then falls','Confusing the relaxation frequency with a resonance frequency']::text[],ARRAY['Measuring a fast ion-pairing equilibrium in solution','Locating a relaxation frequency from an absorption peak','Studying conformational change rates from ultrasonic data']::text[],'advanced','f_r = 1 / (2πτ)','The relaxation frequency equals one divided by two pi times the relaxation time.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic relaxation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e7b783b-2bf4-5bda-a6a8-4cd57beb0f23','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e7b783b-2bf4-5bda-a6a8-4cd57beb0f23') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e7b783b-2bf4-5bda-a6a8-4cd57beb0f23');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e16a7fd9-318b-5528-b9a8-c9b317c6266e','Molecular relaxation absorption','The excess ultrasonic absorption in a medium caused by molecular relaxation, the energy exchange between the sound wave and internal molecular degrees of freedom, whether vibrational, rotational, or structural, or chemical equilibria that cannot follow the rapid pressure cycle. Beyond the classical viscous and thermal absorption, the relaxational contribution to absorption per frequency squared is largest below the relaxation frequency and falls as frequency exceeds it. It dominates the anomalous absorption of many gases and liquids.','Molecular relaxation absorption is extra sound loss from slow molecular changes. Sound rapidly squeezes the molecules. Some internal energy shifts lag behind. That lag drains energy from the wave. It adds to the normal loss from friction and heat.','It explains and quantifies the anomalous, frequency-dependent absorption of sound in fluids, linking it to molecular energy exchange and reaction rates.','It is used to determine vibrational relaxation and fast reaction rates in gases and liquids and to account for excess attenuation in acoustic propagation and measurement.','Chemical & Molecular Acoustics',ARRAY['Ultrasonic relaxation','Acoustic absorption','Classical absorption','Relaxation time','Vibrational relaxation']::text[],ARRAY['Attributing all absorption to viscosity and thermal conduction, ignoring the relaxational excess','Assuming a single relaxation, when many systems have several overlapping relaxation processes']::text[],ARRAY['Explaining anomalous sound absorption in a gas','Extracting a vibrational relaxation rate from absorption data','Correcting an attenuation measurement for the relaxational contribution']::text[],'advanced','α/f² = A / (1 + (f/f_r)²) + B','Absorption per frequency squared has a relaxational part that falls above the relaxation frequency, plus a constant classical part.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Molecular relaxation absorption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e16a7fd9-318b-5528-b9a8-c9b317c6266e','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e16a7fd9-318b-5528-b9a8-c9b317c6266e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e16a7fd9-318b-5528-b9a8-c9b317c6266e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '712ac7a8-a4d0-5f40-affd-1b55ac75dc53','Viscoelastic acoustic response','The acoustic behaviour of a material that is both viscous and elastic, so its stress response to acoustic strain is frequency-dependent and complex: it stores energy elastically, in phase with strain, and dissipates energy viscously, out of phase, described by a complex modulus and a complex sound speed. It sets the frequency-dependent sound speed and attenuation in polymers, gels, tissues, and complex fluids, and it underlies acoustic sensing of such media.','Viscoelastic acoustic response is how part-solid, part-liquid materials react to sound. Such materials both spring back and flow. So they store some sound energy and waste some. This makes sound speed and loss change with frequency. Gels, polymers, and tissue behave this way.','It captures how real, non-ideal materials transmit and absorb sound, linking acoustic measurements to their mechanical, viscoelastic properties.','It is used in acoustic characterization of polymers, gels, foods, and tissue, and in sensor readout where a viscoelastic film loads a resonator.','Chemical & Molecular Acoustics',ARRAY['Complex modulus','Molecular relaxation absorption','Acoustic impedance spectroscopy','Bulk acoustic wave sensor','Acoustic attenuation']::text[],ARRAY['Treating such media as purely elastic, so predicted speed and loss are wrong','Ignoring frequency dependence, when viscoelastic properties change strongly with frequency']::text[],ARRAY['Characterizing a polymer melt''s stiffness and loss with ultrasound','Interpreting a resonator loaded by a soft, viscoelastic film','Modelling frequency-dependent attenuation in tissue']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Viscoelastic acoustic response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '712ac7a8-a4d0-5f40-affd-1b55ac75dc53','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='712ac7a8-a4d0-5f40-affd-1b55ac75dc53') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='712ac7a8-a4d0-5f40-affd-1b55ac75dc53');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3f2ec81b-a79e-5f15-862b-44a4f1d24b25','Surface acoustic wave microfluidics','The use of surface acoustic waves, typically Rayleigh waves launched by interdigital transducers on a piezoelectric substrate, to manipulate fluids and particles at the microscale, a branch of acoustofluidics. When a surface acoustic wave meets a liquid it radiates sound into it as a leaky wave, driving acoustic streaming and radiation forces that pump, mix, jet, atomize, concentrate, sort, and pattern droplets, cells, and particles in lab-on-a-chip devices.','Surface acoustic wave microfluidics moves tiny fluids with surface sound waves. A patterned electrode on a crystal makes waves on its surface. These waves leak into a nearby droplet or channel. The energy pushes and stirs the liquid. It can pump, mix, and sort cells on a chip.','It provides label-free, contactless, precise on-chip control of fluids and particles using acoustic streaming and radiation forces from surface waves.','It is used in lab-on-a-chip systems to pump, mix, sort, and concentrate cells and particles and to atomize droplets for mass spectrometry.','Chemical & Molecular Acoustics',ARRAY['Acoustofluidics','Interdigital transducer','Acoustic streaming','Acoustic radiation force','Love-wave chemical sensor']::text[],ARRAY['Confusing surface-wave streaming and manipulation with bulk cavitation, when this technique is usually non-cavitational','Assuming any substrate works, when a piezoelectric substrate and matched transducers are required']::text[],ARRAY['Sorting cells in a microchannel by acoustic radiation force','Mixing reagents in a droplet with surface-wave streaming','Atomizing a sample droplet for mass spectrometry']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface acoustic wave microfluidics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3f2ec81b-a79e-5f15-862b-44a4f1d24b25','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3f2ec81b-a79e-5f15-862b-44a4f1d24b25') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3f2ec81b-a79e-5f15-862b-44a4f1d24b25');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec244537-fdf8-50a8-b879-92ace038ae6a','Bulk acoustic wave sensor','A resonant sensor in which an acoustic wave propagates through the bulk, or thickness, of a piezoelectric plate, most commonly a thickness-shear-mode quartz crystal, the quartz crystal microbalance, or a thin-film bulk acoustic resonator. Mass or property changes at the surface shift the resonant frequency; for a thin, rigid added layer the shift follows the Sauerbrey relation, in which the frequency decreases in proportion to the added mass per unit area, enabling sensitive chemical and biochemical detection.','A bulk acoustic wave sensor detects changes using a vibrating crystal. Sound waves ring through the whole thickness of the crystal. Its natural frequency depends on what sits on it. Added mass lowers the frequency. Measuring that shift senses tiny amounts of a substance.','It converts tiny surface mass or property changes into a measurable frequency shift, giving sensitive, label-free chemical and biosensing.','It is used as quartz crystal microbalances and film bulk acoustic resonators for gas sensing, biosensing, film-thickness monitoring, and electrochemical studies.','Chemical & Molecular Acoustics',ARRAY['Quartz crystal microbalance','Surface acoustic wave microfluidics','Love-wave chemical sensor','Sauerbrey equation','Acoustic waveguide sensor']::text[],ARRAY['Applying the Sauerbrey relation to thick or soft, viscoelastic films, where it fails','Ignoring liquid loading and temperature, which also shift the resonant frequency']::text[],ARRAY['Weighing a nanogram film with a quartz crystal microbalance','Detecting a gas by the frequency shift on a coated resonator','Following a biomolecule binding event in real time']::text[],'advanced','Δf = -C_f·Δm','The resonant frequency shift is proportional to, and opposite in sign to, the mass added per unit area.','dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bulk acoustic wave sensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec244537-fdf8-50a8-b879-92ace038ae6a','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec244537-fdf8-50a8-b879-92ace038ae6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec244537-fdf8-50a8-b879-92ace038ae6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea2845e3-b436-5533-bfe0-9ae1d42790a8','Love-wave chemical sensor','A guided-wave acoustic chemical sensor based on Love waves, which are shear-horizontal surface waves trapped in a thin guiding layer on a piezoelectric substrate. The waveguiding concentrates acoustic energy near the surface, giving high mass sensitivity; a chemically selective coating changes the wave''s velocity and phase on analyte binding, and the shear-horizontal polarization allows low-loss operation in liquids. It is used for sensitive gas and liquid biochemical detection.','A Love-wave chemical sensor detects chemicals using a trapped surface wave. A thin top layer guides a sideways-shaking wave near the surface. A coating on top grabs the target chemical. Binding slightly slows the wave. Measuring that change senses the chemical, even in liquid.','It provides very sensitive, liquid-compatible acoustic sensing by trapping shear-horizontal wave energy at the coated surface where analyte binding shifts the wave velocity.','It is used for biosensing and gas or vapour detection where high sensitivity and operation in liquid are needed, often in lab-on-a-chip immunosensors.','Chemical & Molecular Acoustics',ARRAY['Acoustic waveguide sensor','Surface acoustic wave microfluidics','Bulk acoustic wave sensor','Shear-horizontal wave','Guiding layer']::text[],ARRAY['Assuming Rayleigh-type surface-wave sensors work well in liquid, when their vertical motion radiates and loses energy there','Overlooking the guiding-layer thickness, which is tuned to maximize sensitivity']::text[],ARRAY['Detecting a protein in solution with a coated Love-wave device','Tuning a guiding layer to boost mass sensitivity','Running a liquid-phase immunoassay on a sensor chip']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Love-wave chemical sensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea2845e3-b436-5533-bfe0-9ae1d42790a8','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea2845e3-b436-5533-bfe0-9ae1d42790a8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea2845e3-b436-5533-bfe0-9ae1d42790a8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4f03f411-c82e-5da6-8392-13e2cca3c8c6','Acoustic waveguide sensor','A class of acoustic sensors that confine and guide a wave along a structure, such as a plate, layer, or rod, so the propagating mode interacts strongly with the surrounding medium or a surface coating. Guided modes, including Love waves, shear-horizontal acoustic plate modes, and Lamb or flexural plate waves, concentrate energy at the sensing surface, and analyte-induced changes in velocity, phase, or amplitude give the signal. It is used for chemical and biosensing, often in liquids.','An acoustic waveguide sensor guides a sound wave along a structure to sense changes. The wave is trapped in a plate or layer. This keeps its energy near the sensing surface. Substances touching that surface change the wave. Measuring the change reveals what is present.','It uses guided-wave confinement to maximize interaction with the sample, giving sensitive, often liquid-compatible chemical and biological sensing.','It is used in gas and liquid biochemical detection, in Love-wave, acoustic-plate-mode, and flexural-plate-wave devices, in portable and lab-on-a-chip sensors.','Chemical & Molecular Acoustics',ARRAY['Love-wave chemical sensor','Bulk acoustic wave sensor','Surface acoustic wave microfluidics','Lamb wave','Acoustic plate mode']::text[],ARRAY['Conflating all acoustic sensors, when waveguide sensors specifically rely on guided, confined modes','Assuming higher frequency always means better sensing, when loss and liquid loading impose limits']::text[],ARRAY['Sensing a vapour with a shear-horizontal plate-mode device','Detecting a biomolecule with a flexural-plate-wave sensor in liquid','Choosing a guided mode that keeps energy at the sensing surface']::text[],'advanced',NULL,NULL,'dd8b965c-5f45-4093-b6c3-4bef7412a57e' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic waveguide sensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4f03f411-c82e-5da6-8392-13e2cca3c8c6','dd8b965c-5f45-4093-b6c3-4bef7412a57e',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4f03f411-c82e-5da6-8392-13e2cca3c8c6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4f03f411-c82e-5da6-8392-13e2cca3c8c6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7caafa5a-4305-5eaf-be22-e9937fb45a3f','Anthrophony','The component of a soundscape produced by human activity and technology, encompassing sound from transportation, industry, construction, recreation, and electronic devices. Within the soundscape-ecology framework it is distinguished from biophony (sound of non-human organisms) and geophony (non-biological natural sound), and is typically the dominant source of environmental noise that can mask biological signals and alter animal acoustic behaviour.','Anthrophony is all the sound that people and machines make. It includes cars, planes, engines, tools, and other devices. Scientists group it apart from animal sounds and natural sounds. This human noise can hide the calls that animals use.','Naming this category lets researchers separate human-made noise from biological and geophysical sound, so its ecological effects, such as masking and habitat degradation, can be measured and managed.','Analysts label anthrophony in field recordings and acoustic indices to quantify noise pollution, assess its overlap with wildlife signals, and inform noise mitigation or protected-area planning.','Bioacoustics & Ecoacoustics',ARRAY['Biophony','Geophony','Soundscape ecology','Acoustic masking','Noise pollution']::text[],ARRAY['Treating anthrophony as any loud sound rather than specifically human-caused sound','Assuming it means only urban traffic and overlooking aircraft, boats, and machinery in remote areas','Confusing anthrophony with geophony when a natural source is misidentified']::text[],ARRAY['Measuring traffic-noise intrusion into a national-park soundscape','Separating jet overflights from the bird chorus in long-term recordings','Assessing the shipping-noise contribution to a marine soundscape']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Anthrophony');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7caafa5a-4305-5eaf-be22-e9937fb45a3f','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7caafa5a-4305-5eaf-be22-e9937fb45a3f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7caafa5a-4305-5eaf-be22-e9937fb45a3f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a67db77b-9f4e-532a-8efa-8316617b4f7b','Biotic sound','Sound generated by living organisms, including vocalizations, stridulations, wing beats, and other biologically produced acoustic emissions. In ecoacoustics the aggregate of biotic sound from a community is termed biophony; biotic sound is contrasted with abiotic (geophysical) sound and with human-generated anthrophony.','Biotic sound is any sound made by living things. Birds singing, frogs calling, and insects buzzing all count. The whole mix of these sounds in one place is called biophony. It is set apart from wind, rain, and machine noise.','The category groups organism-produced sound so researchers can study communication, biodiversity, and community activity separately from physical and human noise sources.','Ecologists isolate biotic sound in recordings to estimate species presence, calling activity, and biodiversity, often using acoustic indices tuned to biological frequency bands.','Bioacoustics & Ecoacoustics',ARRAY['Biophony','Abiotic sound','Anthrophony','Vocalization','Soundscape ecology']::text[],ARRAY['Equating biotic sound only with bird or mammal voices and ignoring insects and other invertebrates','Assuming all sound in a natural recording is biotic when wind or water may dominate','Treating one individual''s sound as if it were the whole community''s biophony']::text[],ARRAY['Isolating the dawn-chorus band for a biodiversity index','Distinguishing frog calls from rainfall in a wetland recording','Comparing biotic sound levels across seasons']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Biotic sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a67db77b-9f4e-532a-8efa-8316617b4f7b','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a67db77b-9f4e-532a-8efa-8316617b4f7b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a67db77b-9f4e-532a-8efa-8316617b4f7b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0e6382f-dc96-5552-99ea-72b8f5482597','Abiotic sound','Sound arising from non-living, physical processes in the environment, such as wind, flowing or falling water, rain, thunder, surf, and earth movement. In soundscape ecology the natural subset of abiotic sound is termed geophony; abiotic sound is distinguished from biotic sound (biophony) and human-produced anthrophony.','Abiotic sound comes from nonliving parts of nature. Wind, rain, rivers, waves, and thunder are all examples. The natural part of this is often called geophony. It is separate from animal sounds and from human noise.','Classifying abiotic sound lets researchers account for background physical noise that shapes what animals can hear and that can bias acoustic measurements.','Field analysts identify abiotic sound such as wind and rain to exclude or correct for it before measuring biological activity or running detectors.','Bioacoustics & Ecoacoustics',ARRAY['Geophony','Biotic sound','Anthrophony','Soundscape ecology','Acoustic masking']::text[],ARRAY['Confusing abiotic sound with anthrophony because both are non-biological','Forgetting that heavy wind and rain can mask or mimic animal signals in detectors','Assuming abiotic sound is always low level and negligible']::text[],ARRAY['Flagging wind-noise periods to clean a recording dataset','Modeling how stream noise limits frog-call detection','Separating thunder from gunshot-like biotic events']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Abiotic sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0e6382f-dc96-5552-99ea-72b8f5482597','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0e6382f-dc96-5552-99ea-72b8f5482597') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0e6382f-dc96-5552-99ea-72b8f5482597');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3ef3d1e0-e33b-5d52-bf95-88975600d2ce','Soundscape ecology','The scientific study of the acoustic relationships between organisms and their environment across spatial and temporal scales, treating the soundscape—the totality of biophony, geophony, and anthrophony at a place and time—as an ecological property. It integrates bioacoustics, landscape ecology, and acoustics to investigate how sound reflects biodiversity, ecosystem state, and human impact.','Soundscape ecology studies all the sound in a place as a whole. It looks at animal sounds, natural sounds, and human noise together. Researchers use this mix of sounds to learn about wildlife and habitat health. It joins ideas from ecology and acoustics.','It provides a framework for using sound as an ecological indicator, letting scientists monitor biodiversity and disturbance non-invasively over large areas and long periods.','Practitioners deploy long-term recorders and compute acoustic indices to track habitat change, compare sites, and evaluate conservation actions across landscapes.','Bioacoustics & Ecoacoustics',ARRAY['Soundscape','Biophony','Geophony','Anthrophony','Acoustic index','Ecoacoustics']::text[],ARRAY['Treating soundscape ecology as identical to traditional single-species bioacoustics','Assuming one acoustic index alone fully captures biodiversity','Analysing only target species while ignoring geophony and anthrophony']::text[],ARRAY['Long-term monitoring of a forest before and after logging','Comparing urban, suburban, and wild soundscapes','Using acoustic indices as a rapid biodiversity proxy']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Soundscape ecology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3ef3d1e0-e33b-5d52-bf95-88975600d2ce','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3ef3d1e0-e33b-5d52-bf95-88975600d2ce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3ef3d1e0-e33b-5d52-bf95-88975600d2ce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '10f3e2f6-6129-5907-9ba0-a546aa2e312d','Acoustic habitat','The sound environment available to an organism at a given location, comprising the ambient sound, propagation conditions, and signal-transmission characteristics that determine which acoustic signals an animal can produce, detect, and interpret. It is the acoustic dimension of habitat, shaped by vegetation, terrain, water, weather, and the biophony, geophony, and anthrophony present.','An acoustic habitat is the sound world an animal lives in. It covers the background sounds and how sound travels there. These conditions set what calls an animal can hear and use. Trees, water, weather, and noise all shape it.','The concept links physical habitat to communication, helping explain how sound conditions constrain signalling, detection ranges, and species coexistence.','Researchers characterise acoustic habitats to predict communication distances, site suitability, and how noise or habitat change may disrupt animal signalling.','Bioacoustics & Ecoacoustics',ARRAY['Acoustic niche partitioning','Sound propagation','Acoustic masking','Soundscape','Acoustic adaptation']::text[],ARRAY['Confusing the acoustic habitat with the broader soundscape rather than the animal''s usable sound environment','Ignoring how vegetation and terrain change signal transmission','Assuming the acoustic habitat is fixed rather than varying by time of day and weather']::text[],ARRAY['Estimating how dense forest shortens bird-song range','Assessing whether road noise degrades an amphibian''s acoustic habitat','Comparing reef acoustic habitats for fish settlement']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic habitat');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '10f3e2f6-6129-5907-9ba0-a546aa2e312d','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='10f3e2f6-6129-5907-9ba0-a546aa2e312d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='10f3e2f6-6129-5907-9ba0-a546aa2e312d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0f666e2f-2cf4-5f76-adb6-c2d23d6bab01','Acoustic refuge','A location or time period in which ambient noise—particularly masking anthrophony or competing biophony—is sufficiently reduced that an organism can produce or detect acoustic signals with improved fidelity. Acoustic refuges arise spatially (quiet areas shielded from noise) or temporally (quiet intervals), and can influence habitat selection and signalling schedules.','An acoustic refuge is a quiet spot or quiet time. In it, noise is low enough for animals to hear or call clearly. A refuge can be a sheltered place or a calm part of the day. Animals may seek one out to communicate better.','The idea explains how animals exploit gaps in noise to maintain communication, and it guides conservation aimed at protecting or restoring quiet.','Managers identify and protect acoustic refuges when planning noise mitigation, quiet zones, and the timing of disruptive activities near sensitive species.','Bioacoustics & Ecoacoustics',ARRAY['Acoustic masking','Anthrophony','Acoustic habitat','Noise pollution','Acoustic niche partitioning']::text[],ARRAY['Assuming a visually pristine area is automatically an acoustic refuge despite distant noise','Overlooking temporal refuges such as pre-dawn quiet windows','Treating any quiet place as a refuge without confirming animals actually use it']::text[],ARRAY['Locating quiet valleys shielded from highway noise','Timing surveys to natural low-noise periods','Designing marine quiet zones away from shipping lanes']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic refuge');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0f666e2f-2cf4-5f76-adb6-c2d23d6bab01','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0f666e2f-2cf4-5f76-adb6-c2d23d6bab01') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0f666e2f-2cf4-5f76-adb6-c2d23d6bab01');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f3ec2cc-95cd-567d-a593-4ca00eff6de8','Acoustic niche partitioning','The hypothesis and observed pattern whereby co-occurring, acoustically signalling species divide the available signal space—along frequency, time, amplitude, or spatial axes—so as to reduce overlap and mutual masking of their signals. Proposed within soundscape ecology as an acoustic analogue of ecological niche partitioning, it predicts that community signals are structured to minimize acoustic competition.','Acoustic niche partitioning means species split up the sound space. Each uses its own frequency band or time slot to be heard. This lowers overlap between their signals. It works like animals sharing food by using different parts of it.','It explains how many species can signal in the same place without jamming each other, and it frames predictions about community acoustic structure.','Ecologists test for partitioning in spectrograms and indices to assess community organisation and detect how noise or invasion collapses the shared signal space.','Bioacoustics & Ecoacoustics',ARRAY['Acoustic competition','Acoustic interference','Acoustic niche hypothesis','Soundscape ecology','Acoustic masking']::text[],ARRAY['Assuming any frequency difference proves active partitioning rather than shared ancestry or chance','Testing only frequency overlap while ignoring the time axis','Treating the acoustic niche hypothesis as proven in every community']::text[],ARRAY['Mapping the frequency bands of a frog chorus for overlap','Testing whether noise forces species to shift call timing','Comparing partitioning between intact and disturbed communities']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic niche partitioning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f3ec2cc-95cd-567d-a593-4ca00eff6de8','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f3ec2cc-95cd-567d-a593-4ca00eff6de8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f3ec2cc-95cd-567d-a593-4ca00eff6de8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3c8c951d-b5cf-51de-8190-ded9e3cd4ee2','Acoustic competition','Interference among signallers for access to the shared acoustic channel, in which overlapping signals from conspecifics or heterospecifics reduce the detectability, discriminability, or effective transmission of one another''s signals. It acts as a selective pressure driving signal timing, frequency use, amplitude adjustment, and niche partitioning.','Acoustic competition happens when many animals call at once. Their sounds overlap and become harder to tell apart. This makes each signal less clear to listeners. It pushes animals to change when, how loud, or how high they call.','The concept identifies a driver of signal evolution and behaviour, explaining why animals adjust their calls to be heard above rivals and other species.','Researchers study acoustic competition to interpret call adjustments, chorus structure, and the impact of added noise on communication success.','Bioacoustics & Ecoacoustics',ARRAY['Acoustic niche partitioning','Acoustic interference','Acoustic masking','Conspecific signal','Heterospecific signal']::text[],ARRAY['Confusing acoustic competition with physical fighting rather than signal interference','Assuming competition occurs only within a species and ignoring heterospecific overlap','Overlooking that animals may raise amplitude, the Lombard effect, in response']::text[],ARRAY['Explaining call-timing shifts in a dense frog chorus','Assessing how urban noise raises acoustic competition','Studying overlap avoidance between neighbouring birds']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic competition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3c8c951d-b5cf-51de-8190-ded9e3cd4ee2','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3c8c951d-b5cf-51de-8190-ded9e3cd4ee2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3c8c951d-b5cf-51de-8190-ded9e3cd4ee2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '41ac6237-ec41-58ac-ba78-e826bd004549','Acoustic interference','The reduction or distortion of an acoustic signal''s reception caused by other sound occupying the same time-frequency space, whether from environmental noise, conspecifics, heterospecifics, or human sources. Interference can be energetic (masking by overlapping energy) or informational (confusion among similar signals), degrading detection, recognition, and localization.','Acoustic interference is when other sounds get in the way of a signal. The wanted sound becomes harder to hear or understand. It can be simple masking by overlapping energy. It can also be confusion between two similar calls.','The term describes the mechanism by which competing sound degrades communication, underpinning studies of masking, noise impact, and signal design.','Field workers evaluate acoustic interference when noise or overlapping species reduce detector accuracy and animal communication range.','Bioacoustics & Ecoacoustics',ARRAY['Acoustic masking','Acoustic competition','Signal-to-noise ratio','Anthrophony','Acoustic niche partitioning']::text[],ARRAY['Using interference and masking as identical when masking is one form of interference','Ignoring informational interference from similar-sounding species','Assuming only loud noise interferes and overlooking persistent low-level noise']::text[],ARRAY['Diagnosing why a detector misses calls during machinery noise','Studying how overlapping songs impair mate recognition','Assessing sonar interference with marine-mammal signals']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic interference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '41ac6237-ec41-58ac-ba78-e826bd004549','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='41ac6237-ec41-58ac-ba78-e826bd004549') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='41ac6237-ec41-58ac-ba78-e826bd004549');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '10b593d6-8438-50bd-b1fd-c81ccf22ccab','Acoustic adaptation','The hypothesis that animal acoustic signals evolve to maximize transmission through the habitat in which they are typically broadcast, so that signal structure (frequency, temporal pattern, tonality) matches the sound-degradation properties of the environment. Closed forest, for example, is predicted to favour lower-frequency, more tonal signals that resist attenuation and reverberation better than those suited to open habitat.','Acoustic adaptation is the idea that calls evolve to travel well at home. Signals change to fit how their habitat carries sound. Thick forest may favour lower, purer notes that fade less. Open land may allow faster, higher calls.','It links signal form to habitat acoustics, offering testable predictions about why species in different environments sound the way they do.','Researchers compare signals across habitats to test acoustic adaptation and predict how habitat change may reduce a signal''s transmission.','Bioacoustics & Ecoacoustics',ARRAY['Acoustic adaptation hypothesis','Sound propagation','Acoustic habitat','Signal degradation','Reverberation']::text[],ARRAY['Treating the hypothesis as universally confirmed despite mixed evidence','Ignoring competing pressures like body size and sexual selection on frequency','Assuming habitat is the only factor shaping signal structure']::text[],ARRAY['Comparing forest and grassland bird songs for frequency','Predicting signal loss when a forest is fragmented','Testing frog-call structure across vegetation types']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic adaptation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '10b593d6-8438-50bd-b1fd-c81ccf22ccab','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='10b593d6-8438-50bd-b1fd-c81ccf22ccab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='10b593d6-8438-50bd-b1fd-c81ccf22ccab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ecfc230f-5bf0-538b-b077-8927103edf89','Acoustic communication network','A social context in which multiple signallers and receivers are within signalling and receiving range of one another, so communication is not confined to isolated sender–receiver dyads but occurs among many individuals, including unintended receivers (eavesdroppers). Network structure allows signals to be evaluated comparatively and information to spread among bystanders.','An acoustic communication network is a group within earshot of each other. Many animals send and hear calls at once, not just in pairs. Others nearby can listen in on the signals. Information can then spread through the whole group.','The framework recognises that most signalling occurs before an audience, shaping eavesdropping, comparative assessment, and the spread of information such as alarm.','Behavioural researchers design playback and microphone-array studies to capture network-level effects rather than single-pair exchanges.','Bioacoustics & Ecoacoustics',ARRAY['Eavesdropping','Conspecific signal','Alarm call','Playback experiment','Territorial song']::text[],ARRAY['Modeling communication only as one sender to one receiver','Overlooking eavesdroppers and unintended receivers','Assuming a signal reaches only its intended target']::text[],ARRAY['Studying how alarm information spreads through a mixed-species flock','Using microphone arrays to map who signals to whom','Testing female eavesdropping on male song contests']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic communication network');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ecfc230f-5bf0-538b-b077-8927103edf89','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ecfc230f-5bf0-538b-b077-8927103edf89') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ecfc230f-5bf0-538b-b077-8927103edf89');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef593ccd-0ced-5f30-b0f1-f816072ffac4','Conspecific signal','An acoustic signal produced by, and typically directed at or relevant to, members of the same species as the signaller. Conspecific signals mediate intraspecific functions such as mate attraction, territory defence, individual or group recognition, and coordination, and their features are shaped by selection for efficient intraspecific communication.','A conspecific signal is a call between animals of the same species. It is meant to reach others of its own kind. Such calls help with mating, defending space, and staying in touch. The signal is tuned for its own species to understand.','The label specifies same-species communication, distinguishing it from heterospecific signals and clarifying the intended audience of a call.','Researchers classify signals as conspecific to interpret their function and to design playbacks that test same-species responses.','Bioacoustics & Ecoacoustics',ARRAY['Heterospecific signal','Acoustic communication network','Mating call','Territorial song','Species recognition']::text[],ARRAY['Confusing conspecific with heterospecific signals','Assuming a conspecific signal is never exploited by eavesdropping other species','Treating all same-species sounds as one signal type regardless of function']::text[],ARRAY['Playing back conspecific song to test territorial response','Distinguishing same-species from other-species calls in a chorus','Studying individual recognition from conspecific calls']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conspecific signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef593ccd-0ced-5f30-b0f1-f816072ffac4','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef593ccd-0ced-5f30-b0f1-f816072ffac4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef593ccd-0ced-5f30-b0f1-f816072ffac4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '896f1a06-2d20-5bb8-9d2d-ab0f3cbcb967','Heterospecific signal','An acoustic signal produced by a different species from the focal animal, which may nonetheless carry information the focal animal can exploit—such as heterospecific alarm calls used for predator detection—or which may cause interference or confusion during communication. The term frames cross-species eavesdropping and acoustic interactions within a community.','A heterospecific signal is a call from another species. An animal may still get useful news from it. One species may react to another''s alarm call. Such calls can also cause confusion or clash.','The concept captures cross-species information use and interference, which are key to community-level communication and eavesdropping studies.','Researchers test whether animals respond to heterospecific calls, informing studies of mixed-species groups and shared alarm systems.','Bioacoustics & Ecoacoustics',ARRAY['Conspecific signal','Alarm call','Eavesdropping','Acoustic interference','Acoustic communication network']::text[],ARRAY['Assuming heterospecific signals are always irrelevant noise to the listener','Confusing heterospecific with conspecific signals','Overlooking that shared alarm calls can benefit several species']::text[],ARRAY['Testing whether a bird flees to another species'' alarm call','Studying mixed-species flock coordination','Assessing cross-species interference in a dense chorus']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Heterospecific signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '896f1a06-2d20-5bb8-9d2d-ab0f3cbcb967','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='896f1a06-2d20-5bb8-9d2d-ab0f3cbcb967') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='896f1a06-2d20-5bb8-9d2d-ab0f3cbcb967');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '89ec1e83-47a8-59bc-a7fb-f90f92814846','Alarm call','A vocalization produced in response to a predator or other threat that alerts nearby receivers, often eliciting escape, freezing, or mobbing. Alarm calls may encode information about predator type, distance, or urgency, are frequently heeded by both conspecifics and heterospecifics, and some are acoustically structured to be difficult for the predator to localize.','An alarm call is a sound given when danger appears. It warns others nearby to hide, flee, or mob the threat. Some alarm calls even signal what kind of predator it is. Other species often listen and react to them too.','Alarm calls function to reduce predation risk for the caller''s group and kin, and they serve as a widely used public source of danger information.','Behavioural studies use alarm-call playbacks to probe predator recognition, referential signalling, and cross-species eavesdropping.','Bioacoustics & Ecoacoustics',ARRAY['Heterospecific signal','Mobbing call','Referential signal','Eavesdropping','Acoustic communication network']::text[],ARRAY['Assuming all alarm calls are simple and undifferentiated','Overlooking that alarm calls can encode predator type or urgency','Treating alarm calls as conspecific-only signals']::text[],ARRAY['Playing predator-specific alarm calls to test escape behaviour','Studying how ground squirrels vary calls by threat','Documenting cross-species alarm responses in a forest']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Alarm call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '89ec1e83-47a8-59bc-a7fb-f90f92814846','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='89ec1e83-47a8-59bc-a7fb-f90f92814846') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='89ec1e83-47a8-59bc-a7fb-f90f92814846');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd408b7d9-b090-5771-8d11-2074a6d59166','Contact call','A typically low-amplitude, frequently repeated vocalization used to maintain contact, spacing, and cohesion among members of a group or between mates, especially when visual contact is limited. Contact calls often encode individual or group identity and coordinate movement, foraging, and reunion.','A contact call is a quiet, repeated sound that keeps a group together. Animals use it to stay in touch when they cannot see each other. It often carries the caller''s identity. It helps a group move and forage as one.','Contact calls maintain group cohesion and coordination, letting individuals track one another''s position and identity without visual contact.','Researchers use contact calls to study group membership, individual recognition, and movement in flocks, herds, and family groups.','Bioacoustics & Ecoacoustics',ARRAY['Conspecific signal','Cohesion call','Individual recognition','Acoustic communication network','Vocalization']::text[],ARRAY['Confusing quiet contact calls with alarm or mating signals','Assuming contact calls carry no individual information','Overlooking their role in coordinating group movement']::text[],ARRAY['Tracking flock cohesion from repeated contact notes','Testing parent-offspring reunion by call identity','Studying contact calls in foraging parrots']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Contact call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd408b7d9-b090-5771-8d11-2074a6d59166','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d408b7d9-b090-5771-8d11-2074a6d59166') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d408b7d9-b090-5771-8d11-2074a6d59166');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ab43524-107b-516a-b9b4-d66a11592000','Begging call','A vocalization produced by dependent offspring, typically nestlings or juveniles, that solicits food or care from parents. Begging call rate and intensity commonly signal hunger or need and influence parental provisioning; begging is studied as a model of parent–offspring communication and conflict, and can also attract predators to the nest.','A begging call is the sound young animals make for food. Chicks and pups use it to ask parents to feed them. Louder or faster begging often means more hunger. These calls can also draw predators to the nest.','Begging calls communicate offspring need and influence how parents share food, and they sit at the centre of parent–offspring communication and conflict.','Researchers measure begging call rate and structure to study provisioning, sibling competition, and nest-predation risk.','Bioacoustics & Ecoacoustics',ARRAY['Parent-offspring conflict','Provisioning','Contact call','Conspecific signal','Honest signal']::text[],ARRAY['Assuming begging always honestly reflects true need','Ignoring that begging raises predation risk','Treating begging intensity as unrelated to sibling competition']::text[],ARRAY['Measuring nestling begging against controlled hunger','Studying how begging noise attracts nest predators','Comparing begging in single- versus multiple-chick broods']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Begging call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ab43524-107b-516a-b9b4-d66a11592000','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ab43524-107b-516a-b9b4-d66a11592000') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ab43524-107b-516a-b9b4-d66a11592000');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '434de858-5dd1-54aa-9dba-843b453b8bb6','Mating call','An acoustic signal produced to attract potential mates and/or stimulate reproductive behaviour, typically by males but in some taxa by either sex. Mating calls often carry information about species identity, location, and signaller quality (size, condition, motivation), and are subject to sexual selection through mate choice and same-sex competition.','A mating call is a sound used to attract a mate. It is often made by males to draw in females. The call can show the species, the caller''s spot, and its quality. Mate choice shapes how these calls sound.','Mating calls advertise availability and quality to prospective mates, functioning as a primary channel of sexual selection.','Researchers analyse mating calls to study species identity, mate choice, and how noise or habitat change reduces mating success.','Bioacoustics & Ecoacoustics',ARRAY['Advertisement call','Territorial song','Sexual selection','Conspecific signal','Lek acoustics']::text[],ARRAY['Assuming only males ever produce mating calls','Confusing mating calls with territorial songs when their functions overlap','Ignoring that call features can honestly signal body size']::text[],ARRAY['Relating frog-call pitch to male body size','Testing female preference with call playbacks','Assessing noise effects on mating-call detection']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mating call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '434de858-5dd1-54aa-9dba-843b453b8bb6','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='434de858-5dd1-54aa-9dba-843b453b8bb6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='434de858-5dd1-54aa-9dba-843b453b8bb6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '692d8ca4-10b7-5c8d-9d57-5b7b9b0ee6b2','Territorial song','A vocal display, often long-range and repeated, used to advertise ownership of and defend a territory against rivals, typically of the same species and sex. Territorial song communicates the resident''s presence, identity, motivation, and quality, deterring intrusion and frequently functioning simultaneously in mate attraction.','A territorial song is a call that claims an area. An animal repeats it to warn rivals to stay away. The song shows who the owner is and how strong it is. It can also attract a mate at the same time.','Territorial song advertises occupancy and deters rivals, reducing costly fights while often doubling as a mate-attraction signal.','Researchers use territorial song for population surveys, territory mapping, and playback tests of rival deterrence.','Bioacoustics & Ecoacoustics',ARRAY['Mating call','Conspecific signal','Playback experiment','Acoustic communication network','Song repertoire']::text[],ARRAY['Assuming territorial song serves only defence and never mate attraction','Treating every repeated song as territorial without testing its function','Ignoring the individual identity encoded in song']::text[],ARRAY['Mapping bird territories by song location','Playing rival song to test boundary defence','Using song counts to estimate the breeding population']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Territorial song');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '692d8ca4-10b7-5c8d-9d57-5b7b9b0ee6b2','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='692d8ca4-10b7-5c8d-9d57-5b7b9b0ee6b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='692d8ca4-10b7-5c8d-9d57-5b7b9b0ee6b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c32ec71-75e1-5e7a-90fe-c62938827c4e','Duetting','Coordinated acoustic signalling in which two individuals, usually a mated pair, combine their vocalizations with temporal precision to produce a joint display, sometimes so tightly timed that it sounds like a single individual. Duets function in pair-bond maintenance, joint territory defence, mate guarding, and coordination.','Duetting is when two animals sing together in time. Usually a mated pair combines their calls closely. The two parts can lock together so well they sound like one. Duets help pairs bond and defend their space.','Duetting coordinates and signals the partnership of a pair, supporting pair-bond maintenance, joint defence, and mate guarding.','Researchers analyse duet timing and structure to study pair bonds, coordination, and joint territory defence, often in tropical birds.','Bioacoustics & Ecoacoustics',ARRAY['Antiphonal calling','Territorial song','Pair bond','Conspecific signal','Vocal coordination']::text[],ARRAY['Mistaking a tightly timed duet for a single bird','Confusing duetting with two birds singing independently','Ignoring the sex-specific roles within a duet']::text[],ARRAY['Analysing duet timing in tropical wrens','Testing whether pairs defend territory jointly','Studying duets as pair-bond indicators']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Duetting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c32ec71-75e1-5e7a-90fe-c62938827c4e','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c32ec71-75e1-5e7a-90fe-c62938827c4e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c32ec71-75e1-5e7a-90fe-c62938827c4e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '00fc1bb0-4c6b-518c-a2d8-048eeb947717','Antiphonal calling','A pattern of alternating vocal exchange in which individuals call back and forth in turn, timing their calls to avoid overlapping one another. Antiphonal calling coordinates communication, maintains contact and spacing, and can strengthen social or pair bonds; it is a form of turn-taking that sometimes underlies duets.','Antiphonal calling is back-and-forth calling in turns. Each animal waits so its call does not overlap the other. This turn-taking keeps their signals clear. It helps animals stay in contact and coordinate.','Antiphonal calling organises exchanges into non-overlapping turns, keeping signals clear and coordinating contact between individuals.','Researchers study antiphonal timing to understand turn-taking, contact maintenance, and the mechanics behind duets.','Bioacoustics & Ecoacoustics',ARRAY['Duetting','Contact call','Vocal coordination','Overlap avoidance','Conspecific signal']::text[],ARRAY['Confusing antiphonal calling with simultaneous chorusing','Assuming turn-taking is random rather than timed to avoid overlap','Treating antiphonal calling and duetting as identical']::text[],ARRAY['Measuring the turn-taking gaps between paired calls','Studying antiphonal contact calls in primates','Distinguishing alternating from overlapping exchanges']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Antiphonal calling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '00fc1bb0-4c6b-518c-a2d8-048eeb947717','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='00fc1bb0-4c6b-518c-a2d8-048eeb947717') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='00fc1bb0-4c6b-518c-a2d8-048eeb947717');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd94ab6f-96eb-5420-a518-29559e8a843b','Lek acoustics','The acoustic features and dynamics of signalling at a lek—an aggregation of displaying males that females visit to choose mates. Lek acoustics concerns how clustered males produce, coordinate, and compete with mating signals, how signal overlap and interference are managed, and how acoustic cues influence female choice within the aggregation.','Lek acoustics is the study of sound at a lek. A lek is a group of males displaying together to attract females. It looks at how the packed males call and compete. It also asks how females use these sounds to choose.','The concept addresses how males signal and compete acoustically in dense aggregations and how those signals drive female mate choice.','Researchers record leks to study signal competition, overlap, and the acoustic cues females use when selecting mates.','Bioacoustics & Ecoacoustics',ARRAY['Mating call','Acoustic competition','Sexual selection','Chorus','Acoustic interference']::text[],ARRAY['Assuming lekking males signal independently rather than competing acoustically','Ignoring how dense overlap challenges female discrimination','Treating lek acoustics as identical to solitary mate calling']::text[],ARRAY['Recording overlap among calling males at a lek','Testing which acoustic cues predict male mating success','Studying signal timing in a chorusing frog lek']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lek acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd94ab6f-96eb-5420-a518-29559e8a843b','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd94ab6f-96eb-5420-a518-29559e8a843b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd94ab6f-96eb-5420-a518-29559e8a843b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e1b4f725-9fc7-501c-8731-23ab491fcb64','Frequency-modulated call','A call whose frequency changes over its duration, sweeping upward, downward, or along more complex contours rather than remaining constant. In echolocating bats, broadband FM calls are well suited to precise ranging and target localization; more generally, frequency modulation encodes information and improves resolution in time and space.','A frequency-modulated call sweeps in pitch as it plays. Its frequency slides up or down instead of holding steady. Bats use FM sweeps to judge distance and detail. The changing pitch packs more information into the call.','Frequency modulation spreads signal energy across a band, aiding precise ranging, localization, and information encoding.','Bioacousticians identify FM sweeps on spectrograms to classify bat species and interpret echolocation behaviour.','Bioacoustics & Ecoacoustics',ARRAY['Constant-frequency call','Echolocation','Broadband signal','Chirp','Spectrogram']::text[],ARRAY['Confusing FM calls with constant-frequency calls on a spectrogram','Assuming all sweeps go in the same direction','Ignoring the harmonics that often accompany FM sweeps']::text[],ARRAY['Classifying bat species by FM-sweep shape','Measuring the bandwidth of an echolocation sweep','Distinguishing FM from CF components in a call']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-modulated call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e1b4f725-9fc7-501c-8731-23ab491fcb64','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e1b4f725-9fc7-501c-8731-23ab491fcb64') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e1b4f725-9fc7-501c-8731-23ab491fcb64');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a9fe62c-2766-5607-af47-d5e4f7ffc9e3','Constant-frequency call','A call, or call component, that maintains a nearly constant frequency for a substantial part of its duration, appearing as a horizontal band on a spectrogram. In CF-echolocating bats the long CF component supports detection of fluttering prey through Doppler-shifted echoes and Doppler-shift compensation, concentrating energy at a narrow frequency for sensitive detection.','A constant-frequency call holds one pitch for most of its length. On a spectrogram it looks like a flat line. Some bats use a long steady tone to spot fluttering insects. The steady pitch packs energy into a narrow band.','A constant frequency concentrates energy in a narrow band, aiding sensitive detection and, in some bats, Doppler-based detection of fluttering prey.','Bioacousticians recognise CF bands on spectrograms to identify bat species and study Doppler-shift compensation.','Bioacoustics & Ecoacoustics',ARRAY['Frequency-modulated call','Echolocation','Doppler shift','Narrowband signal','Spectrogram']::text[],ARRAY['Confusing CF components with FM sweeps','Assuming CF calls contain no frequency change at all','Overlooking the FM tails that often bound a CF component']::text[],ARRAY['Identifying horseshoe bats by their long CF tones','Studying Doppler-shift compensation in CF bats','Separating the CF and FM parts of a call']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant-frequency call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a9fe62c-2766-5607-af47-d5e4f7ffc9e3','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a9fe62c-2766-5607-af47-d5e4f7ffc9e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a9fe62c-2766-5607-af47-d5e4f7ffc9e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b28e9520-7d50-5b20-83b6-a92ec1117894','Harmonic call','A call whose energy is distributed across a fundamental frequency and integer-multiple overtones (harmonics), producing a stacked series of bands on a spectrogram. The harmonic structure results from a periodic sound source and shapes timbre; the relative strength of harmonics can encode identity, size, or motivation and affects transmission through the environment.','A harmonic call has a base pitch plus higher tones above it. These extra tones sit at whole-number multiples of the base. On a spectrogram they appear as stacked bands. Their pattern shapes the call''s tone and can carry information.','Harmonic structure gives a call its timbre and can encode caller traits, while influencing how the signal travels and is recognised.','Analysts read harmonic stacks on spectrograms to identify species and to measure features such as the fundamental frequency.','Bioacoustics & Ecoacoustics',ARRAY['Fundamental frequency','Overtone','Timbre','Spectrogram','Formant']::text[],ARRAY['Mistaking a higher harmonic for the fundamental frequency','Assuming harmonics are equally strong rather than shaped by the source','Confusing harmonics with unrelated overlapping calls']::text[],ARRAY['Measuring the fundamental beneath a harmonic stack','Using harmonic spacing to identify a species','Studying how harmonics fade with distance']::text[],'intermediate','f_n = n · f_0  (n = 1, 2, 3, …)','The frequency of the nth harmonic equals n times the fundamental frequency f-zero, for whole numbers n.','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b28e9520-7d50-5b20-83b6-a92ec1117894','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b28e9520-7d50-5b20-83b6-a92ec1117894') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b28e9520-7d50-5b20-83b6-a92ec1117894');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e4bf6208-d87e-5b4a-8969-14689ce88e56','Pulse train','A temporally structured series of discrete, brief acoustic pulses produced in succession, characterized by pulse rate (pulses per second) and inter-pulse interval. Pulse trains occur in insect, anuran, and marine-mammal signals; pulse rate and pattern often carry species identity and information, and in echolocation the pulse timing governs the update rate on a target.','A pulse train is a run of short sound bursts in a row. Each burst is one pulse, spaced by small gaps. How fast the pulses come often marks the species. Bats and dolphins speed up pulses as they close on prey.','The pattern and rate of pulses encode information and, in echolocation, set how often an animal updates its information about a target.','Analysts measure pulse rate and interval on spectrograms and waveforms to classify signals and study echolocation behaviour.','Bioacoustics & Ecoacoustics',ARRAY['Inter-pulse interval','Pulse repetition rate','Terminal buzz','Click train','Echolocation']::text[],ARRAY['Confusing pulse rate with the frequency (pitch) of each pulse','Assuming a pulse train keeps a fixed rate throughout','Miscounting pulses when they merge at high rates']::text[],ARRAY['Measuring pulse rate to identify an insect species','Tracking the rising pulse rate in a bat approach','Separating merged pulses in a fast train']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pulse train');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e4bf6208-d87e-5b4a-8969-14689ce88e56','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e4bf6208-d87e-5b4a-8969-14689ce88e56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e4bf6208-d87e-5b4a-8969-14689ce88e56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'abebfdda-0db5-5469-8dcc-089cebf605bc','Buzz phase','A segment of an echolocating animal''s call sequence in which pulses are emitted at a greatly increased repetition rate, producing a buzz-like sound. In bats and toothed whales the buzz phase accompanies the final approach to and capture of prey, giving rapid sensory updates; it is characterized by short inter-pulse intervals and often reduced pulse duration and frequency.','The buzz phase is a burst of very fast echolocation pulses. The animal packs pulses close together so they sound like a buzz. Bats and toothed whales use it as they close on prey. The fast rate gives quick updates on the target.','Raising the pulse rate in the buzz phase gives the animal rapid, fine-grained sensory updates during the critical final approach to prey.','Analysts detect buzz phases in recordings to identify foraging attempts and to measure feeding activity of bats and cetaceans.','Bioacoustics & Ecoacoustics',ARRAY['Terminal buzz','Feeding buzz','Approach-phase call','Echolocation','Pulse train']::text[],ARRAY['Confusing the buzz phase with a normal search-call sequence','Assuming every buzz means a successful capture','Overlooking that buzz pulses shorten and drop in frequency']::text[],ARRAY['Counting buzz phases to quantify bat foraging','Marking capture attempts in dolphin echolocation','Separating buzz from search phases on a spectrogram']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Buzz phase');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'abebfdda-0db5-5469-8dcc-089cebf605bc','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='abebfdda-0db5-5469-8dcc-089cebf605bc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='abebfdda-0db5-5469-8dcc-089cebf605bc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '721159c5-8cd9-5ddc-a392-886127ce9a66','Terminal buzz','The final, most rapid portion of the echolocation buzz emitted immediately before prey capture, in which pulse repetition rate reaches its maximum—often around 150 to 200 pulses per second in many aerial-hawking bats—and individual pulses become very short. The terminal buzz marks the moment of interception and is a reliable acoustic signature of a capture attempt.','The terminal buzz is the fastest part of the buzz, just before capture. Pulses come extremely quickly and each is very short. In many bats the rate can reach around 150 to 200 per second. It clearly marks a strike at prey.','The terminal buzz maximises the sensory update rate at the instant of prey interception, and it serves researchers as a clear marker of capture attempts.','Ecologists count terminal buzzes in acoustic surveys as an index of foraging effort and habitat use by bats.','Bioacoustics & Ecoacoustics',ARRAY['Buzz phase','Feeding buzz','Approach-phase call','Echolocation','Pulse repetition rate']::text[],ARRAY['Treating every terminal buzz as a confirmed successful capture','Confusing the terminal buzz with the earlier approach phase','Assuming the buzz rate is the same across all species']::text[],ARRAY['Indexing bat foraging by terminal-buzz counts','Pinpointing the strike moment in a feeding sequence','Comparing buzz rates among bat species']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Terminal buzz');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '721159c5-8cd9-5ddc-a392-886127ce9a66','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='721159c5-8cd9-5ddc-a392-886127ce9a66') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='721159c5-8cd9-5ddc-a392-886127ce9a66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b060cd44-188b-58d0-8689-8989cec8a631','Search-phase call','The echolocation calls produced while an animal is searching for prey, before a target is detected. Search-phase calls typically have the longest inter-pulse intervals and pulse durations and are emitted at a low, regular rate, maximizing detection range; in many bats they are the most species-distinctive calls and form the basis of acoustic identification.','Search-phase calls are made while an animal hunts for prey. At this stage no target has been found yet. The pulses are long and spaced well apart. These calls carry farthest and often best show which species it is.','Search-phase calls maximise detection range while scanning for prey, and their stable structure makes them the main basis for species identification.','Bioacousticians classify bats mainly from search-phase calls, since these are the most consistent and species-specific part of a sequence.','Bioacoustics & Ecoacoustics',ARRAY['Approach-phase call','Buzz phase','Echolocation','Call library','Automated species recognition']::text[],ARRAY['Trying to identify species from buzz calls instead of search-phase calls','Assuming search calls have the short intervals of approach calls','Ignoring how habitat clutter changes search-call structure']::text[],ARRAY['Identifying bat species from search-phase calls','Building a reference call library from search calls','Measuring search-call interval in open versus cluttered space']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Search-phase call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b060cd44-188b-58d0-8689-8989cec8a631','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b060cd44-188b-58d0-8689-8989cec8a631') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b060cd44-188b-58d0-8689-8989cec8a631');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a7bad032-62d5-563d-9062-4c05460b830f','Approach-phase call','Echolocation calls emitted after a target is detected but before the terminal buzz, as the animal homes in on prey. Compared with search-phase calls, approach-phase calls show progressively shortening inter-pulse intervals and pulse durations and an increasing repetition rate, reflecting the need for more frequent updates as the animal nears the target.','Approach-phase calls come after prey is found but before the buzz. As the animal closes in, its pulses speed up and shorten. This gives more frequent updates on the moving target. It sits between the search phase and the final buzz.','Shortening intervals during the approach increase the update rate on a detected target, guiding the animal accurately toward it.','Analysts use the shift from search to approach calls to detect when a foraging animal has locked onto prey.','Bioacoustics & Ecoacoustics',ARRAY['Search-phase call','Buzz phase','Terminal buzz','Echolocation','Pulse repetition rate']::text[],ARRAY['Confusing approach calls with search-phase calls','Assuming the pulse rate jumps suddenly rather than rising gradually','Treating the approach phase as the moment of capture']::text[],ARRAY['Identifying prey detection from the search-to-approach shift','Measuring interval shortening during the approach','Separating approach from terminal buzz on a spectrogram']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Approach-phase call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a7bad032-62d5-563d-9062-4c05460b830f','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a7bad032-62d5-563d-9062-4c05460b830f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a7bad032-62d5-563d-9062-4c05460b830f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '86c3a718-269f-56ab-88e5-f7329fca11c9','Feeding buzz','A rapid terminal sequence of echolocation pulses associated with an attempt to capture prey, functionally equivalent to and often used synonymously with the terminal buzz. In acoustic monitoring the feeding buzz is treated as a behavioural indicator that an animal is actively foraging at a site rather than merely commuting.','A feeding buzz is the fast burst of pulses at a capture attempt. It is basically the same as the terminal buzz. Researchers treat it as a sign of hunting. It shows an animal is feeding at a spot, not just passing through.','The feeding buzz signals an active capture attempt, letting researchers distinguish foraging from commuting activity at a site.','Bat and cetacean monitoring programs count feeding buzzes to map foraging hotspots and assess habitat quality.','Bioacoustics & Ecoacoustics',ARRAY['Terminal buzz','Buzz phase','Approach-phase call','Echolocation','Foraging activity']::text[],ARRAY['Assuming every feeding buzz equals a successful catch','Confusing commuting passes with feeding buzzes','Treating feeding-buzz counts as absolute prey-capture counts']::text[],ARRAY['Mapping foraging hotspots from feeding-buzz density','Comparing feeding activity across habitats','Distinguishing foraging from commuting bats']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Feeding buzz');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '86c3a718-269f-56ab-88e5-f7329fca11c9','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='86c3a718-269f-56ab-88e5-f7329fca11c9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='86c3a718-269f-56ab-88e5-f7329fca11c9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4b787a54-5c37-559c-8edc-26039595adf0','Animal-call source level','The acoustic level of an animal''s vocalization referenced to a standard distance from the source, expressed in decibels—conventionally dB re 20 µPa at 1 m in air or dB re 1 µPa at 1 m in water. Source level quantifies how loud a call is at its origin, independent of propagation loss, and together with transmission loss and background noise sets the distance over which the signal can be detected.','Source level is how loud a call is right at the animal. It is measured at a set distance, usually one metre. It uses decibels with a fixed reference pressure. This value, minus the loss over distance, sets how far the call reaches.','Source level provides a distance-standardised measure of call loudness, enabling comparison across species and calculation of communication and detection ranges.','Bioacousticians estimate source level from calibrated recordings and known ranges to model detection distances and set survey spacing.','Bioacoustics & Ecoacoustics',ARRAY['Transmission loss','Received level','Detection radius','Sound pressure level','Sonar equation']::text[],ARRAY['Reporting a source level without stating the reference distance and pressure','Confusing source level (at the source) with received level (at the receiver)','Comparing air and water source levels without noting their different references']::text[],ARRAY['Estimating whale-call source level for range modeling','Standardising bird-song amplitude to one metre','Setting recorder spacing from expected source levels']::text[],'advanced','RL = SL − TL','The received level equals the source level minus the transmission loss between source and receiver.','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Animal-call source level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4b787a54-5c37-559c-8edc-26039595adf0','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4b787a54-5c37-559c-8edc-26039595adf0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4b787a54-5c37-559c-8edc-26039595adf0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b39bb424-0526-5325-bc26-d187fe7150d6','Detection radius','The maximum distance from a sound source at which its signal can be reliably detected by a receiver or recording system, given the source level, propagation (transmission) loss, background noise, and the detector''s threshold. Detection radius defines the sampling range of a passive acoustic sensor and varies with call type, habitat, weather, and noise.','Detection radius is the farthest distance a call can still be detected. Past this range the signal is too weak or masked. It depends on how loud the call is and how sound fades. Noise, habitat, and the detector''s threshold all change it.','Detection radius defines how far a sensor effectively listens, which is essential for converting detections into density or occupancy estimates.','Ecologists estimate detection radius to space recorders, define the survey area, and correct counts for imperfect detection.','Bioacoustics & Ecoacoustics',ARRAY['Effective detection area','Animal-call source level','Transmission loss','Detection probability','Passive acoustic monitoring']::text[],ARRAY['Assuming detection radius is fixed rather than varying with noise and weather','Using one radius for loud and quiet call types alike','Ignoring detection radius when estimating density from counts']::text[],ARRAY['Spacing recorders so their detection radii do not overlap','Adjusting the survey area for a species'' detection radius','Comparing detection radius in calm versus windy conditions']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Detection radius');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b39bb424-0526-5325-bc26-d187fe7150d6','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b39bb424-0526-5325-bc26-d187fe7150d6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b39bb424-0526-5325-bc26-d187fe7150d6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5a0d8056-d4dd-5245-b5af-398deea04c54','Effective detection area','The area around a sensor within which the number of animals or calls detected equals the number that would be detected under perfect detection out to a fixed radius and none beyond it. It integrates the declining detection probability with distance into an equivalent perfect-detection area, and for a circular detection field of effective radius r equals πr². It is central to converting acoustic detections into density estimates.','Effective detection area is a fix used to count animals from sound. Sound is picked up less as it comes from far off. This turns that slow fade into one clean area. For a circle of radius r it is pi times r squared.','It lets researchers convert raw acoustic counts into densities by defining the equivalent area a sensor perfectly samples.','Passive acoustic surveys compute the effective detection area to estimate animal or call density from detections at fixed sensors.','Bioacoustics & Ecoacoustics',ARRAY['Detection radius','Detection probability','Density estimation','Effective detection radius','Passive acoustic monitoring']::text[],ARRAY['Confusing effective detection area with the maximum detection area','Using a plain circle area without accounting for falling detection probability','Ignoring how call type and noise change the effective detection area']::text[],ARRAY['Converting call detections to density with an effective detection area','Estimating the area from distance-detection data','Comparing effective detection area across sensor types']::text[],'advanced','EDA = π · r²  (r = effective detection radius)','Effective detection area equals pi times the square of the effective detection radius r.','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Effective detection area');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5a0d8056-d4dd-5245-b5af-398deea04c54','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5a0d8056-d4dd-5245-b5af-398deea04c54') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5a0d8056-d4dd-5245-b5af-398deea04c54');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d0caa86-258e-5b04-a79b-7899a60874e6','Occupancy modeling','A statistical framework that estimates the probability a species occupies a site while explicitly accounting for imperfect detection, using repeated surveys to separate true absence from failure to detect. Occupancy models jointly estimate occupancy probability and detection probability, and in acoustic studies they use replicate recordings or time intervals as the repeated detection occasions.','Occupancy modeling asks if a species uses a site. It allows for the chance that a present species is missed. Repeat checks tell a true miss from a real gap. It gives both a use rate and a catch rate.','The method corrects species-distribution estimates for imperfect detection, avoiding the bias of treating non-detection as true absence.','Acoustic monitoring uses occupancy models with replicate recording periods to map species distributions and trends from detector data.','Bioacoustics & Ecoacoustics',ARRAY['Detection probability','False-negative detection','Passive acoustic monitoring','Site occupancy','Automated species recognition']::text[],ARRAY['Treating non-detection as confirmed absence','Ignoring detection probability when interpreting occupancy','Using too few replicate surveys to estimate detection reliably']::text[],ARRAY['Mapping species occupancy from replicate night recordings','Correcting distribution data for missed detections','Modeling how habitat affects occupancy and detection']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Occupancy modeling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d0caa86-258e-5b04-a79b-7899a60874e6','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d0caa86-258e-5b04-a79b-7899a60874e6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d0caa86-258e-5b04-a79b-7899a60874e6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30c22502-b869-539e-b678-338855adb5fd','Vocal activity rate','A metric quantifying the amount of vocal output at a site over time, typically expressed as the number of calls, vocalizations, or vocal events detected per unit time or per recording period. Vocal activity rate is used as an index of animal presence, abundance, or behavioural activity in acoustic monitoring, though it reflects calling behaviour as well as animal numbers.','Vocal activity rate counts how many calls occur over a set time. It is often given as calls per hour or per night. Researchers use it as a sign of how active or common a species is. But more calling does not always mean more animals.','The rate provides a simple, standardised index of acoustic activity for comparing sites, times, or treatments.','Monitoring programs report calls per unit time to track seasonal activity, compare habitats, and flag changes in a population''s calling.','Bioacoustics & Ecoacoustics',ARRAY['Acoustic encounter rate','Call rate','Passive acoustic monitoring','Vocalization','Relative abundance']::text[],ARRAY['Equating a higher vocal activity rate directly with more individuals','Ignoring that calling varies with season, weather, and time of day','Comparing rates from different recording windows without standardising']::text[],ARRAY['Tracking seasonal song activity as calls per hour','Comparing vocal activity across habitats','Relating nightly call rates to weather']::text[],'intermediate','VAR = N / T','Vocal activity rate equals the number of detected calls N divided by the recording time T.','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vocal activity rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30c22502-b869-539e-b678-338855adb5fd','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30c22502-b869-539e-b678-338855adb5fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30c22502-b869-539e-b678-338855adb5fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '300d4cf6-a4a8-5d9f-bf0c-118602594eca','Acoustic encounter rate','The number of acoustic detections or encounters of a target species recorded per unit of survey effort—such as per unit time, per recording, or per distance travelled on a towed survey. Acoustic encounter rate serves as a relative-abundance index in passive acoustic monitoring, standardizing detections by effort so surveys can be compared.','Acoustic encounter rate counts detections per amount of effort. Effort can be time listened or distance travelled. Dividing by effort lets surveys be compared fairly. It works as a rough index of how common a species is.','Standardising detections by effort produces a comparable relative-abundance index across surveys of differing duration or coverage.','Marine and terrestrial acoustic surveys report encounters per hour or per kilometre to compare abundance across sites and years.','Bioacoustics & Ecoacoustics',ARRAY['Vocal activity rate','Relative abundance','Survey effort','Passive acoustic monitoring','Detection probability']::text[],ARRAY['Comparing encounter rates without standardising by effort','Treating encounter rate as an absolute density','Ignoring detection-probability differences between surveys']::text[],ARRAY['Reporting whale encounters per hour on a towed array','Comparing encounter rates between survey years','Standardising detections by listening time']::text[],'intermediate','AER = N / E','Acoustic encounter rate equals the number of encounters N divided by the survey effort E.','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic encounter rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '300d4cf6-a4a8-5d9f-bf0c-118602594eca','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='300d4cf6-a4a8-5d9f-bf0c-118602594eca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='300d4cf6-a4a8-5d9f-bf0c-118602594eca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd8c990b4-c40d-5b90-b40e-9b9a4f1bfc0b','False-positive detection','A detection event in which a signal is reported as the target when the target is in fact absent—for example, a detector or classifier labelling noise, a non-target species, or an artefact as the species of interest. False positives inflate apparent presence or abundance and, if unaccounted for, bias occupancy and density estimates; managing them involves threshold tuning and manual validation.','A false-positive detection flags the target when it is not there. Noise or another species gets mistaken for it. These errors make a species seem more common than it is. Checking flagged detections by hand helps catch them.','Recognising false positives is essential for accurate acoustic data, since uncorrected errors overstate presence and bias downstream estimates.','Analysts set detector thresholds and manually verify a sample of detections to measure and limit the false-positive rate.','Bioacoustics & Ecoacoustics',ARRAY['False-negative detection','Automated species recognition','Detection probability','Occupancy modeling','Classifier threshold']::text[],ARRAY['Assuming automated detections are all correct without validation','Confusing false positives with false negatives','Setting thresholds so low that data floods with false positives']::text[],ARRAY['Validating a sample of classifier hits for false positives','Adjusting thresholds to control the false-positive rate','Correcting occupancy estimates for false positives']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='False-positive detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd8c990b4-c40d-5b90-b40e-9b9a4f1bfc0b','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d8c990b4-c40d-5b90-b40e-9b9a4f1bfc0b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d8c990b4-c40d-5b90-b40e-9b9a4f1bfc0b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17bd41df-eca0-5a55-befa-90e77d01fde2','False-negative detection','A detection failure in which a target signal that is genuinely present is missed and not reported by a detector, classifier, or observer. False negatives arise from low signal-to-noise ratio, masking, distance beyond detection range, or conservative thresholds; unless modelled through detection probability, they bias occupancy and abundance estimates downward.','A false-negative detection misses a target that is really there. The call may be faint, masked, or too far away. These misses make a species look rarer than it is. Occupancy models account for them using detection probability.','Accounting for false negatives is central to unbiased monitoring, since missed detections otherwise understate presence and abundance.','Researchers estimate detection probability and use occupancy models to correct counts for false negatives.','Bioacoustics & Ecoacoustics',ARRAY['False-positive detection','Detection probability','Occupancy modeling','Signal-to-noise ratio','Acoustic masking']::text[],ARRAY['Treating a non-detection as proof of absence','Confusing false negatives with false positives','Setting thresholds so high that many real calls are missed']::text[],ARRAY['Estimating detection probability to correct for misses','Assessing how noise raises the false-negative rate','Modeling occupancy to handle missed detections']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='False-negative detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17bd41df-eca0-5a55-befa-90e77d01fde2','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17bd41df-eca0-5a55-befa-90e77d01fde2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17bd41df-eca0-5a55-befa-90e77d01fde2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cb47de98-8e31-5f50-8d8c-c1145063af38','Automated species recognition','The use of computational algorithms—signal-processing detectors and, increasingly, machine-learning and deep-learning classifiers—to automatically detect and identify species from their sounds in audio recordings. Systems are trained or configured on labelled reference sounds and output species identifications with confidence scores; performance is evaluated with precision, recall, and related metrics against validated data.','Automated species recognition uses software to name species by sound. It scans recordings and finds and tags calls. Modern tools learn from many tagged examples. Experts check its results against known true data.','Automation lets researchers process very large acoustic datasets that would be impractical to review by ear, enabling large-scale monitoring.','Tools such as deep-learning bird classifiers scan continuous recordings to identify species, which analysts then validate on a sample.','Bioacoustics & Ecoacoustics',ARRAY['Template matching','Bioacoustic event detector','False-positive detection','Machine learning classifier','Spectrogram annotation']::text[],ARRAY['Trusting outputs without validating precision and recall','Applying a model outside the species or region it was trained on','Ignoring that background noise degrades recognition accuracy']::text[],ARRAY['Running a deep-learning classifier over season-long recordings','Validating automated identifications against expert labels','Comparing recognisers on a labelled test set']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Automated species recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cb47de98-8e31-5f50-8d8c-c1145063af38','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cb47de98-8e31-5f50-8d8c-c1145063af38') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cb47de98-8e31-5f50-8d8c-c1145063af38');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73eb9aff-3244-5d22-87f8-63effc9af3f3','Template matching','A detection method that locates occurrences of a target sound by comparing a stored reference template—an example call or its spectrographic representation—against a recording, scoring similarity (for example by cross-correlation) at each position and flagging matches above a threshold. It is effective for stereotyped signals but sensitive to variation in call structure, noise, and distortion.','Template matching finds a sound by comparing it to a saved example. The software slides the template along the recording. Where the match score is high enough, it marks a detection. It works best for calls that always sound alike.','Template matching provides a simple, interpretable way to detect stereotyped calls without large training datasets.','Analysts build spectrogram cross-correlation templates to detect species with consistent calls in long recordings.','Bioacoustics & Ecoacoustics',ARRAY['Cross-correlation','Bioacoustic event detector','Automated species recognition','Spectrogram','Detection threshold']::text[],ARRAY['Expecting one template to detect highly variable calls well','Setting the match threshold without checking false positives and negatives','Ignoring how noise and distance lower match scores']::text[],ARRAY['Detecting a stereotyped whale call by cross-correlation','Building multiple templates to cover call variation','Tuning the match threshold on a labelled subset']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Template matching');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73eb9aff-3244-5d22-87f8-63effc9af3f3','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73eb9aff-3244-5d22-87f8-63effc9af3f3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73eb9aff-3244-5d22-87f8-63effc9af3f3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1399262f-a00d-5bf2-99fe-c38388b3c723','Spectrogram annotation','The process of marking and labelling sound events on a spectrogram—delimiting them in time and frequency and assigning identities or categories—to create reference and training data or to document signal features. Annotations typically record start and end times, frequency bounds, and a label, and they underpin call libraries, classifier training, and validation.','Spectrogram annotation means marking sounds on a spectrogram. Each event is boxed in time and frequency and given a label. These labels build reference and training data. They are needed to teach and check recognition software.','Annotation produces the labelled ground-truth data required to train, evaluate, and validate detectors and classifiers, and to build call references.','Analysts draw time-frequency boxes and assign species labels in annotation software to create training and test sets.','Bioacoustics & Ecoacoustics',ARRAY['Spectrogram','Automated species recognition','Call library','Training data','Bioacoustic event detector']::text[],ARRAY['Annotating inconsistently between people without agreed protocols','Labelling only clear calls and skipping faint ones, biasing training','Recording labels without precise time-frequency bounds']::text[],ARRAY['Building a labelled training set for a classifier','Marking call bounds to measure signal features','Creating a validated test set for detector evaluation']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectrogram annotation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1399262f-a00d-5bf2-99fe-c38388b3c723','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1399262f-a00d-5bf2-99fe-c38388b3c723') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1399262f-a00d-5bf2-99fe-c38388b3c723');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '867985ba-dcd4-5ffc-bc1c-bf1a802c4d34','Acoustic Richness Index','A rank-based acoustic index (denoted AR) that combines the temporal entropy and the median of the amplitude envelope of a recording to summarize acoustic activity and complexity, intended as a proxy for biodiversity or activity. Each recording''s median envelope amplitude and temporal entropy are ranked across a set of recordings, and their product is scaled to the range 0 to 1; it is one of several alpha acoustic indices used in ecoacoustics.','The Acoustic Richness Index sums up how busy and varied a recording sounds. It blends the sound''s loudness pattern and its spread over time. Recordings are ranked against each other and scaled from zero to one. Higher values suggest more acoustic activity.','The index gives a single comparable number summarizing acoustic activity, used as a rapid proxy for biodiversity or soundscape richness.','Ecoacousticians compute the index over many recordings to compare sites or track soundscape change without labelling every sound.','Bioacoustics & Ecoacoustics',ARRAY['Acoustic index','Temporal entropy','Acoustic Complexity Index','Soundscape ecology','Amplitude envelope']::text[],ARRAY['Treating the index as a direct species count rather than a proxy','Comparing values from different recording sets, since the ranks are relative','Ignoring that noise and geophony can inflate the index']::text[],ARRAY['Ranking recordings to compare site activity','Tracking soundscape change over a season','Screening large datasets before detailed analysis']::text[],'advanced','AR = rank(M) · rank(H_t) / n²','The index scales the product of the ranked median amplitude envelope M and the ranked temporal entropy H-t by the square of the number of recordings n.','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Richness Index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '867985ba-dcd4-5ffc-bc1c-bf1a802c4d34','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='867985ba-dcd4-5ffc-bc1c-bf1a802c4d34') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='867985ba-dcd4-5ffc-bc1c-bf1a802c4d34');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4116cb55-847d-519b-83f6-b486c2660fc4','Bioacoustic event detector','An algorithm or system that automatically locates candidate sound events of interest within a continuous recording—segmenting the audio in time, and often frequency, to flag potential signals for further classification or review—typically using energy thresholds, spectral features, or learned models. It is the detection stage that precedes species classification in an acoustic-analysis pipeline.','A bioacoustic event detector finds sounds worth examining in a recording. It scans the audio and marks where events occur. It flags candidates but need not name the species. A classifier usually identifies them afterward.','The detector reduces continuous audio to a manageable set of candidate events, providing the first stage of an automated analysis pipeline.','Monitoring pipelines run an event detector to extract call candidates from days of audio before classification and review.','Bioacoustics & Ecoacoustics',ARRAY['Automated species recognition','Template matching','Spectrogram annotation','Signal-to-noise ratio','Detection threshold']::text[],ARRAY['Confusing the detection stage with species classification','Setting energy thresholds that miss faint events or flag noise','Assuming a detector tuned for one taxon works for all']::text[],ARRAY['Extracting call candidates from continuous recordings','Tuning a detector to balance misses and false alarms','Feeding detected events into a classifier']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bioacoustic event detector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4116cb55-847d-519b-83f6-b486c2660fc4','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4116cb55-847d-519b-83f6-b486c2660fc4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4116cb55-847d-519b-83f6-b486c2660fc4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8c2cfe77-454e-53c7-95b6-e8ad1cf01adc','Behavioral audiometry','A class of hearing assessment in which threshold and suprathreshold responses are inferred from a listener''s overt, voluntary or trained behavioral reactions to controlled acoustic stimuli, rather than from physiological measures. It encompasses conventional pure-tone and speech audiometry in cooperative listeners and developmentally appropriate paradigms such as visual reinforcement and conditioned play audiometry in young children. Results are expressed relative to audiometric zero and depend on the patient''s attention, conditioning, and response reliability.','Behavioral audiometry checks hearing by watching how a person acts. The listener responds when they hear a sound. They may raise a hand, press a button, or turn their head. It needs the person to pay attention and take part. It differs from tests that measure the body directly.','It provides a direct, ear- and frequency-specific measure of what a person can actually hear, forming the reference against which objective tests and hearing-aid fittings are judged.','Clinicians use it daily to plot audiograms, obtain speech thresholds, and monitor hearing, choosing a paradigm matched to the patient''s developmental age and ability to respond.','Medical, Hearing & Clinical Acoustics',ARRAY['Pure-tone audiometry','Speech audiometry','Visual reinforcement audiometry','Conditioned play audiometry','Audiometric zero']::text[],ARRAY['Assuming a no-response result always means no hearing rather than poor attention or conditioning','Treating behavioral thresholds as exact values rather than statistical estimates','Using an adult response method with a child too young to cooperate']::text[],ARRAY['Plotting an adult audiogram with hand-raise responses','Selecting a play-based method for a three-year-old','Cross-checking behavioral thresholds against otoacoustic emissions']::text[],'beginner',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Behavioral audiometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8c2cfe77-454e-53c7-95b6-e8ad1cf01adc','f9e9fa38-e692-44c0-92da-653529165c7c',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8c2cfe77-454e-53c7-95b6-e8ad1cf01adc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8c2cfe77-454e-53c7-95b6-e8ad1cf01adc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ca854773-da7b-5c7f-9e92-fbc75d961c2a','Conditioned play audiometry','A behavioral pure-tone and speech technique for young children, roughly two-and-a-half to five years old, in which the child is operantly conditioned to perform a simple, rewarding motor play task—such as placing a peg or dropping a block—each time a signal is detected. This lets the tester obtain frequency-specific, ear-specific thresholds under earphones or in sound field while keeping the child engaged.','Play audiometry tests hearing in young children through a game. The child learns to do a fun action when a sound comes. For example, they drop a block in a bucket. Doing this each time shows they heard the sound. It turns the test into play so children stay interested.','It extends reliable, frequency-specific behavioral testing down to preschool ages by replacing an abstract response with a motivating game the child can sustain.','Pediatric audiologists use it to get ear- and frequency-specific thresholds under headphones, training the child on a clearly audible tone before testing near threshold.','Medical, Hearing & Clinical Acoustics',ARRAY['Behavioral audiometry','Visual reinforcement audiometry','Pure-tone audiometry','Operant conditioning','Pediatric audiology']::text[],ARRAY['Starting near threshold before the child is reliably conditioned to the task','Rewarding responses that are guesses rather than true detections','Assuming every three-year-old can do the task without a practice phase']::text[],ARRAY['Testing a cooperative four-year-old under insert earphones','Training the play task at a loud, easy level first','Switching to play audiometry when a child outgrows visual reinforcement']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conditioned play audiometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ca854773-da7b-5c7f-9e92-fbc75d961c2a','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ca854773-da7b-5c7f-9e92-fbc75d961c2a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ca854773-da7b-5c7f-9e92-fbc75d961c2a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ace8fee6-2fdf-5260-b716-c551bf66f7d7','Visual reinforcement audiometry','A behavioral method for infants and toddlers, developmentally about six months to two-and-a-half years, that conditions a head-turn response to sound by pairing detection with an attractive visual reward such as an animated toy or video. Once the response is conditioned, sound-field or earphone thresholds are estimated by presenting stimuli and reinforcing correct head-turn responses.','This test checks hearing in babies and toddlers. When the child hears a sound, they turn to look. A fun toy or video then lights up as a reward. The child learns to turn each time a sound plays. This lets testers find the softest sounds a baby hears.','It gives a developmentally appropriate behavioral estimate of hearing in very young children who cannot follow instructions, bridging the gap before play audiometry is possible.','It is used with infants seated on a caregiver''s lap in a sound booth, with two testers coordinating stimulus delivery and reinforcement, often using insert earphones for ear-specific data.','Medical, Hearing & Clinical Acoustics',ARRAY['Behavioral audiometry','Conditioned play audiometry','Conditioned orientation response','Sound-field threshold','Pediatric audiology']::text[],ARRAY['Reinforcing random head turns that are not tied to the sound','Assuming sound-field results give ear-specific thresholds','Continuing after the infant has habituated and stopped responding']::text[],ARRAY['Screening a ten-month-old after a failed newborn screen','Estimating aided detection levels in sound field','Confirming low-frequency hearing before a hearing-aid fitting']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Visual reinforcement audiometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ace8fee6-2fdf-5260-b716-c551bf66f7d7','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ace8fee6-2fdf-5260-b716-c551bf66f7d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ace8fee6-2fdf-5260-b716-c551bf66f7d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af5cea0b-4794-588c-819f-3df97481404e','Conditioned orientation response','The precursor paradigm to modern visual reinforcement audiometry, in which an infant''s natural orienting head-turn toward a sound source is strengthened by conditioning it to a visual reinforcer. It classically uses loudspeakers paired with lighted toys on each side to exploit the child''s localization response, and it established the principle later refined into visual reinforcement audiometry.','This is an older method that led to today''s baby hearing tests. A baby naturally turns toward a new sound. The tester rewards that turn with a lighted toy. Over time the baby learns to turn on purpose. It uses the child''s habit of looking toward sounds.','It established the principle, later refined into visual reinforcement audiometry, that a young child''s localization reflex can be conditioned and reinforced to yield behavioral hearing estimates.','It is encountered mainly as the historical and conceptual basis of visual reinforcement audiometry, and the localization-plus-reinforcement design still underlies two-loudspeaker pediatric setups.','Medical, Hearing & Clinical Acoustics',ARRAY['Visual reinforcement audiometry','Behavioral audiometry','Sound localization','Pediatric audiology','Operant conditioning']::text[],ARRAY['Treating it and visual reinforcement audiometry as unrelated rather than one being the refinement of the other','Assuming it gives ear-specific results when tested in sound field','Expecting reliable turns before the localization reflex has matured']::text[],ARRAY['Understanding the origin of visual reinforcement methods','Using paired loudspeakers to elicit a localizing turn','Comparing historical pediatric test techniques']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conditioned orientation response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af5cea0b-4794-588c-819f-3df97481404e','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af5cea0b-4794-588c-819f-3df97481404e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af5cea0b-4794-588c-819f-3df97481404e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb153cab-4914-532b-a45d-5656f489f45a','Free-field audiometry','Audiometric testing in which stimuli are delivered through one or more loudspeakers in a calibrated room approximating a free or diffuse sound field, rather than through earphones. Thresholds therefore reflect the better-hearing ear or the combined and aided system rather than a single ear, and calibration references sound pressure at the listener''s reference point per the relevant sound-field standard.','In free-field testing, sounds come from speakers, not headphones. The person listens with both ears open. This shows how well they hear in a room. It cannot separate the two ears. It is often used to test hearing aids.','It allows testing when earphones cannot be used and enables aided testing, measuring how a listener, with or without devices, responds to sound arriving through the air.','It is applied in pediatric testing, hearing-aid verification, and cochlear-implant evaluation, with the room and loudspeaker output calibrated for the test frequencies and warble or noise stimuli.','Medical, Hearing & Clinical Acoustics',ARRAY['Sound-field threshold','Aided threshold','Visual reinforcement audiometry','Warble tone','Loudspeaker calibration']::text[],ARRAY['Reading sound-field thresholds as ear-specific results','Using steady pure tones that cause standing waves instead of warble tones or noise bands','Ignoring room calibration and loudspeaker placement']::text[],ARRAY['Testing a child who refuses earphones','Measuring aided detection with hearing aids on','Verifying benefit in a cochlear-implant user']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Free-field audiometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb153cab-4914-532b-a45d-5656f489f45a','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb153cab-4914-532b-a45d-5656f489f45a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb153cab-4914-532b-a45d-5656f489f45a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fae63b21-9fc7-580b-bbc5-55675d112e46','Sound-field threshold','The lowest stimulus level, expressed in dB HL or dB SPL at a defined reference point, at which a listener reliably detects a warble tone or narrow-band noise presented through loudspeakers in a calibrated sound field. It reflects the response of the better ear, or of an aided system, rather than a single isolated ear.','A sound-field threshold is the softest speaker sound a person can hear. The sound comes through the air, not headphones. Both ears listen together. So it shows the better ear, or the ears with hearing aids. Warble tones or noise are used, not steady tones.','It quantifies the softest sound detectable through the air, providing the reference for aided-versus-unaided comparisons and for testing patients who cannot wear earphones.','It is recorded during pediatric and hearing-aid evaluations using frequency-modulated warble tones or narrow-band noise to avoid room standing waves that distort pure-tone levels.','Medical, Hearing & Clinical Acoustics',ARRAY['Free-field audiometry','Aided threshold','Unaided threshold','Warble tone','Audiometric zero']::text[],ARRAY['Attributing a sound-field threshold to one specific ear','Using pure tones and getting errors from room standing waves','Comparing sound-field dB HL directly to earphone thresholds without accounting for calibration']::text[],ARRAY['Estimating hearing in an infant using visual reinforcement','Documenting the softest aided detection level','Monitoring change in a device user over time']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-field threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fae63b21-9fc7-580b-bbc5-55675d112e46','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fae63b21-9fc7-580b-bbc5-55675d112e46') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fae63b21-9fc7-580b-bbc5-55675d112e46');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8494ab3a-b68b-55e1-a249-37885e367481','Aided threshold','A sound-field detection threshold measured while the patient wears an amplification device—a hearing aid, cochlear implant, or bone-conduction device—expressed as the softest warble-tone or narrow-band-noise level detected. Compared with the unaided threshold it indexes the audibility gained from the device, but it is a detection rather than a clarity measure.','An aided threshold is the softest sound a person hears with a hearing aid on. It is measured through speakers in a room. Comparing it to the no-aid result shows what the device adds. It only tells detection, not how clear speech is.','It documents how much softer a person can hear once a device is fitted, giving a simple audibility check for the fitting.','It is plotted during hearing-aid or cochlear-implant fittings; modern hearing-aid practice favors real-ear measures, but aided thresholds remain common in cochlear-implant follow-up.','Medical, Hearing & Clinical Acoustics',ARRAY['Unaided threshold','Sound-field threshold','Real-ear measurement','Functional gain','Cochlear implant mapping']::text[],ARRAY['Reading better aided thresholds as proof of good speech understanding','Using aided thresholds instead of real-ear measures to verify a hearing aid','Ignoring that compression makes aided thresholds an incomplete picture']::text[],ARRAY['Checking detection of soft sounds after a cochlear-implant activation','Comparing aided and unaided warble-tone levels','Demonstrating an audibility change to a family']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aided threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8494ab3a-b68b-55e1-a249-37885e367481','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8494ab3a-b68b-55e1-a249-37885e367481') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8494ab3a-b68b-55e1-a249-37885e367481');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6fa62e14-c559-5f2d-9440-8a8968fb6950','Unaided threshold','A sound-field or earphone detection threshold obtained without any amplification device in place, serving as the baseline against which aided thresholds and device benefit are compared. When measured in sound field it reflects the better-hearing ear rather than a single ear.','An unaided threshold is the softest sound a person hears with no hearing aid. It is the starting point for testing. Comparing it to the aided result shows the device''s help. In room testing it reflects the better ear.','It establishes the listener''s baseline audibility so any improvement from a device can be quantified as functional gain.','It is measured before or alongside aided testing during device evaluations, and the difference between unaided and aided sound-field thresholds is the functional gain at each frequency.','Medical, Hearing & Clinical Acoustics',ARRAY['Aided threshold','Functional gain','Sound-field threshold','Free-field audiometry','Pure-tone audiometry']::text[],ARRAY['Confusing an unaided sound-field threshold with an ear-specific earphone threshold','Forgetting that it reflects the better ear in sound field','Comparing unaided and aided values taken under different calibration conditions']::text[],ARRAY['Establishing baseline detection before a fitting','Computing functional gain from unaided minus aided thresholds','Documenting hearing before a device trial']::text[],'beginner',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Unaided threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6fa62e14-c559-5f2d-9440-8a8968fb6950','f9e9fa38-e692-44c0-92da-653529165c7c',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6fa62e14-c559-5f2d-9440-8a8968fb6950') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6fa62e14-c559-5f2d-9440-8a8968fb6950');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ec15724-e552-5538-ba85-4b1951d24e2f','Most comfortable level','The suprathreshold intensity, in dB HL or dB SPL, at which a listener judges speech or a specified signal to be most comfortable for sustained listening. It is a subjective loudness landmark used to position presentation levels for word-recognition testing and to inform amplification targets; it varies with signal type and instructions and typically spans a range rather than a single point.','The most comfortable level is the loudness that feels easiest to listen to. The listener says when speech sounds just right, not too soft or loud. It is used to set the volume for word tests. It is a personal judgment, so it can vary.','It identifies a comfortable presentation level for suprathreshold speech testing and helps set amplification so everyday sounds land in a comfortable loudness zone.','Clinicians establish it before word-recognition testing and use it, with the loudness discomfort level, to define a patient''s dynamic range for hearing-aid fitting.','Medical, Hearing & Clinical Acoustics',ARRAY['Loudness discomfort level','Dynamic range','Word recognition score','Speech audiometry','Uncomfortable loudness level']::text[],ARRAY['Treating it as a single fixed number rather than a range','Assuming it is always where word recognition peaks','Confusing it with the loudness discomfort level']::text[],ARRAY['Setting the level for a word-recognition list','Defining the comfort end of a patient''s dynamic range','Counseling a patient on comfortable volume settings']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Most comfortable level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ec15724-e552-5538-ba85-4b1951d24e2f','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ec15724-e552-5538-ba85-4b1951d24e2f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ec15724-e552-5538-ba85-4b1951d24e2f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '000dfa17-4fbc-5343-9888-35d59f13a44b','Speech discrimination score','The percentage of monosyllabic words, typically from phonetically balanced lists, that a listener repeats correctly when presented at a suprathreshold level, historically termed speech discrimination. It quantifies suprathreshold speech-recognition ability; the term has largely been superseded by word recognition score because the task measures open-set recognition rather than discrimination between items.','This score shows how many words a person repeats right. Single words are played at a clear, comfortable volume. The score is the percent said correctly. A high score means good understanding of clear speech. The newer name is word recognition score.','It gauges how well a person understands clear speech above threshold, helping separate loss of audibility from loss of clarity and flagging retrocochlear or central problems.','It is reported as a percentage on the audiogram from recorded word lists; a poor score out of proportion to the pure-tone loss prompts further medical or central testing.','Medical, Hearing & Clinical Acoustics',ARRAY['Word recognition score','Phonetically balanced word list','Speech audiometry','Most comfortable level','Performance-intensity function']::text[],ARRAY['Calling the task discrimination when it is open-set recognition','Assuming a normal audiogram guarantees a high score','Presenting words too softly and blaming clarity for poor audibility']::text[],ARRAY['Testing clarity at the most comfortable level','Investigating a poor score with normal thresholds','Comparing right- and left-ear recognition']::text[],'intermediate','Score (%) = (words correct / words presented) × 100','The score equals the number of words repeated correctly divided by the number of words presented, multiplied by one hundred.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech discrimination score');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '000dfa17-4fbc-5343-9888-35d59f13a44b','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='000dfa17-4fbc-5343-9888-35d59f13a44b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='000dfa17-4fbc-5343-9888-35d59f13a44b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53556e43-96d7-525c-9793-4a6af06edd83','Word recognition score','The percentage of monosyllabic words correctly identified from a standardized, often phonetically balanced, list presented at a defined suprathreshold level; it is the current standard term for open-set suprathreshold speech-recognition ability. Scores are interpreted alongside the presentation level, the list used, and the possibility of rollover at high levels in retrocochlear pathology.','The word recognition score is the percent of words a person repeats right. Single words play at a set, comfortable loudness. It shows how clearly the person hears speech. A low score can point to nerve or brain issues. It is the modern name for speech discrimination.','It measures suprathreshold speech clarity to distinguish audibility loss from processing loss and to help localize the site of a hearing disorder.','It is obtained from recorded lists at a level above the speech threshold; asymmetries or rollover between ears can indicate retrocochlear disease and guide referral.','Medical, Hearing & Clinical Acoustics',ARRAY['Speech discrimination score','Phonetically balanced word list','Rollover','Speech recognition threshold','Performance-intensity function']::text[],ARRAY['Presenting only a half list and treating the score as fully reliable','Testing at a single level and missing rollover','Assuming a high score means normal hearing in noise']::text[],ARRAY['Documenting speech clarity for a hearing-aid candidate','Detecting rollover during an acoustic-tumor workup','Comparing ears for asymmetry']::text[],'intermediate','Score (%) = (words correct / words presented) × 100','The score equals the number of words repeated correctly divided by the total number of words presented, multiplied by one hundred.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Word recognition score');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53556e43-96d7-525c-9793-4a6af06edd83','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53556e43-96d7-525c-9793-4a6af06edd83') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53556e43-96d7-525c-9793-4a6af06edd83');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '50736b51-e2bd-59d5-a2b3-7a66f96e9a63','Speech-in-noise test','Any of a family of speech-audiometric procedures that measure recognition of words or sentences against a competing background of speech babble or noise, reported either as percent-correct at a fixed signal-to-noise ratio or as the signal-to-noise ratio yielding a criterion score such as fifty percent. These tests quantify real-world listening difficulty that quiet word tests miss.','A speech-in-noise test checks understanding when background noise is present. Words or sentences play with noise or babble behind them. The result shows how much noise a person can handle. Many people hear fine in quiet but struggle in noise. This test finds that problem.','It reveals difficulty understanding speech in realistic noisy settings, which pure-tone and quiet-speech tests do not predict well, and helps set expectations and technology choices.','Clinicians run tests such as QuickSIN, BKB-SIN, or the hearing-in-noise test to derive a signal-to-noise-ratio loss, informing counseling and directional or remote-microphone decisions.','Medical, Hearing & Clinical Acoustics',ARRAY['QuickSIN','BKB-SIN','Hearing-in-noise test','Signal-to-noise ratio','Speech reception threshold']::text[],ARRAY['Assuming a good quiet score predicts good performance in noise','Using an unknown or uncontrolled signal-to-noise ratio so results are not comparable','Skipping these tests when a patient''s main complaint is noisy places']::text[],ARRAY['Explaining why quiet tests look normal but restaurants are hard','Choosing directional or remote microphones','Setting realistic hearing-aid expectations']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech-in-noise test');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '50736b51-e2bd-59d5-a2b3-7a66f96e9a63','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='50736b51-e2bd-59d5-a2b3-7a66f96e9a63') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='50736b51-e2bd-59d5-a2b3-7a66f96e9a63');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '852ebdbd-302f-5019-afca-8e41afd08922','QuickSIN','A standardized speech-in-noise test in which lists of six sentences, each containing five key words, are presented in four-talker babble at successively decreasing signal-to-noise ratios, typically from 25 down to 0 dB in 5-dB steps. The patient''s total correct key words yield a signal-to-noise-ratio loss—the increase in signal-to-noise ratio, relative to normal hearers, needed to understand speech in noise.','QuickSIN measures how well someone hears sentences in babble. Six sentences play, each with five key words. The noise grows louder with each sentence. The tester counts the key words heard right. From this it finds the extra signal a person needs over noise.','It gives a fast, repeatable estimate of a listener''s signal-to-noise-ratio loss, showing how much louder speech must be than noise for them compared with normal hearers.','Used in a few minutes per ear, it grades noise difficulty from mild to severe and helps justify directional microphones or remote-microphone systems.','Medical, Hearing & Clinical Acoustics',ARRAY['Speech-in-noise test','BKB-SIN','Hearing-in-noise test','Signal-to-noise ratio','Four-talker babble']::text[],ARRAY['Scoring whole sentences instead of the five key words','Reusing the same list and inflating scores through learning','Assuming signal-to-noise-ratio loss tracks with pure-tone loss']::text[],ARRAY['Grading a patient''s noise difficulty quickly','Documenting the need for a remote microphone','Re-testing with a fresh list to avoid learning effects']::text[],'intermediate','SNR loss = 25.5 − (total key words correct in a list)','The signal-to-noise-ratio loss equals a constant of 25.5 minus the total number of key words repeated correctly across the list.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='QuickSIN');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '852ebdbd-302f-5019-afca-8e41afd08922','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='852ebdbd-302f-5019-afca-8e41afd08922') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='852ebdbd-302f-5019-afca-8e41afd08922');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac2003ed-a44c-52c1-95d6-1d3d48c289a5','BKB-SIN','A speech-in-noise test using Bamford-Kowal-Bench sentences—simple and syntactically appropriate for children and adults—presented in four-talker babble at decreasing signal-to-noise ratios. Scoring of key words across sentence pairs yields the signal-to-noise ratio for fifty percent correct and a signal-to-noise-ratio loss, with the simpler vocabulary making it suitable for young children and cochlear-implant users.','BKB-SIN measures hearing sentences in babble using easy sentences. The simple wording suits children and implant users. Sentences play as the noise grows louder. The score is the signal level needed to get half the words. It works when harder tests are too difficult.','It extends signal-to-noise-ratio testing to children and to listeners with poorer hearing by using simple, predictable sentences, yielding the ratio needed for fifty percent recognition.','It is chosen for pediatric and cochlear-implant assessment where QuickSIN sentences are too hard; list pairs are averaged to estimate signal-to-noise-ratio loss for counseling and device decisions.','Medical, Hearing & Clinical Acoustics',ARRAY['QuickSIN','Speech-in-noise test','Hearing-in-noise test','Signal-to-noise ratio','Bamford-Kowal-Bench sentences']::text[],ARRAY['Using it interchangeably with QuickSIN norms','Testing a single list pair when more are needed for a stable result','Assuming child norms match adult norms']::text[],ARRAY['Testing a school-age child''s hearing in noise','Assessing a cochlear-implant user','Tracking noise performance across visits']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BKB-SIN');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac2003ed-a44c-52c1-95d6-1d3d48c289a5','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac2003ed-a44c-52c1-95d6-1d3d48c289a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac2003ed-a44c-52c1-95d6-1d3d48c289a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7be13d8c-8ff4-5ad1-8ef9-e56a8490d837','Hearing-in-noise test','A sentence-in-noise procedure in which simple sentences are presented in speech-spectrum noise and the presentation level is adaptively varied to find the reception threshold for sentences—the signal-to-noise ratio, or level in quiet, yielding fifty percent correct whole-sentence repetition. Conditions typically include noise from the front and noise to each side to assess spatial listening benefit.','This test finds the level where a person repeats half of full sentences right. Sentences play in steady noise. The tester raises or lowers the level to find the fifty percent point. Noise can come from the front or the sides. This shows how a person uses both ears in noise.','It provides an adaptive sentence reception threshold in noise, including spatial conditions, to quantify real-world difficulty and binaural or directional benefit.','It is used in clinics and research to derive a signal-to-noise ratio for fifty percent and to compare noise-front with noise-side conditions, informing directional and bilateral-device decisions.','Medical, Hearing & Clinical Acoustics',ARRAY['Speech-in-noise test','QuickSIN','BKB-SIN','Speech reception threshold','Signal-to-noise ratio']::text[],ARRAY['Scoring key words instead of the whole sentence as the test requires','Ignoring the spatial noise-side conditions','Comparing its threshold directly with a QuickSIN signal-to-noise-ratio loss']::text[],ARRAY['Measuring spatial release from masking','Setting a research baseline threshold','Comparing bilateral versus unilateral device benefit']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hearing-in-noise test');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7be13d8c-8ff4-5ad1-8ef9-e56a8490d837','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7be13d8c-8ff4-5ad1-8ef9-e56a8490d837') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7be13d8c-8ff4-5ad1-8ef9-e56a8490d837');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1355e78c-60ea-5335-a43d-d38a2438dd8e','Central auditory processing disorder','A deficit in the neural processing of auditory information within the central auditory nervous system, not attributable to peripheral hearing loss or to higher-order language or cognitive disorders. It is diagnosed with a battery of behavioral tests—such as dichotic, temporal-processing, and degraded-speech tasks—supported where appropriate by electrophysiology, and manifests as difficulty with listening in noise, dichotic listening, temporal processing, and localization despite a normal audiogram.','This means the brain has trouble making sense of sound. The ears may work fine, but the signal is handled poorly. People struggle to follow speech in noise or fast talk. It is not caused by a hearing loss alone. Special listening tests help diagnose it.','It names and frames a central, brain-based listening difficulty so it can be identified with targeted tests and managed with therapy, seating, and assistive listening technology.','Audiologists administer a test battery in a sound booth, often for children with normal audiograms but listening complaints, and recommend management such as remote-microphone systems.','Medical, Hearing & Clinical Acoustics',ARRAY['Auditory processing disorder','Dichotic listening','Temporal processing','Speech-in-noise test','Auditory evoked potentials']::text[],ARRAY['Diagnosing it from a single test rather than a battery','Confusing it with attention or language disorders','Assuming a normal audiogram rules out any auditory problem']::text[],ARRAY['Evaluating a child who struggles to hear in class','Recommending a remote-microphone system','Distinguishing listening from attention issues']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Central auditory processing disorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1355e78c-60ea-5335-a43d-d38a2438dd8e','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1355e78c-60ea-5335-a43d-d38a2438dd8e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1355e78c-60ea-5335-a43d-d38a2438dd8e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '830867bd-9385-593b-af0c-719bd31dd1ac','Auditory processing disorder','The current umbrella term, synonymous in most usage with central auditory processing disorder, for difficulty processing auditory information in the central auditory system despite adequate peripheral hearing. It encompasses deficits in temporal processing, dichotic listening, and speech recognition in adverse conditions; diagnosis requires a test battery, and comorbid attention and language factors must be considered.','Auditory processing disorder is trouble handling sound in the brain. Hearing in the ear can be normal. Still, understanding speech in noise is hard. It is basically the same idea as central auditory processing disorder. A set of tests is needed to find it.','It provides a broadly used label for central listening difficulties, guiding assessment and multidisciplinary management while acknowledging overlap with language and attention conditions.','It is used in referrals and reports; the audiologist rules out peripheral loss, runs a processing battery, and coordinates with speech-language and educational teams.','Medical, Hearing & Clinical Acoustics',ARRAY['Central auditory processing disorder','Dichotic listening','Temporal resolution','Speech-in-noise test','Remote microphone system']::text[],ARRAY['Treating it and central auditory processing disorder as different disorders','Diagnosing without excluding hearing loss and language issues','Expecting a single cure rather than layered management']::text[],ARRAY['Writing a referral for listening difficulty','Coordinating care with a speech-language pathologist','Planning classroom accommodations']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory processing disorder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '830867bd-9385-593b-af0c-719bd31dd1ac','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='830867bd-9385-593b-af0c-719bd31dd1ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='830867bd-9385-593b-af0c-719bd31dd1ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fae5fd1d-d7f3-592d-a7ed-8686f91f3ea2','Auditory steady-state response','An auditory evoked potential elicited by periodically modulated or rapidly repeated stimuli, in which the brain''s phase-locked response at the modulation rate is detected objectively and statistically in the ongoing electroencephalogram. Because responses can be evoked simultaneously at several carrier frequencies and analyzed automatically, it is used to estimate frequency-specific thresholds, especially in infants and other difficult-to-test patients.','This test measures brain activity that follows a fast, repeating sound. The brain locks onto the sound''s rhythm. A computer detects this response for you. It can test several pitches at once. It helps estimate hearing in babies who cannot respond.','It provides an objective, frequency-specific estimate of hearing thresholds using automated detection, valuable when behavioral testing is impossible.','It is used in newborn and pediatric diagnostics, often alongside the auditory brainstem response, to build an estimated audiogram for hearing-aid fitting in non-responsive patients.','Medical, Hearing & Clinical Acoustics',ARRAY['Auditory brainstem response','Auditory evoked potentials','Objective audiometry','Frequency-specific threshold','Electroencephalography']::text[],ARRAY['Reading its estimates as exact behavioral thresholds','Using it alone without an auditory brainstem response cross-check in newborns','Ignoring that high-level responses can arise from artifact or spread']::text[],ARRAY['Estimating thresholds in a sleeping infant','Building an audiogram for a baby''s first hearing aids','Confirming a severe loss objectively']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory steady-state response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fae5fd1d-d7f3-592d-a7ed-8686f91f3ea2','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fae5fd1d-d7f3-592d-a7ed-8686f91f3ea2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fae5fd1d-d7f3-592d-a7ed-8686f91f3ea2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '38ef6ecc-b1c0-5a05-ab77-da7bab591950','Cortical auditory evoked potential','A class of longer-latency auditory evoked potentials, chiefly the P1-N1-P2 complex occurring roughly 50 to 300 milliseconds after stimulus onset, generated by the auditory cortex and associated areas in response to sound onset or change. Because they reflect cortical detection of audible stimuli, these responses are used to verify audibility—including aided audibility—and to study auditory maturation and processing.','This is a brain wave from the hearing cortex. It appears about a tenth to a third of a second after a sound. It shows the higher brain has received the sound. It can be tested with hearing aids on. It also tracks how hearing develops in children.','It confirms that sound, or a change in sound, has reached and been registered by the auditory cortex, offering an objective audibility check even in aided conditions.','It is recorded in infants and difficult-to-test patients to verify aided detection of speech sounds, and in research on auditory development and processing.','Medical, Hearing & Clinical Acoustics',ARRAY['Auditory late response','Auditory evoked potentials','P1-N1-P2 complex','Auditory brainstem response','Aided threshold']::text[],ARRAY['Assuming a present response proves speech understanding rather than mere detection','Expecting adult latencies in infants whose responses are immature','Confusing cortical with brainstem responses']::text[],ARRAY['Verifying aided audibility in a baby','Tracking cortical maturation over time','Cross-checking behavioral results objectively']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cortical auditory evoked potential');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '38ef6ecc-b1c0-5a05-ab77-da7bab591950','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='38ef6ecc-b1c0-5a05-ab77-da7bab591950') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='38ef6ecc-b1c0-5a05-ab77-da7bab591950');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e5fa30e2-86ff-528e-971c-fa44a04895dd','Auditory late response','The late-latency auditory evoked potential complex, chiefly the N1-P2 components arising roughly 80 to 300 milliseconds after stimulus onset from the auditory cortex, essentially synonymous with the exogenous cortical auditory evoked response. It indexes cortical registration of sound and is used, in awake and attentive states, to estimate audibility and study higher auditory processing.','The auditory late response is a slow brain wave to sound. It comes from the hearing cortex about a quarter second after a sound. It shows the brain noticed the sound. It works best when the person is awake and alert. It overlaps with the cortical evoked response.','It provides an objective cortical marker of sound detection and change, used to estimate audibility and probe higher auditory processing.','It is recorded in cooperative or awake patients to confirm detection of tones or speech, including aided conditions, and in research on attention and processing.','Medical, Hearing & Clinical Acoustics',ARRAY['Cortical auditory evoked potential','Auditory evoked potentials','Middle latency response','N1-P2 complex','Objective audiometry']::text[],ARRAY['Recording it during sleep, where the response degrades','Treating it as a brainstem measure','Assuming detection equals comprehension']::text[],ARRAY['Estimating thresholds in an awake adult who cannot respond','Verifying detection of speech sounds','Studying attention effects on cortical responses']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory late response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e5fa30e2-86ff-528e-971c-fa44a04895dd','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e5fa30e2-86ff-528e-971c-fa44a04895dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e5fa30e2-86ff-528e-971c-fa44a04895dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '06214b7a-a4d4-5fae-979a-9fa1fe3fc8a5','Middle latency response','The auditory evoked potential occurring roughly 10 to 80 milliseconds after stimulus onset, with components labeled Na, Pa, and Nb, generated by thalamocortical pathways and primary auditory cortex. It bridges the early brainstem and later cortical responses and is used to assess the integrity of higher auditory pathways and, in some protocols, to estimate low-frequency thresholds.','This is a brain wave that comes soon after a sound. It appears between the fast brainstem waves and the slow cortical waves. It reflects the path from deep brain to the hearing cortex. It can check that these higher pathways work. It also helps estimate low-pitch hearing.','It assesses the thalamocortical portion of the auditory pathway, filling the gap between brainstem and cortical responses for diagnosis and threshold work.','It is used in select diagnostic and research settings, including central-pathway assessment and cochlear-implant outcome studies, where muscle artifact and maturation affect its reliability.','Medical, Hearing & Clinical Acoustics',ARRAY['Auditory brainstem response','Cortical auditory evoked potential','Auditory evoked potentials','Thalamocortical pathway','Objective audiometry']::text[],ARRAY['Mistaking postauricular muscle artifact for the neural response','Expecting mature responses in young children','Using it as a stand-alone threshold test without cross-checks']::text[],ARRAY['Assessing central auditory pathway integrity','Estimating low-frequency thresholds objectively','Studying cortical responses in implant users']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Middle latency response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '06214b7a-a4d4-5fae-979a-9fa1fe3fc8a5','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='06214b7a-a4d4-5fae-979a-9fa1fe3fc8a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='06214b7a-a4d4-5fae-979a-9fa1fe3fc8a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd900706c-0f9e-5dae-bf9d-b476df6ed286','Electrocochleography','An electrophysiological technique that records stimulus-evoked potentials generated by the cochlea and auditory nerve—the cochlear microphonic, summating potential, and compound action potential—using an electrode at or near the cochlea, placed on the tympanic membrane, in the ear canal, or transtympanically on the promontory. It is applied to identify endolymphatic hydrops and Meniere''s disease, enhance wave I of the auditory brainstem response, and monitor the ear during surgery.','This test records tiny electrical signals from the inner ear. A sound is played and an electrode picks up the response. It captures signals from the cochlea and hearing nerve. Doctors use it to help diagnose Meniere''s disease. It also helps during some ear surgeries.','It captures cochlear and auditory-nerve potentials to diagnose inner-ear disorders such as Meniere''s disease, clarify the auditory brainstem response wave I, and monitor cochlear function during surgery.','It is performed with ear-canal, tympanic-membrane, or transtympanic electrodes; the summating-potential to action-potential ratio is examined for hydrops, and the method aids intraoperative and cochlear-implant monitoring.','Medical, Hearing & Clinical Acoustics',ARRAY['Summating potential','Action potential','Cochlear microphonic','Auditory brainstem response','Endolymphatic hydrops']::text[],ARRAY['Reading a raised summating-to-action-potential ratio as proof of Meniere''s without clinical context','Confusing the cochlear microphonic with neural responses','Assuming a normal result excludes hydrops']::text[],ARRAY['Investigating suspected Meniere''s disease','Enhancing a hard-to-see auditory brainstem response wave I','Monitoring the cochlea during surgery']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrocochleography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd900706c-0f9e-5dae-bf9d-b476df6ed286','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d900706c-0f9e-5dae-bf9d-b476df6ed286') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d900706c-0f9e-5dae-bf9d-b476df6ed286');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3c46c67f-cf4e-565f-8fdf-0d4c41bb8dcd','Summating potential','A stimulus-related, direct-current shift in cochlear potential that follows the envelope of the acoustic stimulus, reflecting the nonlinear component of cochlear hair-cell transduction. Recorded in electrocochleography, its magnitude—often expressed as a ratio to the auditory-nerve action potential—is elevated in endolymphatic hydrops and used as a marker supporting the diagnosis of Meniere''s disease.','The summating potential is a steady voltage from the inner ear during sound. It follows the shape of the sound. It comes from the hair cells'' response. In this test its size is compared to the nerve''s signal. A large ratio can point to Meniere''s disease.','It serves as an electrophysiological marker of cochlear function, and its ratio to the action potential helps flag endolymphatic hydrops.','It is measured in electrocochleography traces; clinicians compute the summating-to-action-potential ratio and watch for an enlarged summating potential as evidence supporting hydrops or Meniere''s disease.','Medical, Hearing & Clinical Acoustics',ARRAY['Action potential','Electrocochleography','Cochlear microphonic','Endolymphatic hydrops','Hair cell transduction']::text[],ARRAY['Interpreting the summating potential in isolation from the action potential','Assuming any elevation confirms Meniere''s disease','Confusing the direct-current summating potential with the alternating cochlear microphonic']::text[],ARRAY['Computing a summating-to-action-potential ratio for suspected hydrops','Comparing affected and unaffected ears','Reviewing electrocochleography in a Meniere''s workup']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Summating potential');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3c46c67f-cf4e-565f-8fdf-0d4c41bb8dcd','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3c46c67f-cf4e-565f-8fdf-0d4c41bb8dcd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3c46c67f-cf4e-565f-8fdf-0d4c41bb8dcd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '43a5e895-49e7-5c1a-937e-82055de6636a','Action potential','In the auditory and electrocochleographic context, the compound action potential is the synchronous, all-or-none neural discharge of many auditory-nerve fibers at stimulus onset, corresponding to wave I of the auditory brainstem response. Its amplitude and latency index auditory-nerve function, and it is the denominator of the summating-to-action-potential ratio used in hydrops assessment; more generally, an action potential is the transient membrane depolarization by which neurons signal.','An action potential is the electrical spike a nerve makes to send a signal. In ear testing, many nerve fibers fire together at a sound''s start. This combined spike is recorded in electrocochleography. It matches wave I of the brainstem response. Its size is compared with the summating potential.','It represents the auditory nerve''s synchronous response to sound and is used to gauge nerve function and as the reference for the summating-to-action-potential ratio.','It is identified in electrocochleography as the sharp onset response; audiologists use its amplitude and latency, and the summating-to-action-potential ratio, in hydrops and nerve assessments.','Medical, Hearing & Clinical Acoustics',ARRAY['Summating potential','Electrocochleography','Compound action potential','Auditory nerve','Auditory brainstem response']::text[],ARRAY['Confusing the compound action potential with a single-fiber spike','Ignoring how stimulus polarity affects the recording','Reading the action potential without noting the summating potential alongside it']::text[],ARRAY['Marking wave I in a difficult auditory brainstem response','Forming the summating-to-action-potential ratio in a Meniere''s workup','Assessing auditory-nerve synchrony']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Action potential');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '43a5e895-49e7-5c1a-937e-82055de6636a','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='43a5e895-49e7-5c1a-937e-82055de6636a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='43a5e895-49e7-5c1a-937e-82055de6636a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0b861334-d92e-51cf-a4c6-911c5191044f','Distortion-product otoacoustic emission','A sound generated by the cochlea''s active, nonlinear outer-hair-cell mechanism when two pure tones of frequencies f1 and f2 are presented simultaneously; the most prominent distortion product measured in humans occurs at the frequency 2f1 minus f2. The presence and level of these emissions indicate functioning outer hair cells, making them a frequency-specific objective tool for screening and site-of-lesion assessment.','This is a faint sound the healthy inner ear makes back. It appears when two tones play together. The ear creates extra tones not in the input. A tiny microphone records the strongest one. Its presence shows the outer hair cells are working.','It provides an objective, frequency-specific check of outer-hair-cell function, used to screen hearing and to help separate cochlear from neural problems.','It is measured with a probe delivering two tones and recording the 2f1-minus-f2 product; it is used in newborn screening, ototoxicity monitoring, and cochlear site-of-lesion testing.','Medical, Hearing & Clinical Acoustics',ARRAY['Transient-evoked otoacoustic emission','Otoacoustic emissions','Outer hair cells','Cochlear amplifier','Newborn hearing screening']::text[],ARRAY['Treating present emissions as proof of normal hearing rather than working outer hair cells','Testing in a noisy room that masks the emission','Assuming absent emissions always mean cochlear loss without checking the ear canal']::text[],ARRAY['Screening a newborn''s hearing','Monitoring for ototoxic damage during treatment','Separating cochlear from neural loss']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distortion-product otoacoustic emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0b861334-d92e-51cf-a4c6-911c5191044f','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0b861334-d92e-51cf-a4c6-911c5191044f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0b861334-d92e-51cf-a4c6-911c5191044f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dca4d4f2-cf7a-5433-bf0c-986ab2446bb6','Transient-evoked otoacoustic emission','An otoacoustic emission evoked by a brief transient stimulus, typically a click, recorded from the ear canal as a time-delayed cochlear response that reflects active outer-hair-cell function across a broad frequency range. It is present in ears with roughly normal outer-hair-cell function, generally better than a mild hearing loss, and is widely used for newborn screening and cochlear assessment.','This is a faint echo the inner ear sends back after a click. A tiny probe plays the click and records the reply. The healthy ear makes this sound on its own. It covers many pitches at once. It is common in newborn hearing screening.','It provides a quick, objective indication that the cochlea''s outer hair cells respond across a range of frequencies, which is ideal for screening.','It is recorded with an ear-canal probe delivering clicks; a present, reproducible response passes a newborn screen, while an absent one prompts follow-up.','Medical, Hearing & Clinical Acoustics',ARRAY['Distortion-product otoacoustic emission','Otoacoustic emissions','Outer hair cells','Newborn hearing screening','Cochlear amplifier']::text[],ARRAY['Reading a pass as proof of perfect hearing at all levels','Testing with background noise or a poor probe fit','Assuming absent emissions always mean cochlear loss without ruling out debris or fluid']::text[],ARRAY['Screening a newborn before discharge','Confirming outer-hair-cell function','Following up a failed screen']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transient-evoked otoacoustic emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dca4d4f2-cf7a-5433-bf0c-986ab2446bb6','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dca4d4f2-cf7a-5433-bf0c-986ab2446bb6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dca4d4f2-cf7a-5433-bf0c-986ab2446bb6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '207ab7e9-f167-5d14-b5ec-f94afd8bd351','Spontaneous otoacoustic emission','A narrow-band acoustic signal emitted by the cochlea in the absence of any external stimulus, detectable in the ear canal in a substantial minority of normal-hearing ears. Reflecting the active, nonlinear cochlear amplifier, these emissions are usually inaudible to the person and are of clinical interest mainly as evidence of cochlear health and, rarely, as a source of objective tinnitus.','This is a faint tone the ear makes on its own. No outside sound is needed. Many normal ears produce these quiet signals. The person usually cannot hear them. They show the inner ear''s amplifier is active.','It demonstrates spontaneous activity of the healthy cochlear amplifier, and its presence supports normal outer-hair-cell function.','It is recorded with a sensitive ear-canal microphone in quiet; it is encountered in research and, rarely, when investigating a patient who reports a tone that can be objectively measured.','Medical, Hearing & Clinical Acoustics',ARRAY['Transient-evoked otoacoustic emission','Distortion-product otoacoustic emission','Cochlear amplifier','Outer hair cells','Objective tinnitus']::text[],ARRAY['Assuming everyone with normal hearing has measurable emissions','Confusing a spontaneous emission with subjective tinnitus','Mistaking equipment noise for an emission']::text[],ARRAY['Documenting cochlear activity in research','Investigating rare objective tinnitus','Confirming outer-hair-cell health']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spontaneous otoacoustic emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '207ab7e9-f167-5d14-b5ec-f94afd8bd351','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='207ab7e9-f167-5d14-b5ec-f94afd8bd351') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='207ab7e9-f167-5d14-b5ec-f94afd8bd351');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b55a2f8f-39ce-534e-ab83-2df4823847d5','Wideband tympanometry','An extension of aural acoustic-immittance testing that measures middle-ear energy reflectance or absorbance across a broad frequency band, roughly 0.2 to 8 kHz, using a click or chirp stimulus rather than a single 226-Hz probe tone. It characterizes middle-ear function more completely and can improve detection of conditions such as otitis media with effusion and ossicular disorders.','This test checks the middle ear across many pitches at once. Older tests use just one tone. This method uses a click covering a wide range. It shows how much sound the eardrum absorbs or reflects. It can find middle-ear problems more clearly.','It gives a fuller picture of middle-ear function by measuring sound absorbance over a wide frequency range, improving sensitivity to some middle-ear disorders.','It is performed with a probe that delivers a wideband click; clinicians read absorbance curves to assess fluid, ossicular problems, or eardrum abnormalities, often in infants.','Medical, Hearing & Clinical Acoustics',ARRAY['Tympanometry','Acoustic immittance','Absorbance','Static compliance','Middle-ear function']::text[],ARRAY['Expecting a single number like traditional tympanometry rather than a frequency curve','Ignoring ear-canal probe fit','Assuming it replaces rather than complements other immittance tests']::text[],ARRAY['Assessing middle-ear fluid in an infant','Evaluating an ossicular problem','Adding detail to a standard tympanogram']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wideband tympanometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b55a2f8f-39ce-534e-ab83-2df4823847d5','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b55a2f8f-39ce-534e-ab83-2df4823847d5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b55a2f8f-39ce-534e-ab83-2df4823847d5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a7a14ea7-526b-5ced-bb0f-1ef089246f57','Acoustic susceptance','The imaginary component of acoustic admittance, representing the reactive part of acoustic energy flow through the middle-ear system that arises from its stiffness and mass elements. In aural immittance it combines with acoustic conductance to form the complex acoustic admittance, and its behavior with probe frequency and ear-canal pressure aids characterization of middle-ear mechanics.','Acoustic susceptance is part of how easily the ear passes sound energy. It comes from the springiness and mass of the middle ear. It is one of two parts of admittance. The other part is conductance. Together they describe the middle ear''s response.','It represents the reactive, stiffness- and mass-controlled portion of admittance, helping characterize middle-ear mechanics beyond a single admittance number.','It is measured in multicomponent and multifrequency tympanometry, where susceptance and conductance patterns help identify stiffness- or mass-dominated middle-ear conditions.','Medical, Hearing & Clinical Acoustics',ARRAY['Acoustic conductance','Acoustic admittance','Acoustic immittance','Tympanometry','Acoustic reactance']::text[],ARRAY['Confusing susceptance, an admittance component, with reactance, an impedance component','Ignoring its dependence on probe frequency','Treating it as identical to compliance']::text[],ARRAY['Interpreting a multifrequency tympanogram','Identifying a stiffness-dominated middle ear','Analyzing admittance components']::text[],'advanced','Ya = Ga + jBa','Acoustic admittance equals acoustic conductance plus the imaginary unit times acoustic susceptance.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic susceptance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a7a14ea7-526b-5ced-bb0f-1ef089246f57','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a7a14ea7-526b-5ced-bb0f-1ef089246f57') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a7a14ea7-526b-5ced-bb0f-1ef089246f57');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1064778d-7ca6-5b2c-81a5-f2a64ee70036','Acoustic conductance','The real component of acoustic admittance, representing the acoustic energy actually transmitted or dissipated by the middle-ear system rather than stored. Together with acoustic susceptance it forms the complex acoustic admittance measured in aural immittance, and its variation with frequency and pressure contributes to multicomponent middle-ear analysis.','Acoustic conductance is the part of admittance tied to energy that passes through. It reflects sound the middle ear lets flow rather than store. It pairs with susceptance to give admittance. Both are read in detailed ear tests. Together they describe middle-ear behavior.','It captures the energy-transmitting, resistive portion of admittance, complementing susceptance in a full description of middle-ear mechanics.','It is read in multicomponent tympanometry alongside susceptance; the pair helps distinguish normal ears from mass- or stiffness-dominated conditions.','Medical, Hearing & Clinical Acoustics',ARRAY['Acoustic susceptance','Acoustic admittance','Acoustic immittance','Tympanometry','Acoustic resistance']::text[],ARRAY['Confusing conductance, an admittance component, with resistance, an impedance component','Overlooking its dependence on frequency','Assuming a single probe frequency tells the whole story']::text[],ARRAY['Reading admittance components in tympanometry','Characterizing middle-ear energy flow','Analyzing multifrequency results']::text[],'advanced','Ya = Ga + jBa','Acoustic admittance equals acoustic conductance plus the imaginary unit times acoustic susceptance.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic conductance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1064778d-7ca6-5b2c-81a5-f2a64ee70036','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1064778d-7ca6-5b2c-81a5-f2a64ee70036') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1064778d-7ca6-5b2c-81a5-f2a64ee70036');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd2b3ba45-3a4d-544a-88fe-87dc73af769c','Equivalent ear-canal volume','An estimate of the air volume enclosed between the probe tip and the tympanic membrane, derived from the acoustic admittance measured at a high ear-canal pressure, such as plus 200 decapascals, where the eardrum is effectively stiffened. It is expressed in cubic centimeters, or equivalently in millimhos at 226 Hz, and helps interpret tympanograms; an abnormally large value can flag a perforation or a patent ventilation tube.','This estimates the air space in front of the eardrum. It is found by measuring at a high pressure that stiffens the eardrum. The result is given as a small volume. A very large value can mean a hole in the eardrum. It helps make sense of the tympanogram.','It isolates the ear-canal contribution so the true middle-ear admittance can be computed, and it provides a check for eardrum perforations or open tubes.','It is read automatically by the tympanometer at high pressure; a large value in a non-responsive ear suggests a perforation or patent tube, while a small value may indicate a blockage.','Medical, Hearing & Clinical Acoustics',ARRAY['Static compliance','Tympanometry','Acoustic admittance','Tympanic membrane perforation','Acoustic immittance']::text[],ARRAY['Confusing ear-canal volume with the middle-ear static admittance','Ignoring age norms that differ for children and adults','Missing a perforation signaled by a very large volume']::text[],ARRAY['Checking a suspected eardrum perforation','Confirming a patent ventilation tube','Correcting a tympanogram for canal volume']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent ear-canal volume');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd2b3ba45-3a4d-544a-88fe-87dc73af769c','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d2b3ba45-3a4d-544a-88fe-87dc73af769c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d2b3ba45-3a4d-544a-88fe-87dc73af769c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5bf52711-648f-5647-868c-6baca6302907','Tympanometric peak pressure','The ear-canal air pressure, in decapascals, at which the measured acoustic admittance reaches its maximum during tympanometry—that is, the pressure at which the middle-ear system is most efficiently coupled, ideally near ambient. Negative values indicate reduced middle-ear pressure, as in Eustachian-tube dysfunction, and it is one of the standard descriptors read from a tympanogram.','This is the pressure where the eardrum moves most freely. The tester changes the air pressure in the canal. Admittance peaks when canal and middle-ear pressures match. A normal peak sits near zero. A negative peak can mean poor Eustachian-tube function.','It indicates the pressure state of the middle ear, helping identify Eustachian-tube dysfunction and negative middle-ear pressure.','It is read directly from the tympanogram peak; clinicians flag markedly negative pressures and track them during otitis-media and Eustachian-tube follow-up.','Medical, Hearing & Clinical Acoustics',ARRAY['Static compliance','Tympanometry','Eustachian tube dysfunction','Middle-ear pressure','Tympanogram']::text[],ARRAY['Treating any nonzero peak as disease rather than allowing a normal range','Confusing peak pressure with static admittance','Ignoring that crying or swallowing can shift middle-ear pressure']::text[],ARRAY['Assessing negative middle-ear pressure','Monitoring Eustachian-tube function','Interpreting a shifted tympanogram peak']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tympanometric peak pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5bf52711-648f-5647-868c-6baca6302907','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5bf52711-648f-5647-868c-6baca6302907') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5bf52711-648f-5647-868c-6baca6302907');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8396e5ed-efdd-536e-9c78-49db97fbafa2','Static compliance','The peak-compensated acoustic admittance of the middle ear at the tympanogram peak, obtained by subtracting the ear-canal tail admittance from the peak admittance, expressed in millimhos or a cubic-centimeter equivalent at the 226-Hz probe tone. It reflects overall middle-ear mobility; low values suggest stiffening from effusion or otosclerosis, and high values suggest a flaccid or discontinuous system.','Static compliance measures how freely the middle ear moves. It is the peak admittance minus the ear-canal part. The result is a small number at a standard test tone. Low values suggest a stiff middle ear. High values suggest a loose or broken system.','It quantifies middle-ear mobility after removing the ear-canal contribution, helping separate stiff conditions like fluid or otosclerosis from hypermobile ossicular conditions.','It is computed automatically as peak minus tail admittance; clinicians read it with peak pressure and canal volume to classify tympanograms.','Medical, Hearing & Clinical Acoustics',ARRAY['Tympanometric peak pressure','Equivalent ear-canal volume','Acoustic admittance','Tympanometry','Otosclerosis']::text[],ARRAY['Forgetting to subtract the ear-canal tail admittance','Judging it without age-appropriate norms','Reading low compliance as always meaning fluid']::text[],ARRAY['Detecting reduced mobility from an effusion','Flagging a hypermobile ossicular chain','Classifying tympanogram type']::text[],'intermediate','Static Ytm = Ypeak − Ytail','Static acoustic admittance equals the admittance at the tympanogram peak minus the ear-canal tail admittance.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Static compliance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8396e5ed-efdd-536e-9c78-49db97fbafa2','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8396e5ed-efdd-536e-9c78-49db97fbafa2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8396e5ed-efdd-536e-9c78-49db97fbafa2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e21b50c-b1f3-5c1a-bcdc-f91a6528f67a','Reflex decay','An acoustic-reflex test in which a sustained activating tone, typically at 500 or 1000 Hz, is presented above the acoustic-reflex threshold for about 10 seconds while the reflex admittance change is monitored. A decline of the reflex amplitude to half or less of its initial value within the first 5 seconds is a positive sign suggesting retrocochlear, auditory-nerve pathology due to abnormal neural adaptation.','Reflex decay checks whether the ear''s reflex fades during a steady tone. A tone plays above the reflex level for several seconds. In healthy ears the reflex holds fairly steady. If it drops to half quickly, that is abnormal. This can point to a nerve problem.','It screens for retrocochlear disorders by revealing abnormal neural adaptation of the acoustic reflex to a sustained loud tone.','It is run as part of an immittance battery when a tumor or nerve lesion is suspected; a rapid decay at 500 or 1000 Hz prompts further audiologic and imaging workup.','Medical, Hearing & Clinical Acoustics',ARRAY['Ipsilateral acoustic reflex','Contralateral acoustic reflex','Acoustic reflex threshold','Retrocochlear pathology','Immittance audiometry']::text[],ARRAY['Testing decay at high frequencies where normal ears also show decay','UNSAFE: presenting sustained high-level reflex-activating tones above the equipment''s rated maximum or prolonging exposure beyond the standard test duration','Reading decay without first confirming a stable reflex']::text[],ARRAY['Screening for an acoustic-nerve tumor','Completing an immittance battery','Following up an asymmetric hearing loss']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reflex decay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e21b50c-b1f3-5c1a-bcdc-f91a6528f67a','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e21b50c-b1f3-5c1a-bcdc-f91a6528f67a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e21b50c-b1f3-5c1a-bcdc-f91a6528f67a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b98ca436-c5a5-555a-b6ef-3be878db20a6','Ipsilateral acoustic reflex','The reflexive contraction of the stapedius muscle measured in the same ear that receives the activating stimulus, detected as a transient change in acoustic admittance. Because the eliciting sound and the probe are in one ear, the response involves the ipsilateral brainstem reflex arc; its threshold and presence aid site-of-lesion analysis and cross-checking of behavioral thresholds.','This is a middle-ear muscle response in the same ear. A loud sound makes the stapedius muscle tighten. A probe in that same ear detects the tiny change. It uses a short nerve loop on one side. Its level helps locate hearing problems.','It tests the same-ear reflex arc, helping confirm middle-ear, cochlear, or nerve status and cross-check behavioral thresholds.','It is measured by the immittance meter delivering the activator and probe in one ear, and it is used with contralateral results to build a reflex pattern for site-of-lesion analysis.','Medical, Hearing & Clinical Acoustics',ARRAY['Contralateral acoustic reflex','Acoustic reflex threshold','Stapedius muscle','Reflex decay','Immittance audiometry']::text[],ARRAY['Confusing the ipsilateral with the contralateral pathway','UNSAFE: raising activator levels beyond the device''s rated maximum output to force a reflex','Assuming an absent reflex always means nerve disease rather than a stiff middle ear']::text[],ARRAY['Building a reflex pattern for site of lesion','Cross-checking behavioral thresholds','Screening middle-ear function']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ipsilateral acoustic reflex');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b98ca436-c5a5-555a-b6ef-3be878db20a6','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b98ca436-c5a5-555a-b6ef-3be878db20a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b98ca436-c5a5-555a-b6ef-3be878db20a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ddb9dab8-9527-5465-aab2-761c2fa67ebd','Contralateral acoustic reflex','The stapedius reflex measured in the ear opposite to the one receiving the activating stimulus, so the activator is in one ear and the probe in the other; this crossed pathway traverses both sides of the brainstem. Comparing ipsilateral and contralateral reflex patterns helps localize lesions along the reflex arc in the middle ear, cochlea, nerve, or brainstem.','This reflex is measured in the opposite ear. A loud sound goes into one ear. A probe in the other ear detects the muscle response. The signal crosses through the brainstem. Comparing both sides helps find where a problem sits.','It tests the crossed reflex arc and, together with ipsilateral results, helps pinpoint the site of a lesion in the middle ear, cochlea, nerve, or brainstem.','The activator is delivered to one ear while the probe records the other; clinicians read the four-cell reflex pattern to interpret brainstem and nerve involvement.','Medical, Hearing & Clinical Acoustics',ARRAY['Ipsilateral acoustic reflex','Acoustic reflex threshold','Stapedius muscle','Reflex decay','Brainstem auditory pathway']::text[],ARRAY['Mixing up which ear is the activator and which is the probe','UNSAFE: exceeding the equipment''s maximum activator output to elicit an absent reflex','Interpreting one cell without the full reflex pattern']::text[],ARRAY['Localizing a brainstem lesion','Reading the four-cell reflex pattern','Investigating an asymmetric loss']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Contralateral acoustic reflex');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ddb9dab8-9527-5465-aab2-761c2fa67ebd','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ddb9dab8-9527-5465-aab2-761c2fa67ebd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ddb9dab8-9527-5465-aab2-761c2fa67ebd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71fa7ecd-630c-5cc7-a9a4-3560e534999c','Stenger test','A test for suspected unilateral or asymmetric nonorganic hearing loss based on the Stenger principle: when the same tone is presented to both ears, only the louder is perceived. By presenting a tone slightly above threshold in the good ear and well above the admitted threshold in the poorer ear, a truly impaired listener still responds, whereas a feigning listener, hearing only the louder poor-ear tone, denies hearing anything.','This test checks for a faked or exaggerated loss in one ear. The same tone plays in both ears at once. A person only notices the louder tone. The good ear gets a soft tone; the bad ear gets a louder one. A faker hears only the loud side and stays silent.','It detects and helps quantify nonorganic unilateral hearing loss by exploiting the fact that only the louder of two identical tones is heard.','It is used when a one-sided loss looks inconsistent; a positive result, meaning no response when the good ear alone would still hear, signals exaggeration and prompts re-counseling and retesting.','Medical, Hearing & Clinical Acoustics',ARRAY['Nonorganic hearing loss','Pure-tone audiometry','Functional hearing loss','Weber test','Speech Stenger test']::text[],ARRAY['Applying it to symmetric losses where it does not work','Concluding malingering without careful re-instruction and cross-checks','Confusing a negative result with proof of organic loss']::text[],ARRAY['Investigating an inconsistent one-sided loss','Screening for exaggerated loss in a compensation case','Confirming a true asymmetry']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stenger test');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71fa7ecd-630c-5cc7-a9a4-3560e534999c','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71fa7ecd-630c-5cc7-a9a4-3560e534999c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71fa7ecd-630c-5cc7-a9a4-3560e534999c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71e5e791-bacb-5190-9770-7382fe8c0ced','Rinne test','A tuning-fork test, commonly using a 512-Hz fork, that compares a patient''s air-conduction and bone-conduction hearing in one ear by alternating the vibrating fork at the ear canal and on the mastoid. Normal or sensorineural ears hear air conduction as louder or longer, a positive Rinne, whereas a negative Rinne, with bone louder than air, indicates a conductive loss in that ear.','The Rinne test compares hearing by air and by bone in one ear. A vibrating fork is held by the ear, then on the bone behind it. Normally the by-air sound seems louder or lasts longer. If the bone sound wins, a conductive block is likely. It is a quick bedside check.','It gives a rapid bedside indication of whether a hearing loss is conductive, complementing the Weber test and formal audiometry.','It is performed with a 512-Hz fork during ear exams; a negative Rinne points to a conductive component and guides further audiometric and medical evaluation.','Medical, Hearing & Clinical Acoustics',ARRAY['Weber test','Bone conduction','Air conduction','Conductive hearing loss','Tuning-fork tests']::text[],ARRAY['Using a low-frequency fork whose vibrotactile cues can confound the result','Forgetting that a false-negative Rinne occurs with a non-functioning test ear','Relying on it instead of a full audiogram']::text[],ARRAY['Screening for a conductive loss at the bedside','Pairing it with the Weber test','Checking a suspected middle-ear problem']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rinne test');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71e5e791-bacb-5190-9770-7382fe8c0ced','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71e5e791-bacb-5190-9770-7382fe8c0ced') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71e5e791-bacb-5190-9770-7382fe8c0ced');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7eb7cd9d-9dd9-507d-90b8-8faedf0bc162','Weber test','A tuning-fork test in which a vibrating fork, commonly 512 Hz, is placed at the midline of the skull, on the forehead or vertex, and the patient reports where the tone is heard. Midline or symmetric perception is normal; lateralization to the poorer ear suggests a conductive loss there, while lateralization to the better ear suggests a sensorineural loss in the poorer ear.','The Weber test finds which ear a midline sound favors. A vibrating fork sits on the middle of the head. The person says where the tone seems loudest. A conductive block pulls the sound to the bad ear. A nerve loss pulls it to the good ear.','It helps classify a hearing loss as conductive or sensorineural at the bedside by how a midline tone lateralizes.','It is used with the Rinne test during ear exams; the direction of lateralization steers the clinician toward a conductive or sensorineural interpretation pending audiometry.','Medical, Hearing & Clinical Acoustics',ARRAY['Rinne test','Bone conduction','Conductive hearing loss','Sensorineural hearing loss','Tuning-fork tests']::text[],ARRAY['Interpreting lateralization without pairing it with the Rinne result','Assuming midline perception always means normal hearing','Using excessive force that adds vibrotactile cues']::text[],ARRAY['Localizing the type of a sudden one-sided loss','Pairing it with the Rinne test','Quick bedside triage before audiometry']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Weber test');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7eb7cd9d-9dd9-507d-90b8-8faedf0bc162','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7eb7cd9d-9dd9-507d-90b8-8faedf0bc162') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7eb7cd9d-9dd9-507d-90b8-8faedf0bc162');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eaa310fe-ff45-56b4-ad68-4af0184a60ac','Real-ear measurement','Probe-microphone measurement of sound pressure level in a patient''s own ear canal, near the eardrum, made with a thin probe tube placed alongside the ear or hearing aid. It characterizes the acoustic effect of the ear and of amplification in the real ear and is the standard, evidence-based method for verifying that a hearing aid meets prescriptive targets.','Real-ear measurement records the sound level inside a person''s own ear canal. A thin tube sits near the eardrum next to the hearing aid. It shows what the ear actually receives. This checks that the hearing aid hits its targets. It is the trusted way to verify a fitting.','It measures true in-ear amplification so a hearing aid can be adjusted to evidence-based prescriptive targets for that individual''s ear.','It is performed at the fitting with a probe tube and reference microphone; the clinician matches aided output to targets such as NAL or DSL across soft, medium, and loud inputs.','Medical, Hearing & Clinical Acoustics',ARRAY['Real-ear insertion gain','Real-ear aided response','Speech mapping','Hearing-aid verification','Probe-tube microphone']::text[],ARRAY['Skipping the measurement and trusting the fitting software''s simulated ear','Placing the probe tube too shallow, near a pressure node','UNSAFE: fitting without checking that loud-input output stays below the patient''s loudness discomfort level']::text[],ARRAY['Verifying a new hearing-aid fitting to targets','Troubleshooting a device that sounds wrong','Documenting output for different input levels']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Real-ear measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eaa310fe-ff45-56b4-ad68-4af0184a60ac','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eaa310fe-ff45-56b4-ad68-4af0184a60ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eaa310fe-ff45-56b4-ad68-4af0184a60ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b17399ce-e5f6-5c2d-ac2c-acaa30e90979','Real-ear unaided gain','The difference, as a function of frequency, between the sound pressure level measured near the eardrum with the ear open and unaided and the level at a reference point outside the ear, expressed in decibels. It quantifies the natural amplification of the open ear canal and concha, whose resonance peaks around 2.5 to 3 kHz, and it forms the baseline used to compute real-ear insertion gain.','This is the ear''s own natural boost with no device in. It compares sound near the eardrum to sound outside the ear. The open ear canal adds a peak around 2 to 3 kHz. This natural gain is measured first. It is later subtracted to find the aid''s added gain.','It quantifies the open ear''s natural resonance so a hearing aid''s true added benefit, the insertion gain, can be separated from the ear''s own effect.','It is measured with a probe tube in the open ear before insertion; the curve is stored and subtracted from the aided response to compute real-ear insertion gain.','Medical, Hearing & Clinical Acoustics',ARRAY['Real-ear aided response','Real-ear insertion gain','Ear-canal resonance','Real-ear measurement','Probe-tube microphone']::text[],ARRAY['Ignoring unaided gain and treating aided response as if it were added gain','Measuring with an inconsistent probe-tube depth','Assuming everyone has the same canal resonance']::text[],ARRAY['Establishing the open-ear baseline','Computing insertion gain later','Comparing an occluded fitting to the natural ear']::text[],'advanced','REUG = REUR − input level at the reference point','Real-ear unaided gain equals the unaided sound level near the eardrum minus the input level at the reference point, at each frequency.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Real-ear unaided gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b17399ce-e5f6-5c2d-ac2c-acaa30e90979','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b17399ce-e5f6-5c2d-ac2c-acaa30e90979') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b17399ce-e5f6-5c2d-ac2c-acaa30e90979');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3d82cbe7-44ae-549e-bed7-262d7159b82f','Real-ear insertion gain','The difference between the real-ear aided gain and the real-ear unaided gain at each frequency—that is, the additional gain a hearing aid provides in the real ear over the open, unaided ear, expressed in decibels. It is compared against prescriptive-target insertion gain to verify the fitting.','This is the extra boost a hearing aid adds in the ear. It is the aided gain minus the ear''s natural gain. The result shows only what the device contributes. It is checked against the target for the person''s loss. It confirms the aid gives the right help.','It isolates the hearing aid''s own contribution to gain so it can be matched to prescriptive targets during verification.','It is computed as aided minus unaided gain during real-ear measurement; the clinician adjusts the aid until measured insertion gain matches targets across frequencies.','Medical, Hearing & Clinical Acoustics',ARRAY['Real-ear unaided gain','Real-ear aided response','Real-ear measurement','Prescriptive target','Hearing-aid verification']::text[],ARRAY['Confusing insertion gain with aided output level','Verifying at a single input level instead of soft, medium, and loud','Skipping the unaided measure and mislabeling total gain as insertion gain']::text[],ARRAY['Matching a fitting to NAL or DSL targets','Adjusting gain across frequencies','Verifying a fitting against prescription']::text[],'advanced','REIG = REAG − REUG','Real-ear insertion gain equals the real-ear aided gain minus the real-ear unaided gain, at each frequency.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Real-ear insertion gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3d82cbe7-44ae-549e-bed7-262d7159b82f','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3d82cbe7-44ae-549e-bed7-262d7159b82f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3d82cbe7-44ae-549e-bed7-262d7159b82f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb9ba8b8-2df2-5d7b-b913-0de2f577f9df','Real-ear aided response','The sound pressure level, as a function of frequency, measured near the eardrum with the hearing aid in place and operating, for a specified input signal and level. It is the primary quantity matched to prescriptive sound-pressure-level targets in modern verification, and comparing it across input levels reveals the aid''s compression behavior.','This is the sound level near the eardrum with the aid on. A test signal plays and the probe records the output. It shows what the ear actually gets from the device. It is compared to targets for the person''s loss. Different input levels reveal how the aid compresses.','It provides the actual in-ear output of a working hearing aid so it can be matched to sound-pressure-level targets across input levels.','It is measured for soft, average, and loud inputs, plus a loud tone for maximum output; the clinician shapes the response to targets and checks that loud sounds stay comfortable.','Medical, Hearing & Clinical Acoustics',ARRAY['Real-ear insertion gain','Real-ear unaided gain','Speech mapping','Real-ear measurement','Prescriptive target']::text[],ARRAY['Verifying at only one input level and missing compression errors','Confusing aided response, a sound level, with insertion gain, a decibel difference','UNSAFE: allowing the maximum output to exceed the patient''s loudness discomfort level']::text[],ARRAY['Matching aided output to sound-pressure-level targets','Checking compression across input levels','Confirming maximum output is safe and comfortable']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Real-ear aided response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb9ba8b8-2df2-5d7b-b913-0de2f577f9df','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb9ba8b8-2df2-5d7b-b913-0de2f577f9df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb9ba8b8-2df2-5d7b-b913-0de2f577f9df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ecd3c865-bca7-5d5f-bcb1-565788f8f184','Speech mapping','A real-ear verification approach in which a speech or speech-like signal, often calibrated to standard long-term speech spectra at several input levels, is presented and the aided output in the ear canal is displayed relative to the patient''s thresholds and targets. Visualizing where amplified speech falls between threshold and loudness discomfort helps confirm audibility and counsel patients.','Speech mapping shows amplified speech inside the ear on a live display. Real or speech-like sound plays at soft, medium, and loud levels. The screen shows where speech lands for the listener. It confirms soft speech is audible and loud speech is comfortable. It also helps explain the fitting to patients.','It verifies and demonstrates that amplified speech is audible yet comfortable across input levels, using a visual, speech-based display for both clinician and patient.','It is run during hearing-aid verification with standardized speech signals; the clinician adjusts the aid so soft speech is audible and loud speech stays below discomfort, then reviews the display with the patient.','Medical, Hearing & Clinical Acoustics',ARRAY['Real-ear aided response','Real-ear measurement','Hearing-aid verification','Long-term average speech spectrum','Prescriptive target']::text[],ARRAY['Using an uncalibrated live voice and calling it verification','Judging only average speech and ignoring soft and loud inputs','UNSAFE: leaving loud-speech output above the patient''s loudness discomfort level']::text[],ARRAY['Demonstrating audibility to a new hearing-aid user','Fine-tuning gain for soft speech','Confirming comfort for loud speech']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ecd3c865-bca7-5d5f-bcb1-565788f8f184','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ecd3c865-bca7-5d5f-bcb1-565788f8f184') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ecd3c865-bca7-5d5f-bcb1-565788f8f184');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e73827c9-d647-5012-a123-b5ceb009079b','Hearing-aid verification','The objective, evidence-based process of confirming that a fitted hearing aid delivers the intended amplification—matching prescriptive targets for gain and output across input levels and keeping maximum output within safe, comfortable limits—primarily through probe-microphone real-ear measurement. It is distinct from validation, which assesses real-world benefit and satisfaction.','Hearing-aid verification confirms a fitted aid does what it should. Real-ear tests check that gain and output match the targets. It also checks that loud sounds stay comfortable. It is done with probe-microphone measures, not guesswork. It differs from validation, which asks if the aid helps in daily life.','It ensures a hearing aid actually meets prescriptive targets and safe output limits before the patient relies on it, rather than trusting default or simulated settings.','It is performed at the fitting using real-ear measurement and speech mapping; the clinician documents target match and maximum output, then schedules validation of real-world benefit.','Medical, Hearing & Clinical Acoustics',ARRAY['Real-ear measurement','Speech mapping','Real-ear insertion gain','Prescriptive target','Hearing-aid validation']::text[],ARRAY['Treating first-fit software settings as verified without real-ear measures','Confusing verification with validation','UNSAFE: skipping the maximum-output check so loud sounds can exceed the loudness discomfort level']::text[],ARRAY['Signing off a new fitting against targets','Documenting safe maximum output','Preparing before a real-world benefit check']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hearing-aid verification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e73827c9-d647-5012-a123-b5ceb009079b','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e73827c9-d647-5012-a123-b5ceb009079b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e73827c9-d647-5012-a123-b5ceb009079b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '823a95f3-8c35-591a-9c6d-df1d3aad6365','Forensic audio enhancement','The application of signal-processing techniques to a recording, within a documented and repeatable workflow, to improve the intelligibility or audibility of a target signal, usually speech, without adding, removing, or altering the underlying evidentiary content. Common operations include broadband and adaptive noise reduction, spectral filtering, equalization, de-reverberation, and level normalization, chosen and parameterized to attenuate interfering noise while preserving the questioned material. In a forensic context the processing is non-destructive to the original, fully logged, and reproducible so that another examiner can replicate the result.','This work makes a noisy recording clearer. It cuts noise so a voice is easier to hear. It uses filters and careful volume changes. It must not add or fake any sound. The first file is kept safe and untouched. Each step is written down so others can repeat it.','To raise the intelligibility of speech or other target sounds buried in noise so listeners, transcribers, or the court can better perceive what was recorded, while keeping the evidence trustworthy.','An examiner loads a verified working copy into a forensic audio workstation, applies adaptive noise reduction and narrow notch filters to remove hum and hiss, and exports an enhanced version alongside a processing log for disclosure.','Forensic Audio & Investigative Acoustics',ARRAY['Noise reduction','Spectral filtering','Forensic transcription','Working copy','De-reverberation']::text[],ARRAY['Believing enhancement can recover speech the microphone never captured','Processing the original evidence file instead of a verified working copy','Over-processing until artifacts appear that could be mistaken for real content','Not recording the settings used, so the result cannot be reproduced']::text[],ARRAY['Clarifying a threatening phone message for a transcript','Reducing traffic noise on a covert recording before review','Preparing an enhanced exhibit for presentation in court']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forensic audio enhancement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '823a95f3-8c35-591a-9c6d-df1d3aad6365','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='823a95f3-8c35-591a-9c6d-df1d3aad6365') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='823a95f3-8c35-591a-9c6d-df1d3aad6365');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'edf79a83-30fa-50fa-a75a-dc393daa1750','Forensic transcription','The systematic production of a written record of the speech content of a questioned recording, prepared by a trained examiner under a documented protocol, in which uncertain passages are marked and unintelligible passages are labelled rather than guessed. It distinguishes verified speech from inference, may use multiple independent passes and critical listening on calibrated monitoring, and records confidence for disputed words. The transcript is an aid to the trier of fact and remains subordinate to the audio itself.','This is writing down what is said on a recording. A trained worker listens closely, often many times. Unclear words are marked as unsure. Parts that cannot be made out are left blank. The written text helps a jury, but the audio still rules. Guessing at words is not allowed.','To give investigators and the court an accurate, honestly hedged written version of spoken content, so disputed passages can be located and reviewed against the recording.','An examiner transcribes an intercepted call on a forensic workstation, uses looping and slowed playback for difficult passages, flags overlapping talkers, and notes time codes and confidence for each disputed word.','Forensic Audio & Investigative Acoustics',ARRAY['Forensic audio enhancement','Critical listening','Questioned recording','Speaker attribution','Intelligibility']::text[],ARRAY['Filling unintelligible gaps with plausible guesses instead of marking them unclear','Letting an existing draft transcript bias what the listener hears','Attributing words to the wrong speaker in overlapping speech','Treating the transcript as evidence in place of the audio']::text[],ARRAY['Transcribing a covert body-wire recording for disclosure','Resolving a dispute over a single contested word in a call','Producing a time-coded transcript to accompany a courtroom playback']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forensic transcription');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'edf79a83-30fa-50fa-a75a-dc393daa1750','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='edf79a83-30fa-50fa-a75a-dc393daa1750') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='edf79a83-30fa-50fa-a75a-dc393daa1750');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1aed8f5-790b-5442-9a80-c1f2f45ba106','Automatic speaker recognition','A computational approach that compares voice recordings by extracting acoustic features, commonly short-term spectral features such as mel-frequency cepstral coefficients or learned embeddings such as i-vectors and x-vectors, and modelling them statistically to score how similar two samples are. In forensics it supports speaker comparison between a questioned recording and a known sample, ideally producing a calibrated score interpreted within a likelihood-ratio framework rather than a hard identity decision. Its performance depends on recording quality, duration, channel mismatch, and the relevance of the chosen background population.','This is software that compares voices by machine. It turns each voice into a set of numbers. Then it measures how alike two clips are. It can support, but not replace, an expert. Bad audio and short clips make it less sure. It should give a score, not a yes-or-no answer.','To provide an objective, repeatable measure of voice similarity that assists forensic speaker comparison and reduces reliance on subjective listening alone.','An examiner runs a questioned call and a suspect''s known sample through an x-vector system, checks that durations and channels are comparable, and reports a calibrated score with its background population.','Forensic Audio & Investigative Acoustics',ARRAY['Likelihood-ratio speaker comparison','Known-speaker sample','Questioned recording','Speaker embedding','Calibration']::text[],ARRAY['Reading a similarity score as a definite identification','Ignoring channel or language mismatch between the two samples','Using too short or too noisy a sample for a reliable result','Choosing a background population that does not fit the case']::text[],ARRAY['Screening a large set of calls for a suspect''s voice','Supporting a speaker comparison with an objective score','Testing whether two anonymous threat calls share one speaker']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Automatic speaker recognition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1aed8f5-790b-5442-9a80-c1f2f45ba106','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1aed8f5-790b-5442-9a80-c1f2f45ba106') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1aed8f5-790b-5442-9a80-c1f2f45ba106');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '28bf082a-33e3-5dba-977b-cbbd40017c70','Likelihood-ratio speaker comparison','A Bayesian framework for forensic speaker comparison in which the examiner evaluates the strength of the voice evidence as a likelihood ratio: the probability of the observed similarity between questioned and known samples if they share one speaker, divided by the probability of the same observation if they come from different speakers. The numerator addresses the prosecution hypothesis and the denominator the defence hypothesis, both assessed against a relevant background population. The examiner reports this ratio as strength of evidence and does not opine on the ultimate probability of identity, which belongs to the court.','This method scores voice evidence as a ratio. The top asks how likely the match is for the same person. The bottom asks how likely it is for someone else. A big ratio favors the same speaker. A ratio near one gives little help. The expert gives strength of evidence, not a verdict.','To express voice-comparison results in a logically sound, transparent way that separates the expert''s role of weighing evidence from the court''s role of deciding identity.','A phonetician combines automatic scores and analysis of a questioned call and a suspect''s known sample, references a background population, and reports a likelihood ratio with its verbal equivalent in the expert statement.','Forensic Audio & Investigative Acoustics',ARRAY['Automatic speaker recognition','Known-speaker sample','Questioned recording','Background population','Calibration']::text[],ARRAY['Treating the likelihood ratio as the probability that the suspect is the speaker','Ignoring the defence hypothesis and reporting only similarity','Using an irrelevant background population for the denominator','Stating a firm identification instead of strength of evidence']::text[],ARRAY['Reporting the weight of voice evidence in an expert statement','Comparing a ransom call to a suspect''s police interview','Explaining to a court why a match is not a certainty']::text[],'advanced','LR = p(E | Hp) / p(E | Hd)','The likelihood ratio equals the probability of the evidence given the prosecution hypothesis of one speaker, divided by its probability given the defence hypothesis of different speakers.','0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Likelihood-ratio speaker comparison');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '28bf082a-33e3-5dba-977b-cbbd40017c70','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='28bf082a-33e3-5dba-977b-cbbd40017c70') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='28bf082a-33e3-5dba-977b-cbbd40017c70');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '868d6629-4966-549f-a2cc-fe1065402ef9','Known-speaker sample','A recording of a person whose identity is established, used as the reference in a forensic speaker comparison against a questioned recording. Its evidential value depends on adequate duration and quality and, ideally, comparability to the questioned material in language, speaking style, channel, and recording conditions, to limit mismatch. Known samples may come from police interviews, prior lawful recordings, or purpose-made exemplars.','This is a recording of a named person. Its speaker is not in doubt. It is the reference used to compare with an unknown voice. It works best when it is long and clear. It should match the unknown clip in language and channel. Otherwise the comparison is weaker.','To supply a trustworthy reference voice against which a questioned recording can be compared in a speaker-comparison analysis.','An examiner uses a suspect''s recorded police interview as the known sample, checks it is long enough, and where possible obtains an exemplar recorded under conditions similar to the questioned call.','Forensic Audio & Investigative Acoustics',ARRAY['Questioned recording','Exemplar recording','Likelihood-ratio speaker comparison','Automatic speaker recognition','Channel mismatch']::text[],ARRAY['Using a sample too short to capture the speaker''s range','Ignoring a large channel or style mismatch with the questioned clip','Assuming a poor-quality reference cannot bias the result','Confusing a known sample with a purpose-made exemplar']::text[],ARRAY['Taking a suspect''s interview as the reference voice','Recording a fresh exemplar to match a phone-quality clip','Rejecting a reference that is too brief for comparison']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Known-speaker sample');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '868d6629-4966-549f-a2cc-fe1065402ef9','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='868d6629-4966-549f-a2cc-fe1065402ef9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='868d6629-4966-549f-a2cc-fe1065402ef9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77a077ce-97e6-5b61-8476-9c8beebb64ad','Questioned recording','The recording whose content, source, integrity, or speaker is in dispute and is the subject of a forensic examination. It is the item compared against known references or tested for authenticity and integrity, handled under chain of custody with all analysis performed on verified working copies. The term denotes evidential status rather than any particular technical property.','This is the recording under doubt. Its speaker, source, or edits may be disputed. It is the item the examiner tests or compares. It is kept under strict control. All work is done on safe copies, never the master.','To label the piece of audio evidence that an examination is trying to explain, compare, or verify, distinguishing it from known references and exemplars.','On receiving a disputed emergency call, the examiner logs it as the questioned recording, hashes and copies it, and performs authentication and speaker comparison on the working copy.','Forensic Audio & Investigative Acoustics',ARRAY['Known-speaker sample','Exemplar recording','Original recording','Chain of custody','Authentication']::text[],ARRAY['Analyzing the questioned original directly instead of a verified copy','Assuming questioned status implies the recording is fake','Breaking chain of custody while handling the item','Confusing the questioned recording with a later derivative copy']::text[],ARRAY['Logging a disputed call as the item to be examined','Comparing a questioned threat message to a suspect''s voice','Testing a questioned recording for signs of editing']::text[],'beginner',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Questioned recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77a077ce-97e6-5b61-8476-9c8beebb64ad','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77a077ce-97e6-5b61-8476-9c8beebb64ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77a077ce-97e6-5b61-8476-9c8beebb64ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2c88c80f-562c-5d5f-b541-2442d21228e4','Exemplar recording','A recording made specifically to serve as a controlled reference for comparison, typically produced under conditions chosen to resemble the questioned recording, with the same or similar language, speaking style, handset or microphone, and channel, so that comparison is not confounded by mismatch. In speaker comparison an exemplar is a purpose-made known sample; the concept also extends to recreating device or environment recordings for authenticity and audibility work.','An exemplar is a reference made on purpose. It is recorded to match the unknown clip. The examiner may copy its language, phone, and setting. This keeps the comparison fair. A good exemplar removes differences that are not about the voice.','To create a well-matched reference that reduces channel and style mismatch, strengthening the validity of a comparison.','To compare with a mobile-phone threat call, an examiner has the suspect read similar material over a comparable handset, producing an exemplar with matched channel characteristics.','Forensic Audio & Investigative Acoustics',ARRAY['Known-speaker sample','Questioned recording','Channel mismatch','Likelihood-ratio speaker comparison','Speaker attribution']::text[],ARRAY['Recording an exemplar under conditions unlike the questioned clip','Coaching the speaker so the exemplar is unnatural','Assuming any known sample counts as a matched exemplar','Ignoring handset or codec differences when planning the exemplar']::text[],ARRAY['Recording a suspect over a phone to match a call','Recreating a scene recording to test audibility','Building a matched reference for speaker comparison']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exemplar recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2c88c80f-562c-5d5f-b541-2442d21228e4','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2c88c80f-562c-5d5f-b541-2442d21228e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2c88c80f-562c-5d5f-b541-2442d21228e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95d0aa29-f2d2-5f78-9946-813adc4b0892','Original recording','In forensic audio, the first instance of a recording as captured and stored by the originating device on its original medium, together with its native file structure and metadata. Establishing that an item is the original, rather than a copy, export, or re-encode, is central to authentication, because integrity and structural analysis are most reliable on the native original. Where only copies exist, this must be documented and factored into any authenticity opinion.','The original is the very first version. It is the file the device itself made and saved. It still has its first format and hidden data. Checks for editing work best on this file. A copy or re-save loses clues it still holds.','To identify the most trustworthy version of a recording for integrity and authenticity analysis, before any copying or format change occurs.','An examiner seeks the recorder''s native file from the source device, verifies it against copies by hash, and bases structural authentication on this original rather than an emailed export.','Forensic Audio & Investigative Acoustics',ARRAY['Native file analysis','Derivative recording','Container metadata','Authentication','Chain of custody']::text[],ARRAY['Treating an emailed or re-encoded copy as the original','Overwriting the original on the device before it is preserved','Assuming metadata survives copying unchanged','Basing authentication on a derivative when the original is available']::text[],ARRAY['Recovering the native file from a seized phone','Distinguishing the original from a messaging-app compressed copy','Preserving a body-camera original before analysis']::text[],'beginner',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Original recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95d0aa29-f2d2-5f78-9946-813adc4b0892','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95d0aa29-f2d2-5f78-9946-813adc4b0892') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95d0aa29-f2d2-5f78-9946-813adc4b0892');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e7c61a6-bd0a-557b-8f9f-d45dce9fa684','Derivative recording','Any recording produced from another recording by copying, exporting, editing, re-recording, or format conversion, as opposed to the native original. Derivatives may differ from the original in codec, sample rate, metadata, and quality, and each processing generation can add artifacts; identifying a chain of derivatives is important to authentication and to interpreting any structural analysis. A derivative can still be evidentially useful when its history is properly documented.','A derivative comes from another recording. It is a copy, export, edit, or re-save. It often differs in format or quality. Each new version can add flaws. Knowing a file is a copy changes how you read it.','To flag that a file is not the native original, so its metadata, quality, and any structural findings are interpreted with that history in mind.','An examiner notes that a submitted clip is a messaging-app export, treats it as a derivative, and adjusts expectations for metadata and codec-based authentication accordingly.','Forensic Audio & Investigative Acoustics',ARRAY['Original recording','Transcoding history','Generation loss','Codec lineage','Native file analysis']::text[],ARRAY['Reporting on a derivative as if it were the original','Blaming compression artifacts on tampering','Ignoring that each copy generation can degrade quality','Assuming a derivative''s metadata reflects the capture device']::text[],ARRAY['Recognizing a re-recorded screen capture of a video','Tracing a clip exported and re-shared several times','Documenting a derivative when the original is unavailable']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Derivative recording');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e7c61a6-bd0a-557b-8f9f-d45dce9fa684','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e7c61a6-bd0a-557b-8f9f-d45dce9fa684') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e7c61a6-bd0a-557b-8f9f-d45dce9fa684');
